-- william-shakespeare_king-lear (753 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_king-lear', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","kinglearspalace~kinglearspalace~15":"O palácio do Rei Lear","enterkentgloucesterandedmund~rkentgloucesterandedmund~28":"Entram Kent, Gloucester e Edmund.","kentithoughtthekinghadmoreaffectedtheduk~dukeofalbanythancornwall~61":"Kent — Pensei que o rei tivesse mais afeição ao Duque de Albany do que a Cornwall.","gloucesteritdidalwaysseemsotousbutnowint~akechoiceofeithersmoiety~176":"Gloucester — Sempre nos pareceu assim: mas agora, na divisão do reino, não se vê qual dos duques ele mais estima; pois as porções são tão equilibradas que o exame mais minucioso não saberia escolher entre uma metade e outra.","kentisnotthisyoursonmylord~ntisnotthisyoursonmylord~26":"Kent — Não é este o seu filho, milorde?","gloucesterhisbreedingsirhathbeenatmychar~ehimthatnowiambrazedtoit~97":"Gloucester — Sua criação, senhor, correu por minha conta: tantas vezes corei ao reconhecê-lo, que agora estou calejado.","kenticannotconceiveyou~kenticannotconceiveyou~22":"Kent — Não o compreendo.","gloucestersirthisyoungfellowsmothercould~orherbeddoyousmellafault~140":"Gloucester — Senhor, a mãe deste rapaz compreendeu: pelo que ficou de ventre redondo, e teve, de fato, senhor, um filho no berço antes de ter um marido no leito. Sente cheiro de falta?","kenticannotwishthefaultundonetheissueofi~heissueofitbeingsoproper~54":"Kent — Não posso desejar a falta desfeita, sendo o fruto dela tão bem-feito.","gloucesterbutihavesirasonbyorderoflawsom~thisnoblegentlemanedmund~262":"Gloucester — Mas tenho, senhor, um filho por força da lei, uns anos mais velho que este, que nem por isso me é mais caro: embora este maroto tenha vindo ao mundo um tanto atrevidamente, antes de ser chamado, sua mãe era bela; houve bom divertimento em sua feitura, e o bastardo deve ser reconhecido. Conhece este nobre cavalheiro, Edmund?","edmundnomylord~edmundnomylord~14":"Edmund — Não, milorde.","gloucestermylordofkentrememberhimhereaft~fterasmyhonourablefriend~62":"Gloucester — Milorde de Kent: lembre-se dele daqui por diante como meu honrado amigo.","edmundmyservicestoyourlordship~myservicestoyourlordship~30":"Edmund — Meus serviços a Vossa Senhoria.","kentimustloveyouandsuetoknowyoubetter~youandsuetoknowyoubetter~37":"Kent — Devo estimá-lo, e peço conhecê-lo melhor.","edmundsirishallstudydeserving~dsirishallstudydeserving~29":"Edmund — Senhor, esforçar-me-ei por merecê-lo.","gloucesterhehathbeenoutnineyearsandawayh~hallagainthekingiscoming~66":"Gloucester — Esteve fora nove anos, e fora estará de novo. O rei vem vindo.","sennetenterkinglearcornwallalbanygoneril~gancordeliaandattendants~66":"Toque de trombetas. Entram o Rei Lear, Cornwall, Albany, Goneril, Regan, Cordélia e Séquito.","kinglearattendthelordsoffranceandburgund~nceandburgundygloucester~51":"Rei Lear — Atenda os senhores de França e Borgonha, Gloucester.","gloucesterishallmyliege~gloucesterishallmyliege~23":"Gloucester — Atenderei, meu soberano.","exeuntgloucesterandedmund~xeuntgloucesterandedmund~25":"Saem Gloucester e Edmund.","kinglearmeantimeweshallexpressourdarkerp~loureldestbornspeakfirst~697":"Rei Lear — Entrementes exporemos nosso propósito mais sombrio.\nDai-me o mapa. Sabei que dividimos\nem três o nosso reino: e é firme intento nosso\nsacudir de nossa idade todos os cuidados e negócios,\nconferindo-os a forças mais jovens, enquanto nós,\naliviados, rastejamos para a morte. Nosso filho de Cornwall,\ne vós, nosso não menos amado filho de Albany,\ntemos nesta hora vontade firme de tornar público\no dote de cada uma de nossas filhas, para que futura contenda\nseja prevenida desde já. Os príncipes, França e Borgonha,\ngrandes rivais no amor de nossa filha mais nova,\nlongamente fizeram em nossa corte sua estada amorosa,\ne aqui devem ser respondidos. Dizei-me, filhas minhas —\nvisto que agora nos despiremos juntos de mando,\nposse de território, cuidados de Estado —\nqual de vós diremos que mais nos ama?\nPara que nossa maior generosidade se estenda\nonde a natureza com o mérito disputa. Goneril,\nnossa primogênita, falai primeiro.","gonerilsiriloveyoumorethanwordscanwieldt~llmannerofsomuchiloveyou~257":"Goneril — Senhor, amo-vos mais do que palavras podem manejar a matéria;\nmais que a luz dos olhos, o espaço e a liberdade;\nalém de tudo o que se possa avaliar, rico ou raro;\nnão menos que a vida, com graça, saúde, beleza, honra;\ntanto quanto filha jamais amou, ou pai achou;\num amor que faz o fôlego pobre e a fala incapaz;\nalém de toda medida de tanto eu vos amo.","cordeliaasidewhatshallcordeliadoloveandb~ordeliadoloveandbesilent~47":"Cordélia — À parte. Que fará Cordélia? Amar, e calar.","learofalltheseboundsevenfromthislinetoth~reganwifetocornwallspeak~229":"Lear — De todos estes limites, desta linha até esta,\ncom florestas sombrias e planícies enriquecidas,\ncom rios abundantes e vastos prados,\nfazemos-te senhora: à tua descendência e à de Albany\nseja isto perpétuo. Que diz nossa segunda filha,\nnossa queridíssima Regan, esposa de Cornwall? Falai.","regansiriammadeoftheselfsamemetalthatmys~teinyourdearhighnesslove~257":"Regan — Senhor, sou feita\ndo mesmo metal que minha irmã,\ne avaliai-me pelo seu valor. Em meu verdadeiro coração\nacho que ela nomeia o próprio ato do meu amor;\nsó que fica aquém: pois declaro\nser inimiga de todas as outras alegrias\nque o mais precioso domínio dos sentidos possui;\ne sinto-me feliz somente\nno amor de Vossa cara Alteza.","cordeliaasidethenpoorcordeliaandyetnotso~esmorericherthanmytongue~81":"Cordélia — À parte. Pobre Cordélia, então! \nE contudo não, pois estou certa de que meu amor \né mais rico que minha língua.","kingleartotheeandthinehereditaryeverrema~lentthanyoursistersspeak~285":"Rei Lear — A ti e aos teus, hereditariamente para sempre, \npermaneça este amplo terço de nosso belo reino; \nem nada menor em extensão, valor e deleite \nque o conferido a Goneril. Agora, nossa alegria, \nembora a última, não a menor; por cujo jovem amor \nas vinhas da França e o leite da Borgonha \ndisputam interessar-se; que podes dizer para obter \num terço mais opulento que o de tuas irmãs? Fala.","cordelianothingmylord~cordelianothingmylord~21":"Cordélia — Nada, meu senhor.","kinglearnothing~kinglearnothing~15":"Rei Lear — Nada!","cordelianothing~cordelianothing~15":"Cordélia — Nada.","kinglearnothingwillcomeofnothingspeakaga~lcomeofnothingspeakagain~42":"Rei Lear — Nada virá do nada: fala de novo.","cordeliaunhappythatiamicannotheavemyhear~ngtomybondnormorenorless~99":"Cordélia — Infeliz de mim, não consigo erguer \no coração até à boca: amo vossa majestade \nsegundo meu dever; nem mais nem menos.","kinglearhowhowcordeliamendyourspeechalit~lestitmaymaryourfortunes~67":"Rei Lear — Como, como, Cordélia! Emenda um pouco a fala, \npara que não arruíne tua fortuna.","cordeliagoodmylordyouhavebegotmebredmelo~sisterstolovemyfatherall~302":"Cordélia — Bom meu senhor, \ngerastes-me, criastes-me, amastes-me: eu \nretribuo esses deveres como é justo: \nobedeço-vos, amo-vos e honro-vos acima de tudo. \nPor que têm minhas irmãs maridos, se dizem \namar-vos totalmente? Talvez, quando eu me casar, \no senhor cuja mão receber minha promessa levará consigo \nmetade do meu amor, metade de meu cuidado e dever: \ncerto, jamais me casarei como minhas irmãs, \npara amar só o meu pai.","kinglearbutgoesthyheartwiththis~rbutgoesthyheartwiththis~31":"Rei Lear — Mas teu coração está com isso?","cordeliaaygoodmylord~cordeliaaygoodmylord~20":"Cordélia — Sim, bom meu senhor.","kinglearsoyoungandsountender~learsoyoungandsountender~28":"Rei Lear — Tão jovem, e tão pouco terna?","cordeliasoyoungmylordandtrue~eliasoyoungmylordandtrue~28":"Cordélia — Tão jovem, meu senhor, e verdadeira.","kinglearletitbesothytruththenbethydowerf~asthoumysometimedaughter~408":"Rei Lear — Seja assim; que tua verdade, então, seja teu dote: \npois, pelo sagrado fulgor do sol, \npelos mistérios de Hécate e da noite; \npor toda a operação dos orbes \nde que existimos e deixamos de ser; \naqui renego todo o meu cuidado paterno, \nparentesco e propriedade de sangue, \ne como uma estranha a meu coração e a mim \ntenho-te, desde agora, para sempre. O bárbaro cita, \nou aquele que faz da própria prole iguaria \npara fartar o apetite, será a meu peito \ntão bem vizinho, compadecido e socorrido \nquanto tu, minha outrora filha.","kentgoodmyliege~kentgoodmyliege~15":"Kent — Bom meu soberano —","kinglearpeacekentcomenotbetweenthedragon~betwixtyougivingthecrown~636":"Rei Lear — Paz, Kent! \nNão te ponhas entre o dragão e sua cólera. \nAmava-a mais, e pensava repousar \nem seus ternos cuidados. Fora, e foge-me da vista! \nSeja o meu túmulo a minha paz, como aqui lhe tiro \no coração de pai! Chamai a França; quem se move? \nChamai a Borgonha. Cornualha e Albany, \ncom os dotes de minhas duas filhas digeri este terço: \nque o orgulho, que ela chama franqueza, a despose. \nInvisto-vos conjuntamente de meu poder, \npreeminência e todos os grandes efeitos \nque acompanham a majestade. Nós mesmo, por turno mensal, \ncom reserva de cem cavaleiros, \npor vós sustentados, faremos nossa morada \nconvosco em devidas alternâncias. Só retemos \no nome e todos os atributos de um rei; \no mando, a renda, a execução do resto, \namados filhos, sejam vossos: para o que confirmar, \nesta coroa dividi entre vós. Entregando a coroa.","kentroyallearwhomihaveeverhonourdasmykin~tronthoughtoninmyprayers~108":"Kent — Real Lear, \na quem sempre honrei como meu rei, \namei como meu pai, segui como meu amo, \nlembrei como meu grande protetor nas orações —","kinglearthebowisbentanddrawnmakefromthes~anddrawnmakefromtheshaft~44":"Rei Lear — O arco está curvado e retesado, foge da flecha.","kentletitfallratherthoughtheforkinvadeth~soundreverbsnohollowness~395":"Kent — Que caia antes, ainda que a ponta invada \na região do meu coração: seja Kent descortês \nquando Lear está louco. Que farás, velho? \nPensas que o dever temerá falar \nquando o poder se curva à adulação? À franqueza está obrigada a honra, \nquando a majestade se curva à loucura. Revoga a sentença; \ne, em tua melhor reflexão, refreia \nesta hedionda precipitação: respondo com minha vida pelo meu juízo: \ntua filha mais moça não te ama menos; \nnem são vazios de coração aqueles cujo som baixo \nnão ecoa oco.","kinglearkentonthylifenomore~glearkentonthylifenomore~27":"Rei Lear — Kent, por tua vida, nem mais uma palavra.","kentmylifeineverheldbutasapawntowageagai~tthysafetybeingthemotive~91":"Kent — Minha vida nunca a tive senão como penhor \npara apostar contra teus inimigos; nem temo perdê-la, \nsendo a tua segurança o motivo.","kinglearoutofmysight~kinglearoutofmysight~20":"Rei Lear — Fora da minha vista!","kentseebetterlearandletmestillremainthet~inthetrueblankofthineeye~58":"Kent — Vê melhor, Lear; e deixa-me ainda ser \no verdadeiro alvo do teu olhar.","kinglearnowbyapollo~kinglearnowbyapollo~19":"Rei Lear — Agora, por Apolo —","kentnowbyapollokingthouswearstthygodsinv~thouswearstthygodsinvain~43":"Kent — Agora, por Apolo, rei, \njuras em vão por teus deuses.","kinglearovassalmiscreantlayinghishandonh~tlayinghishandonhissword~47":"Rei Lear — Oh, vassalo! Miserável! Pondo a mão na espada.","albanycornwalldearsirforbear~nycornwalldearsirforbear~28":"Albany\nCornualha — Caro senhor, contende.","kentdokillthyphysicianandthefeebestowupo~tilltelltheethoudostevil~126":"Kent — Faze-o: \nmata teu médico, e dá o pagamento \nà tua doença imunda. Revoga a sentença; \nou, enquanto puder exalar clamor da garganta, \ndir-te-ei que fazes mal.","kinglearhearmerecreantonthineallegianceh~terthisshallnotberevoked~448":"Rei Lear — Ouve-me, covarde! \nPor tua lealdade, ouve-me! \nJá que procuraste fazer-nos quebrar nosso voto, \nque nunca ousamos antes, e com orgulho forçado \nte meteste entre nossa sentença e nosso poder, \ncoisa que nem nossa natureza nem nosso posto suportam, \ntendo nossa potência se afirmado, toma tua paga. \nCinco dias te concedemos, para provisão \ncontra as doenças do mundo; \ne no sexto para virar tuas odiadas costas \nao nosso reino: se, no décimo dia seguinte, \nteu tronco banido for achado em nossos domínios, \nnaquele instante é tua morte. Fora! Por Júpiter, \nisto não será revogado.","kentfaretheewellkingsiththusthouwiltappe~dcourseinacountrynewexit~328":"Kent — Passa bem, rei: já que assim te mostras, \na liberdade vive fora daqui, e o banimento está aqui. \nA Cordélia. Os deuses te tomem em seu caro abrigo, donzela, \nque pensas com justiça e falaste com toda a retidão! \nA Regana e Goneril. E vossas grandes palavras vossos atos confirmem, \npara que bons efeitos brotem de palavras de amor. \nAssim Kent, ó princesas, vos diz adeus a todas; \nseguirá seu velho caminho num país novo. Sai.","flourishreentergloucesterwithkingoffranc~nceburgundyandattendants~62":"Fanfarra. Reentra Gloucester, com o Rei da França, Borgonha e Criados.","gloucesterheresfranceandburgundymynoblel~ceandburgundymynoblelord~43":"Gloucester — Aqui estão a França e a Borgonha, meu nobre senhor.","kinglearmylordofburgundywefirstaddressto~erorceaseyourquestoflove~159":"Rei Lear — Meu senhor de Borgonha, \nprimeiro nos dirigimos a vós, que com este rei \nrivalizastes por nossa filha: que, no mínimo, \nexigis como dote presente com ela, \nou cessais vossa busca de amor?","burgundymostroyalmajestyicravenomorethan~ferdnorwillyoutenderless~82":"Borgonha — Majestade real, \nnão peço mais que o que vossa alteza ofereceu, \nnem vós ofertareis menos.","kinglearrightnobleburgundywhenshewasdear~ceshesthereandsheisyours~225":"Rei Lear — Nobilíssimo Borgonha, \nquando ela nos era cara, assim a tínhamos; \nmas agora seu preço caiu. Senhor, ei-la ali: \nse algo naquela pequena substância aparente, \nou tudo dela, com nosso desagrado remendado, \ne nada mais, puder convir à vossa graça, \nela está ali, e é vossa.","burgundyiknownoanswer~burgundyiknownoanswer~21":"Borgonha — Não sei responder.","kinglearwillyouwiththoseinfirmitiessheow~ouroathtakeherorleaveher~129":"Rei Lear — Quereis, com as enfermidades que ela tem, \nsem amigos, recém-adotada em nosso ódio, \ndotada de nossa maldição e estranhada por nosso juramento, \ntomá-la ou deixá-la?","burgundypardonmeroyalsirelectionmakesnot~kesnotuponsuchconditions~58":"Borgonha — Perdoai-me, real senhor; \na escolha não se faz em tais condições.","kinglearthenleavehersirforbythepowerthat~dalmosttoacknowledgehers~257":"Rei Lear — Então deixai-a, senhor; pois, pelo poder que me fez, \ndigo-vos toda a sua riqueza. Ao Rei da França. Quanto a vós, grande rei, \nnão quereria desviar-me tanto do vosso amor \npara vos casar onde odeio; por isso vos rogo \nque desvieis vossa afeição para caminho mais digno \ndo que uma desgraçada que a própria natureza se envergonha \nquase de reconhecer por sua.","kingoffrancethisismoststrangethatshethat~raclecouldneverplantinme~366":"Rei da França — Isto é estranhíssimo, \nque ela, que ainda há pouco era vosso melhor objeto, \no tema de vosso louvor, bálsamo de vossa velhice, \na melhor, a mais querida, neste breve instante \ncometa algo tão monstruoso a ponto de desfazer \ntantas dobras de favor. Certo, sua ofensa \ndeve ser de grau tão antinatural \nque a torna monstro, ou vossa afeição outrora jurada \ncaiu em mácula: crer o que de ela \nexige uma fé que a razão, sem milagre, \njamais plantaria em mim.","cordeliaiyetbeseechyourmajestyifforiwant~ithathlostmeinyourliking~361":"Cordélia — Ainda assim rogo a vossa majestade — \nse porque me falta aquela arte fácil e untuosa \nde falar sem propor — pois o que bem pretendo, \nfaço antes de falar — que torneis sabido \nque não é nenhuma nódoa viciosa, assassínio ou torpeza, \nnenhuma ação impudica ou passo desonrado \nque me privou de vossa graça e favor; \nmas justamente a falta daquilo em que sou mais rica, \num olho sempre a solicitar e uma língua tal \nque me alegro de não ter, embora não tê-la \nme tenha feito perder vossa estima.","kinglearbetterthouhadstnotbeenbornthanno~nottohavepleasedmebetter~62":"Rei Lear — Melhor \nnão teres nascido do que não me teres agradado melhor.","kingoffranceisitbutthisatardinessinnatur~avehersheisherselfadowry~228":"Rei da França — É só isto — uma lentidão da natureza \nque muitas vezes deixa por contar a história \nque pretende fazer? Meu senhor de Borgonha, \nque dizeis da dama? Amor não é amor \nquando se mistura a considerações que ficam \nlonge do ponto inteiro. Quereis tomá-la? \nEla é, em si mesma, um dote.","burgundyroyalleargivebutthatportionwhich~thehandduchessofburgundy~102":"Borgonha — Real Lear, \ndai apenas aquela porção que vós mesmo propusestes, \ne aqui tomo Cordélia pela mão, \nduquesa de Borgonha.","kinglearnothingihavesworniamfirm~nothingihavesworniamfirm~32":"Rei Lear — Nada: jurei; estou firme.","burgundyiamsorrythenyouhavesolostafather~rthatyoumustloseahusband~63":"Borgonha — Lamento, então, que tenhais perdido assim um pai \npara que tenhais de perder um marido.","cordeliapeacebewithburgundysincethatresp~isloveishallnotbehiswife~81":"Cordélia — A paz esteja com Borgonha! \nJá que respeitos de fortuna são o seu amor, \nnão serei sua esposa.","kingoffrancefairestcordeliathatartmostri~sthereabetterwheretofind~435":"Rei da França — Belíssima Cordélia, riquíssima por ser pobre; \nescolhidíssima, abandonada; e amadíssima, desprezada! \nA ti e a tuas virtudes aqui tomo para mim: \nseja lícito eu recolher o que é lançado fora. \nDeuses, deuses! É estranho que de seu mais frio descaso \nmeu amor se inflame em respeito ardente. \nTua filha sem dote, rei, lançada à minha sorte, \né rainha de nós, dos nossos e de nossa bela França: \nnem todos os duques da aguada Borgonha \npoderão comprar de mim esta donzela preciosa e desprezada. \nDespede-te deles, Cordélia, embora cruéis: \naqui perdes, para achar um lugar melhor.","kinglearthouhastherfranceletherbethinefo~egonerilreganandcordelia~214":"Rei Lear — Tens-na, França: seja tua; pois nós \nnão temos tal filha, nem veremos jamais \naquele rosto seu de novo. Portanto ide-vos \nsem nossa graça, nosso amor, nossa bênção. \nVinde, nobre Borgonha. Fanfarra. Saem todos, menos o Rei da França, Goneril, Regana e Cordélia.","kingoffrancebidfarewelltoyoursisters~bidfarewelltoyoursisters~36":"Rei da França — Despede-te de tuas irmãs.","cordeliathejewelsofourfatherwithwashdeye~placesofarewelltoyouboth~256":"Cordélia — As joias de nosso pai, com olhos lavados \nCordélia vos deixa: sei o que sois; \ne como irmã tenho muita relutância em chamar \nvossas faltas pelos nomes que têm. Tratai bem nosso pai: \na vossos peitos professos o confio. \nMas, ai, se eu estivesse em sua graça, \npreferiria pô-lo em lugar melhor. \nAssim, adeus a ambas.","reganprescribenotusourduties~nprescribenotusourduties~28":"Regana — Não nos prescrevais deveres.","gonerilletyourstudybetocontentyourlordwh~thewantthatyouhavewanted~132":"Goneril — Que vosso estudo \nseja contentar vosso senhor, que vos recebeu \nde esmola da fortuna. Escasseastes a obediência, \ne bem mereceis a falta que haveis feito.","cordeliatimeshallunfoldwhatplaitedcunnin~derideswellmayyouprosper~99":"Cordélia — O tempo desvendará o que a astúcia trançada esconde: \nos que cobrem faltas, no fim a vergonha os zomba. \nPossais prosperar!","kingoffrancecomemyfaircordeliaexeuntking~tkingoffranceandcordelia~59":"Rei da França — Vem, minha bela Cordélia. Saem o Rei da França e Cordélia.","gonerilsisteritisnotalittleihavetosayofw~urfatherwillhencetonight~102":"Goneril — Irmã, não é pouco o que tenho a dizer do que mais de perto nos toca a ambas. Creio que nosso pai partirá daqui esta noite.","reganthatsmostcertainandwithyounextmonth~ndwithyounextmonthwithus~46":"Regana — É certíssimo, e para vossa casa; no mês que vem, para a nossa.","gonerilyouseehowfullofchangeshisageisthe~theroffappearstoogrossly~167":"Goneril — Vedes quão cheia de mudanças é sua velhice; a observação que fizemos não foi pequena: sempre amou mais nossa irmã; e com que pobre juízo a rejeitou agora aparece com demasiada evidência.","regantistheinfirmityofhisageyethehatheve~butslenderlyknownhimself~65":"Regana — É a enfermidade da idade: contudo ele sempre se conheceu apenas escassamente.","gonerilthebestandsoundestofhistimehathbe~olericyearsbringwiththem~203":"Goneril — O melhor e mais sadio de seus tempos foi apenas impetuoso; então devemos esperar receber de sua velhice não só as imperfeições de um temperamento longamente enraizado, mas junto com elas a teimosia indomável que anos enfermos e coléricos trazem consigo.","regansuchunconstantstartsareweliketohave~masthisofkentsbanishment~70":"Regana — Tais arrancos inconstantes é provável que tenhamos dele, como este do banimento de Kent.","gonerilthereisfurthercomplimentofleaveta~nderofhiswillbutoffendus~176":"Goneril — Há ainda a cerimônia de despedida entre a França e ele. Peço-vos, ajustemo-nos juntas: se nosso pai conservar autoridade com tais humores como os que tem, esta última entrega de seu poder só nos ofenderá.","reganweshallfurtherthinkont~anweshallfurtherthinkont~27":"Regana — Pensaremos mais nisso.","gonerilwemustdosomethinganditheheatexeun~methinganditheheatexeunt~41":"Goneril — Devemos fazer algo, e no calor. Saem.","sceneii~sceneii~7":"Cena II","theearlofgloucesterscastle~eearlofgloucesterscastle~26":"O castelo do Conde de Gloucester.","enteredmundwithaletter~enteredmundwithaletter~22":"Entra Edmundo, com uma carta.","edmundthounatureartmygoddesstothylawmyse~owgodsstandupforbastards~726":"Edmundo — Tu, natureza, és minha deusa; a tua lei \nmeus serviços estão obrigados. Por que haveria eu \nde ficar na praga do costume, e permitir \nque o escrúpulo das nações me prive, \nporque sou uns doze ou catorze luares \natrás de um irmão? Por que bastardo? Por que baixo? \nQuando minhas dimensões são tão bem compostas, \nminha mente tão generosa e minha forma tão verdadeira \nquanto as da prole de uma honesta senhora? Por que nos marcam \ncom baixo? Com baixeza? Bastardia? Baixo, baixo? \nNós, que no furtivo vigor da natureza recebemos \nmais composição e feroz qualidade \ndo que, num leito tedioso, rançoso e cansado, \nvai para a criação de toda uma tribo de patetas, \ngerada entre o sono e a vigília? Pois bem, então, \nlegítimo Edgar, devo ter tuas terras: \no amor de nosso pai é ao bastardo Edmundo \ncomo ao legítimo: bela palavra — legítimo! \nPois bem, meu legítimo, se esta carta surtir efeito \ne minha invenção prosperar, Edmundo, o baixo, \nsuplantará o legítimo. Cresço; prospero: \nAgora, deuses, ponde-vos em pé pelos bastardos!","entergloucester~entergloucester~15":"Entra Gloucester.","gloucesterkentbanishdthusandfranceinchol~egadedmundhownowwhatnews~148":"Gloucester — Kent banido assim! E a França partida em cólera! \nE o rei partindo esta noite! Rendeu seu poder! \nConfinado a uma pensão! Tudo isto feito \nde arrebatamento! Edmundo, então! Que notícias?","edmundsopleaseyourlordshipnoneputtingupt~ipnoneputtinguptheletter~48":"Edmundo — Com a vossa licença, senhor, nenhuma. Guardando a carta.","gloucesterwhysoearnestlyseekyoutoputupth~seekyoutoputupthatletter~48":"Gloucester — Por que tão ansioso por guardar essa carta?","edmundiknownonewsmylord~edmundiknownonewsmylord~23":"Edmundo — Não sei de notícia, meu senhor.","gloucesterwhatpaperwereyoureading~rwhatpaperwereyoureading~33":"Gloucester — Que papel líeis?","edmundnothingmylord~edmundnothingmylord~19":"Edmundo — Nada, meu senhor.","gloucesternowhatneededthenthatterribledi~gishallnotneedspectacles~157":"Gloucester — Não? Que necessidade havia, então, daquele terrível despacho para o bolso? A qualidade do nada não tem tanta necessidade de se esconder. Vejamos: vamos, se não é nada, não precisarei de óculos.","edmundibeseechyousirpardonmeitisaletterf~tnotfitforyouroerlooking~130":"Edmundo — Suplico-vos, senhor, perdoai-me: é uma carta de meu irmão, que não li toda; e quanto ao que li, acho-a imprópria para vossa leitura.","gloucestergivemethelettersir~cestergivemethelettersir~28":"Gloucester — Dá-me a carta, senhor.","edmundishalloffendeithertodetainorgiveit~understandthemaretoblame~84":"Edmundo — Ofenderei, seja retendo-a, seja dando-a. O conteúdo, tanto quanto em parte o compreendo, é censurável.","gloucesterletsseeletssee~gloucesterletsseeletssee~24":"Gloucester — Vejamos, vejamos.","edmundihopeformybrothersjustificationhew~anessayortasteofmyvirtue~77":"Edmundo — Espero, em justificação de meu irmão, que ele a tenha escrito apenas como ensaio ou prova de minha virtude.","gloucesterreadsthispolicyandreverenceofa~elovedofyourbrotheredgar~363":"Gloucester — Lê. “Esta política e reverência da idade tornam o mundo amargo para a melhor fase de nossas vidas; privam-nos da fortuna até que nossa velhice não possa mais saboreá-la. Começo a achar uma servidão ociosa e tola na opressão da tirania dos velhos; que governa, não como tem poder, mas como é tolerada. Vem a mim, para que eu fale mais sobre isto. Se nosso pai dormisse até que eu o acordasse, gozarias de metade de sua renda para sempre, e viverias como o amado de teu irmão, Edgar.”","humconspiracysleeptilliwakedhimyoushould~amethistoyouwhobroughtit~144":"Hum — conspiração! — “Dormisse até que eu o acordasse — gozarias de metade de sua renda” — Meu filho Edgar! Teve ele mão para escrever isto? Coração e cérebro para o gerar? — Quando isto chegou a ti? Quem o trouxe?","edmunditwasnotbroughtmemylordtheresthecu~natthecasementofmycloset~88":"Edmundo — Não me foi trazido, meu senhor; aí está a astúcia; achei-o lançado pela janela do meu gabinete.","gloucesteryouknowthecharactertobeyourbro~haractertobeyourbrothers~45":"Gloucester — Reconheces a letra como sendo de teu irmão?","edmundifthematterweregoodmylordidurstswe~iwouldfainthinkitwerenot~93":"Edmundo — Se o assunto fosse bom, meu senhor, ousaria jurar que era dele; mas, em vista disso, preferiria pensar que não.","gloucesteritishis~gloucesteritishis~17":"Gloucester — É dele.","edmunditishishandmylordbutihopehishearti~sheartisnotinthecontents~57":"Edmundo — É a mão dele, meu senhor; mas espero que seu coração não esteja no conteúdo.","gloucesterhathheneverheretoforesoundedyo~soundedyouinthisbusiness~55":"Gloucester — Nunca antes te sondou nesse negócio?","edmundnevermylordbutihaveheardhimoftmain~ndthesonmanagehisrevenue~148":"Edmundo — Nunca, meu senhor: mas ouvi-o muitas vezes sustentar que convém que, estando os filhos em idade perfeita e os pais em declínio, o pai seja tutelado do filho, e o filho administre sua renda.","gloucesterovillainvillainhisveryopinioni~ominablevillainwhereishe~168":"Gloucester — Oh, vilão, vilão! Sua própria opinião na carta! Vilão abominável! Vilão desnaturado, detestado, brutal! Pior que brutal! Vai, rapaz, procura-o; prendê-lo-ei: vilão abominável! Onde está ele?","edmundidonotwellknowmylordifitshallpleas~ofurtherpretenceofdanger~389":"Edmundo — Não sei bem, meu senhor. Se for do vosso agrado suspender a indignação contra meu irmão até poderdes tirar dele melhor testemunho de sua intenção, seguireis rumo certo; ao passo que, se procederdes violentamente contra ele, errando seu propósito, abrireis grande brecha em vossa própria honra e despedaçareis o coração de sua obediência. Ouso empenhar minha vida por ele que escreveu isto para sondar minha afeição a vossa honra, e sem nenhum outro pretexto de perigo.","gloucesterthinkyouso~gloucesterthinkyouso~20":"Gloucester — Pensas assim?","edmundifyourhonourjudgeitmeetiwillplacey~delaythanthisveryevening~166":"Edmundo — Se vossa honra julgar conveniente, colocar-vos-ei onde nos ouvireis conferir sobre isto, e por uma certeza auricular tereis vossa satisfação; e isso sem outra demora que esta mesma tarde.","gloucesterhecannotbesuchamonster~erhecannotbesuchamonster~32":"Gloucester — Ele não pode ser tal monstro —","edmundnorisnotsure~edmundnorisnotsure~18":"Edmundo — Nem é, por certo.","gloucestertohisfatherthatsotenderlyanden~selftobeinadueresolution~178":"Gloucester — Para com seu pai, que tão terna e inteiramente o ama. Céu e terra! Edmundo, procura-o: insinua-te nele, peço-te: dispõe o negócio segundo tua sabedoria. Eu me despojaria de meu estado para ter uma devida certeza.","edmundiwillseekhimsirpresentlyconveytheb~eansandacquaintyouwithal~84":"Edmundo — Procurá-lo-ei, senhor, logo: conduzirei o negócio como achar meios e vos informarei.","gloucestertheselateeclipsesinthesunandmo~ncehonestytisstrangeexit~625":"Gloucester — Esses recentes eclipses no sol e na lua não pressagiam nada bom para nós: embora a sabedoria da natureza possa raciocinar assim e assado, contudo a natureza se vê flagelada pelos efeitos que se seguem: o amor esfria, a amizade decai, irmãos se dividem: nas cidades, motins; nos campos, discórdia; nos palácios, traição; e o laço partido entre filho e pai. Este meu vilão cai sob a predição; eis filho contra pai: o rei sai do pendor da natureza; eis pai contra filho. Vimos o melhor de nosso tempo: maquinações, falsidade, traição e todas as desordens ruinosas nos seguem inquietas até a sepultura. Procura este vilão, Edmundo; nada perderás; faze-o com cuidado. E o nobre e leal Kent banido! Sua ofensa, honestidade! É estranho. Sai.","edmundthisistheexcellentfopperyoftheworl~ledonmybastardizingedgar~640":"Edmundo — Esta é a excelente parvoíce do mundo: que, quando adoecemos em fortuna — muitas vezes a sobrecarga de nosso próprio comportamento — fazemos culpados de nossos desastres o sol, a lua e as estrelas: como se fôssemos vilões por necessidade; tolos por compulsão celeste; velhacos, ladrões e traidores por predominância esférica; bêbados, mentirosos e adúlteros por obediência forçada à influência planetária; e tudo em que somos maus, por um impulso divino: admirável evasiva do homem libertino, atribuir sua disposição de bode à conta de uma estrela! Meu pai se juntou a minha mãe sob a cauda do Dragão; e minha natividade foi sob a Ursa Maior; de modo que se segue que sou rude e lascivo. Bah, eu teria sido o que sou, ainda que a mais virginal estrela do firmamento cintilasse sobre minha bastardia. Edgar —","enteredgar~enteredgar~10":"Entra Edgar.","andpathecomeslikethecatastropheoftheoldc~dthesedivisionsfasollami~141":"E vem na hora certa, como a catástrofe da velha comédia: minha deixa é melancolia vilã, com um suspiro de Tom de Bedlam. Oh, esses eclipses pressagiam essas divisões! fá, sol, lá, mi.","edgarhownowbrotheredmundwhatseriousconte~ouscontemplationareyouin~56":"Edgar — Então, irmão Edmundo! Em que séria contemplação estás?","edmundiamthinkingbrotherofapredictionire~houldfollowtheseeclipses~83":"Edmundo — Penso, irmão, numa predição que li outro dia, sobre o que deve seguir-se a esses eclipses.","edgardoyoubusyyourselfaboutthat~youbusyyourselfaboutthat~31":"Edgar — Ocupas-te disso?","edmundipromiseyoutheeffectshewritesofsuc~lbreachesandiknownotwhat~282":"Edmundo — Prometo-te que os efeitos de que ele escreve sucedem infelizmente; como a desnaturalidade entre filho e pai; morte, carestia, dissoluções de amizades antigas; divisões no Estado, ameaças e maldições contra rei e nobres, desconfianças desnecessárias, banimento de amigos, dissipação de coortes, rupturas nupciais, e não sei o que mais.","edgarhowlonghaveyoubeenasectaryastronomi~beenasectaryastronomical~43":"Edgar — Há quanto tempo és sectário astronômico?","edmundcomecomewhensawyoumyfatherlast~mewhensawyoumyfatherlast~36":"Edmundo — Vamos, vamos; quando viste meu pai pela última vez?","edgarwhythenightgoneby~edgarwhythenightgoneby~22":"Edgar — Ora, a noite passada.","edmundspakeyouwithhim~edmundspakeyouwithhim~21":"Edmundo — Falaste com ele?","edgaraytwohourstogether~edgaraytwohourstogether~23":"Edgar — Sim, duas horas seguidas.","edmundpartedyouingoodtermsfoundyounodisp~inhimbywordorcountenance~71":"Edmundo — Separastes em bons termos? Não achaste desagrado nele por palavra ou semblante?","edgarnoneatall~edgarnoneatall~14":"Edgar — Nenhum.","edmundbethinkyourselfwhereinyoumayhaveof~rsonitwouldscarcelyallay~218":"Edmundo — Pensa em que o podes ter ofendido: e a meu pedido abstém-te de sua presença até que algum pouco de tempo abrande o calor de seu desagrado; que neste instante tanto se enraivece nele que nem com o dano de tua pessoa se aplacaria.","edgarsomevillainhathdonemewrong~mevillainhathdonemewrong~31":"Edgar — Algum vilão me fez injustiça.","edmundthatsmyfeariprayyouhaveacontinentf~ifyoudostirabroadgoarmed~201":"Edmundo — Esse é o meu temor. Peço-te, tem uma continente abstenção até que a rapidez de sua fúria diminua; e, como digo, retira-te comigo para meu alojamento, de onde te levarei no momento oportuno a ouvir meu senhor falar: peço-te, vai; eis a minha chave: se saíres, vai armado.","edgararmedbrother~edgararmedbrother~17":"Edgar — Armado, irmão!","edmundbrotheriadviseyoutothebestgoarmedi~andhorrorofitprayyouaway~172":"Edmundo — Irmão, aconselho-te o melhor; vai armado: não sou homem honesto se há alguma boa intenção para contigo: disse-te o que vi e ouvi; mas fracamente, nada como a imagem e o horror disso: peço-te, vai.","edgarshallihearfromyouanon~garshallihearfromyouanon~26":"Edgar — Terei notícias tuas logo?","edmundidoserveyouinthisbusinessexitedgar~uinthisbusinessexitedgar~40":"Edmundo — Sirvo-te neste negócio. Sai Edgar.","acredulousfatherandabrothernoblewhosenat~etthaticanfashionfitexit~204":"Um pai crédulo! E um irmão nobre, cuja natureza está tão longe de fazer mal que não suspeita de ninguém: em cuja tola honestidade minhas tramas cavalgam fáceis! Vejo o negócio. Que eu tenha, se não por nascimento, terras por engenho: tudo me serve que eu possa moldar apropriado. Sai.","sceneiii~sceneiii~8":"Cena III","thedukeofalbanyspalace~thedukeofalbanyspalace~22":"O palácio do Duque de Albany","entergonerilandoswaldhersteward~nerilandoswaldhersteward~31":"Entram Goneril e Oswald, seu mordomo.","gonerildidmyfatherstrikemygentlemanforch~lemanforchidingofhisfool~54":"Goneril — Meu pai bateu em meu fidalgo por repreender seu bobo?","oswaldyesmadam~oswaldyesmadam~14":"Oswald — Sim, senhora.","gonerilbydayandnighthewrongsmeeveryhourh~ellthefaultofitillanswer~278":"Goneril — De dia e de noite me ofende; cada hora \nrompe num ou noutro crime grosseiro \nque nos põe todos em desacordo: não o suportarei: \nseus cavaleiros tornam-se desordeiros, e ele mesmo nos censura \npor qualquer ninharia. Quando voltar da caça, \nnão falarei com ele; dizei que estou doente: \nse vos mostrardes frouxos nos antigos serviços, \nfareis bem; a culpa por isso responderei.","oswaldhescomingmadamihearhimhornswithin~madamihearhimhornswithin~39":"Oswald — Ele vem, senhora; ouço-o. Trompas dentro.","gonerilputonwhatwearynegligenceyouplease~usedrememberwhatitellyou~333":"Goneril — Assumi a negligência cansada que quiserdes, \nvós e vossos companheiros; quero que isso seja posto em questão: \nse ele não gostar, que vá à nossa irmã, \ncuja mente e a minha, sei, nisso são uma, \nnão para serem sobrepujadas. Velho ocioso, \nque ainda quer administrar aquelas autoridades \nque ele mesmo cedeu! Agora, por minha vida, \nvelhos tolos são crianças de novo; e devem ser tratados \ncom repreensões como adulações — quando se veem abusados. \nLembrai o que vos digo.","oswaldwellmadam~oswaldwellmadam~15":"Oswald — Pois bem, senhora.","gonerilandlethisknightshavecolderlooksam~sepreparefordinnerexeunt~203":"Goneril — E que seus cavaleiros tenham olhares mais frios entre vós; \no que dali resultar, não importa; avisai assim vossos companheiros: \nquero daqui gerar ocasiões, e gerarei, \npara poder falar: escreverei logo a minha irmã \npara seguir meu mesmo rumo. Preparai o jantar. Saem.","sceneiv~sceneiv~7":"Cena IV","ahallinthesame~ahallinthesame~14":"Um salão no mesmo palácio.","enterkentdisguised~enterkentdisguised~18":"Entra Kent, disfarçado.","kentifbutaswelliotheraccentsborrowthatca~allfindtheefulloflabours~243":"Kent — Se ao menos eu tomar emprestados outros sotaques \nque possam desfigurar minha fala, minha boa intenção \npoderá levar-se àquele pleno desfecho \npelo qual apaguei meu semblante. Agora, banido Kent, \nse podes servir onde estás condenado, \nassim possa suceder que teu senhor, a quem amas, \nte ache cheio de labores.","hornswithinenterkinglearknightsandattend~learknightsandattendants~44":"Trompas dentro. Entram o Rei Lear, Cavaleiros e Criados.","kinglearletmenotstayajotfordinnergogetit~etitreadyexitanattendant~60":"Rei Lear — Não me faças esperar um instante pelo jantar; vai prepará-lo. Sai um Criado.","hownowwhatartthou~hownowwhatartthou~17":"Então! Quem és tu?","kentamansir~kentamansir~11":"Kent — Um homem, senhor.","kinglearwhatdostthouprofesswhatwouldstth~esswhatwouldstthouwithus~48":"Rei Lear — Qual é tua profissão? Que queres de nós?","kentidoprofesstobenolessthaniseemtoserve~nnotchooseandtoeatnofish~181":"Kent — Professo ser não menos do que pareço; servir fielmente a quem me puser em confiança; amar a quem é honesto; conversar com quem é sábio e diz pouco; temer o juízo; lutar quando não posso escolher; e não comer peixe.","kinglearwhatartthou~kinglearwhatartthou~19":"Rei Lear — Quem és tu?","kentaveryhonestheartedfellowandaspoorast~fellowandaspoorastheking~46":"Kent — Um sujeito de coração muito honesto, e tão pobre quanto o rei.","kinglearifthoubeaspoorforasubjectasheisf~oorenoughwhatwouldstthou~79":"Rei Lear — Se és tão pobre como súdito quanto ele o é como rei, és pobre o bastante. Que queres?","kentservice~kentservice~11":"Kent — Serviço.","kinglearwhowouldstthouserve~glearwhowouldstthouserve~27":"Rei Lear — A quem queres servir?","kentyou~kentyou~7":"Kent — A vós.","kingleardostthouknowmefellow~leardostthouknowmefellow~28":"Rei Lear — Conheces-me, camarada?","kentnosirbutyouhavethatinyourcountenance~hichiwouldfaincallmaster~65":"Kent — Não, senhor; mas tendes no semblante algo que de bom grado chamaria amo.","kinglearwhatsthat~kinglearwhatsthat~17":"Rei Lear — O que é?","kentauthority~kentauthority~13":"Kent — Autoridade.","kinglearwhatservicescanstthoudo~rwhatservicescanstthoudo~31":"Rei Lear — Que serviços sabes fazer?","kenticankeephonestcounselriderunmaracuri~ndthebestofmeisdiligence~156":"Kent — Sei guardar honesto segredo, cavalgar, correr, estragar uma história engenhosa ao contá-la, e entregar um recado simples sem rodeios: aquilo para que os homens comuns servem, nisso sou qualificado; e o melhor de mim é a diligência.","kinglearhowoldartthou~kinglearhowoldartthou~21":"Rei Lear — Quantos anos tens?","kentnotsoyoungsirtoloveawomanforsingingn~eyearsonmybackfortyeight~97":"Kent — Não tão jovem, senhor, que ame uma mulher por cantar, nem tão velho que a idolatre por qualquer coisa: tenho quarenta e oito anos às costas.","kinglearfollowmethoushaltservemeifiliket~oolhitherexitanattendant~156":"Rei Lear — Segue-me; servir-me-ás: se não gostar menos de ti depois do jantar, ainda não me separarei de ti. Jantar, ei, jantar! Onde está meu velhaco? Meu bobo? Ide, e chamai aqui meu bobo. Sai um Criado.","enteroswald~enteroswald~11":"Entra Oswald.","youyousirrahwheresmydaughter~ousirrahwheresmydaughter~28":"Tu, tu, rapaz, onde está minha filha?","oswaldsopleaseyouexit~oswaldsopleaseyouexit~21":"Oswald — Com a vossa licença — Sai.","kinglearwhatsaysthefellowtherecalltheclo~eclotpollbackexitaknight~60":"Rei Lear — Que diz o sujeito? Chamai de volta o paspalho. Sai um Cavaleiro.","wheresmyfoolhoithinktheworldsasleep~lhoithinktheworldsasleep~35":"Onde está meu bobo, ei? Creio que o mundo dorme.","reenterknight~reenterknight~13":"Reentra o Cavaleiro.","hownowwheresthatmongrel~hownowwheresthatmongrel~23":"Então! Onde está aquele vira-lata?","knighthesaysmylordyourdaughterisnotwell~ordyourdaughterisnotwell~39":"Cavaleiro — Diz, meu senhor, que vossa filha não está bem.","kinglearwhycamenottheslavebacktomewhenic~vebacktomewhenicalledhim~48":"Rei Lear — Por que não voltou o escravo quando o chamei?","knightsirheansweredmeintheroundestmanner~roundestmannerhewouldnot~50":"Cavaleiro — Senhor, respondeu-me da maneira mais redonda que não queria.","kinglearhewouldnot~kinglearhewouldnot~18":"Rei Lear — Não queria!","knightmylordiknownotwhatthematterisbutto~mselfalsoandyourdaughter~222":"Cavaleiro — Meu senhor, não sei qual é o caso; mas, a meu juízo, vossa alteza não é recebida com aquele afeto cerimonioso a que estáveis acostumado; há grande diminuição de bondade que aparece tanto nos dependentes em geral quanto no próprio duque e em vossa filha.","kinglearhasayestthouso~kinglearhasayestthouso~22":"Rei Lear — Ha! Dizes assim?","knightibeseechyoupardonmemylordifibemist~thinkyourhighnesswronged~96":"Cavaleiro — Rogo-vos, perdoai-me, meu senhor, se me engano; pois meu dever não pode calar quando penso que vossa alteza é ofendida.","kinglearthoubutrememberestmeofmineowncon~avenotseenhimthistwodays~234":"Rei Lear — Apenas me lembras da minha própria concepção: percebi um desprezo muito leve de uns tempos para cá; que antes censurei como minha própria curiosidade ciumenta do que como verdadeiro pretexto e propósito de desamor: olharei mais a fundo. Mas onde está meu bobo? Não o vejo há dois dias.","knightsincemyyoungladysgoingintofrancesi~thefoolhathmuchpinedaway~65":"Cavaleiro — Desde a partida de minha jovem senhora para a França, senhor, o bobo definhou muito.","kinglearnomoreofthatihavenoteditwellgoyo~hermyfoolexitanattendant~127":"Rei Lear — Basta disso; notei-o bem. Ide, e dizei a minha filha que quero falar com ela. Sai um Criado. Ide, chamai aqui meu bobo. Sai um Criado.","reenteroswald~reenteroswald~13":"Reentra Oswald.","oyousiryoucomeyouhithersirwhoamisir~omeyouhithersirwhoamisir~35":"Oh, senhor, vós, vinde cá, senhor: quem sou eu, senhor?","oswaldmyladysfather~oswaldmyladysfather~19":"Oswald — O pai de minha senhora.","kinglearmyladysfathermylordsknaveyourwho~horesondogyouslaveyoucur~62":"Rei Lear — “O pai de minha senhora”! O velhaco de meu senhor: teu cão de filho de uma puta! Escravo! Cão vadio!","oswaldiamnoneofthesemylordibeseechyourpa~mylordibeseechyourpardon~44":"Oswald — Não sou nada disso, meu senhor; rogo vosso perdão.","kingleardoyoubandylookswithmeyourascalst~thmeyourascalstrikinghim~49":"Rei Lear — Trocas olhares comigo, tratante? Batendo-lhe.","oswaldillnotbestruckmylord~waldillnotbestruckmylord~26":"Oswald — Não serei esbofeteado, meu senhor.","kentnortrippedneitheryoubasefootballplay~playertrippinguphisheels~60":"Kent — Nem derrubado tampouco, vil jogador de bola. Passando-lhe uma rasteira.","kinglearithanktheefellowthouservestmeand~uservestmeandilllovethee~51":"Rei Lear — Agradeço-te, camarada; serves-me, e te estimarei.","kentcomesirariseawayillteachyoudifferenc~uwisdomsopushesoswaldout~134":"Kent — Vamos, senhor, levantai, fora! Ensinarei as diferenças: fora, fora! Se quereis medir de novo vosso comprimento de paspalhão, ficai: mas fora! Ide; tendes juízo? Assim. Empurra Oswald para fora.","kinglearnowmyfriendlyknaveithanktheether~hyservicegivingkentmoney~76":"Rei Lear — Agora, meu amigável velhaco, agradeço-te: eis sinal de teu serviço. Dando dinheiro a Kent.","enterfool~enterfool~9":"Entra o Bobo.","foolletmehirehimtooheresmycoxcombofferin~oxcombofferingkenthiscap~51":"Bobo — Deixa-me contratá-lo também: eis meu barrete de bobo. Oferecendo seu gorro a Kent.","kinglearhownowmyprettyknavehowdostthou~myprettyknavehowdostthou~38":"Rei Lear — Então, meu belo velhaco! Como vais?","foolsirrahyouwerebesttakemycoxcomb~youwerebesttakemycoxcomb~34":"Bobo — Rapaz, farias bem em tomar meu barrete de bobo.","kentwhyfool~kentwhyfool~11":"Kent — Por quê, bobo?","foolwhyfortakingonespartthatsoutoffavour~ocoxcombsandtwodaughters~279":"Bobo — Ora, por tomares o partido de quem está fora de favor: não, se não sabes sorrir conforme o vento sopra, logo apanharás um resfriado: toma, pega meu barrete: ora, este sujeito baniu duas de suas filhas, e deu à terceira uma bênção contra a vontade; se o seguires, tens de usar meu barrete de bobo. Então, tio! Quisera ter dois barretes e duas filhas!","kinglearwhymyboy~kinglearwhymyboy~16":"Rei Lear — Por quê, meu rapaz?","foolifigavethemallmylivingildkeepmycoxco~beganotherofthydaughters~83":"Bobo — Se eu lhes desse todo o meu sustento, guardaria os barretes para mim. Eis o meu; pede outro às tuas filhas.","kingleartakeheedsirrahthewhip~eartakeheedsirrahthewhip~29":"Rei Lear — Cuidado, rapaz; o chicote.","fooltruthsadogmusttokennelhemustbewhippe~aystandbythefireandstink~85":"Bobo — A verdade é um cão que tem de ir para o canil; tem de ser chicoteada para fora, enquanto Madame a cadela pode ficar junto ao fogo a feder.","kinglearapestilentgalltome~nglearapestilentgalltome~26":"Rei Lear — Fel pestilento para mim!","foolsirrahillteachtheeaspeech~irrahillteachtheeaspeech~29":"Bobo — Rapaz, ensinar-te-ei um discurso.","kingleardo~kingleardo~10":"Rei Lear — Ensina.","foolmarkitnunclehavemorethanthoushowests~emorethantwotenstoascore~229":"Bobo — Nota, tio: \nTem mais do que mostras, \nFala menos do que sabes, \nEmpresta menos do que deves, \nCavalga mais do que andas, \nAprende mais do que crês, \nAposta menos do que lanças; \nLarga a bebida e a puta, \nE fica em casa de porta fechada, \nE terás mais \nDo que duas dezenas por vintena.","kentthisisnothingfool~kentthisisnothingfool~21":"Kent — Isto é nada, bobo.","foolthentislikethebreathofanunfeedlawyer~makenouseofnothingnuncle~90":"Bobo — Então é como o fôlego de um advogado sem honorários; nada me deste por isso. Não podes fazer uso do nada, tio?","kinglearwhynoboynothingcanbemadeoutofnot~ingcanbemadeoutofnothing~44":"Rei Lear — Ora, não, rapaz; nada pode ser feito do nada.","fooltokentpritheetellhimsomuchtherentofh~stohewillnotbelieveafool~74":"Bobo — A Kent. Peço-te, dize-lhe que a renda de suas terras chega a isso: ele não acredita num bobo.","kinglearabitterfool~kinglearabitterfool~19":"Rei Lear — Um bobo amargo!","fooldostthouknowthedifferencemyboybetwee~abitterfoolandasweetfool~65":"Bobo — Sabes a diferença, meu rapaz, entre um bobo amargo e um bobo doce?","kinglearnoladteachme~kinglearnoladteachme~20":"Rei Lear — Não, rapaz; ensina-me.","foolthatlordthatcounselldtheetogiveawayt~eretheotherfoundoutthere~162":"Bobo — O senhor que te aconselhou \nA dar tua terra embora, \nTraze-o a postar-se aqui comigo, \nTu por ele fica agora: \nO bobo doce e o amargo \nLogo aparecerão; \nUm aqui de malhado, \nOutro ali, no chão.","kingleardostthoucallmefoolboy~eardostthoucallmefoolboy~29":"Rei Lear — Chamas-me de bobo, rapaz?","foolallthyothertitlesthouhastgivenawayth~awaythatthouwastbornwith~58":"Bobo — Todos os teus outros títulos deste embora; esse, trouxeste de nascença.","kentthisisnotaltogetherfoolmylord~snotaltogetherfoolmylord~33":"Kent — Isto não é de todo bobo, meu senhor.","foolnofaithlordsandgreatmenwillnotletmei~eandillgivetheetwocrowns~181":"Bobo — Não, na verdade, senhores e grandes homens não me deixam; se eu tivesse um monopólio, quereriam parte nele: e as damas também, não me deixam ter todo o bobo para mim; hão de arrebatar. Dá-me um ovo, tio, e dar-te-ei duas coroas.","kinglearwhattwocrownsshalltheybe~whattwocrownsshalltheybe~32":"Rei Lear — Que duas coroas serão elas?","foolwhyafterihavecuttheeggithemiddleande~hippedthatfirstfindsitso~280":"Bobo — Ora, depois de cortar o ovo ao meio e comer o miolo, as duas coroas do ovo. Quando partiste tua coroa ao meio e deste ambas as partes, carregaste teu asno nas costas por cima da lama: tinhas pouco juízo na tua coroa calva quando deste embora a de ouro. Se falo como eu mesmo nisto, que seja chicoteado quem primeiro achar assim.","singingfoolshadneerlesswitinayearforwise~artheirmannersaresoapish~109":"Cantando. Nunca bobos tiveram menos juízo num ano; \nPois os sábios se fizeram tolos, \nNão sabem como usar o seu engenho, \nTão macacos são seus modos.","kinglearwhenwereyouwonttobesofullofsongs~ttobesofullofsongssirrah~46":"Rei Lear — Desde quando és tão cheio de canções, rapaz?","foolihaveuseditnuncleeversincethoumadest~utstdownthineownbreeches~117":"Bobo — Tenho-o costume, tio, desde que fizeste de tuas filhas tuas mães: pois quando lhes deste a vara, e baixaste tuas próprias calças,","singingthentheyforsuddenjoydidweepandifo~bopeepandgothefoolsamong~98":"Cantando. Elas, de súbita alegria, choraram, \nE eu, de tristeza, cantei, \nQue tal rei brincasse de esconde-esconde, \nE fosse entre os bobos andar.","pritheenunclekeepaschoolmasterthatcantea~olieiwouldfainlearntolie~74":"Peço-te, tio, mantém um mestre-escola que ensine teu bobo a mentir: bem quisera aprender a mentir.","kinglearanyouliesirrahwellhaveyouwhipped~sirrahwellhaveyouwhipped~40":"Rei Lear — Se mentires, rapaz, mandar-te-emos chicotear.","foolimarvelwhatkinthouandthydaughtersare~eherecomesoneotheparings~277":"Bobo — Admiro-me de que parentesco tens com tuas filhas: elas me mandarão chicotear por falar a verdade, tu me mandarás chicotear por mentir; e às vezes sou chicoteado por calar. Preferiria ser qualquer outra coisa a bobo: contudo não quereria ser tu, tio; aparaste teu juízo dos dois lados e nada deixaste no meio: eis aqui uma das aparas.","entergoneril~entergoneril~12":"Entra Goneril.","kinglearhownowdaughterwhatmakesthatfront~retoomuchoflateithefrown~81":"Rei Lear — Então, filha! Que faz essa testeira posta? Parece-me que ultimamente andas demais de cenho franzido.","foolthouwastaprettyfellowwhenthouhadstno~idsmethoughyousaynothing~208":"Bobo — Eras um belo sujeito quando não tinhas necessidade de te importar com o franzir dela; agora és um zero sem algarismo: sou melhor que tu agora; sou um bobo, tu és nada. A Goneril. Sim, na verdade, calarei a língua; assim o manda vosso rosto, embora nada digais.","mummumhethatkeepsnorcrustnorcrumwearyofa~mwearyofallshallwantsome~55":"Cala, cala, Quem não guarda côdea nem migalha, \nCansado de tudo, de algo vai precisar.","pointingtokinglearthatsashealedpeascod~learthatsashealedpeascod~38":"Apontando para o Rei Lear. Eis uma vagem de ervilha debulhada.","gonerilnotonlysirthisyouralllicensedfool~llcalldiscreetproceeding~492":"Goneril — Não só, senhor, este vosso bobo de licença total, \nmas outros de vossa insolente comitiva \nbrigam e ralham a toda hora; irrompendo \nem desordens grosseiras e insuportáveis. Senhor, \npensara eu, ao tornar isto bem conhecido de vós, \nachar um remédio seguro; mas agora me assusto, \npelo que vós mesmo, tarde demais, falastes e fizestes, \nde que protegeis este rumo e o incitais \npor vossa aprovação; o que, se o fizerdes, a falta \nnão escapará à censura, nem os remédios dormirão, \nque, em prol de um bem-estar sadio, \npoderiam em sua ação causar-vos aquela ofensa \nque de outro modo seria vergonha, mas que então a necessidade \nchamará proceder discreto.","foolforyoutrownunclethehedgesparrowfedth~dleandwewereleftdarkling~123":"Bobo — Pois, tu sabes, tio, \nO pardal da sebe alimentou o cuco tanto tempo \nQue teve a cabeça arrancada a bicadas pelo filhote. \nAssim, apagou-se a vela, e ficamos às escuras.","kinglearareyouourdaughter~inglearareyouourdaughter~25":"Rei Lear — Sois nossa filha?","gonerilcomesiriwouldyouwouldmakeuseoftha~youfromwhatyourightlyare~146":"Goneril — Vamos, senhor, \nquisera que fizesseis uso daquela boa sabedoria \nde que sei estardes provido; e deixásseis de lado \nestes humores que ultimamente vos transformam \nno que não sois de direito.","foolmaynotanassknowwhenthecartdrawstheho~hehorsewhoopjugilovethee~60":"Bobo — Não pode um asno saber quando a carroça puxa o cavalo? Eia, Joana! Amo-te.","kingleardothanyhereknowmethisisnotleardo~oisitthatcantellmewhoiam~169":"Rei Lear — Alguém aqui me conhece? Este não é Lear: \nanda Lear assim? Fala assim? Onde estão seus olhos? \nOu seu entendimento enfraquece, ou seus discernimentos \nestão letárgicos — Ha! Desperto? Não é assim. \nQuem é que me pode dizer quem sou?","foollearsshadow~foollearsshadow~15":"Bobo — A sombra de Lear.","kingleariwouldlearnthatforbythemarksofso~sepersuadedihaddaughters~103":"Rei Lear — Quero saber isso; pois, pelas marcas de soberania, conhecimento e razão, eu seria falsamente persuadido de que tinha filhas.","foolwhichtheywillmakeanobedientfather~willmakeanobedientfather~37":"Bobo — Que farão de ti um pai obediente.","kinglearyournamefairgentlewoman~ryournamefairgentlewoman~31":"Rei Lear — Vosso nome, bela dama?","gonerilthisadmirationsirismuchothesavour~eandknowthemselvesandyou~534":"Goneril — Esta admiração, senhor, tem muito do sabor \ndas outras vossas novas travessuras. Rogo-vos \nque entendais meus propósitos com acerto: \ncomo sois velho e reverendo, deveríeis ser sábio. \nAqui mantendes cem cavaleiros e escudeiros; \nhomens tão desordenados, tão devassos e ousados, \nque esta nossa corte, infectada por seus modos, \nparece uma estalagem de desordem: epicurismo e luxúria \nfazem-na mais semelhante a uma taverna ou a um bordel \ndo que a um palácio decoroso. A própria vergonha clama \npor remédio imediato: sede então rogado \npor aquela que, do contrário, tomará o que implora, \na diminuir um pouco vossa comitiva; \ne o remanescente, que ainda dependerá de vós, \nseja de homens que convenham à vossa idade, \ne conheçam a si mesmos e a vós.","kingleardarknessanddevilssaddlemyhorsesc~heeyethaveileftadaughter~113":"Rei Lear — Trevas e demônios! \nSelai meus cavalos; reuni minha comitiva: \nbastarda degenerada! Não te incomodarei. \nAinda me resta uma filha.","gonerilyoustrikemypeopleandyourdisorderd~keservantsoftheirbetters~72":"Goneril — Batéis em minha gente; e vossa turba desordenada \nfaz de servos seus superiores.","enteralbany~enteralbany~11":"Entra Albany.","kinglearwoethattoolaterepentstoalbanyosi~nachildthantheseamonster~173":"Rei Lear — Ai, que tarde se arrepende — \nA Albany. Oh, senhor, viestes? \nÉ vossa vontade? Falai, senhor. Preparai meus cavalos. \nIngratidão, demônio de coração de mármore, \nmais hedionda quando te mostras num filho \ndo que o monstro marinho!","albanypraysirbepatient~albanypraysirbepatient~22":"Albany — Rogo-vos, senhor, tende paciência.","kingleartogonerildetestedkitethouliestmy~rjudgmentoutgogomypeople~381":"Rei Lear — A Goneril. Detestável abutre! Mentes. \nMeu séquito é de homens escolhidos e de raras qualidades, \nque conhecem todas as minúcias do dever, \ne com o mais exato zelo sustentam \na honra do seu nome. Ó pequeníssima falta, \nque feia te mostraste em Cordélia! \nQual máquina, arrancaste o arcabouço da minha natureza \nde seu lugar fixo; tiraste do coração todo o amor \ne acrescentaste ao fel. Ó Lear, Lear, Lear! \nBate neste portão, que deixou entrar tua loucura, Batendo na cabeça. \ne sair teu caro juízo! Ide, ide, meu povo.","albanymylordiamguiltlessasiamignorantofw~norantofwhathathmovedyou~55":"Albany — Meu senhor, sou inocente, como ignoro \no que vos comoveu.","kinglearitmaybesomylordhearnatureheardea~anklesschildawayawayexit~503":"Rei Lear — Pode ser, meu senhor. \nOuve, natureza, ouve; cara deusa, ouve! \nSuspende teu propósito, se pretendias \ntornar esta criatura fecunda! \nNo ventre dela introduz esterilidade! \nSeca nela os órgãos da geração; \ne de seu corpo degenerado jamais brote \num filho para honrá-la! Se tiver de gerar, \ncria-lhe um filho de despeito; que ele viva \ne seja para ela tormento perverso e desnaturado! \nQue lhe estampe rugas na fronte juvenil; \ncom lágrimas cadentes cave sulcos nas faces; \nvolte todas as dores e benefícios de mãe \nem riso e desprezo; para que ela sinta \nquanto é mais agudo que o dente de serpente \nter um filho ingrato! Fora, fora! Sai.","albanynowgodsthatweadorewhereofcomesthis~tweadorewhereofcomesthis~40":"Albany — Agora, deuses que adoramos, de onde vem isto?","gonerilneverafflictyourselftoknowthecaus~atscopethatdotagegivesit~91":"Goneril — Nunca vos aflijais por saber a causa; \nmas deixai que seu humor tenha o campo \nque a caduquice lhe dá.","reenterkinglear~reenterkinglear~15":"Reentra o Rei Lear.","kinglearwhatfiftyofmyfollowersataclapwit~sataclapwithinafortnight~53":"Rei Lear — Como, cinquenta dos meus seguidores de um golpe! \nDentro de quinze dias!","albanywhatsthemattersir~albanywhatsthemattersir~23":"Albany — Que há, senhor?","kinglearilltelltheetogonerillifeanddeath~inglearkentandattendants~585":"Rei Lear — Dir-te-ei: A Goneril. \nVida e morte! Tenho vergonha \nde que tenhas poder para abalar assim minha virilidade; \nde que estas lágrimas ardentes, que me rompem à força, \nte façam digna delas. Tempestades e brumas sobre ti! \nAs feridas sem cura da maldição de um pai \npenetrem todos os teus sentidos! Velhos olhos tolos, \nse chorardes de novo por esta causa, eu vos arranco \ne vos lanço, com as águas que perdeis, \npara amassar barro. Sim, chegou a isso? \nSeja assim: contudo me resta uma filha \nque, estou certo, é bondosa e consoladora: \nquando ouvir isto de ti, com as unhas \nlhe esfolará teu rosto de lobo. Verás \nque retomarei a forma que pensas \nter eu deixado para sempre: verás, \ngaranto-te. Saem o Rei Lear, Kent e Criados.","gonerildoyoumarkthatmylord~nerildoyoumarkthatmylord~26":"Goneril — Notais isso, meu senhor?","albanyicannotbesopartialgoneriltothegrea~iltothegreatloveibearyou~53":"Albany — Não posso ser tão parcial, Goneril, \ncom o grande amor que vos tenho —","gonerilprayyoucontentwhatoswaldhotothefo~ethanfoolafteryourmaster~80":"Goneril — Rogo-vos, contentai-vos. Como, Oswald, ei! Ao Bobo. Vós, senhor, mais velhaco que bobo, ide atrás de vosso amo.","foolnunclelearnuncleleartarryandtakethef~othefoolfollowsafterexit~161":"Bobo — Tio Lear, tio Lear, espera e leva o bobo \ncontigo. \nUma raposa, quando se prende, \ne uma filha dessas, \nIriam à forca, sem demora, \nSe meu gorro comprasse uma corda: \nAssim o bobo vai embora. Sai.","gonerilthismanhathhadgoodcounselahundred~urlivesinmercyoswaldisay~222":"Goneril — Este homem teve bom conselho: cem cavaleiros! \nÉ político e seguro deixá-lo manter \npronto uma centena de cavaleiros: sim, para que, a cada sonho, \na cada zumbido, a cada fantasia, queixa, desgosto, \nele possa guardar sua caduquice com o poder deles, \ne ter nossas vidas à sua mercê. Oswald, digo!","albanywellyoumayfeartoofar~banywellyoumayfeartoofar~26":"Albany — Bem, podeis temer demais.","gonerilsaferthantrusttoofarletmestilltak~enihaveshowdtheunfitness~186":"Goneril — Mais seguro que confiar demais: \nlevem-me sempre a afastar os males que temo, \nnão a temer sempre ser tomada por eles: conheço-lhe o coração. \nO que ele proferiu escrevi à minha irmã; \nse ela o sustentar a ele e a seus cem cavaleiros, \nquando eu tiver mostrado a inconveniência —","hownowoswaldwhathaveyouwritthatlettertom~writthatlettertomysister~47":"Então, Oswald! \nComo, escrevestes aquela carta à minha irmã?","goneriltakeyousomecompanyandawaytohorsei~stenyourreturnexitoswald~160":"Goneril — Tomai alguma companhia, e a cavalo: \ninformai-a plenamente do meu temor particular; \ne a isso acrescentai razões vossas \nque o tornem mais sólido. Ide-vos; \ne apressai o regresso. Sai Oswald.","nonomylordthismilkygentlenessandcourseof~raisedforharmfulmildness~141":"Não, não, meu senhor, \nesta vossa doçura leitosa e vosso proceder, \nembora não os condene, contudo, com perdão, \nmuito mais sois censurado por falta de sabedoria \ndo que louvado por brandura danosa.","albanyhowfaryoureyesmaypierceicannottell~obetteroftwemarwhatswell~73":"Albany — Até onde vossos olhos podem penetrar não sei dizer: \nao querer melhorar, muitas vezes estragamos o que está bem.","gonerilnaythen~gonerilnaythen~14":"Goneril — Não, então —","albanywellwelltheeventexeunt~nywellwelltheeventexeunt~28":"Albany — Bem, bem; veremos o desfecho. Saem.","scenev~scenev~6":"Cena V","courtbeforethesame~courtbeforethesame~18":"Pátio diante do mesmo palácio.","enterkinglearkentandfool~enterkinglearkentandfool~24":"Entram o Rei Lear, Kent e o Bobo.","kingleargoyoubeforetogloucesterwiththese~edyishallbethereaforeyou~176":"Rei Lear — Ide à frente a Gloucester com estas cartas. \nNão informeis minha filha de nada do que sabeis \nalém do que ela perguntar com base na carta. \nSe vossa diligência não for rápida, estarei lá antes de vós.","kentiwillnotsleepmylordtillihavedelivere~edeliveredyourletterexit~55":"Kent — Não dormirei, meu senhor, até entregar vossa carta. Sai.","foolifamansbrainswereinsheelsweretnotind~sweretnotindangerofkibes~52":"Bobo — Se os miolos de um homem estivessem nos calcanhares, não correriam perigo de frieiras?","kinglearayboy~kinglearayboy~13":"Rei Lear — Sim, rapaz.","foolthenipritheebemerrythywitshallneergo~hywitshallneergoslipshod~48":"Bobo — Então, peço-te, alegra-te; teu juízo nunca andará de chinelo arrastado.","kinglearhahaha~kinglearhahaha~14":"Rei Lear — Ha, ha, ha!","foolshaltseethyotherdaughterwillusetheek~eyeticantellwhaticantell~110":"Bobo — Verás que tua outra filha te tratará com bondade; pois, embora se pareça com esta como uma maçã silvestre com uma maçã, sei o que sei.","kinglearwhywhatcanstthoutellmyboy~hywhatcanstthoutellmyboy~33":"Rei Lear — Ora, que sabes dizer, meu rapaz?","foolshewilltasteaslikethisasacrabdoestoa~estandsithemiddleonsface~91":"Bobo — Terá gosto tão parecido com esta como uma maçã azeda com outra maçã azeda. Sabes dizer por que o nariz fica no meio do rosto?","kinglearno~kinglearno~10":"Rei Lear — Não.","foolwhytokeeponeseyesofeithersidesnoseth~nnotsmellouthemayspyinto~76":"Bobo — Ora, para guardar os olhos de cada lado do nariz; para que o que um homem não pode farejar, possa espiar.","kinglearididherwrong~kinglearididherwrong~20":"Rei Lear — Fiz-lhe injustiça —","foolcansttellhowanoystermakeshisshell~howanoystermakeshisshell~37":"Bobo — Sabes dizer como a ostra faz a concha?","foolnorineitherbuticantellwhyasnailhasah~antellwhyasnailhasahouse~44":"Bobo — Nem eu; mas sei dizer por que o caracol tem casa.","kinglearwhy~kinglearwhy~11":"Rei Lear — Por quê?","foolwhytoputhisheadinnottogiveitawaytohi~eavehishornswithoutacase~78":"Bobo — Ora, para meter a cabeça dentro; não para dá-la às filhas e deixar os chifres sem estojo.","kingleariwillforgetmynaturesokindafather~ndafatherbemyhorsesready~55":"Rei Lear — Esquecerei minha natureza. Pai tão bondoso! Estão prontos os meus cavalos?","foolthyassesaregoneaboutemthereasonwhyth~thansevenisaprettyreason~84":"Bobo — Teus asnos foram buscá-los. A razão por que as sete estrelas não são mais que sete é uma bela razão.","kinglearbecausetheyarenoteight~arbecausetheyarenoteight~30":"Rei Lear — Porque não são oito?","foolyesindeedthouwouldstmakeagoodfool~thouwouldstmakeagoodfool~37":"Bobo — Sim, de fato: darias um bom bobo.","kingleartotaketagainperforcemonsteringra~rforcemonsteringratitude~46":"Rei Lear — Tomá-lo de volta à força! Monstro da ingratidão!","foolifthouwertmyfoolnuncleildhavetheebea~forbeingoldbeforethytime~67":"Bobo — Se fosses meu bobo, tio, mandaria te surrar por envelheceres antes do tempo.","kinglearhowsthat~kinglearhowsthat~16":"Rei Lear — Como assim?","foolthoushouldstnothavebeenoldtillthouha~oldtillthouhadstbeenwise~51":"Bobo — Não devias ter ficado velho antes de ficar sábio.","kinglearoletmenotbemadnotmadsweetheavenk~meintemperiwouldnotbemad~67":"Rei Lear — Oh, não me deixes enlouquecer, enlouquecer não, doce céu! \nMantém-me em meu juízo: não quero enlouquecer!","entergentleman~entergentleman~14":"Entra um Fidalgo.","hownowarethehorsesready~hownowarethehorsesready~23":"Então! Estão prontos os cavalos?","gentlemanreadymylord~gentlemanreadymylord~20":"Fidalgo — Prontos, meu senhor.","kinglearcomeboy~kinglearcomeboy~15":"Rei Lear — Vem, rapaz.","foolshethatsamaidnowandlaughsatmydepartu~thingsbecutshorterexeunt~91":"Bobo — Aquela que agora é donzela e ri de minha partida \nnão será donzela por muito tempo, a menos que as coisas sejam encurtadas. Saem.","gloucesterscastle~gloucesterscastle~17":"O castelo de Gloucester.","enteredmundandcuranmeetshim~eredmundandcuranmeetshim~27":"Entra Edmundo, e Curan o encontra.","edmundsavetheecuran~edmundsavetheecuran~19":"Edmundo — Deus te guarde, Curan.","curanandyousirihavebeenwithyourfatherand~llbeherewithhimthisnight~119":"Curan — E a vós, senhor. Estive com vosso pai e avisei-o de que o Duque de Cornualha e Regana, sua duquesa, estarão aqui com ele esta noite.","edmundhowcomesthat~edmundhowcomesthat~18":"Edmundo — Como é isso?","curannayiknownotyouhaveheardofthenewsabr~etbutearkissingarguments~99":"Curan — Não sei. Ouvistes as notícias de fora; digo, as cochichadas, pois são ainda apenas assuntos de beijar o ouvido?","edmundnotiprayyouwhatarethey~ndnotiprayyouwhatarethey~28":"Edmundo — Eu não: peço-vos, quais são?","curanhaveyouheardofnolikelywarstowardtwi~dukesofcornwallandalbany~69":"Curan — Não ouvistes de nenhuma guerra provável entre os Duques de Cornualha e de Albany?","edmundnotaword~edmundnotaword~14":"Edmundo — Nem uma palavra.","curanyoumaydothenintimefareyouwellsirexi~intimefareyouwellsirexit~41":"Curan — Ouvireis, então, a seu tempo. Passai bem, senhor. Sai.","edmundthedukebeheretonightthebetterbestt~raworddescendbrotherisay~211":"Edmundo — O duque aqui esta noite? Melhor! Ótimo! \nIsto se tece à força em meu negócio. \nMeu pai pôs guarda para prender meu irmão; \ne tenho uma coisa, de questão enjoativa, \nque devo executar: rapidez e fortuna, obrai! \nIrmão, uma palavra; desce: irmão, digo!","myfatherwatchesosirflythisplaceintellige~keofalbanyadviseyourself~255":"Meu pai vigia: oh, senhor, foge deste lugar; \ndeu-se aviso de onde estás escondido; \ntens agora a boa vantagem da noite: \nnão falaste contra o Duque de Cornualha? \nEle vem para cá: agora, de noite, com pressa, \ne Regana com ele: nada disseste \nem favor dele contra o Duque de Albany? \nPensa bem.","edgariamsureontnotaword~edgariamsureontnotaword~23":"Edgar — Disso estou certo, nem uma palavra.","edmundihearmyfathercomingpardonmeincunni~therfatherstopstopnohelp~315":"Edmundo — Ouço meu pai vindo: perdoa-me: \npor astúcia devo desembainhar a espada contra ti. \nSaca; finge defender-te; agora te portes bem. \nRende-te: vem diante de meu pai. Luz, ei, aqui! \nFoge, irmão. Tochas, tochas! Assim, adeus. Sai Edgar. \nAlgum sangue tirado de mim geraria a opinião \nde meu mais feroz empenho: vi bêbados \nfazer mais que isto por brincadeira. Pai, pai! \nParai, parai! Nenhum socorro? Fere o próprio braço.","entergloucesterandservantswithtorches~erandservantswithtorches~37":"Entram Gloucester e Criados com tochas.","gloucesternowedmundwheresthevillain~owedmundwheresthevillain~35":"Gloucester — Então, Edmundo, onde está o vilão?","edmundherestoodheinthedarkhissharpswordo~ostandauspiciousmistress~105":"Edmundo — Aqui estava ele no escuro, de espada afiada em punho, \nmurmurando encantos perversos, conjurando a lua \npara que fosse senhora propícia —","gloucesterbutwhereishe~gloucesterbutwhereishe~22":"Gloucester — Mas onde está ele?","edmundlooksiribleed~edmundlooksiribleed~19":"Edmundo — Vede, senhor, sangro.","gloucesterwhereisthevillainedmund~rwhereisthevillainedmund~33":"Gloucester — Onde está o vilão, Edmundo?","edmundfledthiswaysirwhenbynomeanshecould~ysirwhenbynomeanshecould~40":"Edmundo — Fugiu por aqui, senhor. Quando de modo nenhum pôde —","gloucesterpursuehimhogoafterexeuntsomese~omeservantsbynomeanswhat~59":"Gloucester — Persegui-o, ei! Ide atrás. Saem alguns Criados. De modo nenhum o quê?","edmundpersuademetothemurderofyourlordshi~eimadefullsuddenlyhefled~428":"Edmundo — Persuadir-me ao assassínio de vossa senhoria; \nmas eu lhe disse que os deuses vingadores \ncontra parricidas dirigiam todos os seus trovões; \nfalei com quão múltiplo e forte laço \no filho está ligado ao pai; senhor, enfim, \nvendo quão odiosamente me opunha \nao seu propósito desnaturado, em movimento cruel, \ncom a espada preparada, investe a fundo \ncontra meu corpo desprevenido, e feriu-me o braço: \nmas quando viu meus melhores espíritos alarmados, \nousados no direito da querela, despertos para o embate, \nou fosse assustado pelo barulho que fiz, \nmuito de súbito fugiu.","gloucesterlethimflyfarnotinthislandshall~kehethatconcealshimdeath~252":"Gloucester — Que fuja longe: \nnesta terra não ficará sem ser apanhado; \ne achado — despachado. O nobre duque, meu senhor, \nmeu digno chefe e protetor, chega esta noite: \npor sua autoridade o proclamarei, \nque quem o achar merecerá nossos agradecimentos, \ntrazendo o covarde assassino ao suplício; \nquem o ocultar, morte.","edmundwhenidissuadedhimfromhisintentandf~ialspurstomaketheeseekit~460":"Edmundo — Quando o dissuadi de sua intenção \ne o achei decidido a fazê-lo, com fala áspera \nameacei denunciá-lo: respondeu: \n“Bastardo sem posses! Pensas tu, \nse eu me pusesse contra ti, que o depósito \nde qualquer confiança, virtude ou valor em ti \nfaria tuas palavras acreditadas? Não: o que eu negasse — \ncomo isto negaria: sim, ainda que produzisses \nminha própria letra — eu tudo voltaria \npara tua sugestão, trama e maldita prática: \ne terias de fazer do mundo um estúpido, \nse não pensassem que os proveitos de minha morte \nfossem muito fecundos e potentes estímulos \npara te fazer buscá-la.”","gloucesterstrongandfastendvillainwouldhe~hemeanstomaketheecapable~310":"Gloucester — Vilão forte e obstinado! \nNegaria ele a sua carta? Eu nunca o gerei. Toque de trompa dentro. \nEscutai, as trombetas do duque! Não sei por que vem. \nBarrarei todos os portos; o vilão não escapará; \no duque deve conceder-me isso: além disso, seu retrato \nenviarei longe e perto, para que todo o reino \ntenha a devida notícia dele; e de minhas terras, \nleal e natural rapaz, obterei os meios \npara te tornar herdeiro.","entercornwallreganandattendants~rnwallreganandattendants~31":"Entram Cornualha, Regana e Criados.","cornwallhownowmynoblefriendsinceicamehit~nowihaveheardstrangenews~83":"Cornualha — Então, meu nobre amigo! Desde que cheguei aqui, \no que posso dizer que foi agora mesmo, ouvi estranhas notícias.","reganifitbetrueallvengeancecomestooshort~theoffenderhowdostmylord~78":"Regana — Se for verdade, toda vingança fica curta \nque possa perseguir o ofensor. Como estais, meu senhor?","gloucesteromadammyoldheartiscrackditscra~ldheartiscrackditscrackd~43":"Gloucester — Oh, senhora, meu velho coração está rachado, está rachado!","reganwhatdidmyfathersgodsonseekyourlifeh~ommyfathernamedyouredgar~67":"Regana — Como, o afilhado de meu pai buscou vossa vida? \nAquele que meu pai nomeou? Vosso Edgar?","gloucesteroladyladyshamewouldhaveithid~yladyshamewouldhaveithid~38":"Gloucester — Oh, senhora, senhora, a vergonha o queria oculto!","reganwashenotcompanionwiththeriotousknig~ghtsthattenduponmyfather~63":"Regana — Não era ele companheiro dos cavaleiros desordeiros \nque servem meu pai?","gloucesteriknownotmadamtistoobadtoobad~wnotmadamtistoobadtoobad~38":"Gloucester — Não sei, senhora: é demasiado mau, demasiado mau.","edmundyesmadamhewasofthatconsort~smadamhewasofthatconsort~32":"Edmundo — Sim, senhora, era dessa companhia.","regannomarvelthenthoughhewereillaffected~rnatmyhouseillnotbethere~231":"Regana — Não admira, então, que fosse mal-intencionado: \nsão eles que o incitaram à morte do velho, \npara ter a despesa e o desperdício de suas rendas. \nTenho esta mesma tarde de minha irmã \nsido bem informada sobre eles; e com tais avisos \nque, se vierem hospedar-se em minha casa, \nnão estarei lá.","cornwallnoriassuretheereganedmundihearth~urfatherachildlikeoffice~80":"Cornualha — Nem eu, podes crer, Regana. \nEdmundo, ouço que mostraste a teu pai \num ofício filial.","edmundtwasmydutysir~edmundtwasmydutysir~19":"Edmundo — Foi meu dever, senhor.","gloucesterhedidbewrayhispractiseandrecei~eestrivingtoapprehendhim~79":"Gloucester — Ele revelou sua trama; e recebeu \neste ferimento que vedes, esforçando-se por prendê-lo.","cornwallishepursued~cornwallishepursued~19":"Cornualha — É perseguido?","gloucesteraymygoodlord~gloucesteraymygoodlord~22":"Gloucester — Sim, meu bom senhor.","cornwallifhebetakenheshallnevermorebefea~uchneedyouwefirstseizeon~232":"Cornualha — Se for apanhado, nunca mais \nserá temido de causar dano: fazei vosso próprio plano, \ncomo quiserdes em minha força. Quanto a ti, Edmundo, \ncuja virtude e obediência neste instante \ntanto se recomendam, serás nosso: \nnaturezas de tão profunda confiança muito precisaremos; \nem ti primeiro pomos a mão.","edmundishallserveyousirtrulyhoweverelse~veyousirtrulyhoweverelse~39":"Edmundo — Servir-vos-ei, senhor, \nlealmente, seja como for.","gloucesterforhimithankyourgrace~terforhimithankyourgrace~31":"Gloucester — Por ele agradeço a vossa graça.","cornwallyouknownotwhywecametovisityou~ownotwhywecametovisityou~37":"Cornualha — Não sabeis por que viemos visitar-vos —","reganthusoutofseasonthreadingdarkeyednig~whichcravestheinstantuse~343":"Regana — Assim fora de estação, trilhando a noite de olhos negros: \nocasiões, nobre Gloucester, de algum peso, \nnas quais teremos de usar vosso conselho: \nnosso pai escreveu, assim fez nossa irmã, \nde dissensões, que menos julguei conveniente \nresponder de nossa casa; os vários mensageiros \ndaqui aguardam despacho. Nosso bom velho amigo, \ntrazei consolos ao peito; e concedei \nvosso necessário conselho a nosso negócio, \nque reclama o uso imediato.","gloucesteriserveyoumadamyourgracesarerig~cesarerightwelcomeexeunt~55":"Gloucester — Sirvo-vos, senhora: \nvossas graças são muito bem-vindas. Saem.","beforegloucesterscastle~beforegloucesterscastle~23":"Diante do castelo de Gloucester.","enterkentandoswaldseverally~erkentandoswaldseverally~27":"Entram Kent e Oswald, separadamente.","oswaldgooddawningtotheefriendartofthisho~theefriendartofthishouse~43":"Oswald — Bom alvorecer, amigo: és desta casa?","kentay~kentay~6":"Kent — Sim.","oswaldwheremaywesetourhorses~ldwheremaywesetourhorses~28":"Oswald — Onde podemos pôr nossos cavalos?","kentithemire~kentithemire~12":"Kent — Na lama.","oswaldpritheeifthoulovestmetellme~theeifthoulovestmetellme~33":"Oswald — Peço-te, se me tens amizade, dize-me.","kentilovetheenot~kentilovetheenot~16":"Kent — Não te tenho amizade.","oswaldwhythenicarenotforthee~ldwhythenicarenotforthee~28":"Oswald — Pois então não me importo contigo.","kentifihadtheeinlipsburypinfoldiwouldmak~diwouldmaketheecareforme~54":"Kent — Se te tivesse no curral de Lipsbury, far-te-ia importar comigo.","oswaldwhydostthouusemethusiknowtheenot~houusemethusiknowtheenot~38":"Oswald — Por que me tratas assim? Não te conheço.","kentfellowiknowthee~kentfellowiknowthee~19":"Kent — Camarada, eu te conheço.","oswaldwhatdostthouknowmefor~aldwhatdostthouknowmefor~27":"Oswald — Por que me conheces?","kentaknavearascalaneaterofbrokenmeatsaba~astsyllableofthyaddition~415":"Kent — Um velhaco; um tratante; um comedor de restos; um vil, soberbo, raso, mendigo, de três trajes, de cem libras, imundo, de meias de lã, velhaco; um covarde de fígado de lírio, que vive de processos, um filho de uma puta, que se mira no espelho, servil em excesso, almofadinha; um escravo que herda um só baú; um que quereria ser alcoviteiro, a título de bom serviço, e não és nada senão a composição de velhaco, mendigo, covarde, rufião, e o filho e herdeiro de uma cadela vira-lata: um que baterei até choramingar aos gritos, se negares a mínima sílaba de teu título.","oswaldwhywhatamonstrousfellowartthouthus~rknownoftheenorknowsthee~87":"Oswald — Ora, que sujeito monstruoso és tu, de injuriar assim alguém que nem é conhecido de ti nem te conhece!","kentwhatabrazenfacedvarletartthoutodenyt~ongerdrawdrawinghissword~243":"Kent — Que malandro de cara de bronze és tu, de negar que me conheces! Faz dois dias que te dei uma rasteira e te bati diante do rei? Saca, tratante: pois, embora seja noite, a lua brilha; farei de ti uma sopa ao luar: saca, filho de uma puta, vil barbeiro-cortesão, saca. Desembainhando a espada.","oswaldawayihavenothingtodowiththee~ihavenothingtodowiththee~34":"Oswald — Fora! Não tenho nada a ver contigo.","kentdrawyourascalyoucomewithlettersagain~rawyourascalcomeyourways~167":"Kent — Saca, tratante: vens com cartas contra o rei; e tomas o partido da vaidade, a marionete, contra a realeza de seu pai: saca, tratante, ou te farei tantas postas nas canelas: saca, tratante; vem cá.","oswaldhelphomurderhelp~oswaldhelphomurderhelp~22":"Oswald — Socorro, ei! Assassino! Socorro!","kentstrikeyouslavestandroguestandyouneat~eatslavestrikebeatinghim~61":"Kent — Bate, escravo; fica firme, tratante, fica; escravo asseado, bate. Batendo nele.","oswaldhelphomurdermurder~oswaldhelphomurdermurder~24":"Oswald — Socorro, ei! Assassino! Assassino!","enteredmundwithhisrapierdrawncornwallreg~gangloucesterandservants~63":"Entram Edmundo, com o florete desembainhado, Cornualha, Regana, Gloucester e Criados.","edmundhownowwhatsthematter~mundhownowwhatsthematter~26":"Edmundo — Então! Que há?","kentwithyougoodmanboyanyoupleasecomeillf~fleshyecomeonyoungmaster~63":"Kent — Contigo, bom rapaz, se te apraz: vem, abrir-te-ei o apetite; vem, jovem senhor.","gloucesterweaponsarmswhatsthematterhere~nsarmswhatsthematterhere~39":"Gloucester — Armas! Armas! Que há aqui?","cornwallkeeppeaceuponyourliveshediesthat~ikesagainwhatisthematter~67":"Cornualha — Guardai a paz, por vossas vidas: morre quem bater de novo. Que há?","reganthemessengersfromoursisterandthekin~sfromoursisterandtheking~41":"Regana — Os mensageiros de nossa irmã e do rei.","cornwallwhatisyourdifferencespeak~hatisyourdifferencespeak~33":"Cornualha — Qual é a vossa diferença? Falai.","oswaldiamscarceinbreathmylord~diamscarceinbreathmylord~29":"Oswald — Mal tenho fôlego, meu senhor.","kentnomarvelyouhavesobestirredyourvalour~imsintheeatailormadethee~93":"Kent — Não admira, tanto avivaste teu valor. Tratante covarde, a natureza te renega: um alfaiate te fez.","cornwallthouartastrangefellowatailormake~ngefellowatailormakeaman~44":"Cornualha — És um sujeito estranho: um alfaiate fazer um homem?","kentayatailorsirastonecutterorpaintercou~eenbuttwohoursatthetrade~97":"Kent — Sim, um alfaiate, senhor: um escultor ou pintor não o teria feito tão mal, ainda que apenas duas horas no ofício.","cornwallspeakyethowgrewyourquarrel~eakyethowgrewyourquarrel~34":"Cornualha — Fala ainda, como surgiu vossa querela?","oswaldthisancientruffiansirwhoselifeihav~aredatsuitofhisgraybeard~67":"Oswald — Este velho rufião, senhor, cuja vida poupei a pedido de sua barba cinzenta —","kentthouwhoresonzedthouunnecessaryletter~aremygraybeardyouwagtail~160":"Kent — Tu, zê filho de uma puta! Tu, letra desnecessária! Meu senhor, se me der licença, calcarei este vilão não peneirado até virar argamassa, e rebocarei com ele a parede de uma latrina. Poupar minha barba cinzenta, seu pássaro-lavadeira?","cornwallpeacesirrahyoubeastlyknaveknowyo~yknaveknowyounoreverence~52":"Cornualha — Paz, rapaz! \nVelhaco bestial, não conheces reverência?","kentyessirbutangerhathaprivilege~irbutangerhathaprivilege~32":"Kent — Conheço, senhor; mas a ira tem seu privilégio.","cornwallwhyartthouangry~cornwallwhyartthouangry~23":"Cornualha — Por que estás irado?","kentthatsuchaslaveasthisshouldwearasword~eyecacklinghometocamelot~450":"Kent — Que tal escravo como este traga espada, \nele que não traz honestidade. Tais tratantes sorridentes, \ncomo ratos, roem muitas vezes em dois os santos laços \nque são íntimos demais para desatar; alisam toda paixão \nque se rebela na natureza de seus senhores; \ntrazem óleo ao fogo, neve aos humores mais frios; \nrenegam, afirmam e viram seus bicos de alcião \ncom cada sopro e variação de seus amos, \nnada sabendo, como cães, senão seguir. \nPeste sobre tua cara epiléptica! \nSorris de meus discursos, como se eu fosse um tolo? \nGanso, se te tivesse na planície de Sarum, \ntanger-te-ia grasnando até Camelot.","cornwallwhyartthoumadoldfellow~llwhyartthoumadoldfellow~30":"Cornualha — Ora, estás louco, velho?","gloucesterhowfellyououtsaythat~sterhowfellyououtsaythat~30":"Gloucester — Como brigastes? Dizei isso.","kentnocontrariesholdmoreantipathythanian~ipathythaniandsuchaknave~51":"Kent — Nenhuns contrários guardam mais antipatia \ndo que eu e tal velhaco.","cornwallwhydostthoucallhimaknavewhatshis~himaknavewhatshisoffence~47":"Cornualha — Por que o chamas de velhaco? Qual é sua ofensa?","kenthiscountenancelikesmenot~hiscountenancelikesmenot~28":"Kent — Sua fisionomia não me agrada.","cornwallnomoreperchancedoesminenorhisnor~ncedoesminenorhisnorhers~44":"Cornualha — Talvez tampouco a minha, nem a dele, nem a dela.","kentsirtismyoccupationtobeplainihaveseen~seebeforemeatthisinstant~111":"Kent — Senhor, é meu ofício ser franco: \nvi rostos melhores em meu tempo \ndo que o que está em qualquer ombro que vejo \ndiante de mim neste instante.","cornwallthisissomefellowwhohavingbeenpra~stretchtheirdutiesnicely~341":"Cornualha — Este é um sujeito \nque, tendo sido louvado pela franqueza, afeta \numa rudeza atrevida, e força o porte \nbem fora de sua natureza: ele não sabe lisonjear, ele, \num espírito honesto e simples, tem de dizer a verdade! \nSe a tomam, bem; se não, é franco. Conheço essa espécie de velhacos, que nesta franqueza \nabrigam mais astúcia e fins mais corruptos \ndo que vinte tolos servis a se curvar \nque esticam seus deveres com esmero.","kentsiringoodsoothinsincereverityunderth~onflickeringphoebusfront~131":"Kent — Senhor, em boa verdade, em sincera veracidade, \ncom a permissão de vosso grande aspecto, \ncuja influência, como a coroa de fogo radiante \nna fronte vacilante de Febo —","cornwallwhatmeanstbythis~cornwallwhatmeanstbythis~24":"Cornualha — Que queres dizer com isto?","kenttogooutofmydialectwhichyoudiscommend~ispleasuretoentreatmetot~182":"Kent — Sair do meu dialeto, que tanto desaprovais. Sei, senhor, que não sou lisonjeiro: aquele que vos enganou com sotaque simples era um simples velhaco; o que de minha parte não serei, ainda que ganhasse vosso desagrado para me rogardes que o fosse.","cornwallwhatwastheoffenceyougavehim~twastheoffenceyougavehim~35":"Cornualha — Qual foi a ofensa que lhe fizeste?","oswaldinevergavehimanyitpleasedthekinghi~exploitdrewonmehereagain~312":"Oswald — Nunca lhe fiz nenhuma: \naprouve ao rei, seu amo, há pouco, \nbater em mim, por um mal-entendido dele; \nquando ele, aliado e adulando seu desagrado, \ndeu-me uma rasteira por trás; estando eu no chão, insultou, injuriou, \ne assumiu tamanha pose de homem \nque o fez digno, e colheu louvores do rei \npor atacar quem já estava vencido por si; \ne, no embalo desse temível feito, \nsacou de novo contra mim aqui.","kentnoneoftheseroguesandcowardsbutajaxis~owardsbutajaxistheirfool~49":"Kent — Nenhum desses tratantes e covardes \nque não tenha Ajax por seu bobo.","cornwallfetchforththestocksyoustubbornan~rendbraggartwellteachyou~81":"Cornualha — Trazei o tronco! \nVelho velhaco teimoso, reverendo fanfarrão, \nensinar-te-emos —","kentsiriamtoooldtolearncallnotyourstocks~sterstockinghismessenger~181":"Kent — Senhor, sou velho demais para aprender: \nnão chameis vosso tronco para mim: sirvo o rei; \na serviço de quem fui enviado a vós: \nmostrareis pouco respeito, e demasiado ousada malícia \ncontra a graça e a pessoa de meu amo, \nprendendo seu mensageiro no tronco.","cornwallfetchforththestocksasihavelifean~rthereshallhesittillnoon~70":"Cornualha — Trazei o tronco! Por minha vida e honra, \nali sentará até o meio-dia.","regantillnoontillnightmylordandallnightt~ightmylordandallnighttoo~42":"Regana — Até o meio-dia! Até a noite, meu senhor; e a noite toda também.","kentwhymadamifiwereyourfathersdogyoushou~rsdogyoushouldnotusemeso~52":"Kent — Ora, senhora, se eu fosse o cão de vosso pai, \nnão me tratarieis assim.","regansirbeinghisknaveiwill~gansirbeinghisknaveiwill~26":"Regana — Senhor, sendo seu velhaco, tratarei.","cornwallthisisafellowoftheselfsamecolour~hestocksstocksbroughtout~95":"Cornualha — Este é um sujeito da mesma cor \nde que nossa irmã fala. Vamos, trazei o tronco! Trazem o tronco.","gloucesterletmebeseechyourgracenottodoso~ouldhavehimthusrestraind~288":"Gloucester — Deixai-me rogar a vossa graça que não o façais: \nsua falta é grande, e o bom rei, seu amo, \nlhe fará censura por isso: a baixa correção que propondes \né tal como com as mais ínfimas e desprezadas criaturas \npor furtos e transgressões comuns \nse pune: o rei há de levar a mal \nque seja tão pouco estimado em seu mensageiro, \nque o tenhais assim contido.","cornwallillanswerthat~cornwallillanswerthat~21":"Cornualha — Responderei por isso.","reganmysistermayreceiveitmuchmoreworseto~stockscomemygoodlordaway~143":"Regana — Minha irmã poderá receber muito pior \nver seu fidalgo ultrajado, agredido, \npor seguir seus negócios. Metei-lhe as pernas. Kent é posto no tronco. \nVamos, meu bom senhor, andemos.","exeuntallbutgloucesterandkent~tallbutgloucesterandkent~29":"Saem todos, menos Gloucester e Kent.","gloucesteriamsorryfortheefriendtistheduk~rstoppdillentreatforthee~126":"Gloucester — Sinto por ti, amigo; é o prazer do duque, \ncuja índole, todo o mundo bem sabe, \nnão será refreada nem detida: rogarei por ti.","kentpraydonotsirihavewatchedandtravelldh~atheelsgiveyougoodmorrow~132":"Kent — Peço-vos, não, senhor: velei e viajei duro; \nalgum tempo dormirei, o resto assobiarei. \nA fortuna de um bom homem pode sair pelos calcanhares: \nDeus vos dê bom dia!","gloucesterthedukestoblameinthistwillbeil~nthistwillbeilltakenexit~50":"Gloucester — O duque tem culpa nisto; será mal recebido. Sai.","kentgoodkingthatmustapprovethecommonsawt~cemoreturnthywheelsleeps~454":"Kent — Bom rei, que deves provar o velho ditado: \nsaíste da bênção do céu \npara o sol quente! \nAproxima-te, tu, farol deste globo inferior, \npara que por teus raios confortadores eu possa \nler esta carta! Quase nada vê milagres \nsenão a miséria: sei que é de Cordélia, \nque foi, felizmente, informada \nde meu curso obscurecido; e achará tempo, \ndeste estado enorme, buscando dar \nàs perdas seus remédios. Todo cansado e velado, \naproveitai, olhos pesados, para não ver \neste alojamento vergonhoso. \nFortuna, boa noite: sorri mais uma vez: gira tua roda! Dorme.","awood~awood~5":"Um bosque.","edgariheardmyselfproclaimdandbythehappyh~ngyetedgarinothingamexit~720":"Edgar — Ouvi-me proclamado; \ne pelo feliz oco de uma árvore \nescapei da caçada. Nenhum porto está livre; nenhum lugar \nonde guarda e vigilância mais que costumeira \nnão aguardem minha captura. Enquanto puder escapar, \nhei de me preservar: e pensei \nem tomar a forma mais vil e mais pobre \nque jamais a penúria, em desprezo do homem, \ntrouxe perto da besta: o rosto sujarei de imundície; \nenrolarei os quadris em manta; emaranharei todo o cabelo em nós de elfo; \ne com a nudez apresentada enfrentarei \nos ventos e as perseguições do céu. \nO campo me dá prova e precedente \nde mendigos de Bedlam, que, com vozes rugidoras, \nenterram nos braços nus, entorpecidos e mortificados, \nalfinetes, espetos de madeira, pregos, ramos de alecrim; \ne com este objeto horrível, de fazendas baixas, \npobres aldeias miseráveis, currais de ovelhas e moinhos, \nàs vezes com maldições de lunático, às vezes com preces, \nforçam a caridade. Pobre Turlygod! Pobre Tom! \nIsso ainda é algo: Edgar nada sou. Sai.","kentinthestocks~kentinthestocks~15":"Kent no tronco.","enterkinglearfoolandgentleman~kinglearfoolandgentleman~29":"Entram o Rei Lear, o Bobo e um Fidalgo.","kingleartisstrangethattheyshouldsodepart~ndnotsendbackmymessenger~73":"Rei Lear — É estranho que tenham assim partido de casa, \ne não enviado de volta meu mensageiro.","gentlemanasilearndthenightbeforetherewas~urposeinthemofthisremove~67":"Fidalgo — Pelo que soube, \na noite anterior não havia neles propósito \ndesta mudança.","kenthailtotheenoblemaster~enthailtotheenoblemaster~25":"Kent — Salve, nobre amo!","kinglearhamakestthouthisshamethypastime~tthouthisshamethypastime~39":"Rei Lear — Ha! \nFazes desta vergonha teu passatempo?","kentnomylord~kentnomylord~12":"Kent — Não, meu senhor.","foolhahahewearscruelgartershorsesaretied~ewearswoodennetherstocks~156":"Bobo — Ha, ha! Usa ligas cruéis. Cavalos são presos pela cabeça, cães e ursos pelo pescoço, macacos pela cintura, e homens pelas pernas: quando um homem é demasiado vigoroso de pernas, então usa meias de madeira.","kinglearwhatshethathathsomuchthyplacemis~lacemistooktosettheehere~57":"Rei Lear — Quem é que tanto confundiu teu posto \npara aqui te pôr?","kentitisbothheandsheyoursonanddaughter~andsheyoursonanddaughter~38":"Kent — É ele e ela; \nvosso genro e vossa filha.","kentyes~kentyes~7":"Kent — Sim.","kinglearnoisay~kinglearnoisay~14":"Rei Lear — Não, digo.","kentisayyea~kentisayyea~11":"Kent — Digo que sim.","kinglearnonotheywouldnot~kinglearnonotheywouldnot~24":"Rei Lear — Não, não, não o fariam.","kentyestheyhave~kentyestheyhave~15":"Kent — Sim, fizeram.","kinglearbyjupiteriswearno~inglearbyjupiteriswearno~25":"Rei Lear — Por Júpiter, juro que não.","kentbyjunoiswearay~kentbyjunoiswearay~18":"Kent — Por Juno, juro que sim.","kingleartheydurstnotdottheycouldnotwould~osethisusagecomingfromus~183":"Rei Lear — Não ousariam fazê-lo; \nnão poderiam, não quereriam fazê-lo; é pior que assassínio, \nfazer de caso pensado tão violento ultraje: \nesclarece-me, com toda a modesta pressa, de que modo \ntu poderias merecer, ou eles impor, este tratamento, \nvindo de nós.","kentmylordwhenattheirhomeididcommendyour~eshamewhichhereitsuffers~646":"Kent — Meu senhor, quando em sua casa \nentreguei as cartas de vossa alteza a eles, \nantes que me erguesse do lugar que mostrava \nmeu dever ajoelhado, chegou um correio suarento, \ncozido em sua pressa, meio sem fôlego, ofegando \nsaudações de Goneril, sua senhora; \nentregou cartas, a despeito da interrupção, \nque logo leram: com cujo conteúdo \nreuniram sua gente, tomaram logo cavalo; \nordenaram-me seguir, e aguardar \no lazer de sua resposta; deram-me olhares frios: \ne encontrando aqui o outro mensageiro, \ncuja acolhida, percebi, envenenara a minha — \nsendo o mesmo sujeito que há pouco \nse portou tão atrevido contra vossa alteza — \ntendo mais homem que juízo em mim, saquei: \nele alvoroçou a casa com gritos altos e covardes. \nVosso genro e vossa filha acharam esta ofensa digna \nda vergonha que aqui sofre.","foolwintersnotgoneyetifthewildgeeseflyth~rsasthoucansttellinayear~257":"Bobo — O inverno ainda não se foi, se os gansos selvagens voam por aí. \nPais que vestem trapos \nFazem seus filhos cegos; \nMas pais que carregam sacos \nVerão seus filhos afetuosos. \nA Fortuna, essa puta rematada, \nNunca gira a chave para o pobre. \nMas, apesar de tudo, terás tantas dores \npor tuas filhas quantas puderes contar num ano.","kinglearohowthismotherswellsuptowardmyhe~belowwhereisthisdaughter~115":"Rei Lear — Oh, como esta mãe sobe até meu coração! \nHysterica passio, desce, tu, dor que trepas, \ntua região é embaixo! Onde está esta filha?","kentwiththeearlsirherewithin~withtheearlsirherewithin~28":"Kent — Com o conde, senhor, aqui dentro.","kinglearfollowmenotstayhereexit~rfollowmenotstayhereexit~31":"Rei Lear — Não me sigais; \nficai aqui. Sai.","gentlemanmadeyounomoreoffencebutwhatyous~offencebutwhatyouspeakof~46":"Fidalgo — Não cometestes outra ofensa senão a que dizeis?","kentnonehowchancethekingcomeswithsosmall~ngcomeswithsosmallatrain~46":"Kent — Nenhuma. \nComo é que o rei vem com tão pequena comitiva?","foolandthouhadstbeensetithestocksforthat~nthouhadstwelldeservedit~71":"Bobo — E se tivesses sido posto no tronco por essa pergunta, bem o terias merecido.","foolwellsettheetoschooltoananttoteachthe~ollowitsinceafoolgivesit~394":"Bobo — Poremos você na escola de uma formiga, para ensinar que não se trabalha no inverno. Todos que seguem o nariz são guiados pelos olhos, exceto os cegos; e não há nariz entre vinte que não sinta o cheiro de quem fede. Larga o que seguras quando uma grande roda desce o morro, para que não te quebre o pescoço ao segui-la: mas a grande que sobe o morro, deixa que te arraste atrás. Quando um sábio te der melhor conselho, devolve-me o meu: não queria que o seguisse senão velhacos, já que quem o dá é um bobo.","thatsirwhichservesandseeksforgainandfoll~sawaythefoolnoknaveperdy~196":"Aquele senhor que serve e busca ganho, \nE segue só por formalidade, \nFará as malas quando começar a chover, \nE te deixará na tempestade. \nMas eu ficarei; o bobo fica, \nE deixa o sábio fugir: \nO velhaco que foge vira bobo; \nO bobo nunca velhaco, por Deus.","kentwherelearnedyouthisfool~twherelearnedyouthisfool~27":"Kent — Onde aprendeste isto, bobo?","foolnotithestocksfool~foolnotithestocksfool~21":"Bobo — No tronco é que não, bobo.","reenterkinglearwithgloucester~erkinglearwithgloucester~29":"Reentra o Rei Lear com Gloucester.","kingleardenytospeakwithmetheyaresickthey~gofffetchmeabetteranswer~135":"Rei Lear — Recusar falar comigo? Estão doentes? Estão cansados? \nViajaram a noite toda? Meros pretextos; \nas imagens da revolta e do afastamento. \nTrazei-me melhor resposta.","gloucestermydearlordyouknowthefieryquali~ndfixdheisinhisowncourse~91":"Gloucester — Meu caro senhor, \nconheceis a qualidade fogosa do duque; \nquão inamovível e fixo ele é \nem seu próprio curso.","kinglearvengeanceplaguedeathconfusionfie~dukeofcornwallandhiswife~115":"Rei Lear — Vingança! Peste! Morte! Confusão! \nFogosa? Que qualidade? Ora, Gloucester, Gloucester, \nquero falar com o Duque de Cornualha e sua mulher.","gloucesterwellmygoodlordihaveinformdthem~odlordihaveinformdthemso~42":"Gloucester — Pois bem, meu bom senhor, informei-os disso.","kinglearinformdthemdostthouunderstandmem~mdostthouunderstandmeman~42":"Rei Lear — Informaste-os! Entendes-me, homem?","kinglearthekingwouldspeakwithcornwallthe~rumtillitcrysleeptodeath~674":"Rei Lear — O rei quer falar com Cornualha; o caro pai \nquer falar com a filha, ordena seu serviço: \nestão informados disso? Meu fôlego e sangue! \nFogoso? O fogoso duque? Dize ao duque ardente que — \nNão, mas ainda não: talvez ele não esteja bem: \na enfermidade sempre descuida todo ofício \na que nossa saúde está obrigada; não somos nós mesmos \nquando a natureza, oprimida, ordena à mente \nsofrer com o corpo: abster-me-ei; \ne desavim-me com minha vontade mais impetuosa, \npor tomar o acesso indisposto e doentio \npelo homem são. Morte sobre meu estado! Por que Olhando para Kent. \ndeve ele sentar-se aqui? Este ato me persuade \nde que esta retirada do duque e dela \né mera manobra. Dá-me meu servo livre. \nVai dizer ao duque e à mulher que quero falar-lhes, \nagora, já: manda-os vir e ouvir-me, \nou à porta da câmara deles baterei o tambor \naté que grite o sono à morte.","gloucesteriwouldhaveallwellbetwixtyouexi~aveallwellbetwixtyouexit~41":"Gloucester — Queria que tudo estivesse bem entre vós. Sai.","kinglearomemyheartmyrisingheartbutdown~eartmyrisingheartbutdown~38":"Rei Lear — Ai de mim, meu coração, meu coração que sobe! Mas, desce!","foolcrytoitnuncleasthecockneydidtotheeel~tohishorsebutteredhishay~180":"Bobo — Grita-lhe, tio, como a cozinheira de Londres às enguias quando as pôs vivas na massa; batia-lhes nas cabeças com um pau, e gritava: ‘Desce, travessas, desce!’ Foi o irmão dela que, por pura bondade para com o cavalo, passou manteiga no feno.","entercornwallregangloucesterandservants~gangloucesterandservants~39":"Entram Cornualha, Regana, Gloucester e Criados.","kingleargoodmorrowtoyouboth~gleargoodmorrowtoyouboth~27":"Rei Lear — Bom dia a ambos.","cornwallhailtoyourgracekentissetatlibert~rgracekentissetatliberty~41":"Cornualha — Salve vossa graça! Kent é posto em liberdade.","reganiamgladtoseeyourhighness~iamgladtoseeyourhighness~29":"Regana — Alegro-me de ver vossa alteza.","kinglearreganithinkyouareiknowwhatreason~owdepravedaqualityoregan~333":"Rei Lear — Regana, creio que sim; sei que razão \ntenho para pensá-lo: se não te alegrasses, \ndivorciar-me-ia do túmulo de tua mãe, \nsepultando uma adúltera. \nA Kent. Oh, estás livre? \nOutra hora para isso. Amada Regana, \ntua irmã é um nada: oh, Regana, ela prendeu \na ingratidão de dentes agudos, como um abutre, aqui: Aponta o coração. \nMal posso falar-te; não acreditarás \ncom que depravada qualidade — oh, Regana!","reganiprayyousirtakepatienceihavehopeyou~ertthanshetoscantherduty~88":"Regana — Rogo-vos, senhor, tende paciência: tenho esperança. \nSabeis menos valorizar seu mérito \ndo que ela escassear seu dever.","kinglearsayhowisthat~kinglearsayhowisthat~20":"Rei Lear — Dize, como é isso?","reganicannotthinkmysisterintheleastwould~dasclearsherfromallblame~169":"Regana — Não posso pensar que minha irmã no mínimo \nfaltasse à sua obrigação: se, senhor, por acaso \nela refreou as desordens de vossos seguidores, \né por tal razão, e para tal fim saudável, \nque a livra de toda culpa.","kinglearmycursesonher~kinglearmycursesonher~21":"Rei Lear — Minhas maldições sobre ela!","reganosiryouareoldnatureinyoustandsonthe~rnsayyouhavewrongdhersir~210":"Regana — Oh, senhor, sois velho. \nA natureza em vós está no próprio limite \nde seu confim: devíeis ser regido e guiado \npor alguma discrição, que discirna vosso estado \nmelhor que vós mesmo. Portanto, rogo-vos \nque volteis a nossa irmã; \ndizei que a ofendestes, senhor.","kinglearaskherforgivenessdoyoubutmarkhow~hsafemeraimentbedandfood~163":"Rei Lear — Pedir-lhe perdão? \nReparai só como isto fica bem na casa: \n“Cara filha, confesso que sou velho; Ajoelhando-se. \na velhice é desnecessária: de joelhos suplico \nque vos digneis dar-me roupa, cama e comida.”","regangoodsirnomoretheseareunsightlytrick~ricksreturnyoutomysister~60":"Regana — Bom senhor, basta; são truques indecorosos: \nvolta a minha irmã.","kinglearrisingneverreganshehathabatedmeo~outakingairswithlameness~216":"Rei Lear — Levantando-se. Nunca, Regana: \nela diminuiu-me metade de minha comitiva; \nolhou-me sombria; feriu-me com a língua, \nmuito como serpente, no próprio coração: \ntodas as vinganças guardadas do céu caiam \nsobre seu cume ingrato! Atinge seus ossos jovens, \nvós, ares que tomais, com paralisia!","cornwallfiesirfie~cornwallfiesirfie~17":"Cornualha — Ora, senhor, ora!","kinglearyounimblelightningsdartyourblind~untofallandblastherpride~141":"Rei Lear — Vós, relâmpagos ágeis, lançai vossas chamas cegantes \nem seus olhos desdenhosos! Infecta sua beleza, \nvós, brumas sugadas dos pântanos, atraídas pelo sol poderoso, \npara cair e fulminar seu orgulho!","reganotheblestgodssowillyouwishonmewhent~honmewhentherashmoodison~54":"Regana — Oh, deuses benditos! Assim desejareis a mim, \nquando o humor impetuoso vos tomar.","kinglearnoreganthoushaltneverhavemycurse~forgotwhereinitheeendowd~392":"Rei Lear — Não, Regana, nunca terás minha maldição: \ntua natureza terna não te entregará \nà aspereza: os olhos dela são ferozes; mas os teus \nconfortam e não queimam. Não está em ti \nregatear meus prazeres, cortar minha comitiva, \ntrocar palavras apressadas, escassear minhas rações, \ne enfim opor o ferrolho \nà minha entrada: tu melhor sabes \nos ofícios da natureza, o laço da filiação, \nefeitos de cortesia, deveres de gratidão; \na tua metade do reino não esqueceste, \nem que te dotei.","regangoodsirtothepurpose~regangoodsirtothepurpose~24":"Regana — Bom senhor, ao assunto.","kinglearwhoputmymanithestockstucketwithi~anithestockstucketwithin~41":"Rei Lear — Quem pôs meu homem no tronco? Toque de trompa dentro.","cornwallwhattrumpetsthat~cornwallwhattrumpetsthat~24":"Cornualha — Que trombeta é essa?","reganiknowtmysistersthisapprovesherlette~erthatshewouldsoonbehere~63":"Regana — Conheço-a, é de minha irmã: isto confirma sua carta, \nque logo estaria aqui.","isyourladycome~isyourladycome~14":"Vossa senhora chegou?","kinglearthisisaslavewhoseeasyborrowdprid~lowsoutvarletfrommysight~97":"Rei Lear — Este é um escravo, cujo orgulho de fácil empréstimo \nmora na graça volúvel daquela a quem segue. \nFora, patife, da minha vista!","cornwallwhatmeansyourgrace~rnwallwhatmeansyourgrace~26":"Cornualha — Que pretende vossa graça?","kinglearwhostockdmyservantreganihavegood~wontwhocomeshereoheavens~83":"Rei Lear — Quem pôs meu servo no tronco? Regana, tenho boa esperança \nde que não soubeste disso. Quem vem aí? Oh, céus,","ifyoudoloveoldmenifyoursweetswayallowobe~wiltthoutakeherbythehand~171":"se amais os velhos, se vosso doce domínio \npermite obediência, se vós mesmos sois velhos, \nfazei disto vossa causa; descei, e tomai meu partido! \nA Goneril. Não te envergonhas de olhar esta barba? \nOh, Regana, tomarás sua mão?","gonerilwhynotbythehandsirhowhaveioffende~ionfindsanddotagetermsso~92":"Goneril — Por que não a mão, senhor? Em que ofendi? \nNem tudo é ofensa que a indiscrição acha \ne a caduquice assim denomina.","kinglearosidesyouaretootoughwillyouyetho~ldhowcamemymanithestocks~64":"Rei Lear — Oh, costelas, sois duras demais; \naguentareis ainda? Como foi que meu homem foi parar no tronco?","cornwallisethimtheresirbuthisowndisorder~ervedmuchlessadvancement~68":"Cornualha — Eu o pus ali, senhor: mas suas próprias desordens \nmereciam muito menos promoção.","kinglearyoudidyou~kinglearyoudidyou~17":"Rei Lear — Tu! Fizeste-o?","reganiprayyoufatherbeingweakseemsoiftill~dfulforyourentertainment~208":"Regana — Rogo-vos, pai, sendo fraco, pareçais sê-lo. \nSe, até o fim de vosso mês, \nquiserdes voltar e hospedar-vos com minha irmã, \ndespedindo metade de vossa comitiva, vinde então a mim: \nestou agora fora de casa, e sem aquela provisão \nque será necessária para vosso agasalho.","kinglearreturntoherandfiftymendismissdno~tedgroompointingatoswald~376":"Rei Lear — Voltar a ela, e cinquenta homens despedidos? \nNão, antes abjuro todos os tetos, e escolho \nlutar contra a inimizade do ar; \nser camarada do lobo e da coruja — \nO pesado aperto da necessidade! Voltar com ela? \nOra, a França de sangue quente, que sem dote tomou \nnossa filha mais moça, eu poderia do mesmo modo ser levado \na ajoelhar-me a seu trono, e, como um escudeiro, pedir pensão \npara manter de pé a vida vil. Voltar com ela? \nPersuadi-me antes a ser escravo e besta de carga \ndeste detestado lacaio. Apontando para Oswald.","gonerilatyourchoicesir~gonerilatyourchoicesir~22":"Goneril — À vossa escolha, senhor.","kinglearipritheedaughterdonotmakememadiw~eganiandmyhundredknights~459":"Rei Lear — Peço-te, filha, não me enlouqueças: \nnão te incomodarei, minha filha; adeus: \nnão mais nos encontraremos, não mais nos veremos: \nmas ainda assim és minha carne, meu sangue, minha filha; \nou antes uma doença que está em minha carne, \na qual devo por força chamar minha: és um furúnculo, \numa chaga pestilenta, um carbúnculo inchado, \nem meu sangue corrompido. Mas não te censurarei; \nque a vergonha venha quando quiser, eu não a chamo: \nnão mando o portador do trovão disparar, \nnem conto histórias de ti ao alto-julgador Júpiter: \nemenda-te quando puderes; sê melhor no teu lazer: \nposso ter paciência; posso ficar com Regana, \neu e meus cem cavaleiros.","regannotaltogethersoilookdnotforyouyetno~sobutsheknowswhatshedoes~180":"Regana — Não exatamente assim: \nnão vos esperava ainda, nem estou provida \npara vosso digno acolhimento. Dai ouvidos, senhor, a minha irmã; \npois os que misturam razão à vossa paixão \ndevem contentar-se em julgar-vos velho, e assim — \nmas ela sabe o que faz.","kinglearisthiswellspoken~kinglearisthiswellspoken~24":"Rei Lear — Isto é bem falado?","reganidareavouchitsirwhatfiftyfollowersi~ytishardalmostimpossible~213":"Regana — Ouso afirmá-lo, senhor: como, cinquenta seguidores? \nNão é bastante? Que precisais de mais? \nSim, ou tantos, já que tanto o custo como o perigo \nfalam contra tão grande número? Como, numa só casa, \npoderiam muitas pessoas, sob dois comandos, \nmanter amizade? É difícil; quase impossível.","gonerilwhymightnotyoumylordreceiveattend~ecallsservantsorfrommine~83":"Goneril — Por que não poderíeis, meu senhor, receber serviço \ndaqueles que ela chama criados ou dos meus?","reganwhynotmylordifthentheychancedtoslac~rewilligiveplaceornotice~160":"Regana — Por que não, meu senhor? Se então eles vos descuidassem, \npoderíamos controlá-los. Se quiserdes vir a mim — \npois agora vejo um perigo — rogo-vos \nque tragais apenas vinte e cinco: a mais que isso \nnão darei lugar nem atenção.","kinglearigaveyouall~kinglearigaveyouall~19":"Rei Lear — Dei-vos tudo —","reganandingoodtimeyougaveit~anandingoodtimeyougaveit~27":"Regana — E em boa hora o destes.","kinglearmadeyoumyguardiansmydepositaries~eandtwentyregansaidyouso~134":"Rei Lear — Fiz-vos minhas guardiãs, minhas depositárias; \nmas guardei uma reserva de ser seguido \npor tal número. Como, devo ir a ti \ncom vinte e cinco, Regana? Disseste assim?","reganandspeaktagainmylordnomorewithme~tagainmylordnomorewithme~37":"Regana — E repito, meu senhor; nem mais um comigo.","kinglearthosewickedcreaturesyetdolookwel~tyandthouarttwiceherlove~189":"Rei Lear — Aquelas criaturas más ainda parecem de bom semblante \nquando outras são mais más: não ser a pior \nestá em algum grau de louvor. \nA Goneril. Irei contigo: \ntuas cinquenta ainda dobram vinte e cinco, \ne és duas vezes o amor dela.","gonerilhearmemylordwhatneedyoufiveandtwe~anyhaveacommandtotendyou~105":"Goneril — Ouvi-me, meu senhor; \nque necessidade tendes de vinte e cinco, dez, ou cinco, \npara seguir numa casa onde o dobro \ntem ordem de vos servir?","reganwhatneedone~reganwhatneedone~16":"Regana — Que necessidade de um só?","kinglearoreasonnottheneedourbasestbeggar~eillweepofoolishallgomad~769":"Rei Lear — Oh, não raciocineis a necessidade: nossos mendigos mais vis \nsão supérfluos na coisa mais pobre que têm: \nnão concedas à natureza mais do que a natureza precisa, \ne a vida do homem é tão barata quanto a da besta: és uma dama; \nse apenas andar aquecida fosse magnificência, \nora, a natureza não precisa do que magnífica vestes, \nque mal te mantém quente. Mas, por verdadeira necessidade — \nvós, céus, dai-me aquela paciência, a paciência de que preciso! \nVedes-me aqui, deuses, um pobre velho, \ntão cheio de dor quanto de idade; miserável em ambas! \nSe sois vós que agitais os corações destas filhas \ncontra seu pai, não me enganeis a ponto \nde suportá-lo mansamente; tocai-me com nobre ira, \ne não deixeis as armas das mulheres, gotas de água, \nmanchar minhas faces de homem! Não, vós, megeras desnaturadas, \ntais vinganças terei de vós ambas \nque todo o mundo há de — farei tais coisas — \nquais sejam, ainda não sei: mas serão \no terror da terra. Pensais que chorarei? \nNão, não chorarei: \ntenho plena causa para chorar; mas este coração \nse romperá em cem mil fendas, \nantes que eu chore. Oh, bobo, enlouquecerei!","exeuntkingleargloucesterkentandfool~eargloucesterkentandfool~35":"Saem o Rei Lear, Gloucester, Kent e o Bobo.","stormandtempest~stormandtempest~15":"Tempestade e borrasca.","cornwallletuswithdrawtwillbeastorm~tuswithdrawtwillbeastorm~34":"Cornualha — Retiremo-nos; vai haver tempestade.","reganthishouseislittletheoldmanandhispeo~eoplecannotbewellbestowd~62":"Regana — Esta casa é pequena: o velho e sua gente \nnão podem ser bem acomodados.","goneriltishisownblamehathputhimselffromr~ndmustneedstastehisfolly~68":"Goneril — A culpa é dele; pôs-se fora do repouso, \ne tem de provar a sua loucura.","reganforhisparticularillreceivehimgladly~mgladlybutnotonefollower~57":"Regana — Quanto a ele em particular, recebê-lo-ei de bom grado, \nmas nem um seguidor.","gonerilsoamipurposedwhereismylordofglouc~hereismylordofgloucester~45":"Goneril — Assim também me proponho. \nOnde está meu senhor de Gloucester?","cornwallfollowdtheoldmanforthheisreturnd~heoldmanforthheisreturnd~40":"Cornualha — Seguiu o velho para fora: voltou.","reentergloucester~reentergloucester~17":"Reentra Gloucester.","gloucesterthekingisinhighrage~esterthekingisinhighrage~29":"Gloucester — O rei está em grande furor.","cornwallwhitherishegoing~cornwallwhitherishegoing~24":"Cornualha — Para onde vai?","gloucesterhecallstohorsebutwilliknownotw~sebutwilliknownotwhither~46":"Gloucester — Pede cavalos; mas para onde, não sei.","cornwalltisbesttogivehimwayheleadshimsel~givehimwayheleadshimself~41":"Cornualha — Melhor dar-lhe passagem; ele guia a si mesmo.","gonerilmylordentreathimbynomeanstostay~ntreathimbynomeanstostay~38":"Goneril — Meu senhor, não o rogueis de modo algum que fique.","gloucesteralackthenightcomesonandtheblea~esabouttheresscarceabush~94":"Gloucester — Ai, a noite vem, e os ventos gélidos \nsoprão rudemente; por muitas milhas ao redor \nmal há um arbusto.","reganosirtowilfulmentheinjuriesthattheyt~searabusedwisdombidsfear~192":"Regana — Oh, senhor, para os homens teimosos, \nas injúrias que eles mesmos provocam \ndevem ser seus mestres-escolas. Fechai as portas: \nele é acompanhado por uma comitiva desesperada; \ne ao que o possam incitar, sendo propenso \na ter o ouvido abusado, a sabedoria manda temer.","cornwallshutupyourdoorsmylordtisawildnig~llcomeoutothestormexeunt~83":"Cornualha — Fechai as portas, meu senhor; é noite selvagem: \nminha Regana aconselha bem; saí da tempestade. Saem.","aheath~aheath~6":"Uma charneca.","stormstillenterkentandagentlemanmeeting~kentandagentlemanmeeting~39":"A tempestade continua. Entram Kent e um Fidalgo, encontrando-se.","kentwhostherebesidesfoulweather~stherebesidesfoulweather~31":"Kent — Quem está aí, além do tempo funesto?","gentlemanonemindedliketheweathermostunqu~etheweathermostunquietly~45":"Fidalgo — Alguém de ânimo igual ao do tempo, de todo inquieto.","kentiknowyouwherestheking~entiknowyouwherestheking~25":"Kent — Eu vos conheço. Onde está o rei?","gentlemancontendingwiththefretfulelement~nsandbidswhatwilltakeall~415":"Fidalgo — Em luta com o elemento furioso:\nOrdena aos ventos que soprem a terra para dentro do mar,\nOu que alcem a água encrespada acima do oceano,\nPara que as coisas mudem ou cessem; arranca os cabelos brancos,\nQue as rajadas impetuosas, em sua cega fúria,\nAgarram e reduzem a nada; esforça-se, em seu pequeno mundo de homem,\npor desafiar\nO vento e a chuva, que se combatem de lá para cá.\nNesta noite em que a ursa de filhotes famintos se agacharia na toca,\nE o leão e o lobo de ventre encolhido\nConservam seco o pelo, ele corre de cabeça descoberta,\nE manda que tudo leve o que quiser.","kentbutwhoiswithhim~kentbutwhoiswithhim~19":"Kent — Mas quem está com ele?","gentlemannonebutthefoolwholabourstooutje~sthisheartstruckinjuries~64":"Fidalgo — Ninguém, exceto o bobo, que se esforça por vencer em gracejos\nas feridas que lhe atravessam o coração.","kentsiridoknowyouanddareuponthewarrantof~anceofferthisofficetoyou~856":"Kent — Senhor, eu vos conheço;\ne ouso, confiando no que de vós observei,\nconfiar-vos coisa preciosa. Há divisão,\nembora por ora a cara dela se cubra\nde astúcia recíproca, entre Albany e Cornualha;\nos quais têm — como os têm todos aqueles que as grandes estrelas\nentronaram e puseram no alto — criados que parecem tais,\nmas que são para a França espiões e vigias\nbem informados do nosso estado; o que se viu,\nseja nos ressentimentos e conluios dos duques,\nseja na rédea dura que ambos empunharam\ncontra o velho e bondoso rei; ou algo mais fundo,\nde que talvez isso seja apenas adorno;\nmas é verdade que da França vem um exército\na este reino desunido; que já,\nsabendo-se da nossa negligência, tem pés secretos\nem alguns dos nossos melhores portos e está a ponto\nde desfraldar abertamente a bandeira. Agora, a vós:\nse sobre o meu crédito ousardes confiar tanto\nque corrais a Dover, achareis ali\nquem vos agradeça, fazendo fiel relato\nda dor desnaturada e enlouquecedora\nque o rei tem motivo para lamentar.\nSou fidalgo de sangue e de criação;\ne, por algum conhecimento e certeza, vos ofereço\neste encargo.","gentlemaniwilltalkfurtherwithyou~niwilltalkfurtherwithyou~32":"Fidalgo — Falarei mais convosco.","kentnodonotforconfirmationthatiammuchmor~sstormiwillgoseektheking~227":"Kent — Não, não.\nPara confirmar que sou muito mais\ndo que a minha muralha exterior, abri esta bolsa e tomai\no que ela contém. Se virdes Cordélia —\ne não duvideis de que a vereis —, mostrai-lhe este anel;\ne ela vos dirá quem é o vosso companheiro,\nque ainda desconheceis. Maldita seja esta tempestade!\nVou procurar o rei.","gentlemangivemeyourhandhaveyounomoretosa~urhandhaveyounomoretosay~41":"Fidalgo — Dai-me a mão: não tendes mais nada a dizer?","kentfewwordsbuttoeffectmorethanallyettha~atheotherexeuntseverally~142":"Kent — Poucas palavras, mas, no efeito, mais que todas até aqui:\nque, quando tivermos achado o rei — e para isso o vosso esforço\nvai por ali, o meu por aqui —, quem primeiro der com ele\nchame o outro. Saem separadamente.","anotherpartoftheheathstormstill~partoftheheathstormstill~31":"Outra parte da charneca. A tempestade continua.","enterkinglearandfool~enterkinglearandfool~20":"Entram o Rei Lear e o Bobo.","kinglearblowwindsandcrackyourcheeksrageb~ncethatmakeingratefulman~326":"Rei Lear — Soprai, ventos, e rachai as faces! Rugi! Soprai!\nCataratas e furacões, jorrai\naté encharcardes os campanários, afogardes os galos!\nFogos sulfurosos, rápidos como o pensamento,\narautos de raios que fendem carvalhos,\nchamuscai-me a cabeça branca! E tu, trovão que tudo abala,\nachata a espessa redondeza do mundo!\nQuebra os moldes da natureza, derrama de uma vez os germes\nque fazem o homem ingrato!","foolonunclecourtholywaterinadryhouseisbe~iesneitherwisemannorfool~145":"Bobo — Oh, titio, água benta de corte em casa seca é melhor que esta água de chuva lá fora. Bom titio, entra e pede a bênção das tuas filhas: eis uma noite que não tem pena nem do sábio nem do tolo.","kinglearrumblethybellyfulspitfirespoutra~dandwhiteasthisootisfoul~385":"Rei Lear — Ribomba a pança cheia! Cospe, fogo! Jorra, chuva!\nNem chuva, vento, trovão, fogo são minhas filhas:\nnão vos acuso de crueldade, elementos;\nnunca vos dei reino, nunca vos chamei filhos,\nnão me deveis obediência: portanto deixai cair\nvosso horrível prazer: aqui estou, vosso escravo,\num velho pobre, enfermo, fraco e desprezado:\ncontudo vos chamo ministros servis,\nque com duas filhas perversas unistes\nvossas altas hostes contra uma cabeça\ntão velha e tão branca como esta. Oh! Oh! É infame!","foolhethathasahousetoputsheadinhasagoodh~sheadinhasagoodheadpiece~48":"Bobo — Quem tem casa onde meter a cabeça tem um bom miolo.","thecodpiecethatwillhousebeforetheheadhas~butshemademouthsinaglass~219":"A braguilha que arranja casa\nantes que a cabeça tenha uma,\ncabeça e ele terão piolhos;\nassim se casam os mendigos.\nO homem que faz do dedo do pé\no que devia fazer do coração\nhá de gritar por causa de um calo\ne trocar o sono por vigília.\nPois jamais houve mulher formosa que não fizesse\ncaretas ao espelho.","kinglearnoiwillbethepatternofallpatience~lpatienceiwillsaynothing~55":"Rei Lear — Não, serei o modelo de toda a paciência;\nnão direi nada.","enterkent~enterkent~9":"Entra Kent.","kentwhosthere~kentwhosthere~13":"Kent — Quem está aí?","foolmarryheresgraceandacodpiecethatsawis~ecethatsawisemanandafool~52":"Bobo — Ora, eis a graça e a braguilha; isto é, um sábio e um tolo.","kentalassirareyouherethingsthatlovenight~ytheafflictionnorthefear~288":"Kent — Ai, senhor, estais aqui? As criaturas que amam a noite\nnão amam noites como esta; os céus iracundos\naterram até os que vagam nas trevas\ne os fazem guardar as cavernas: desde que sou homem,\ntais lençóis de fogo, tais estouros de trovão horrendo,\ntais gemidos de vento e chuva rugindo, nunca\nme lembro de ter ouvido: a natureza do homem não pode suportar\nnem a aflição nem o medo.","kinglearletthegreatgodsthatkeepthisdread~esinndagainstthansinning~416":"Rei Lear — Que os grandes deuses,\nque fazem este pavoroso tumulto sobre nossas cabeças,\ndescubram agora os seus inimigos. Treme, miserável,\nque tens em ti crimes não revelados,\nnão açoitados pela justiça: esconde-te, mão sangrenta;\nperjuro, e tu, homem de virtude fingida,\nque és incestuoso: celerado, estremece em pedaços,\ntu que, sob dissimulação oculta e cômoda,\natentaste contra a vida do homem: culpas encerradas,\nrompei os invólucros que vos escondem e implorai\ngraça a estes terríveis intimadores. Sou um homem\nmais ofendido do que ofensor.","kentalackbareheadedgraciousmylordhardbyh~orcetheirscantedcourtesy~250":"Kent — Ai de mim, de cabeça descoberta!\nMeu bom senhor, perto daqui há uma choupana;\nela vos dará algum amparo contra a tempestade:\nrepousai ali; enquanto eu, a esta casa dura —\nmais dura que as pedras de que é feita;\nque ainda agora, perguntando eu por vós,\nme negou a entrada —, voltarei e arrancarei\nà força a sua parca cortesia.","kinglearmywitsbegintoturncomeonmyboyhowd~eartthatssorryyetforthee~222":"Rei Lear — Meu juízo começa a turvar-se.\nVem, meu rapaz: como estás, meu rapaz? Tens frio?\nEu mesmo tenho frio. Onde está essa palha, amigo?\nA arte das nossas necessidades é estranha,\npois faz preciosas as coisas vis. Vamos, a vossa choupana.\nPobre bobo e velhaco, tenho no coração uma parte\nque ainda tem pena de ti.","foolsinginghethathasandalittletinywitwit~therainitrainetheveryday~123":"Bobo — Cantando. Quem tem um pouquinho de juízo —\ncom um hei, ho, o vento e a chuva —\ndeve contentar-se com a sorte que lhe cabe,\npois a chuva chove todo dia.","kingleartruemygoodboycomebringustothisho~oycomebringustothishovel~43":"Rei Lear — É verdade, meu bom rapaz. Vamos, leva-nos à choupana.","exeuntkinglearandkent~exeuntkinglearandkent~21":"Saem o Rei Lear e Kent.","foolthisisabravenighttocoolacourtezanill~orilivebeforehistimeexit~521":"Bobo — Esta é uma bela noite para esfriar uma cortesã.\nAntes de ir, direi uma profecia:\nquando os padres forem mais palavra que substância;\nquando os cervejeiros estragarem o malte com água;\nquando os nobres forem mestres dos seus alfaiates;\nnenhum herege queimado, só os que cortejam moças;\nquando todo processo for justo;\nnenhum escudeiro endividado, nem pobre cavaleiro;\nquando as calúnias não viverem em línguas;\nnem os batedores de carteira vierem às multidões;\nquando os usurários contarem o ouro em campo aberto;\ne rufiões e rameiras erguerem igrejas;\nentão o reino de Albion\ncairá em grande confusão:\nentão virá o tempo, para quem viver para vê-lo,\nem que se usará caminhar com os pés.\nEsta profecia fará Merlim; pois eu vivo antes do seu tempo. Sai.","entergloucesterandedmund~entergloucesterandedmund~24":"Entram Gloucester e Edmund.","gloucesteralackalackedmundilikenotthisun~orhimnoranywaysustainhim~219":"Gloucester — Ai, ai, Edmund, não gosto deste procedimento desnaturado. Quando lhes pedi licença para ter piedade dele, tiraram-me o uso da minha própria casa; ordenaram-me, sob pena de seu perpétuo desagrado, que nem falasse dele, nem intercedesse por ele, nem de modo algum o socorresse.","edmundmostsavageandunnatural~ndmostsavageandunnatural~28":"Edmund — Que selvageria e que desnaturalidade!","gloucestergotosayyounothingtheresadivisi~mundprayyoubecarefulexit~509":"Gloucester — Vamos, não digas nada. Há divisão entre os duques; e coisa pior que isso: recebi esta noite uma carta; é perigoso falar dela; tranquei-a no meu gabinete: as injúrias que o rei sofre agora serão vingadas por inteiro; já pisa o solo uma parte de um exército: devemos inclinar-nos ao rei. Irei procurá-lo e socorrê-lo em segredo: vai tu e entretém o duque em conversa, para que ele não perceba a minha caridade: se ele perguntar por mim, estou doente e fui deitar-me. Ainda que eu morra por isso, pois não menos que isso me ameaçam, o rei, meu velho senhor, deve ser socorrido. Algo de estranho se prepara, Edmund; peço-te, sê cauteloso. Sai.","edmundthiscourtesyforbidtheeshalltheduke~eswhentheolddothfallexit~179":"Edmund — Esta cortesia, que te foi vedada, o duque\nsaberá num instante; e daquela carta também:\nisto parece bom merecimento e há de me trazer\no que meu pai perde: nada menos que tudo.\nO jovem se ergue quando o velho cai. Sai.","theheathbeforeahovel~theheathbeforeahovel~20":"A charneca. Diante de uma choupana.","kenthereistheplacemylordgoodmylordentert~ooroughfornaturetoendure~89":"Kent — Eis o lugar, meu senhor; bom senhor, entrai:\na tirania da noite ao relento é demasiado dura\npara a natureza suportar.","stormstill~stormstill~10":"A tempestade continua.","kinglearletmealone~kinglearletmealone~18":"Rei Lear — Deixa-me em paz.","kentgoodmylordenterhere~kentgoodmylordenterhere~23":"Kent — Bom senhor, entrai aqui.","kinglearwiltbreakmyheart~kinglearwiltbreakmyheart~24":"Rei Lear — Queres partir-me o coração?","kentihadratherbreakmineowngoodmylordente~akmineowngoodmylordenter~41":"Kent — Antes partiria o meu. Bom senhor, entrai.","kinglearthouthinksttismuchthatthisconten~etmeshunthatnomoreofthat~571":"Rei Lear — Pensas que é muito que esta tormenta rancorosa\nnos invada até a pele: para ti, é;\nmas onde o mal maior se fixou,\no menor mal mal se sente. Fugirias de um urso;\nmas se a tua fuga fosse rumo ao mar furioso,\ntoparias o urso de frente. Quando o espírito está livre,\no corpo é delicado: a tempestade em minha mente\ntira dos meus sentidos todo outro sentir,\nsalvo o que ali golpeia. Ingratidão filial!\nNão é como se esta boca dilacerasse esta mão\npor lhe levar o alimento? Mas punirei sem piedade:\nnão, não chorarei mais. Numa noite assim\nfechar-me para fora! Derrama-te; suportarei.\nNuma noite como esta! Oh, Regane, Goneril!\nVosso velho e bondoso pai, cujo coração franco tudo deu —\noh, por aí jaz a loucura; devo evitá-la;\nbasta disso.","kinglearpritheegointhyselfseekthineownea~ndshowtheheavensmorejust~503":"Rei Lear — Entra tu mesmo, peço-te: busca o teu conforto:\nesta tempestade não me deixa ponderar\nem coisas que me feririam mais. Mas entrarei.\nAo Bobo. Entra, rapaz; vai primeiro. Ó pobreza sem teto —\nnão, entra tu. Rezarei, e depois dormirei. O Bobo entra.\nPobres miseráveis nus, onde quer que estejais,\nque suportais o açoite desta tormenta impiedosa,\ncomo vos defenderão as cabeças sem teto e os flancos sem pão,\nvossos trapos furados e esburacados,\nde estações como estas? Oh, eu cuidei\npouco demais disto! Toma o remédio, pompa;\nexpõe-te a sentir o que sentem os desgraçados,\npara que sacudas o supérfluo sobre eles\ne mostres os céus mais justos.","edgarwithinfathomandhalffathomandhalfpoo~halffathomandhalfpoortom~44":"Edgar — Dentro. Braça e meia, braça e meia! Pobre Tom!","thefoolrunsoutfromthehovel~efoolrunsoutfromthehovel~26":"O Bobo sai correndo da choupana.","foolcomenotinherenuncleheresaspirithelpm~heresaspirithelpmehelpme~47":"Bobo — Não entres aqui, titio, há um espírito. Socorro, socorro!","kentgivemethyhandwhosthere~ntgivemethyhandwhosthere~26":"Kent — Dá-me a mão. Quem está aí?","foolaspiritaspirithesayshisnamespoortom~rithesayshisnamespoortom~39":"Bobo — Um espírito, um espírito: diz que se chama pobre Tom.","kentwhatartthouthatdostgrumblethereithes~ethereithestrawcomeforth~53":"Kent — Quem és tu que resmungas aí na palha? Vem para fora.","enteredgardisguisedasamadman~redgardisguisedasamadman~28":"Entra Edgar, disfarçado de louco.","edgarawaythefoulfiendfollowsmethroughthe~otothycoldbedandwarmthee~97":"Edgar — Fora! O demônio imundo me persegue!\nPelo espinheiro agudo sopra o vento frio.\nHum! Vai para a tua cama fria e aquece-te.","kinglearhastthougivenalltothytwodaughter~tersandartthoucometothis~61":"Rei Lear — Deste tudo às tuas duas filhas?\nE chegaste a isto?","edgarwhogivesanythingtopoortomwhomthefou~ereandthereagainandthere~466":"Edgar — Quem dá alguma coisa ao pobre Tom? A quem o demônio imundo levou por fogo e por chama, por vau e por remoinho, por pântano e por lodaçal; que lhe pôs facas sob o travesseiro e laços de forca no banco da igreja; pôs veneno de rato junto ao seu mingau; fê-lo orgulhoso de coração, a cavalgar um bailo trotão sobre pontes de quatro polegadas, a perseguir a própria sombra como a um traidor. Abençoados sejam os teus cinco sentidos! Tom tem frio — oh, do de, do de, do de. Que te guardem de redemoinhos, de maus astros e de feitiços! Fazei alguma caridade ao pobre Tom, a quem o demônio imundo atormenta: ali eu o poderia pegar agora — e ali — e ali de novo, e ali.","kinglearwhathavehisdaughtersbroughthimto~hingdidstthougivethemall~90":"Rei Lear — Quê, as filhas o trouxeram a este ponto?\nNão pudeste salvar nada? Deste-lhes tudo?","foolnayhereservedablanketelsewehadbeenal~etelsewehadbeenallshamed~47":"Bobo — Não, reservou um cobertor; senão todos teríamos passado vergonha.","kinglearnowalltheplaguesthatinthependulo~aultslightonthydaughters~86":"Rei Lear — Que todas as pragas que pendem no ar suspenso,\nfadadas contra as culpas dos homens, caiam sobre tuas filhas!","kenthehathnodaughterssir~kenthehathnodaughterssir~24":"Kent — Ele não tem filhas, senhor.","kingleardeathtraitornothingcouldhavesubd~gotthosepelicandaughters~213":"Rei Lear — Morte, traidor! Nada poderia ter sujeitado a natureza\na tal baixeza senão filhas desnaturadas.\nÉ moda que pais repudiados\ntenham tão pouca piedade da própria carne?\nCastigo judicioso! Foi esta carne que gerou\naquelas filhas pelicanos.","edgarpillicocksatonpillicockhillhallooha~ckhillhalloohalloolooloo~50":"Edgar — Pillicock sentou no morro de Pillicock: Olá, olá, lô, lô!","foolthiscoldnightwillturnusalltofoolsand~urnusalltofoolsandmadmen~46":"Bobo — Esta noite fria nos transformará a todos em tolos e loucos.","edgartakeheedothefoulfiendobeythyparents~artonproudarraytomsacold~133":"Edgar — Cuidado com o demônio imundo: obedece a teus pais; cumpre a palavra com justiça; não jures; não te deites com a esposa jurada de outro; não ponhas teu doce coração em trajes de orgulho. Tom tem frio.","kinglearwhathastthoubeen~kinglearwhathastthoubeen~24":"Rei Lear — O que foste?","edgaraservingmanproudinheartandmindthatc~oymyboysessalethimtrotby~635":"Edgar — Um criado, orgulhoso de coração e de espírito; que frisava o cabelo; trazia luvas no chapéu; servia à luxúria do coração de minha senhora e fazia com ela o ato das trevas; jurava tantos juramentos quantas palavras dizia, e os quebrava na doce face do céu: um que dormia tramando a luxúria e acordava para cometê-la: vinho amei profundamente, dados ardentemente: e em mulheres superei o Turco: falso de coração, leve de ouvido, sanguinário de mão; porco na preguiça, raposa na astúcia, lobo na gula, cão na fúria, leão na presa. Não deixes o ranger dos sapatos nem o farfalhar das sedas trair o teu pobre coração a mulher: mantém o pé longe dos bordéis, a mão longe das saias, a pena longe dos livros dos credores, e desafia o demônio imundo. Ainda pelo espinheiro sopra o vento frio: diz suum, mun, ha, no, nonny. Delfim, meu rapaz, meu rapaz, sessa! deixa-o passar a trote.","kinglearwhythouwertbetterinthygravethant~heretearingoffhisclothes~356":"Rei Lear — Ora, melhor estarias na tua cova do que responder com o corpo descoberto a esta extremidade dos céus. Não é o homem mais do que isto? Considerai-o bem. Nada deves ao bicho-da-seda, nada ao animal pelo couro, nada à ovelha pela lã, nada ao gato pelo perfume. Ha! Aqui três de nós estamos adulterados! Tu és a coisa em si: o homem sem arranjos não é mais que um pobre animal nu e bifurcado como tu. Fora, fora, vós, coisas emprestadas! Vamos, desabotoai-me aqui. Arrancando as roupas.","foolpritheenunclebecontentedtisanaughtyn~ookherecomesawalkingfire~160":"Bobo — Peço-te, titio, sossega; é uma noite ruim para nadar. Agora um pouco de fogo num campo selvagem seria como o coração de um velho libertino: uma pequena faísca, e todo o resto do corpo frio. Olha, aí vem um fogo ambulante.","entergloucesterwithatorch~ntergloucesterwithatorch~25":"Entra Gloucester, com uma tocha.","edgarthisisthefoulfiendflibbertigibbethe~tsthepoorcreatureofearth~181":"Edgar — Este é o demônio imundo Flibbertigibbet: começa ao toque de recolher e anda até o primeiro canto do galo; dá a catarata e a película, entorta o olho e faz o lábio leporino; mela o trigo branco e fere a pobre criatura da terra.","switholdfootedthricetheoldhemetthenightm~rointtheewitcharointthee~114":"São Withold percorreu três vezes o morro velho;\nencontrou o pesadelo e suas nove crias;\nmandou-a apear\ne dar a sua palavra,\ne, fora daqui, bruxa, fora!","kenthowfaresyourgrace~kenthowfaresyourgrace~21":"Kent — Como está vossa graça?","kinglearwhatshe~kinglearwhatshe~15":"Rei Lear — Quem é esse?","kentwhostherewhatistyouseek~twhostherewhatistyouseek~27":"Kent — Quem está aí? O que procurais?","gloucesterwhatareyouthereyournames~whatareyouthereyournames~34":"Gloucester — Quem sois vós aí? Vossos nomes?","edgarpoortomthateatstheswimmingfrogtheto~rsetorideandweapontowear~341":"Edgar — Pobre Tom; que come a rã que nada, o sapo, o girino, a lagartixa-d’água e a salamandra; que, na fúria do coração, quando o demônio imundo se enfurece, come bosta de vaca por salada; engole o rato velho e o cão de vala; bebe o manto verde do charco parado; que é açoitado de paróquia em paróquia, castigado no tronco e preso; que teve três casacos nas costas, seis camisas no corpo, cavalo para montar e arma para trazer;","butmiceandratsandsuchsmalldeerhavebeento~tomsfoodforsevenlongyear~62":"mas ratos e camundongos e tal caça miúda\nforam o alimento de Tom por sete longos anos.","bewaremyfollowerpeacesmulkinpeacethoufie~acesmulkinpeacethoufiend~42":"Cuidado com o meu seguidor. Paz, Smulkin; paz, demônio!","gloucesterwhathathyourgracenobettercompa~yourgracenobettercompany~42":"Gloucester — Quê, vossa graça não tem melhor companhia?","edgartheprinceofdarknessisagentlemanmodo~lemanmodohescalldandmahu~55":"Edgar — O príncipe das trevas é um fidalgo: chama-se Modo, e Mahu.","gloucesterourfleshandbloodisgrownsovilem~thatitdothhatewhatgetsit~69":"Gloucester — Nossa carne e sangue ficaram tão vis, meu senhor,\nque odeiam o que os gerou.","edgarpoortomsacold~edgarpoortomsacold~18":"Edgar — O pobre Tom tem frio.","gloucestergoinwithmemydutycannotsufferto~rebothfireandfoodisready~218":"Gloucester — Vem comigo: meu dever não pode suportar\nobedecer em tudo às duras ordens de vossas filhas:\nembora a injunção delas seja barrar-me as portas\ne deixar que esta noite tirânica vos tome,\nainda assim ousei vir procurar-vos\ne levar-vos aonde fogo e comida estão prontos.","kinglearfirstletmetalkwiththisphilosophe~rwhatisthecauseofthunder~64":"Rei Lear — Primeiro deixai-me falar com este filósofo.\nQual é a causa do trovão?","kentgoodmylordtakehisoffergointothehouse~kehisoffergointothehouse~40":"Kent — Bom senhor, aceitai a oferta; entrai na casa.","kinglearilltalkawordwiththissamelearnedt~nedthebanwhatisyourstudy~60":"Rei Lear — Quero trocar uma palavra com este douto tebano.\nQual é o vosso estudo?","edgarhowtopreventthefiendandtokillvermin~tthefiendandtokillvermin~40":"Edgar — Como prevenir o demônio e matar a vermina.","kinglearletmeaskyouonewordinprivate~measkyouonewordinprivate~35":"Rei Lear — Deixai-me perguntar-vos uma palavra em particular.","kentimportunehimoncemoretogomylordhiswit~rdhiswitsbegintounsettle~56":"Kent — Insisti com ele mais uma vez para que entre, senhor;\no juízo dele começa a desarranjar-se.","gloucestercanstthoublamehimstormstillhis~sthisidobeseechyourgrace~335":"Gloucester — Podes culpá-lo? A tempestade continua.\nAs filhas procuram-lhe a morte: ah, aquele bom Kent!\nDisse que seria assim, pobre homem banido!\nDizes que o rei enlouquece; dir-te-ei, amigo,\neu mesmo estou quase louco: tive um filho,\nagora proscrito do meu sangue; buscou-me a vida,\nmas há pouco, bem pouco: amei-o, amigo;\nnenhum pai amou mais o filho: a verdade te digo,\na dor me desvairou o juízo. Que noite é esta!\nRogo a vossa graça —","kinglearocryyourmercysirnoblephilosopher~lephilosopheryourcompany~51":"Rei Lear — Oh, perdão, senhor. Nobre filósofo, a vossa companhia.","edgartomsacold~edgartomsacold~14":"Edgar — Tom tem frio.","gloucesterinfellowthereintothehovelkeept~intothehovelkeeptheewarm~47":"Gloucester — Entra, companheiro, ali, na choupana: aquece-te.","kinglearcomeletsinall~kinglearcomeletsinall~21":"Rei Lear — Vamos entrar todos.","kentthiswaymylord~kentthiswaymylord~17":"Kent — Por aqui, meu senhor.","kinglearwithhimiwillkeepstillwithmyphilo~epstillwithmyphilosopher~46":"Rei Lear — Com ele; ficarei sempre com o meu filósofo.","kentgoodmylordsoothehimlethimtakethefell~hehimlethimtakethefellow~42":"Kent — Bom senhor, agradai-o; deixai que leve o sujeito.","gloucestertakehimyouon~gloucestertakehimyouon~22":"Gloucester — Levai-o vós.","kentsirrahcomeongoalongwithus~irrahcomeongoalongwithus~29":"Kent — Rapaz, vem; vai conosco.","kinglearcomegoodathenian~kinglearcomegoodathenian~24":"Rei Lear — Vem, bom ateniense.","gloucesternowordsnowordshush~cesternowordsnowordshush~28":"Gloucester — Sem palavras, sem palavras: silêncio.","edgarchildrowlandtothedarktowercamehiswo~ellthebloodofabritishman~89":"Edgar — O jovem Rolando à torre escura chegou,\ne sua palavra era sempre — Fie, foh e fum,\nsinto o cheiro do sangue de um britânico.","exeunt~exeunt~6":"Saem.","entercornwallandedmund~entercornwallandedmund~22":"Entram Cornualha e Edmund.","cornwalliwillhavemyrevengeereideparthish~evengeereideparthishouse~44":"Cornualha — Terei a minha vingança antes de deixar a casa dele.","edmundhowmylordimaybecensuredthatnaturet~omethingfearsmetothinkof~85":"Edmund — Como, meu senhor, serei censurado por a natureza ceder assim à lealdade; isso me causa certo temor só de pensar.","cornwallinowperceiveitwasnotaltogetheryo~provablebadnessinhimself~139":"Cornualha — Percebo agora que não foi apenas a má índole de vosso irmão que o levou a buscar a morte dele; mas um mérito provocador, posto em obra por uma maldade reprovável nele mesmo.","edmundhowmaliciousismyfortunethatimustre~werenotornotithedetector~180":"Edmund — Como é maliciosa a minha sorte, que eu deva arrepender-me de ser justo! Esta é a carta de que ele falou, a qual o prova parte conhecedora dos intentos da França: oh, céus! Quisera que esta traição não existisse, ou que eu não fosse o denunciante!","cornwallgowithmetotheduchess~wallgowithmetotheduchess~28":"Cornualha — Vem comigo à duquesa.","edmundifthematterofthispaperbecertainyou~havemightybusinessinhand~64":"Edmund — Se o conteúdo deste papel é certo, tendes grande negócio em mãos.","cornwalltrueorfalseithathmadetheeearlofg~ereadyforourapprehension~106":"Cornualha — Verdadeiro ou falso, fez-te conde de Gloucester. Descobre onde está teu pai, para que esteja pronto para a nossa prisão.","edmundasideififindhimcomfortingthekingit~orebetweenthatandmyblood~147":"Edmund — À parte. Se o achar confortando o rei, isso lhe encherá mais plenamente a suspeita. — Perseverarei no meu curso de lealdade, ainda que o conflito seja duro entre ela e meu sangue.","cornwalliwilllaytrustupontheeandthoushal~indadearerfatherinmylove~66":"Cornualha — Depositarei confiança em ti; e acharás em meu amor um pai mais caro.","scenevi~scenevi~7":"Cena VI","achamberinafarmhouseadjoiningthecastle~mhouseadjoiningthecastle~38":"Um aposento numa casa de campo junto ao castelo.","entergloucesterkinglearkentfoolandedgar~kinglearkentfoolandedgar~39":"Entram Gloucester, o Rei Lear, Kent, o Bobo e Edgar.","gloucesterhereisbetterthantheopenairtake~caniwillnotbelongfromyou~116":"Gloucester — Aqui é melhor que o ar livre; aceitai-o com gratidão. Completarei o conforto com o que puder acrescentar: não me demorarei longe de vós.","kentallthepowerofhiswitshavegivenwaytohi~hegodsrewardyourkindness~76":"Kent — Todo o poder do juízo dele cedeu à sua impaciência: que os deuses recompensem a vossa bondade!","exitgloucester~exitgloucester~14":"Sai Gloucester.","edgarfraterettocallsmeandtellsmeneroisan~entandbewarethefoulfiend~98":"Edgar — Frateretto me chama; e me diz\nque Nero é pescador no lago das trevas.\nReza, inocente, e guarda-te do demônio imundo.","foolpritheenuncletellmewhetheramadmanbea~manbeagentlemanorayeoman~58":"Bobo — Peço-te, titio, dize-me: um louco é fidalgo ou camponês livre?","kinglearakingaking~kinglearakingaking~18":"Rei Lear — Um rei, um rei!","foolnohesayeomanthathasagentlemantohisso~issonagentlemanbeforehim~90":"Bobo — Não, é um camponês livre quem tem um fidalgo por filho; pois é louco o camponês que vê o filho fidalgo antes de si.","kingleartohaveathousandwithredburningspi~spitscomehissinginuponem~61":"Rei Lear — Ter mil com espetos vermelhos em brasa\nvindo silvando sobre eles —","edgarthefoulfiendbitesmyback~rthefoulfiendbitesmyback~28":"Edgar — O demônio imundo morde-me as costas.","foolhesmadthattrustsinthetamenessofawolf~thaboysloveorawhoresoath~75":"Bobo — É louco quem confia na mansidão de um lobo, na saúde de um cavalo, no amor de um rapaz ou no juramento de uma meretriz.","kinglearitshallbedoneiwillarraignthemstr~sirsitherenowyoushefoxes~130":"Rei Lear — Assim será feito; vou julgá-las já.\nA Edgar. Vem, senta-te aqui, douto justiceiro;\nAo Bobo. Tu, sapiente senhor, senta-te aqui. Agora, raposas fêmeas!","edgarlookwherehestandsandglareswantestth~comeoerthebournbessytome~82":"Edgar — Vede onde ele está, a fuzilar com os olhos!\nQuereis olhos no julgamento, senhora?\nVem além do riacho, Bessy, a mim —","foolherboathathaleakandshemustnotspeakwh~hedaresnotcomeovertothee~66":"Bobo — O barco dela tem um furo,\ne ela não deve dizer\npor que não ousa chegar até ti.","edgarthefoulfiendhauntspoortominthevoice~kangelihavenofoodforthee~132":"Edgar — O demônio imundo assombra o pobre Tom com a voz de um rouxinol. Hopdance grita na barriga de Tom por dois arenques brancos. Não grasnes, anjo negro; não tenho comida para ti.","kenthowdoyousirstandyounotsoamazedwillyo~wnandrestuponthecushions~70":"Kent — Como estais, senhor? Não fiqueis tão atônito:\nquereis deitar-vos e repousar sobre as almofadas?","kinglearillseetheirtrialfirstbringinthee~eothecommissionsityoutoo~173":"Rei Lear — Primeiro verei o julgamento delas. Trazei as testemunhas.\nA Edgar. Tu, homem togado da justiça, toma o teu lugar;\nAo Bobo. E tu, seu parelheiro de equidade,\nsenta-te ao lado dele no banco; A Kent. vós sois da comissão,\nsentai-vos também.","edgarletusdealjustlysleepestorwakestthou~akenoharmpurthecatisgray~141":"Edgar — Sejamos justos.\nDormes ou velas, alegre pastor?\nTuas ovelhas estão no trigo;\ne por um sopro da tua boquinha,\ntuas ovelhas não sofrerão dano.\nPur! O gato é cinzento.","kingleararraignherfirsttisgonerilihereta~ckedthepoorkingherfather~105":"Rei Lear — Julgai-a primeiro; é Goneril. Aqui presto\njuramento perante esta honrada assembleia: ela chutou\no pobre rei, seu pai.","foolcomehithermistressisyournamegoneril~istressisyournamegoneril~39":"Bobo — Vem cá, senhora. Chamas-te Goneril?","kinglearshecannotdenyit~kinglearshecannotdenyit~23":"Rei Lear — Ela não pode negar.","foolcryyoumercyitookyouforajointstool~cyitookyouforajointstool~37":"Bobo — Perdão, tomei-vos por um banquinho.","kinglearandheresanotherwhosewarpdlookspr~erwhyhastthouletherscape~155":"Rei Lear — E aqui está outra, cujo olhar torto proclama\nde que matéria é feito o seu coração. Detende-a ali!\nArmas, armas, espada, fogo! Corrupção no tribunal!\nFalso justiceiro, por que a deixaste escapar?","edgarblessthyfivewits~edgarblessthyfivewits~21":"Edgar — Abençoados sejam os teus cinco sentidos!","kentopitysirwhereisthepatiencenowthattho~soofthaveboastedtoretain~65":"Kent — Oh, que pena! Senhor, onde está agora a paciência\nque tantas vezes te gabaste de conservar?","edgarasidemytearsbegintotakehispartsomuc~heyllmarmycounterfeiting~66":"Edgar — À parte. Minhas lágrimas já tomam tanto o partido dele\nque vão estragar o meu fingimento.","kinglearthelittledogsandalltrayblanchand~weetheartseetheybarkatme~65":"Rei Lear — Os cachorrinhos e todos, Tray, Blanch e\nSweet-heart, vede, latem para mim.","edgartomwillthrowhisheadatthemavauntyouc~eapthehatchandallarefled~248":"Edgar — Tom lhes arremessará a cabeça. Fora, cães!\nSeja a tua boca preta ou branca,\ndente que envenena se morde;\nmastim, galgo, vira-lata feroz,\ncão de caça ou spaniel, braco ou lima,\ncão de rabo cortado ou de rabo enrolado,\nTom os fará chorar e gemer:\npois, com este arremesso da cabeça,\nos cães saltam a porteira e todos fogem.","dodededesessacomemarchtowakesandfairsand~townspoortomthyhornisdry~70":"Do de, de, de. Sessa! Vamos, marchemos para festas, feiras e vilas de mercado. Pobre Tom, teu chifre está seco.","kinglearthenletthemanatomizereganseewhat~ttirebutletthembechanged~233":"Rei Lear — Então que dissequem Regane; vejam o que se cria ao redor do coração dela. Há alguma causa na natureza que faça estes corações duros? A Edgar. A vós, senhor, tomo para um dos meus cem; só não gosto da moda das vossas roupas: direis que é traje persa: mas mudem-se.","kentnowgoodmylordliehereandrestawhile~lordliehereandrestawhile~37":"Kent — Agora, bom senhor, deitai-vos aqui e descansai um pouco.","kinglearmakenonoisemakenonoisedrawthecur~tosupperihemorningsososo~81":"Rei Lear — Não façais barulho, não façais barulho; fechai as cortinas: assim, assim, assim. Iremos cear amanhã cedo. Assim, assim, assim.","foolandillgotobedatnoon~foolandillgotobedatnoon~23":"Bobo — E eu irei dormir ao meio-dia.","gloucestercomehitherfriendwhereistheking~ndwhereisthekingmymaster~48":"Gloucester — Vem cá, amigo: onde está o rei, meu senhor?","kentheresirbuttroublehimnothiswitsaregon~ublehimnothiswitsaregone~41":"Kent — Aqui, senhor; mas não o perturbeis, o juízo dele se foi.","gloucestergoodfriendipritheetakehiminthy~siongivetheequickconduct~342":"Gloucester — Bom amigo, peço-te, toma-o nos braços;\nouvi por acaso um plano de morte contra ele:\nhá uma liteira pronta; deita-o nela\ne segue para Dover, amigo, onde encontrarás\nboas-vindas e proteção. Levanta o teu senhor:\nse te demorares meia hora, a vida dele,\ncom a tua, e a de todos os que ofereçam defendê-lo,\nficam em perda certa: levanta, levanta;\ne segue-me, que te darei rápida guia\naté algum socorro.","kentoppressednaturesleepsthisrestmightye~terthoumustnotstaybehind~163":"Kent — A natureza oprimida dorme:\neste repouso ainda poderia ter dado bálsamo a teus sentidos partidos,\nque, se a conveniência não o permitir,\nficarão de difícil cura.\nAo Bobo. Vem, ajuda a carregar teu amo;\nnão deves ficar para trás.","gloucestercomecomeawayexeuntallbutedgar~omeawayexeuntallbutedgar~39":"Gloucester — Vamos, vamos, embora. Saem todos, exceto Edgar.","edgarwhenweourbettersseebearingourwoeswe~scapethekinglurklurkexit~481":"Edgar — Quando vemos os maiores que nós carregando nossos males,\nmal pensamos que nossas misérias são inimigas.\nQuem sofre só sofre mais no espírito,\ndeixando para trás as coisas livres e as alegres aparências:\nmas o espírito muito do sofrimento salta,\nquando a dor tem companheiros e suporta em comunhão.\nComo parece leve e suportável a minha dor agora,\nquando o que me faz curvar faz o rei dobrar-se,\nele filhado como eu paternado! Tom, vai-te!\nAtenta nos grandes rumores; e revela-te,\nquando a falsa opinião, cujo pensamento errado te macula,\nna tua justa prova te revogar e reconciliar.\nO que mais suceder esta noite, que o rei escape a salvo!\nEsconde-te, esconde-te. Sai.","scenevii~scenevii~8":"Cena VII","entercornwallregangoneriledmundandservan~goneriledmundandservants~42":"Entram Cornualha, Regane, Goneril, Edmund e Criados.","cornwallpostspeedilytomylordyourhusbands~rexeuntsomeoftheservants~129":"Cornualha — Correi depressa a meu senhor vosso marido; mostrai-lhe esta carta: o exército da França desembarcou. Procurai o vilão Gloucester. Saem alguns dos Criados.","reganhanghiminstantly~reganhanghiminstantly~21":"Regane — Enforcai-o já.","gonerilpluckouthiseyes~gonerilpluckouthiseyes~22":"Goneril — Arrancai-lhe os olhos.","cornwallleavehimtomydispleasureedmundkee~rewellmylordofgloucester~298":"Cornualha — Deixai-o ao meu desagrado. Edmund, fazei companhia à nossa irmã: as vinganças que somos obrigados a tomar de vosso pai traidor não são para os vossos olhos. Aconselhai o duque, aonde fordes, a uma preparação muito apressada: estamos obrigados à mesma. Nossos mensageiros serão rápidos e inteligentes entre nós. Adeus, cara irmã: adeus, meu senhor de Gloucester.","hownowwherestheking~hownowwherestheking~19":"Então! Onde está o rei?","oswaldmylordofgloucesterhathconveydhimhe~sttohavewellarmedfriends~208":"Oswald — Meu senhor de Gloucester levou-o daqui:\nuns trinta e cinco ou trinta e seis de seus cavaleiros,\nardentes em busca dele, encontraram-no ao portão;\ne estes, com alguns outros dependentes dos lordes,\nforam com ele para Dover, onde se gabam\nde ter amigos bem armados.","cornwallgethorsesforyourmistress~gethorsesforyourmistress~32":"Cornualha — Buscai cavalos para vossa senhora.","gonerilfarewellsweetlordandsister~rewellsweetlordandsister~33":"Goneril — Adeus, doce senhor, e irmã.","cornwalledmundfarewellexeuntgoneriledmun~ntrolwhostherethetraitor~271":"Cornualha — Edmund, adeus. Saem Goneril, Edmund e Oswald.\nIde buscar o traidor Gloucester,\natai-lhe os braços como a um ladrão, trazei-o diante de nós. Saem os outros Criados.\nEmbora não possamos sentenciar-lhe a vida\nsem a forma da justiça, nosso poder\nfará uma cortesia à nossa ira, o que os homens\npoderão censurar, mas não controlar. Quem vem aí? O traidor?","entergloucesterbroughtinbytwoorthree~terbroughtinbytwoorthree~36":"Entra Gloucester, trazido por dois ou três.","reganingratefulfoxtishe~reganingratefulfoxtishe~23":"Regane — Raposa ingrata! É ele.","cornwallbindfasthiscorkyarms~wallbindfasthiscorkyarms~28":"Cornualha — Atai-lhe com força os braços secos.","gloucesterwhatmeanyourgracesgoodmyfriend~stsdomenofoulplayfriends~84":"Gloucester — Que pretendem vossas graças? Bons amigos, considerai\nque sou vosso anfitrião: não me façais violência, amigos.","cornwallbindhimisayservantsbindhim~ndhimisayservantsbindhim~34":"Cornualha — Atai-o, digo. Os Criados o atam.","reganhardhardofilthytraitor~anhardhardofilthytraitor~27":"Regane — Apertado, apertado. Oh, traidor imundo!","gloucesterunmercifulladyasyouareimnone~rcifulladyasyouareimnone~38":"Gloucester — Senhora impiedosa que sois, eu não sou traidor.","cornwalltothischairbindhimvillainthousha~tfindreganpluckshisbeard~65":"Cornualha — A esta cadeira atai-o. Vilão, hás de achar — Regane lhe arranca a barba.","gloucesterbythekindgodstismostignoblydon~ydonetopluckmebythebeard~60":"Gloucester — Pelos deuses bondosos, é feito de modo ignóbil\narrancar-me a barba.","regansowhiteandsuchatraitor~ansowhiteandsuchatraitor~27":"Regane — Tão branca, e tão traidor!","gloucesternaughtyladythesehairswhichthou~trufflethuswhatwillyoudo~165":"Gloucester — Senhora má,\nestes pelos que arrancas do meu queixo\nreviverão e te acusarão: sou vosso anfitrião:\ncom mãos de ladrões não deveríeis\nassim desfigurar meu rosto hospitaleiro. Que ides fazer?","cornwallcomesirwhatlettershadyoulatefrom~tershadyoulatefromfrance~46":"Cornualha — Vamos, senhor, que cartas recebestes ultimamente da França?","reganbesimpleanswererforweknowthetruth~nswererforweknowthetruth~38":"Regane — Sede simples na resposta, pois sabemos a verdade.","cornwallandwhatconfederacyhaveyouwiththe~rslatefootedinthekingdom~70":"Cornualha — E que conluio tendes com os traidores\nhá pouco desembarcados no reino?","regantowhosehandshaveyousentthelunaticki~usentthelunatickingspeak~47":"Regane — A cujas mãos enviastes o rei lunático? Falai.","gloucesterihavealetterguessinglysetdownw~eartandnotfromoneopposed~95":"Gloucester — Tenho uma carta escrita por conjectura,\nque veio de alguém de coração neutro,\ne não de um adversário.","cornwallcunning~cornwallcunning~15":"Cornualha — Ardilosa.","reganandfalse~reganandfalse~13":"Regane — E falsa.","cornwallwherehastthousenttheking~wherehastthousenttheking~32":"Cornualha — Para onde enviaste o rei?","gloucestertodover~gloucestertodover~17":"Gloucester — A Dover.","reganwhereforetodoverwastthounotchargeda~astthounotchargedatperil~46":"Regane — Por que a Dover? Não te foi ordenado, sob risco —","cornwallwhereforetodoverlethimfirstanswe~verlethimfirstanswerthat~45":"Cornualha — Por que a Dover? Que ele responda isso primeiro.","gloucesteriamtiedtothestakeandimuststand~keandimuststandthecourse~49":"Gloucester — Estou atado ao poste e devo enfrentar o ataque.","reganwhereforetodoversir~reganwhereforetodoversir~24":"Regane — Por que a Dover, senhor?","gloucesterbecauseiwouldnotseethycruelnai~anceovertakesuchchildren~402":"Gloucester — Porque não quis ver tuas unhas cruéis\narrancarem-lhe os pobres olhos de velho, nem tua irmã feroz\ncravar na sua carne ungida presas de javali.\nO mar, com uma tempestade como a que sua cabeça nua\nsuportou na noite negra como o inferno, teria subido\ne apagado os fogos estrelados:\nmas, pobre velho coração, ele ajudou os céus a chover.\nSe lobos tivessem uivado ao teu portão naquele tempo cruel,\nterias dito “Bom porteiro, gira a chave”,\ncom todos os outros cruéis assentindo: mas verei\na vingança alada alcançar tais filhas.","cornwallseetshaltthouneverfellowsholdthe~eeyesofthineillsetmyfoot~77":"Cornualha — Isso nunca verás. Companheiros, segurai a cadeira.\nSobre estes teus olhos porei o pé.","gloucesterhethatwillthinktolivetillhebeo~mesomehelpocrueloyougods~70":"Gloucester — Quem pensa em viver até ficar velho,\ndê-me ajuda! Oh, cruel! Oh, deuses!","reganonesidewillmockanothertheothertoo~llmockanothertheothertoo~38":"Regane — Um lado zombará do outro; o outro também.","cornwallifyouseevengeance~ornwallifyouseevengeance~25":"Cornualha — Se vedes a vingança —","firstservantholdyourhandmylordihaveserve~neyouthannowtobidyouhold~115":"Primeiro criado — Detende a mão, meu senhor:\nsirvo-vos desde que era criança;\nmas melhor serviço nunca vos prestei\ndo que agora, mandando-vos deter.","reganhownowyoudog~reganhownowyoudog~17":"Regane — Como assim, cão!","firstservantifyoudidwearabearduponyourch~thisquarrelwhatdoyoumean~77":"Primeiro criado — Se tivésseis barba no queixo,\neu a sacudiria nesta contenda. Que pretendeis?","cornwallmyvillaintheydrawandfight~yvillaintheydrawandfight~33":"Cornualha — Meu vilão! Desembainham e lutam.","firstservantnaythencomeonandtakethechanc~nandtakethechanceofanger~48":"Primeiro criado — Pois bem, vinde, e corra-se o risco da ira.","regangivemethyswordapeasantstandupthusta~aswordandrunsathimbehind~67":"Regane — Dá-me a tua espada. Um camponês levantar-se assim! Toma uma espada e investe contra ele por trás.","firstservantoiamslainmylordyouhaveoneeye~eesomemischiefonhimodies~71":"Primeiro criado — Oh, estou morto! Meu senhor, tendes um olho ainda\npara ver algum mal sobre ele. Oh! Morre.","cornwalllestitseemorepreventitoutvilejel~jellywhereisthylustrenow~61":"Cornualha — Para que não veja mais, impeçamo-lo. Fora, geleia vil!\nOnde está agora o teu brilho?","gloucesteralldarkandcomfortlesswheresmys~aturetoquitthishorridact~101":"Gloucester — Tudo escuro e sem consolo. Onde está meu filho Edmund?\nEdmund, acende todas as centelhas da natureza\npara vingar este ato horrendo.","reganouttreacherousvillainthoucallstonhi~uswhoistoogoodtopitythee~119":"Regane — Fora, vilão traiçoeiro!\nInvocas aquele que te odeia: foi ele\nque nos fez a revelação das tuas traições;\nele é bom demais para ter pena de ti.","gloucesteromyfolliesthenedgarwasabusedki~rgivemethatandprosperhim~72":"Gloucester — Oh, minhas loucuras! Então Edgar foi enganado.\nDeuses bondosos, perdoai-me isso e fazei-o prosperar!","regangothrusthimoutatgatesandlethimsmell~erhowistmylordhowlookyou~96":"Regane — Ide pô-lo para fora dos portões e que farejando\nache o caminho de Dover. Sai um com Gloucester.\nComo estais, meu senhor? Que tal vos sentis?","cornwallihavereceivedahurtfollowmeladytu~rmexitcornwallledbyregan~164":"Cornualha — Recebi um ferimento: segue-me, senhora.\nPonde para fora esse vilão sem olhos; lançai este escravo\nno monturo. Regane, sangro depressa:\neste ferimento vem fora de hora: dá-me teu braço. Sai Cornualha, conduzido por Regane.","secondservantillnevercarewhatwickednessi~ssidoifthismancometogood~61":"Segundo criado — Nunca me importarei com a maldade que eu faça,\nse este homem acabar bem.","thirdservantifshelivelongandintheendmeet~womenwillallturnmonsters~83":"Terceiro criado — Se ela viver muito\ne no fim encontrar o velho curso da morte,\nas mulheres todas se tornarão monstros.","secondservantletsfollowtheoldearlandgett~ssallowsitselftoanything~108":"Segundo criado — Sigamos o velho conde e busquemos o louco de Bedlam\npara guiá-lo aonde queira: a sua loucura velhaca\npresta-se a qualquer coisa.","thirdservantgothouillfetchsomeflaxandwhi~enhelphimexeuntseverally~104":"Terceiro criado — Vai tu: buscarei estopa e claras de ovos\npara aplicar-lhe no rosto sangrando. Agora, que o céu o ajude! Saem separadamente."}$tr$::jsonb, 753)
