-- william-shakespeare_macbeth (435 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_macbeth', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","adesertplace~adesertplace~12":"Um lugar deserto.","thunderandlightningenterthreewitches~ghtningenterthreewitches~36":"Trovões e relâmpagos. Entram três Bruxas.","firstwitchwhenshallwethreemeetagaininthu~thunderlightningorinrain~61":"Primeira Bruxa — Quando nos reuniremos as três outra vez\nNo trovão, no relâmpago ou na chuva?","secondwitchwhenthehurlyburlysdonewhenthe~whenthebattleslostandwon~57":"Segunda Bruxa — Quando o alvoroço acabar,\nQuando a batalha for perdida e ganha.","thirdwitchthatwillbeerethesetofsun~thatwillbeerethesetofsun~34":"Terceira Bruxa — Isso será antes de o sol se pôr.","firstwitchwheretheplace~firstwitchwheretheplace~23":"Primeira Bruxa — E o lugar?","secondwitchupontheheath~secondwitchupontheheath~23":"Segunda Bruxa — Na charneca.","thirdwitchtheretomeetwithmacbeth~chtheretomeetwithmacbeth~32":"Terceira Bruxa — Lá, para encontrar Macbeth.","firstwitchicomegraymalkin~irstwitchicomegraymalkin~25":"Primeira Bruxa — Já vou, Graymalkin!","secondwitchpaddockcalls~secondwitchpaddockcalls~23":"Segunda Bruxa — O Sapo chama.","thirdwitchanon~thirdwitchanon~14":"Terceira Bruxa — Já.","allfairisfoulandfoulisfairhoverthroughth~thefogandfilthyairexeunt~62":"Todas — O belo é feio, e o feio é belo:\nPairemos pela névoa e pelo ar imundo. Saem.","sceneii~sceneii~7":"Cena II","acampnearforres~acampnearforres~15":"Um acampamento perto de Forres.","alarumwithinenterduncanmalcolmdonalbainl~meetingableedingsergeant~83":"Toque de alarme ao longe. Entram Duncan, Malcolm, Donalbain, Lennox e Criados, ao encontro de um Sargento ensanguentado.","duncanwhatbloodymanisthathecanreportasse~ftherevolttheneweststate~81":"Duncan — Quem é aquele homem coberto de sangue? Ele pode informar,\nPelo que sua condição indica, sobre a revolta\nO estado mais recente.","malcolmthisisthesergeantwholikeagoodandh~ebroilasthoudidstleaveit~141":"Malcolm — Este é o sargento\nQue, como bom e valente soldado, lutou\nPara me livrar do cativeiro. Salve, bravo amigo!\nDize ao rei o que sabes da refrega\nTal como a deixaste.","sergeantdoubtfulitstoodastwospentswimmer~isheaduponourbattlements~559":"Sargento — Duvidosa ela estava;\nComo dois nadadores exaustos que se agarram um ao outro\nE sufocam a própria arte. O impiedoso Macdonwald —\nDigno de ser rebelde, pois para isso\nAs multiplicadas vilanias da natureza\nEnxameiam sobre ele — das ilhas ocidentais\nÉ suprido de kerns e gallowglasses;\nE a fortuna, sorrindo à sua causa maldita,\nParecia a prostituta de um rebelde: mas tudo era fraco demais:\nPois o bravo Macbeth — bem merece esse nome —\nDesdenhando a fortuna, com seu aço brandido,\nQue fumegava de sangrenta execução,\nComo favorito da valentia abriu a sua passagem\nAté enfrentar o canalha;\nQue nem lhe apertou a mão, nem lhe disse adeus,\nAté o rasgar desde o umbigo até as queixadas,\nE fixar-lhe a cabeça em nossas ameias.","duncanovaliantcousinworthygentleman~antcousinworthygentleman~35":"Duncan — Ó valente primo! digno cavalheiro!","sergeantaswhencethesunginshisreflections~sofmenbeganafreshassault~320":"Sargento — Assim como de onde o sol começa a sua reflexão\nTempestades que naufragam e trovões terríveis irrompem,\nAssim da fonte de onde parecia vir o conforto\nO desconforto transborda. Atende, rei da Escócia, atende:\nMal a justiça, armada de valor,\nObrigara esses kerns saltitantes a confiar nos calcanhares,\nO senhor norueguês, avaliando a vantagem,\nCom armas areadas e novos reforços de homens\nComeçou um novo assalto.","duncandismaydnotthisourcaptainsmacbethan~captainsmacbethandbanquo~47":"Duncan — Isso não desanimou\nNossos capitães, Macbeth e Banquo?","sergeantyesassparrowseaglesortheharethel~mfaintmygashescryforhelp~249":"Sargento — Sim;\nComo pardais a águias, ou a lebre ao leão.\nSe digo a verdade, devo relatar que eles eram\nComo canhões sobrecarregados de dupla carga, tanto\nDobrando e redobrando golpes sobre o inimigo:\nA não ser que pretendessem banhar-se em feridas fumegantes\nOu perpetuar a memória de outro Gólgota,\nNão sei dizer.\nMas estou fraco, meus ferimentos pedem socorro.","duncansowellthywordsbecometheeasthywound~eantattendedwhocomeshere~110":"Duncan — Tão bem te ornam as palavras como as feridas;\nAmbas têm sabor de honra. Ide buscar-lhe cirurgiões. Sai o Sargento, acompanhado.\nQuem vem aí?","enterross~enterross~9":"Entra Ross.","malcolmtheworthythaneofross~colmtheworthythaneofross~27":"Malcolm — O digno barão de Ross.","lennoxwhatahastelooksthroughhiseyessosho~eemstospeakthingsstrange~78":"Lennox — Que pressa transparece em seus olhos! Assim deve olhar\nQuem parece falar de coisas estranhas.","rossgodsavetheking~rossgodsavetheking~18":"Ross — Deus salve o rei!","duncanwhencecamestthouworthythane~ncecamestthouworthythane~33":"Duncan — De onde vens, digno barão?","rossfromfifegreatkingwherethenorweyanban~ncludethevictoryfellonus~337":"Ross — De Fife, grande rei;\nOnde os estandartes noruegueses zombam do céu\nE abanam gelo em nossa gente. O próprio rei da Noruega,\nCom terríveis multidões,\nAuxiliado por esse desleal traidor,\nO barão de Cawdor, iniciou um funesto combate;\nAté que o noivo de Belona, revestido de armadura à prova,\nO enfrentou com igualdades de si mesmo,\nPonta contra ponta rebelde, braço contra braço,\nRefreando-lhe o espírito pródigo: e, para concluir,\nA vitória coube a nós.","duncangreathappiness~duncangreathappiness~20":"Duncan — Grande ventura!","rossthatnowswenothenorwayskingcravescomp~nddollarstoourgeneraluse~144":"Ross — Que agora\nSweno, o rei dos noruegueses, implora um acordo;\nNem consentimos em dar sepultura a seus homens\nAntes que desembolsasse na ilha de Saint Colme\nDez mil dólares para o uso geral de nossa causa.","duncannomorethatthaneofcawdorshalldeceiv~sformertitlegreetmacbeth~116":"Duncan — Nunca mais esse barão de Cawdor enganará\nNossa mais íntima confiança: vai, pronuncia sua morte imediata,\nE com o seu antigo título saúda Macbeth.","rossillseeitdone~rossillseeitdone~16":"Ross — Verei que seja feito.","duncanwhathehathlostnoblemacbethhathwone~oblemacbethhathwonexeunt~45":"Duncan — O que ele perdeu o nobre Macbeth ganhou. Saem.","sceneiii~sceneiii~8":"Cena III","aheathnearforres~aheathnearforres~16":"Uma charneca perto de Forres.","thunderenterthethreewitches~nderenterthethreewitches~27":"Trovões. Entram as três Bruxas.","firstwitchwherehastthoubeensister~hwherehastthoubeensister~33":"Primeira Bruxa — Onde estiveste, irmã?","secondwitchkillingswine~secondwitchkillingswine~23":"Segunda Bruxa — Matando porcos.","thirdwitchsisterwherethou~hirdwitchsisterwherethou~25":"Terceira Bruxa — E tu, irmã?","firstwitchasailorswifehadchestnutsinherl~tataililldoilldoandilldo~221":"Primeira Bruxa — A mulher de um marinheiro tinha castanhas no regaço,\ne mastigava, e mastigava, e mastigava. “Dá-me”, disse eu.\n“Fora, bruxa!”, grita a gorda e sarnenta.\nO marido dela foi a Alepo, capitão do Tigre:\nmas numa peneira para lá navegarei,\ne, como um rato sem cauda,\nfarei, farei, e farei.","secondwitchillgivetheeawind~ondwitchillgivetheeawind~27":"Segunda Bruxa — Eu te darei um vento.","firstwitchthourtkind~firstwitchthourtkind~20":"Primeira Bruxa — És bondosa.","thirdwitchandianother~thirdwitchandianother~21":"Terceira Bruxa — E eu, outro.","firstwitchimyselfhavealltheotherandtheve~tempesttostlookwhatihave~303":"Primeira Bruxa — Eu mesma tenho todos os demais,\ne os próprios portos que eles sopram,\ntodos os rumos que conhecem\nna carta do navegante.\nHei de secá-lo como feno:\no sono, nem de noite nem de dia,\npenderá da pálpebra dele;\nviverá como homem proscrito:\npor nove vezes nove semanas cansadas\ndefinhará, mirrará e penará:\nembora seu barco não possa perder-se,\nserá ainda assim açoitado pela tempestade.\nVede o que tenho.","secondwitchshowmeshowme~secondwitchshowmeshowme~23":"Segunda Bruxa — Mostra, mostra.","firstwitchhereihaveapilotsthumbwreckdash~ewardhedidcomedrumwithin~66":"Primeira Bruxa — Aqui tenho o polegar de um piloto,\nnaufragado quando voltava para casa. Tambor, dentro.","thirdwitchadrumadrummacbethdothcome~drumadrummacbethdothcome~35":"Terceira Bruxa — Um tambor, um tambor!\nMacbeth vem vindo.","alltheweirdsistershandinhandpostersofthe~inepeacethecharmswoundup~143":"Todas — As irmãs fatídicas, de mãos dadas,\nmensageiras do mar e da terra,\nassim vão rodando, rodando:\ntrês voltas para ti e três para mim\ne outras três, para completar nove.\nPaz! O encanto está enrolado.","entermacbethandbanquo~entermacbethandbanquo~21":"Entram Macbeth e Banquo.","macbethsofoulandfairadayihavenotseen~landfairadayihavenotseen~36":"Macbeth — Tão feio e tão belo dia nunca vi.","banquohowfaristcalldtoforreswhatarethese~etointerpretthatyouareso~293":"Banquo — A quanto se diz que está Forres? Que são estas,\ntão mirradas e tão selvagens no vestir,\nque não parecem habitantes da terra,\ne no entanto estão nela? Viveis? Ou sois algo\nque o homem possa interrogar? Pareceis entender-me,\npois cada uma, ao mesmo tempo, põe o dedo rachado\nnos lábios descarnados: deveríeis ser mulheres,\ne no entanto as barbas vos proíbem de interpretar\nque o sejais.","macbethspeakifyoucanwhatareyou~hspeakifyoucanwhatareyou~30":"Macbeth — Falai, se podeis: quem sois?","firstwitchallhailmacbethhailtotheethaneo~hhailtotheethaneofglamis~47":"Primeira Bruxa — Salve, Macbeth! Salve a ti, barão de Glamis!","secondwitchallhailmacbethhailtotheethane~hhailtotheethaneofcawdor~48":"Segunda Bruxa — Salve, Macbeth! Salve a ti, barão de Cawdor!","thirdwitchallhailmacbeththoushaltbekingh~thoushaltbekinghereafter~48":"Terceira Bruxa — Salve, Macbeth, que serás rei no futuro!","banquogoodsirwhydoyoustartandseemtofeart~aryourfavoursnoryourhate~368":"Banquo — Bom senhor, por que estremeceis e pareceis temer\ncoisas que soam tão belas? Em nome da verdade,\nsois fantásticas ou sois de fato\no que por fora mostrais? Ao meu nobre companheiro\nsaudais com graça presente e grande predição\nde nobre posse e de real esperança,\nde modo que ele parece arrebatado: a mim nada dizeis.\nSe podeis olhar as sementes do tempo\ne dizer qual grão crescerá e qual não,\nfalai então a mim, que nem peço nem temo\nvossos favores ou vosso ódio.","firstwitchhail~firstwitchhail~14":"Primeira Bruxa — Salve!","secondwitchhail~secondwitchhail~15":"Segunda Bruxa — Salve!","thirdwitchhail~thirdwitchhail~14":"Terceira Bruxa — Salve!","firstwitchlesserthanmacbethandgreater~serthanmacbethandgreater~37":"Primeira Bruxa — Menor que Macbeth, e maior.","secondwitchnotsohappyyetmuchhappier~notsohappyyetmuchhappier~35":"Segunda Bruxa — Não tão feliz, contudo muito mais feliz.","thirdwitchthoushaltgetkingsthoughthouben~oallhailmacbethandbanquo~68":"Terceira Bruxa — Gerarás reis, embora não o sejas:\nassim, salve, Macbeth e Banquo!","firstwitchbanquoandmacbethallhail~hbanquoandmacbethallhail~33":"Primeira Bruxa — Banquo e Macbeth, salve!","macbethstayyouimperfectspeakerstellmemor~kichargeyouwitchesvanish~328":"Macbeth — Esperai, falantes imperfeitas, dizei-me mais:\npela morte de Sinel sei que sou barão de Glamis;\nmas de Cawdor, como? O barão de Cawdor vive,\num fidalgo próspero; e ser rei\nnão está no horizonte do crível,\nnão mais que ser Cawdor. Dizei de onde\ntirais essa estranha notícia? Ou por que\nnesta charneca ressequida nos barrais o caminho\ncom tal saudação profética? Falai, eu vos ordeno. As Bruxas desaparecem.","banquotheearthhathbubblesasthewaterhasan~hemwhitheraretheyvanishd~76":"Banquo — A terra tem bolhas, como a água tem,\ne estas são delas. Para onde sumiram?","macbethintotheairandwhatseemdcorporalmel~thewindwouldtheyhadstayd~79":"Macbeth — No ar; e o que parecia corpóreo derreteu-se\ncomo alento no vento. Tivessem ficado!","banquoweresuchthingshereaswedospeakabout~attakesthereasonprisoner~94":"Banquo — Estavam aqui as coisas de que falamos?\nOu comemos da raiz insana\nque aprisiona a razão?","macbethyourchildrenshallbekings~yourchildrenshallbekings~31":"Macbeth — Teus filhos serão reis.","banquoyoushallbeking~banquoyoushallbeking~20":"Banquo — Tu serás rei.","macbethandthaneofcawdortoowentitnotso~neofcawdortoowentitnotso~37":"Macbeth — E barão de Cawdor também: não foi assim?","banquototheselfsametuneandwordswhoshere~sametuneandwordswhoshere~39":"Banquo — Na mesma melodia e nas mesmas palavras. Quem vem aí?","enterrossandangus~enterrossandangus~17":"Entram Ross e Angus.","rossthekinghathhappilyreceivedmacbeththe~ndpourdthemdownbeforehim~405":"Ross — O rei recebeu com alegria, Macbeth,\na notícia do teu êxito; e quando lê\ntua ousadia pessoal no combate contra os rebeldes,\nseu espanto e seu louvor disputam\nqual deve ser teu ou dele: calado com isso,\nao rever o resto do mesmo dia,\nacha-te nas fileiras do bravo norueguês,\nnada temendo o que tu mesmo fazias,\nestranhas imagens de morte. Densos como granizo\nchegaram mensageiro após mensageiro; e cada um trazia\nteus louvores pela grande defesa do seu reino\ne os despejava diante dele.","anguswearesenttogivetheefromourroyalmast~eeintohissightnotpaythee~86":"Angus — Fomos enviados\npara dar-te agradecimentos de nosso real senhor;\napenas para te conduzir à sua presença,\nnão para te pagar.","rossandforanearnestofagreaterhonourhebad~tworthythaneforitisthine~117":"Ross — E, como penhor de maior honra,\nmandou-me, da parte dele, chamar-te barão de Cawdor:\ncom este título, salve, digníssimo barão!\nPois é teu.","banquowhatcanthedevilspeaktrue~whatcanthedevilspeaktrue~30":"Banquo — Quê, pode o diabo dizer a verdade?","macbeththethaneofcawdorliveswhydoyoudres~youdressmeinborrowdrobes~57":"Macbeth — O barão de Cawdor vive: por que me vestis\ncom roupas emprestadas?","anguswhowasthethanelivesyetbutunderheavy~dprovedhaveoverthrownhim~261":"Angus — Quem era o barão vive ainda;\nmas sob pesado julgamento carrega a vida\nque merece perder. Se ele se aliou\naos da Noruega, ou forrou o rebelde\ncom ajuda e vantagem ocultas, ou se com ambos\ntrabalhou pela ruína do seu país, não sei;\nmas traições capitais, confessadas e provadas,\no derrubaram.","macbethasideglamisandthaneofcawdorthegre~tomepromisednolesstothem~186":"Macbeth — À parte. Glamis, e barão de Cawdor!\nO maior vem depois. A Ross e Angus. Obrigado pelo vosso trabalho.\nA Banquo. Não esperais que vossos filhos sejam reis,\nquando os que me deram o baronato de Cawdor\nnão menos prometeram a eles?","banquothattrustedhomemightyetenkindleyou~encecousinsawordiprayyou~224":"Banquo — Isso, confiado até o fim,\npoderia ainda acender-vos para a coroa,\nalém do baronato de Cawdor. Mas é estranho:\ne muitas vezes, para nos ganhar para o nosso mal,\nos instrumentos das trevas nos dizem verdades,\nganham-nos com ninharias honestas, para trair-nos\nnas mais profundas consequências.\nPrimos, uma palavra, peço-vos.","macbethasidetwotruthsaretoldashappyprolo~andnothingisbutwhatisnot~500":"Macbeth — À parte. Duas verdades foram ditas,\ncomo felizes prólogos ao ato crescente\ndo tema imperial. — Agradeço-vos, senhores.\nÀ parte. Este solicitar sobrenatural\nnão pode ser mau, não pode ser bom: se mau,\npor que me deu penhor de êxito,\ncomeçando por uma verdade? Sou barão de Cawdor:\nse bom, por que cedo àquela sugestão\ncuja imagem horrenda me desprende os cabelos\ne faz o coração assentado bater-me nas costelas,\ncontra o uso da natureza? Os temores presentes\nsão menores que as imaginações horríveis:\nmeu pensamento, cujo assassínio é ainda apenas fantasia,\nabala de tal modo meu único estado de homem que a função\nse sufoca na conjetura, e nada existe\nsenão o que não existe.","banquolookhowourpartnersrapt~uolookhowourpartnersrapt~28":"Banquo — Vede como nosso companheiro está absorto.","macbethasideifchancewillhavemekingwhycha~emaycrownmewithoutmystir~66":"Macbeth — À parte. Se o acaso quer que eu seja rei, ora, o acaso pode coroar-me,\nsem que eu me mova.","banquonewhonourscomeuponhimlikeourstrang~rmouldbutwiththeaidofuse~88":"Banquo — Novas honras vêm sobre ele,\ncomo nossas roupas novas, que não se amoldam ao corpo\nsenão com a ajuda do uso.","macbethasidecomewhatcomemaytimeandthehou~unsthroughtheroughestday~66":"Macbeth — À parte. Venha o que vier,\no tempo e a hora correm pelo mais áspero dia.","banquoworthymacbethwestayuponyourleisure~ethwestayuponyourleisure~40":"Banquo — Digno Macbeth, esperamos o vosso vagar.","macbethgivemeyourfavourmydullbrainwaswro~ourfreeheartseachtoother~245":"Macbeth — Perdoai-me: meu cérebro embotado se ocupava\nde coisas esquecidas. Bons senhores, vossos esforços\nestão registrados onde todo dia viro\na folha para lê-los. Vamos ao rei.\nPensai no que sucedeu e, com mais tempo,\ntendo o intervalo ponderado, falemos\nde coração livre uns aos outros.","banquoverygladly~banquoverygladly~16":"Banquo — De muito bom grado.","macbethtillthenenoughcomefriendsexeunt~nenoughcomefriendsexeunt~38":"Macbeth — Até então, basta. Vamos, amigos. Saem.","sceneiv~sceneiv~7":"Cena IV","forresthepalace~forresthepalace~15":"Forres. O palácio.","flourishenterduncanmalcolmdonalbainlenno~lbainlennoxandattendants~54":"Fanfarra. Entram Duncan, Malcolm, Donalbain, Lennox e Criados.","duncanisexecutiondoneoncawdorarenotthose~seincommissionyetreturnd~62":"Duncan — Está feita a execução de Cawdor? Os\nencarregados ainda não voltaram?","malcolmmyliegetheyarenotyetcomebackbutih~edastwereacarelesstrifle~302":"Malcolm — Meu soberano,\nainda não voltaram. Mas falei\ncom alguém que o viu morrer: ele relatou\nque com toda franqueza confessou suas traições,\nimplorou o perdão de vossa alteza e mostrou\nprofundo arrependimento: nada em sua vida\nlhe assentou como o deixá-la; morreu\ncomo quem estudara a própria morte\npara lançar fora a coisa mais cara que possuía,\ncomo se fosse bagatela descuidada.","duncantheresnoarttofindthemindsconstruct~homibuiltanabsolutetrust~94":"Duncan — Não há arte\nde achar no rosto a feição da alma:\nele era um fidalgo em quem eu fundara\nabsoluta confiança.","entermacbethbanquorossandangus~acbethbanquorossandangus~30":"Entram Macbeth, Banquo, Ross e Angus.","oworthiestcousinthesinofmyingratitudeeve~duethanmorethanallcanpay~255":"Ó digníssimo primo!\nO pecado da minha ingratidão pesava-me\nainda agora: tão adiante estás\nque a mais veloz asa da recompensa é lenta\npara alcançar-te. Tivesses merecido menos,\npara que a proporção de agradecimento e de pagamento\npudesse ser minha! Só me resta dizer:\nmais te é devido do que tudo pode pagar.","macbeththeserviceandtheloyaltyioweindoin~etowardyourloveandhonour~211":"Macbeth — O serviço e a lealdade que vos devo,\nao serem prestados, pagam-se a si mesmos. A parte de vossa alteza\né receber nossos deveres; e nossos deveres\nsão para com vosso trono e estado filhos e servos,\nque apenas fazem o que devem, fazendo tudo\nem segurança para com vosso amor e honra.","duncanwelcomehitherihavebeguntoplantthee~theeandholdtheetomyheart~176":"Duncan — Bem-vindo aqui:\ncomecei a plantar-te e hei de trabalhar\npara fazer-te pleno de crescimento. Nobre Banquo,\nque não menos mereceste, nem deves ser conhecido\npor menos tê-lo feito, deixa-me abraçar-te\ne apertar-te ao coração.","banquothereifigrowtheharvestisyourown~igrowtheharvestisyourown~37":"Banquo — Se aí eu crescer,\na colheita é vossa.","duncanmyplenteousjoyswantoninfulnessseek~essandbindusfurthertoyou~343":"Duncan — Minhas alegrias abundantes,\nébrias de plenitude, buscam esconder-se\nem gotas de pranto. Filhos, parentes, barões,\ne vós cujos lugares são os mais próximos, sabei\nque firmaremos nosso estado sobre\nnosso primogênito, Malcolm, a quem nomeamos desde já\nPríncipe de Cumberland; honra que não deve\ninvesti-lo sozinha, sem companhia,\nmas sinais de nobreza, como estrelas, brilharão\nsobre todos os merecedores. Daqui a Inverness,\ne obrigai-nos ainda mais a vós.","macbeththerestislabourwhichisnotusedfory~roachsohumblytakemyleave~131":"Macbeth — O resto é fadiga que não se emprega por vós:\nserei eu mesmo o arauto e alegrarei\nos ouvidos de minha esposa com vossa chegada;\nassim, humildemente, despeço-me.","duncanmyworthycawdor~duncanmyworthycawdor~20":"Duncan — Meu digno Cawdor!","macbethasidetheprinceofcumberlandthatisa~arswhenitisdonetoseeexit~214":"Macbeth — À parte. O Príncipe de Cumberland! Eis um degrau\nem que devo cair ou então transpor,\npois jaz em meu caminho. Estrelas, escondei vossos fogos;\nque a luz não veja meus desejos negros e profundos:\nque o olho feche os olhos à mão; contudo seja feito\no que o olho teme ver depois de feito. Sai.","duncantrueworthybanquoheisfullsovalianta~esskinsmanflourishexeunt~163":"Duncan — É verdade, digno Banquo; é de todo tão valente,\ne em seus elogios me alimento;\né banquete para mim. Sigamo-lo,\nele cujo zelo se adiantou para dar-nos boas-vindas:\né um parente sem par. Fanfarra. Saem.","scenev~scenev~6":"Cena V","invernessmacbethscastle~invernessmacbethscastle~23":"Inverness. O castelo de Macbeth.","enterladymacbethreadingaletter~adymacbethreadingaletter~30":"Entra Lady Macbeth, lendo uma carta.","ladymacbeththeymetmeinthedayofsuccessand~emtohavetheecrowndwithal~1116":"Lady Macbeth — “Encontraram-me no dia do êxito: e soube, pelo mais perfeito relato, que têm em si mais que saber mortal. Quando ardia em desejo de interrogá-las mais, fizeram-se ar, no qual se desvaneceram. Enquanto eu estava arrebatado no espanto disso, vieram mensageiros do rei, que me saudou ‘Barão de Cawdor’; título com que, antes, estas irmãs fatídicas me haviam saudado, remetendo-me ao advento do tempo com ‘Salve, rei que hás de ser!’ Julguei bom comunicar-te isto, minha caríssima companheira de grandeza, para que não percas o que é devido à tua alegria, ignorando a grandeza que te é prometida. Guarda-o no coração, e adeus.” Glamis és, e Cawdor; e serás\no que te é prometido: contudo temo tua natureza;\né cheia demais do leite da bondade humana\npara tomar o caminho mais curto: querias ser grande;\nnão te falta ambição, mas te falta\na maldade que deve acompanhá-la: o que queres com ardor,\nqueres com santidade; não jogarias falso,\ne contudo ganharias mal: terias, grande Glamis,\naquilo que clama “Assim deves fazer, se me queres”;\ne aquilo que antes temes fazer\ndo que desejas que fique por fazer.” Corre para cá,\npara que eu derrame meu ânimo em teu ouvido\ne castigue com o valor de minha língua\ntudo o que te impede do círculo de ouro,\ncom que o destino e o auxílio sobrenatural parecem\nquerer coroar-te.","enteramessenger~enteramessenger~15":"Entra um Mensageiro.","whatisyourtidings~whatisyourtidings~17":"Que novas trazes?","messengerthekingcomesheretonight~rthekingcomesheretonight~32":"Mensageiro — O rei vem aqui esta noite.","ladymacbeththourtmadtosayitisnotthymaste~aveinformdforpreparation~88":"Lady Macbeth — Estás louco de dizê-lo:\nTeu senhor não está com ele? Se fosse assim,\nteria avisado para os preparativos.","messengersopleaseyouitistrueourthaneisco~hanwouldmakeuphismessage~136":"Mensageiro — Com vossa licença, é verdade: nosso barão vem vindo:\num dos meus companheiros correu à frente dele,\ne, quase morto de fôlego, mal tinha mais\ndo que o necessário para dar o recado.","ladymacbethgivehimtendinghebringsgreatne~etofthedarktocryholdhold~621":"Lady Macbeth — Dai-lhe cuidados;\ntraz grandes novas. Sai o Mensageiro.\nO próprio corvo está rouco\nao crocitar a entrada fatal de Duncan\nsob minhas ameias. Vinde, espíritos\nque assistis a pensamentos mortais, des-sexuai-me aqui,\ne enchei-me da coroa à ponta do pé, até o topo,\nda mais terrível crueldade! Engrossai-me o sangue;\ntapai o acesso e a passagem ao remorso,\npara que nenhuma visita compungida da natureza\nabale meu feroz propósito nem faça paz entre\nele e o seu efeito! Vinde aos meus seios de mulher\ne tomai meu leite por fel, ministros assassinos,\nonde quer que, em vossas substâncias invisíveis,\nassistais ao mal da natureza! Vem, noite espessa,\ne envolve-te no mais pardo fumo do inferno,\npara que minha faca aguda não veja a ferida que abre,\nnem o céu espie pelo manto das trevas\npara gritar “Pára, pára!”","entermacbeth~entermacbeth~12":"Entra Macbeth.","greatglamisworthycawdorgreaterthanbothby~nowthefutureintheinstant~143":"Grande Glamis! Digno Cawdor!\nMaior que ambos, pelo “salve” que há de vir!\nTuas cartas transportaram-me para além\ndeste presente ignorante, e sinto agora\no futuro no instante.","macbethmydearestloveduncancomesheretonig~veduncancomesheretonight~42":"Macbeth — Meu mais caro amor,\nDuncan vem aqui esta noite.","ladymacbethandwhengoeshence~ymacbethandwhengoeshence~27":"Lady Macbeth — E quando parte?","macbethtomorrowashepurposes~bethtomorrowashepurposes~27":"Macbeth — Amanhã, como pretende.","ladymacbethonevershallsunthatmorrowseeyo~overeignswayandmasterdom~359":"Lady Macbeth — Oh, nunca\no sol verá esse amanhã!\nTeu rosto, meu barão, é como um livro em que os homens\npodem ler estranhas coisas. Para enganar o tempo,\nparece-te com o tempo; traze boas-vindas no olhar,\nna mão, na língua: parece a flor inocente,\nmas sê a serpente debaixo dela. Aquele que vem\ndeve ser provido: e porás\no grande negócio desta noite sob meu cuidado;\no qual a todas as nossas noites e dias por vir\ndará soberano império e senhorio.","macbethwewillspeakfurther~acbethwewillspeakfurther~25":"Macbeth — Falaremos mais.","ladymacbethonlylookupcleartoalterfavoure~eavealltheresttomeexeunt~76":"Lady Macbeth — Apenas mostra o rosto limpo;\nmudar de semblante é sempre sinal de medo:\ndeixa o resto comigo. Saem.","scenevi~scenevi~7":"Cena VI","beforemacbethscastle~beforemacbethscastle~20":"Diante do castelo de Macbeth.","hautboysandtorchesenterduncanmalcolmdona~ffrossangusandattendants~86":"Oboés e tochas. Entram Duncan, Malcolm, Donalbain, Banquo, Lennox, Macduff, Ross, Angus e Criados.","duncanthiscastlehathapleasantseattheairn~tselfuntoourgentlesenses~90":"Duncan — Este castelo tem situação aprazível; o ar\nse recomenda ágil e suave\naos nossos sentidos gentis.","banquothisguestofsummerthetemplehaunting~observedtheairisdelicate~258":"Banquo — Este hóspede do verão,\na andorinha que frequenta os templos,\nprova, com sua moradia amada, que o hálito do céu\ncheira aqui a carícia: não há saliência, friso,\ncontraforte nem canto favorável onde esta ave\nnão tenha feito seu leito suspenso e berço fecundo:\nonde mais se reproduzem e frequentam, tenho notado,\no ar é delicado.","enterladymacbeth~enterladymacbeth~16":"Entra Lady Macbeth.","duncanseeseeourhonourdhostessthelovethat~andthankusforyourtrouble~165":"Duncan — Vede, vede, nossa honrada anfitriã!\nO amor que nos segue por vezes é nosso incômodo,\nque ainda assim agradecemos como amor. Nisto vos ensino\ncomo haveis de pedir a Deus que nos recompense por vosso trabalho\ne agradecer-nos o incômodo.","ladymacbethallourserviceineverypointtwic~ptothemwerestyourhermits~222":"Lady Macbeth — Todo o nosso serviço,\nem cada ponto duas vezes feito e depois feito em dobro,\nseria pobre e simples negócio para competir\ncom as honras fundas e largas com que\nvossa majestade carrega nossa casa: pelas de outrora,\ne pelas dignidades recentes acumuladas sobre elas,\nficamos vossos eremitas.","duncanwheresthethaneofcawdorwecoursedhim~essweareyourguesttonight~190":"Duncan — Onde está o barão de Cawdor?\nSeguimo-lo de perto e tínhamos o propósito\nde ser seus provedores: mas ele cavalga bem;\ne seu grande amor, agudo como a espora, ajudou-o\na chegar em casa antes de nós. Bela e nobre anfitriã,\nsomos vosso hóspede esta noite.","ladymacbethyourservantseverhavetheirsthe~surestilltoreturnyourown~127":"Lady Macbeth — Vossos servos sempre\ntêm suas pessoas e o que é seu em conta,\npara prestar contas ao prazer de vossa alteza,\nrestituindo sempre o que é vosso.","duncangivemeyourhandconductmetominehostw~byyourleavehostessexeunt~113":"Duncan — Dai-me a mão;\nlevai-me ao meu anfitrião: amamo-lo muito\ne continuaremos a conceder-lhe nossas graças.\nCom vossa licença, anfitriã. Saem.","scenevii~scenevii~8":"Cena VII","macbethscastle~macbethscastle~14":"O castelo de Macbeth.","hautboysandtorchesenteraseweranddiversse~thestagethenentermacbeth~101":"Oboés e tochas. Entram um Mestre-sala e vários Criados com pratos e serviço, e atravessam o palco. Depois entra Macbeth.","macbethifitweredonewhentisdonethentwerew~itselfandfallsontheother~982":"Macbeth — Se feito estivesse quando está feito, então bom seria\nque fosse feito depressa: se o assassínio\npudesse prender a consequência numa rede e colher\nno seu cessar o êxito; se este golpe apenas\npudesse ser o tudo e o fim de tudo aqui,\naqui mesmo, neste banco e baixio do tempo,\nsaltaríamos a vida futura. Mas nestes casos\nainda temos juízo aqui; pois só ensinamos\ninstruções sangrentas, que, ensinadas, voltam\npara atormentar o inventor: esta justiça de mãos iguais\nleva os ingredientes de nosso cálice envenenado\naos nossos próprios lábios. Ele está aqui sob dupla confiança:\nprimeiro, sou seu parente e seu súdito,\nambos fortes contra o ato; depois, como seu anfitrião,\ndevia fechar a porta contra o assassino,\nnão empunhar eu mesmo a faca. Além disso, este Duncan\ntem usado seus poderes com tanta mansidão, tem sido\ntão limpo em seu grande ofício, que suas virtudes\npleitearão como anjos, de língua de trombeta, contra\na profunda danação de sua remoção;\ne a piedade, como um recém-nascido nu,\ncavalgando a rajada, ou os querubins do céu, montados\nnos corcéis invisíveis do ar,\nsoprarão o feito horrendo em todos os olhos,\nde modo que as lágrimas afoguem o vento. Não tenho espora\npara picar os flancos do meu intento, senão apenas\na ambição de salto, que se transpõe a si mesma\ne cai do outro lado.","hownowwhatnews~hownowwhatnews~14":"Então! Que novas?","ladymacbethhehasalmostsuppdwhyhaveyoulef~whyhaveyouleftthechamber~51":"Lady Macbeth — Ele quase acabou de cear: por que deixaste a sala?","macbethhathheaskdforme~macbethhathheaskdforme~22":"Macbeth — Perguntou por mim?","ladymacbethknowyounothehas~dymacbethknowyounothehas~26":"Lady Macbeth — Não sabes que sim?","macbethwewillproceednofurtherinthisbusin~tglossnotcastasidesosoon~167":"Macbeth — Não avançaremos mais neste negócio:\nele me honrou há pouco; e comprei\náureas opiniões de gente de toda sorte,\nque agora devem ser usadas em seu mais novo brilho,\nnão postas de lado tão cedo.","ladymacbethwasthehopedrunkwhereinyoudres~dlikethepoorcatitheadage~347":"Lady Macbeth — Estava embriagada a esperança\nde que te vestiste? Dormiu desde então?\nE agora acorda, para parecer tão verde e pálida\ndiante do que fez com tanta liberdade? Doravante\nassim considero o teu amor. Tens medo\nde ser o mesmo em ato e valor próprios\nque és em desejo? Quererias ter aquilo\nque estimas o ornamento da vida\ne viver covarde na tua própria estima,\ndeixando o “não ouso” servir ao “eu quereria”,\ncomo o pobre gato do adágio?","macbethpritheepeaceidaredoallthatmaybeco~amanwhodaresdomoreisnone~66":"Macbeth — Peço-te, paz:\nouso fazer tudo o que convém a um homem;\nquem ouse mais não o é.","ladymacbethwhatbeastwastthenthatmadeyoub~swornasyouhavedonetothis~427":"Lady Macbeth — Que fera foi, então,\nque te fez revelar-me este empreendimento?\nQuando ousavas fazê-lo, eras homem;\ne, para ser mais do que eras, tu serias\nainda tanto mais homem. Nem tempo nem lugar\nentão se ofereciam, e contudo querias criar ambos:\neles se fizeram a si mesmos, e essa sua oportunidade agora\nte desfaz. Já amamentei e sei\nquão terno é amar o bebê que me mama:\neu, enquanto sorria no meu rosto,\narrancaria o mamilo de suas gengivas sem osso\ne lhe esmagaria os miolos, se tivesse jurado como tu\njuraste isto.","macbethifweshouldfail~macbethifweshouldfail~21":"Macbeth — E se falharmos?","ladymacbethwefailbutscrewyourcouragetoth~rtheguiltofourgreatquell~429":"Lady Macbeth — Falharmos!\nAperta a tua coragem até o ponto de fixação,\ne não falharemos. Quando Duncan dormir —\nao que a dura viagem do dia\no convidará profundamente —, seus dois camareiros\neu vencerei de tal modo com vinho e bebedeira\nque a memória, guarda do cérebro,\nserá fumaça, e o receptáculo da razão\num mero alambique: quando em sono suíno\nsuas naturezas encharcadas jazerem como mortas,\nque não poderemos fazer, tu e eu, ao\ndesguarnecido Duncan? Que não poremos\nsobre seus oficiais embebidos, que carregarão a culpa\nde nossa grande matança?","macbethbringforthmenchildrenonlyforthyun~daggersthattheyhavedonet~193":"Macbeth — Só dá à luz filhos varões;\npois teu temperamento intrépido não deve compor\nsenão machos. Não será aceito,\nquando tivermos marcado de sangue os dois sonolentos\nda própria câmara dele e usado seus próprios punhais,\nque foram eles que o fizeram?","ladymacbethwhodaresreceiveitotheraswesha~dclamourroaruponhisdeath~81":"Lady Macbeth — Quem ousará aceitar outra coisa,\nquando fizermos nossas dores e clamores rugirem\nsobre a morte dele?","macbethiamsettledandbendupeachcorporalag~falseheartdothknowexeunt~142":"Macbeth — Estou decidido e retesto\ncada força do corpo para este feito terrível.\nVai, e zomba do tempo com a mais bela aparência:\nrosto falso deve esconder o que o falso coração sabe. Saem.","courtofmacbethscastle~courtofmacbethscastle~21":"Pátio do castelo de Macbeth.","enterbanquoandfleancebearingatorchbefore~cebearingatorchbeforehim~43":"Entram Banquo e Fleance, com uma tocha diante dele.","banquohowgoesthenightboy~banquohowgoesthenightboy~24":"Banquo — Como vai a noite, rapaz?","fleancethemoonisdownihavenotheardthecloc~ownihavenotheardtheclock~41":"Fleance — A lua se pôs; não ouvi o relógio.","banquoandshegoesdownattwelve~uoandshegoesdownattwelve~28":"Banquo — E ela se põe à meia-noite.","fleanceitakettislatersir~fleanceitakettislatersir~24":"Fleance — Creio que é mais tarde, senhor.","banquoholdtakemyswordthereshusbandryinhe~naturegiveswaytoinrepose~202":"Banquo — Toma, segura minha espada. Há economia no céu:\nsuas velas estão todas apagadas. Toma isto também.\nUma pesada convocação jaz como chumbo sobre mim,\ne contudo não quereria dormir: poderes misericordiosos,\nreprimi em mim os pensamentos malditos a que a natureza\ncede no repouso!","entermacbethandaservantwithatorch~ethandaservantwithatorch~33":"Entram Macbeth e um Criado com uma tocha.","givememyswordwhosthere~givememyswordwhosthere~22":"Dá-me a espada.\nQuem vem aí?","macbethafriend~macbethafriend~14":"Macbeth — Um amigo.","banquowhatsirnotyetatrestthekingsabedheh~utupinmeasurelesscontent~189":"Banquo — Quê, senhor, ainda não repousastes? O rei está deitado:\nesteve em extraordinário contentamento e\nenviou grandes dádivas a vossos servidores.\nCom este diamante saúda vossa esposa,\nchamando-a a mais bondosa anfitriã; e se recolheu\nem contentamento sem medida.","macbethbeingunpreparedourwillbecamethese~lseshouldfreehavewrought~83":"Macbeth — Despreparados como estávamos,\nnossa vontade se fez serva da falta;\nde outro modo teria agido com liberdade.","banquoallswellidreamtlastnightofthethree~outheyhaveshowdsometruth~79":"Banquo — Tudo vai bem.\nSonhei na noite passada com as três irmãs fatídicas:\na vós mostraram alguma verdade.","macbethithinknotofthemyetwhenwecanentrea~ssifyouwouldgrantthetime~117":"Macbeth — Não penso nelas:\ncontudo, quando pudermos obter uma hora que sirva,\ngastá-la-íamos em algumas palavras sobre esse assunto,\nse me concedêsseis o tempo.","banquoatyourkindstleisure~anquoatyourkindstleisure~25":"Banquo — Quando for de vosso melhor agrado.","macbethifyoushallcleavetomyconsentwhenti~sitshallmakehonourforyou~64":"Macbeth — Se vos ligardes a meu parecer, quando chegar o momento,\nisso vos fará honra.","banquosoilosenoneinseekingtoaugmentitbut~ceclearishallbecounselld~101":"Banquo — Contanto que eu não perca nenhuma\nao buscar aumentá-la, mas mantenha sempre\nmeu peito franco e a lealdade limpa,\naceitarei conselho.","macbethgoodreposethewhile~acbethgoodreposethewhile~25":"Macbeth — Bom repouso entretanto!","banquothankssirtheliketoyouexeuntbanquoa~ouexeuntbanquoandfleance~49":"Banquo — Obrigado, senhor: igual a vós! Saem Banquo e Fleance.","macbethgobidthymistresswhenmydrinkisread~theetoheavenortohellexit~1170":"Macbeth — Vai dizer à tua senhora que, quando minha bebida estiver pronta,\ntoque o sino. Vai deitar-te. Sai o Criado.\nÉ isto um punhal que vejo diante de mim,\no cabo voltado para a minha mão? Vem, deixa-me empunhar-te.\nNão te tenho, e contudo ainda te vejo.\nNão és tu, visão fatal, sensível\nao tato como à vista? Ou és apenas\num punhal da mente, falsa criação,\nvinda do cérebro oprimido pelo calor?\nAinda te vejo, em forma tão palpável\ncomo este que agora desembainho.\nGuias-me o caminho que eu seguia;\ne tal instrumento eu iria usar.\nMeus olhos são feitos de tolos dos outros sentidos,\nou então valem todos os demais; ainda te vejo,\ne em tua lâmina e punho, gotas de sangue,\nque antes não havia. Não existe tal coisa:\né o negócio sangrento que assim me informa\naos olhos. Agora, sobre metade do mundo,\na natureza parece morta, e sonhos perversos ludibriam\no sono sob cortinas; a feitiçaria celebra\nas oferendas da pálida Hécate, e o assassínio mirrado,\nalertado pela sentinela, o lobo,\ncujo uivo é sua vigília, assim com seu passo furtivo,\ncom as passadas de ultraje de Tarquínio, rumo a seu intento\nmove-se como um fantasma. Tu, terra firme e segura,\nnão ouças meus passos, por onde andam, por medo\nde que tuas próprias pedras falem do meu paradeiro\ne tirem ao tempo o horror presente,\nque agora lhe convém. Enquanto ameaço, ele vive:\npalavras dão fôlego frio demais ao calor dos atos. Soa um sino.\nVou, e está feito; o sino me convida.\nNão o ouças, Duncan; pois é um dobre de finados\nque te convoca ao céu ou ao inferno. Sai.","thesame~thesame~7":"O mesmo lugar.","ladymacbeththatwhichhathmadethemdrunkhat~themwhethertheyliveordie~313":"Lady Macbeth — O que os embebedou me fez ousada;\no que os extinguiu me deu fogo. Escuta! Silêncio!\nFoi a coruja que gritou, o pregoeiro fatal,\nque dá a mais severa boa-noite. Ele está a fazê-lo:\nas portas estão abertas; e os criados empanturrados\nzombam de sua guarda com roncos: droguei-lhes as bebidas,\nde modo que a morte e a natureza disputam sobre eles\nse vivem ou morrem.","macbethwithinwhostherewhatho~ethwithinwhostherewhatho~28":"Macbeth — Dentro. Quem está aí? Eh, ó!","ladymacbethalackiamafraidtheyhaveawakeda~fatherashesleptihaddonet~171":"Lady Macbeth — Ai de mim, receio que tenham despertado\ne não esteja feito. A tentativa e não o ato\nnos perde. Escuta! Deixei os punhais prontos;\nele não podia deixar de achá-los. Se não se parecesse\ncom meu pai ao dormir, eu mesma o teria feito.","myhusband~myhusband~9":"Meu marido!","macbethihavedonethedeeddidstthounotheara~eddidstthounothearanoise~45":"Macbeth — Fiz o feito. Não ouviste um ruído?","ladymacbethiheardtheowlscreamandthecrick~ricketscrydidnotyouspeak~60":"Lady Macbeth — Ouvi a coruja gritar e os grilos cantar.\nNão falaste?","macbethwhen~macbethwhen~11":"Macbeth — Quando?","ladymacbethnow~ladymacbethnow~14":"Lady Macbeth — Agora.","macbethasidescended~macbethasidescended~19":"Macbeth — Quando eu descia?","ladymacbethay~ladymacbethay~13":"Lady Macbeth — Sim.","macbethharkwholiesithesecondchamber~wholiesithesecondchamber~35":"Macbeth — Escuta!\nQuem dorme no segundo quarto?","ladymacbethdonalbain~ladymacbethdonalbain~20":"Lady Macbeth — Donalbain.","macbeththisisasorrysightlookingonhishand~rysightlookingonhishands~41":"Macbeth — É uma triste visão. Olhando as mãos.","ladymacbethafoolishthoughttosayasorrysig~hthoughttosayasorrysight~42":"Lady Macbeth — Tolo pensamento, dizer triste visão.","macbeththeresonedidlaughinssleepandonecr~addressdthemagaintosleep~143":"Macbeth — Um riu durante o sono, e outro gritou “Assassino!”\nde modo que um acordou o outro: parei e os ouvi:\nmas rezaram suas preces e voltaram\na dormir.","ladymacbeththerearetwolodgedtogether~herearetwolodgedtogether~36":"Lady Macbeth — Estão alojados juntos os dois.","macbethonecriedgodblessusandamentheother~whentheydidsaygodblessus~135":"Macbeth — Um gritou “Deus nos abençoe!” e o outro “Amém”;\ncomo se me tivessem visto com estas mãos de carrasco.\nOuvindo-lhes o medo, não pude dizer “Amém”\nquando disseram “Deus nos abençoe!”","ladymacbethconsideritnotsodeeply~ethconsideritnotsodeeply~32":"Lady Macbeth — Não penses nisso tão fundo.","macbethbutwhereforecouldnotipronounceame~ngandamenstuckinmythroat~85":"Macbeth — Mas por que não pude pronunciar “Amém”?\nEu era quem mais precisava de bênção, e “Amém”\nficou-me preso na garganta.","ladymacbeththesedeedsmustnotbethoughtaft~esewayssoitwillmakeusmad~68":"Lady Macbeth — Estes atos não devem ser pensados\ndesse modo; senão nos farão enlouquecer.","macbethmethoughtiheardavoicecrysleepnomo~iefnourisherinlifesfeast~220":"Macbeth — Pareceu-me ouvir uma voz gritar “Não durmais mais!\nMacbeth assassina o sono”, o sono inocente,\no sono que refaz o novelo embaraçado do cuidado,\na morte da vida de cada dia, banho da dura fadiga,\nbálsamo das mentes feridas, segundo prato da grande natureza,\nprincipal alimento no banquete da vida —","ladymacbethwhatdoyoumean~ladymacbethwhatdoyoumean~24":"Lady Macbeth — Que queres dizer?","macbethstillitcriedsleepnomoretoalltheho~emacbethshallsleepnomore~122":"Macbeth — Sempre gritava “Não durmais mais!” a toda a casa:\n“Glamis assassinou o sono, e portanto Cawdor\nnão dormirá mais; Macbeth não dormirá mais.”","ladymacbethwhowasitthatthuscriedwhyworth~thesleepygroomswithblood~249":"Lady Macbeth — Quem foi que assim gritou? Ora, digno barão,\nafrouxas a tua nobre força ao pensar\ncom tal doença do cérebro nas coisas. Vai buscar água\ne lava da mão esta imunda testemunha.\nPor que trouxeste estes punhais do lugar?\nDevem ficar lá: vai levá-los; e unta\nde sangue os criados adormecidos.","macbethillgonomoreiamafraidtothinkwhatih~donelookontagainidarenot~67":"Macbeth — Não irei mais:\ntenho medo de pensar no que fiz;\nolhar de novo não ouso.","ladymacbethinfirmofpurposegivemethedagge~rguiltexitknockingwithin~205":"Lady Macbeth — Fraco de propósito!\nDá-me os punhais: os que dormem e os mortos\nnão passam de pinturas: é o olho de criança\nque teme um diabo pintado. Se ele sangrar,\ndourarei com isso o rosto dos criados;\npois deve parecer culpa deles. Sai. Batidas, dentro.","macbethwhenceisthatknockinghowistwithmew~dinemakingthegreenonered~227":"Macbeth — De onde vem essa batida?\nQue se passa comigo, se todo ruído me apavora?\nQue mãos são estas? Ah! Arrancam-me os olhos.\nTodo o oceano do grande Netuno lavará este sangue\nlimpo da minha mão? Não, esta minha mão antes\ntingirá de encarnado os mares multitudinários,\nfazendo vermelho o verde.","reenterladymacbeth~reenterladymacbeth~18":"Reentra Lady Macbeth.","ladymacbethmyhandsareofyourcolourbutisha~stsopoorlyinyourthoughts~321":"Lady Macbeth — Minhas mãos têm a tua cor; mas tenho vergonha\nde trazer um coração tão branco. Batidas, dentro. Ouço uma batida\nna entrada do sul: recolhamo-nos ao nosso quarto:\num pouco de água nos limpa deste ato:\ncomo é fácil, então! Tua firmeza\nte abandonou. Batidas, dentro. Escuta! Mais batidas.\nVeste a camisola, para que a ocasião não nos chame\ne mostre que estivemos de vigília. Não te percas\ntão pobremente em teus pensamentos.","macbethtoknowmydeedtwerebestnotknowmysel~giwouldthoucouldstexeunt~103":"Macbeth — Para conhecer meu ato, melhor seria não me conhecer. Batidas, dentro.\nAcorda Duncan com tuas batidas! Quisera que pudesses! Saem.","knockingwithinenteraporter~ockingwithinenteraporter~26":"Batidas, dentro. Entra um Porteiro.","porterheresaknockingindeedifamanwereport~bertheporteropensthegate~826":"Porteiro — Aí é que é bater! Se um homem fosse porteiro do portão do inferno, estaria sempre a girar a chave. Batidas, dentro. Toc, toc, toc! Quem é, em nome de Belzebu? Eis um lavrador que se enforcou na expectativa de fartura: entra a tempo; traz guardanapos de sobra; aqui vais suar por isso. Batidas, dentro. Toc, toc! Quem é, em nome do outro diabo? Por minha fé, eis um equivocador, que podia jurar nos dois pratos da balança contra qualquer um; que cometeu traição bastante por amor de Deus, mas não soube equivocar-se para o céu: oh, entra, equivocador. Batidas, dentro. Toc, toc, toc! Quem é? Por minha fé, eis um alfaiate inglês, vindo aqui por roubar pano de um calção francês: entra, alfaiate; aqui podes assar o teu ganso. Batidas, dentro. Toc, toc; nunca sossego! Que sois? Mas este lugar é frio demais para o inferno. Não farei mais de diabo-porteiro: pensei em deixar entrar alguns de todas as profissões que seguem o caminho das primaveras até a fogueira eterna. Batidas, dentro. Já vou, já vou! Peço-vos, lembrai-vos do porteiro. Abre o portão.","entermacduffandlennox~entermacduffandlennox~21":"Entram Macduff e Lennox.","macduffwasitsolatefriendereyouwenttobedt~ttobedthatyoudoliesolate~57":"Macduff — Foi tão tarde, amigo, que te deitaste,\nque dormes até tão tarde?","porterfaithsirwewerecarousingtilltheseco~eatprovokerofthreethings~86":"Porteiro — Por minha fé, senhor, estivemos em festança até o segundo canto do galo: e a bebida, senhor, é grande provocadora de três coisas.","macduffwhatthreethingsdoesdrinkespeciall~esdrinkespeciallyprovoke~48":"Macduff — Que três coisas a bebida provoca em especial?","portermarrysirnosepaintingsleepandurinel~givinghimthelieleaveshim~343":"Porteiro — Ora, senhor, nariz vermelho, sono e urina. A luxúria, senhor, ela provoca e desprovoca; provoca o desejo, mas tira o desempenho: portanto, muita bebida pode-se dizer equivocadora da luxúria: faz dela e a desfaz; aguça-a e a arranca; persuade-a e desanima-a; faz que fique em pé e não fique em pé; em conclusão, equivoca-a num sono e, dando-lhe o desmentido, deixa-a.","macduffibelievedrinkgavetheethelielastni~kgavetheethelielastnight~43":"Macduff — Creio que a bebida te desmentiu esta noite passada.","porterthatitdidsiritheverythroatonmebuti~eyetimadeashifttocasthim~140":"Porteiro — Desmentiu, senhor, pela própria garganta: mas eu me desforrei da mentira dela; e, creio, sendo forte demais para ela, embora às vezes me pegasse pelas pernas, dei um jeito de derrubá-la.","macduffisthymasterstirring~cduffisthymasterstirring~26":"Macduff — Está de pé o teu amo?","ourknockinghasawakedhimherehecomes~ghasawakedhimherehecomes~34":"Nossas batidas o acordaram; aí vem ele.","lennoxgoodmorrownoblesir~lennoxgoodmorrownoblesir~24":"Lennox — Bom dia, nobre senhor.","macbethgoodmorrowboth~macbethgoodmorrowboth~21":"Macbeth — Bom dia a ambos.","macduffisthekingstirringworthythane~ekingstirringworthythane~35":"Macduff — Está de pé o rei, digno barão?","macbethnotyet~macbethnotyet~13":"Macbeth — Ainda não.","macduffhedidcommandmetocalltimelyonhimih~ihavealmostslippdthehour~62":"Macduff — Ordenou-me que o chamasse cedo:\nquase deixei passar a hora.","macbethillbringyoutohim~macbethillbringyoutohim~23":"Macbeth — Eu vos levarei a ele.","macduffiknowthisisajoyfultroubletoyoubut~troubletoyoubutyettisone~49":"Macduff — Sei que isto é para vós um incômodo alegre;\nmas incômodo é.","macbeththelabourwedelightinphysicspainth~physicspainthisisthedoor~51":"Macbeth — O trabalho que nos deleita cura a dor.\nEsta é a porta.","macduffillmakesoboldtocallfortismylimite~rtismylimitedserviceexit~52":"Macduff — Atrever-me-ei a chamar,\npois é meu serviço marcado. Sai.","lennoxgoesthekinghencetoday~noxgoesthekinghencetoday~27":"Lennox — O rei parte hoje daqui?","macbethhedoeshedidappointso~bethhedoeshedidappointso~27":"Macbeth — Parte: assim determinou.","lennoxthenighthasbeenunrulywherewelayour~thwasfeverousanddidshake~281":"Lennox — A noite foi turbulenta: onde dormimos,\nnossas chaminés foram derrubadas; e, dizem,\nouviram-se lamentos no ar; estranhos gritos de morte,\ne profetizando com acentos terríveis\nde funesta combustão e eventos confusos\nrecém-chocados para o tempo de dor: a ave obscura\nclamou a noite toda: alguns dizem que a terra\nestava febril e tremeu.","macbethtwasaroughnight~macbethtwasaroughnight~22":"Macbeth — Foi uma noite áspera.","lennoxmyyoungremembrancecannotparallelaf~annotparallelafellowtoit~49":"Lennox — Minha jovem memória não pode achar\npar para ela.","reentermacduff~reentermacduff~14":"Reentra Macduff.","macduffohorrorhorrorhorrortonguenorheart~annotconceivenornamethee~65":"Macduff — Oh, horror, horror, horror! Nem língua nem coração\npodem conceber-te nem nomear-te!","macbethlennoxwhatsthematter~bethlennoxwhatsthematter~27":"Macbeth\nLennox — Que houve?","macduffconfusionnowhathmadehismasterpiec~hencethelifeothebuilding~130":"Macduff — A confusão fez agora sua obra-prima!\nO mais sacrílego assassínio arrombou\no templo ungido do Senhor e dele roubou\na vida do edifício!","macbethwhatistyousaythelife~bethwhatistyousaythelife~27":"Macbeth — Que dizeis? A vida?","lennoxmeanyouhismajesty~lennoxmeanyouhismajesty~23":"Lennox — Falais de sua majestade?","macduffapproachthechamberanddestroyyours~rrorringthebellbellrings~376":"Macduff — Aproximai-vos do quarto e destruí a vista\ncom uma nova Górgona: não me peçais que fale;\nvede, e então falai vós mesmos. Saem Macbeth e Lennox. Despertai, despertai!\nTocai o sino de alarme. Assassínio e traição!\nBanquo e Donalbain! Malcolm! Despertai!\nSacudi este sono de penugem, arremedo da morte,\ne olhai a própria morte! De pé, de pé, e vede\na imagem do grande juízo! Malcolm! Banquo!\nComo de vossas covas, erguei-vos e andai como espectros,\npara dar rosto a este horror! Tocai o sino. Soa o sino.","ladymacbethwhatsthebusinessthatsuchahide~persofthehousespeakspeak~94":"Lady Macbeth — Que se passa,\npara que tão horrenda trombeta convoque a parlamento\nos que dormem na casa? Falai, falai!","macduffogentleladytisnotforyoutohearwhat~nsearwouldmurderasitfell~93":"Macduff — Oh, gentil senhora,\nnão é para vós ouvir o que posso dizer:\na repetição, em ouvido de mulher,\nmataria ao cair.","enterbanquo~enterbanquo~11":"Entra Banquo.","obanquobanquoourroyalmastersmurderd~uoourroyalmastersmurderd~35":"Oh, Banquo, Banquo,\nnosso real senhor foi assassinado!","ladymacbethwoealaswhatinourhouse~ethwoealaswhatinourhouse~32":"Lady Macbeth — Ai, desgraça!\nQuê, em nossa casa?","banquotoocruelanywheredearduffipritheeco~ctthyselfandsayitisnotso~70":"Banquo — Cruel demais em qualquer lugar.\nCaro Duff, peço-te, desmente-te a ti mesmo\ne dize que não é assim.","reentermacbethandlennoxwithross~macbethandlennoxwithross~31":"Reentram Macbeth e Lennox, com Ross.","macbethhadibutdiedanhourbeforethischance~sisleftthisvaulttobragof~199":"Macbeth — Tivesse eu morrido uma hora antes deste acaso,\nteria vivido um tempo bendito; pois, deste instante em diante,\nnada há de sério na mortalidade:\ntudo são brinquedos: renome e graça morreram;\no vinho da vida foi tirado, e a mera borra\nresta a esta adega para se gabar.","entermalcolmanddonalbain~entermalcolmanddonalbain~24":"Entram Malcolm e Donalbain.","donalbainwhatisamiss~donalbainwhatisamiss~20":"Donalbain — Que há de errado?","macbethyouareanddonotknowtthespringthehe~heverysourceofitisstoppd~97":"Macbeth — Vós, e não o sabeis:\na nascente, a cabeça, a fonte do vosso sangue\nestá estancada; a própria origem dela está estancada.","macduffyourroyalfathersmurderd~fyourroyalfathersmurderd~30":"Macduff — Vosso real pai está assassinado.","malcolmobywhom~malcolmobywhom~14":"Malcolm — Oh, por quem?","lennoxthoseofhischamberasitseemdhaddonet~fewastobetrustedwiththem~192":"Lennox — Os da câmara dele, ao que parecia, o fizeram:\nsuas mãos e rostos estavam todos marcados de sangue;\nassim estavam seus punhais, que sem limpar achamos\nsobre seus travesseiros:\nolhavam fixos, estavam transtornados; a vida de nenhum homem\nestava segura com eles.","macbethoyetidorepentmeofmyfurythatididki~ofmyfurythatididkillthem~46":"Macbeth — Oh, contudo me arrependo de meu furor,\npor tê-los morto.","macduffwhereforedidyouso~macduffwhereforedidyouso~24":"Macduff — Por que o fizestes?","macbethwhocanbewiseamazedtemperateandfur~tcouragetomakesloveknown~388":"Macbeth — Quem pode ser sábio, atônito, moderado e furioso,\nleal e neutro, num momento? Ninguém:\na pressa de meu violento amor\nultrapassou a razão, que hesita. Aqui jazia Duncan,\na pele de prata rendada de seu sangue dourado;\ne as feridas abertas pareciam uma brecha na natureza\npara a entrada devastadora da ruína: ali, os assassinos,\nbanhados nas cores de seu ofício, os punhais\ngrosseiramente embainhados em sangue: quem poderia conter-se,\ntendo um coração para amar, e nesse coração\ncoragem para dar a conhecer seu amor?","ladymacbethhelpmehenceho~ladymacbethhelpmehenceho~24":"Lady Macbeth — Ajudai-me a sair daqui, ó!","macdufflooktothelady~macdufflooktothelady~20":"Macduff — Cuidai da senhora.","malcolmasidetodonalbainwhydoweholdourton~claimthisargumentforours~79":"Malcolm — À parte, a Donalbain. Por que calamos a língua,\nnós, que mais podemos reclamar este assunto como nosso?","donalbainasidetomalcolmwhatshouldbespoke~ayourtearsarenotyetbrewd~120":"Donalbain — À parte, a Malcolm. Que se deve falar aqui, onde nosso destino,\nescondido num buraco de verruma, pode irromper e agarrar-nos?\nVamo-nos;\nnossas lágrimas ainda não foram fermentadas.","malcolmasidetodonalbainnorourstrongsorro~orrowuponthefootofmotion~60":"Malcolm — À parte, a Donalbain. Nem nossa forte dor\nestá ainda pronta a mover-se.","banquolooktotheladyladymacbethiscarriedo~ifightoftreasonousmalice~264":"Banquo — Cuidai da senhora: Lady Macbeth é levada para fora.\nE quando tivermos coberto nossas frágeis nudezes,\nque sofrem expostas, reunamo-nos\ne interroguemos esta obra tão sangrenta,\npara sabê-la mais. Temores e escrúpulos nos abalam:\nestou na grande mão de Deus; e daí\ncombato o desígnio não revelado\nda malícia traiçoeira.","macduffandsodoi~macduffandsodoi~15":"Macduff — E eu também.","allsoall~allsoall~8":"Todos — E todos.","macbethletsbrieflyputonmanlyreadinessand~sandmeetithehalltogether~60":"Macbeth — Vistamos depressa a prontidão viril\ne reunamo-nos juntos no salão.","allwellcontentedexeuntallbutmalcolmanddo~llbutmalcolmanddonalbain~47":"Todos — De pleno acordo. Saem todos, exceto Malcolm e Donalbain.","malcolmwhatwillyoudoletsnotconsortwithth~emandoeseasyilltoengland~108":"Malcolm — Que fareis? Não nos juntemos a eles:\nmostrar uma dor não sentida é ofício\nque o homem falso faz com facilidade. Irei à Inglaterra.","donalbaintoirelandiourseparatedfortunesh~arinbloodthenearerbloody~125":"Donalbain — Eu, à Irlanda; nossa fortuna separada\nnos manterá ambos mais seguros: onde estamos,\nhá punhais nos sorrisos dos homens: quanto mais próximos no sangue,\nmais próximos do sangue.","malcolmthismurderousshaftthatsshothathno~ntheresnomercyleftexeunt~209":"Malcolm — Esta flecha assassina disparada\nainda não pousou, e nosso caminho mais seguro\né evitar a mira. Portanto, a cavalo;\ne não sejamos delicados nas despedidas,\nmas escapemos: há justificativa no furto\nque furta a si mesmo, quando já não resta piedade. Saem.","outsidemacbethscastle~outsidemacbethscastle~21":"Fora do castelo de Macbeth.","enterrossandanoldman~enterrossandanoldman~20":"Entram Ross e um Velho.","oldmanthreescoreandtenicanrememberwellwi~athtrifledformerknowings~143":"Velho — Setenta anos posso lembrar bem:\nno volume desse tempo vi\nhoras terríveis e coisas estranhas; mas esta noite dolorosa\nfez brinquedo do que antes eu sabia.","rossahgoodfatherthouseesttheheavensastro~nlivinglightshouldkissit~233":"Ross — Ah, bom pai,\nvês que os céus, como perturbados pelo ato do homem,\nameaçam seu palco sangrento: pelo relógio, é dia,\ne no entanto a noite escura estrangula a lâmpada viajante:\né predomínio da noite, ou vergonha do dia,\nque as trevas entombem a face da terra,\nquando a luz viva devia beijá-la?","oldmantisunnaturalevenlikethedeedthatsdo~ousingowlhawkdatandkilld~118":"Velho — É contra a natureza,\ncomo o ato que foi cometido. Na terça-feira passada,\num falcão, alteando-se em seu orgulho de posto,\nfoi atacado e morto por uma coruja caçadora de ratos.","rossandduncanshorsesathingmoststrangeand~ywouldmakewarwithmankind~180":"Ross — E os cavalos de Duncan — coisa estranhíssima e certa —,\nbelos e velozes, favoritos de sua raça,\ntornaram-se selvagens, quebraram as baias, escaparam,\nrebelando-se contra a obediência, como se quisessem fazer\nguerra à humanidade.","oldmantissaidtheyeateachother~ntissaidtheyeateachother~29":"Velho — Dizem que comeram uns aos outros.","rosstheydidsototheamazementofmineeyestha~therecomesthegoodmacduff~74":"Ross — Assim fizeram, para espanto dos meus olhos\nque o viram. Eis que vem o bom Macduff.","entermacduff~entermacduff~12":"Entra Macduff.","howgoestheworldsirnow~howgoestheworldsirnow~21":"Como vai o mundo agora, senhor?","macduffwhyseeyounot~macduffwhyseeyounot~19":"Macduff — Ora, não vedes?","rossistknownwhodidthismorethanbloodydeed~idthismorethanbloodydeed~40":"Ross — Sabe-se quem fez este ato mais que sangrento?","macduffthosethatmacbethhathslain~hosethatmacbethhathslain~32":"Macduff — Os que Macbeth matou.","rossalasthedaywhatgoodcouldtheypretend~whatgoodcouldtheypretend~38":"Ross — Ai, que dia!\nQue bem poderiam pretender?","macdufftheyweresuborndmalcolmanddonalbai~onthemsuspicionofthedeed~110":"Macduff — Foram subornados:\nMalcolm e Donalbain, os dois filhos do rei,\nescaparam furtivamente e fugiram; o que lança sobre eles\na suspeita do feito.","rossgainstnaturestillthriftlessambitiont~igntywillfalluponmacbeth~120":"Ross — Ainda contra a natureza!\nAmbição imprudente, que devoras\nos meios da tua própria vida! Então é mui provável\nque a soberania recaia sobre Macbeth.","macduffheisalreadynamedandgonetosconetob~dgonetosconetobeinvested~49":"Macduff — Ele já foi nomeado e partiu para Scone\npara ser investido.","rosswhereisduncansbody~rosswhereisduncansbody~22":"Ross — Onde está o corpo de Duncan?","macduffcarriedtocolmekillthesacredstoreh~sandguardianoftheirbones~84":"Macduff — Levado a Colmekill,\no sagrado depósito de seus predecessores\ne guarda de seus ossos.","rosswillyoutoscone~rosswillyoutoscone~18":"Ross — Ireis a Scone?","macduffnocousinilltofife~macduffnocousinilltofife~24":"Macduff — Não, primo, irei a Fife.","rosswelliwillthither~rosswelliwillthither~20":"Ross — Bem, eu irei para lá.","macduffwellmayyouseethingswelldonetherea~robessiteasierthanournew~78":"Macduff — Bem, possais ver ali as coisas bem feitas: adeus!\nNão suceda que nossas roupas velhas nos sirvam melhor que as novas!","rossfarewellfather~rossfarewellfather~18":"Ross — Adeus, pai.","oldmangodsbenisongowithyouandwiththoseth~adandfriendsoffoesexeunt~82":"Velho — A bênção de Deus vá convosco; e com os\nque fariam bem do mal e amigos dos inimigos! Saem.","banquothouhastitnowkingcawdorglamisallas~tmeupinhopebuthushnomore~329":"Banquo — Tens agora tudo: rei, Cawdor, Glamis, tudo,\ncomo prometeram as mulheres fatídicas, e temo\nque tenhas jogado mui sujo por isso: contudo foi dito\nque não permaneceria em tua posteridade,\nmas que eu mesmo seria a raiz e o pai\nde muitos reis. Se delas vem verdade —\ncomo sobre ti, Macbeth, suas palavras resplandecem —,\nora, pelas verdades que em ti se cumpriram,\nnão poderiam elas ser também meus oráculos\ne firmar-me em esperança? Mas silêncio! Basta.","sennetsoundedentermacbethaskingladymacbe~lordsladiesandattendants~83":"Toque de trombetas. Entram Macbeth, como rei, Lady Macbeth, como rainha, Lennox, Ross, Lordes, Damas e Criados.","macbethheresourchiefguest~acbethheresourchiefguest~25":"Macbeth — Eis o nosso principal convidado.","ladymacbethifhehadbeenforgottenithadbeen~astandallthingunbecoming~82":"Lady Macbeth — Se o tivessem esquecido,\nseria como um vazio em nossa grande festa,\ne de todo inconveniente.","macbethtonightweholdasolemnsuppersirandi~ndillrequestyourpresence~61":"Macbeth — Esta noite damos uma ceia solene, senhor,\ne peço a vossa presença.","banquoletyourhighnesscommanduponmetothew~dissolubletieforeverknit~90":"Banquo — Que vossa alteza\nme ordene; a isso meus deveres\nestão, por laço indissolúvel,\natados para sempre.","macbethrideyouthisafternoon~bethrideyouthisafternoon~27":"Macbeth — Cavalgais esta tarde?","banquoaymygoodlord~banquoaymygoodlord~18":"Banquo — Sim, meu bom senhor.","macbethweshouldhaveelsedesiredyourgoodad~aketomorrowistfaryouride~133":"Macbeth — Não fosse isso, teríamos desejado o vosso bom conselho,\nsempre grave e proveitoso,\nno conselho de hoje; mas o tomaremos amanhã.\nVai longe a cavalgada?","banquoasfarmylordaswillfillupthetimetwix~nightforadarkhourortwain~124":"Banquo — Tão longe, senhor, quanto preencha o tempo\nentre agora e a ceia: se meu cavalo não for melhor,\nterei de tomar emprestada à noite\numa hora escura ou duas.","macbethfailnotourfeast~macbethfailnotourfeast~22":"Macbeth — Não falteis à nossa festa.","banquomylordiwillnot~banquomylordiwillnot~20":"Banquo — Senhor, não faltarei.","macbethwehearourbloodycousinsarebestowdi~tnightgoesfleancewithyou~258":"Macbeth — Ouvimos que nossos sanguinários primos se abrigam\nna Inglaterra e na Irlanda, sem confessar\nseu cruel parricídio, enchendo os ouvintes\nde estranhas invenções: mas disso amanhã,\nquando, junto com isso, houver assuntos de Estado\na requerer-nos em conjunto. Montai: adeus,\naté que volteis à noite. Fleance vai convosco?","banquoaymygoodlordourtimedoescallupons~lordourtimedoescallupons~38":"Banquo — Sim, meu bom senhor: o nosso tempo nos chama.","macbethiwishyourhorsesswiftandsureoffoot~ttendthosemenourpleasure~295":"Macbeth — Desejo vossos cavalos velozes e de pé seguro;\ne assim vos recomendo ao dorso deles.\nAdeus. Sai Banquo.\nSeja cada um senhor de seu tempo\naté as sete da noite: para tornar a companhia\nmais doce de acolher, ficaremos nós mesmo\nsozinho até a hora da ceia: até então, Deus vos guarde! Saem todos, exceto Macbeth e um Criado.\nRapaz, uma palavra: aqueles homens esperam\no nosso prazer?","attendanttheyaremylordwithoutthepalacega~lordwithoutthepalacegate~42":"Criado — Sim, senhor, estão fora do portão do palácio.","macbethbringthembeforeusexitattendanttob~etotheutterancewhosthere~836":"Macbeth — Trazei-os à nossa presença. Sai o Criado. Ser assim é nada;\nmas ser assim com segurança. — Nossos temores em Banquo\ncravam-se fundo; e em sua realeza de natureza\nreina o que seria de temer: muito ele ousa;\ne, a par desse temperamento intrépido do espírito,\ntem uma sabedoria que guia a sua coragem\na agir em segurança. Não há ninguém senão ele\ncujo ser eu receie: e, diante dele,\nmeu Gênio é repreendido, como dizem que o de\nMarco Antônio o foi por César. Ele repreendeu as irmãs\nquando primeiro puseram em mim o nome de rei,\ne mandou-as falar com ele: então, como profetisas,\nsaudaram-no pai de uma linhagem de reis:\nsobre minha cabeça puseram uma coroa infrutífera\ne em minha mão um cetro estéril,\npara ser dali arrancado por mão de outra estirpe,\nsem que filho meu suceda. Se assim for,\npela prole de Banquo é que manchei meu espírito;\npor eles assassinei o bondoso Duncan;\npus rancores no cálice de minha paz\nsó por eles; e minha joia eterna\ndei ao inimigo comum do homem,\npara fazê-los reis, a semente de Banquo reis!\nAntes que isso, venha o destino à liça\ne me defenda até o extremo! Quem está aí!","reenterattendantwithtwomurderers~ttendantwithtwomurderers~32":"Reentra o Criado, com dois Assassinos.","nowgotothedoorandstaytheretillwecallexit~yesterdaywespoketogether~81":"Agora vai à porta e fica lá até chamarmos. Sai o Criado.\nNão foi ontem que falamos juntos?","firstmurdereritwassopleaseyourhighness~twassopleaseyourhighness~38":"Primeiro Assassino — Foi, se apraz a vossa alteza.","macbethwellthennowhaveyouconsiderdofmysp~oncrazedsaythusdidbanquo~330":"Macbeth — Bem, então, agora\nconsiderastes minhas palavras? Sabei\nque foi ele, em tempos passados, quem vos manteve\ntão abaixo da fortuna, o que pensáveis\nser culpa de nossa inocente pessoa: isto vos demonstrei\nem nossa última conferência, passada em prova convosco:\ncomo fostes enganados, como contrariados, os instrumentos,\nquem obrou com eles, e todas as outras coisas que poderiam\ndizer, a meia alma e a entendimento demente,\n“Assim fez Banquo.”","firstmurdereryoumadeitknowntous~rdereryoumadeitknowntous~31":"Primeiro Assassino — Fizestes-nos saber.","macbethididsoandwentfurtherwhichisnowour~veandbeggardyoursforever~232":"Macbeth — Fiz, e fui adiante, o que é agora\no ponto de nosso segundo encontro. Achais\nvossa paciência tão predominante em vossa natureza\nque podeis deixar isto passar? Sois tão evangélicos\nque rezareis por esse bom homem e por sua prole,\ncuja mão pesada vos curvou à sepultura\ne empobreceu os vossos para sempre?","firstmurdererwearemenmyliege~tmurdererwearemenmyliege~28":"Primeiro Assassino — Somos homens, meu soberano.","macbethayinthecatalogueyegoformenashound~ichinhisdeathwereperfect~560":"Macbeth — Sim, no catálogo passais por homens;\ncomo cães de caça e galgos, vira-latas, spaniels, rafeiros,\ncães de pelo, cães d’água e meio-lobos, são chamados\ntodos pelo nome de cães: a lista de valores\ndistingue o veloz, o lento, o sutil,\no de guarda, o caçador, cada um\nsegundo o dom que a natureza pródiga\nencerrou nele, pelo qual recebe\ntítulo particular, além do rol\nque a todos escreve iguais: e assim com os homens.\nOra, se tendes lugar na lista,\nnão na pior fileira da humanidade, dizei-o;\ne porei em vossos peitos tal negócio\ncuja execução afasta vosso inimigo,\nvos prende ao coração e ao amor de nós,\nque trazemos nossa saúde só doentia enquanto ele vive,\ne que com sua morte seria perfeita.","secondmurdereriamonemyliegewhomthevilebl~sswhatidotospitetheworld~114":"Segundo Assassino — Sou um, meu soberano,\na quem os golpes vis e as bofetadas do mundo\nde tal modo enfureceram que não me importa o que\nfaça para afrontar o mundo.","firstmurdererandianothersowearywithdisas~chancetomenditorberidont~107":"Primeiro Assassino — E eu, outro,\ntão cansado de desastres, puxado de cá para lá pela sorte,\nque apostaria a vida em qualquer lance,\npara melhorá-la ou livrar-me dela.","macbethbothofyouknowbanquowasyourenemy~ouknowbanquowasyourenemy~38":"Macbeth — Ambos\nsabeis que Banquo era vosso inimigo.","bothmurdererstruemylord~bothmurdererstruemylord~23":"Ambos os Assassinos — É verdade, senhor.","macbethsoishemineandinsuchbloodydistance~eforsundryweightyreasons~370":"Macbeth — Assim é ele meu; e em tão sangrenta distância\nque cada minuto de seu existir me investe\ncontra o mais fundo da minha vida: e embora eu pudesse\ncom poder descarado varrê-lo da minha vista\ne mandar que a minha vontade o justifique, contudo não devo,\npor certos amigos que são dele e meus,\ncujo afeto não posso perder, mas chorar a queda\ndaquele que eu mesmo derrubei; e daí é\nque solicito a vossa ajuda,\nencobrindo o negócio do olhar comum\npor várias razões de peso.","secondmurdererweshallmylordperformwhatyo~dperformwhatyoucommandus~50":"Segundo Assassino — Faremos, senhor,\no que nos ordenardes.","firstmurdererthoughourlives~stmurdererthoughourlives~27":"Primeiro Assassino — Ainda que nossas vidas —","macbethyourspiritsshinethroughyouwithint~vesapartillcometoyouanon~410":"Macbeth — Vossos ânimos transparecem em vós. Dentro desta hora, no máximo,\naconselhar-vos-ei onde vos postar;\ninformar-vos do perfeito espião do tempo,\no momento exato; pois há de ser feito esta noite,\ne um pouco longe do palácio; sempre lembrando\nque exijo estar limpo de suspeita: e com ele —\npara não deixar tropeços nem remendos na obra —\nFleance, seu filho, que lhe faz companhia,\ncuja ausência não me é menos importante\nque a de seu pai, deve abraçar o destino\ndaquela hora escura. Decidi-vos à parte:\nlogo irei a vós.","bothmurderersweareresolvedmylord~erersweareresolvedmylord~32":"Ambos os Assassinos — Estamos decididos, senhor.","macbethillcalluponyoustraightabidewithin~mustfinditouttonightexit~126":"Macbeth — Chamar-vos-ei já: ficai lá dentro. Saem os Assassinos.\nEstá concluído. Banquo, o voo da tua alma,\nse achar o céu, há de achá-lo esta noite. Sai.","thepalace~thepalace~9":"O palácio.","enterladymacbethandaservant~erladymacbethandaservant~27":"Entram Lady Macbeth e um Criado.","ladymacbethisbanquogonefromcourt~ethisbanquogonefromcourt~32":"Lady Macbeth — Banquo partiu da corte?","servantaymadambutreturnsagaintonight~ambutreturnsagaintonight~36":"Criado — Sim, senhora, mas volta de novo esta noite.","ladymacbethsaytothekingiwouldattendhisle~ndhisleisureforafewwords~57":"Lady Macbeth — Dize ao rei que aguardo o seu vagar\npara poucas palavras.","servantmadamiwillexit~servantmadamiwillexit~21":"Criado — Senhora, direi. Sai.","ladymacbethnoughtshadallsspentwhereourde~uctiondwellindoubtfuljoy~128":"Lady Macbeth — Nada se ganhou, tudo se gastou,\nonde o desejo se obtém sem contentamento:\né mais seguro ser o que destruímos\ndo que pela destruição habitar numa alegria duvidosa.","hownowmylordwhydoyoukeepaloneofsorriestf~outregardwhatsdoneisdone~186":"Então, meu senhor! Por que ficais só,\nfazendo das mais tristes fantasias vossas companheiras,\nusando os pensamentos que deviam ter morrido\ncom aqueles em quem pensais? O que não tem remédio\ndeve ficar sem atenção: o que está feito, está feito.","macbethwehavescotchdthesnakenotkillditsh~othingcantouchhimfurther~487":"Macbeth — Cortamos a cobra, não a matamos:\nela se fechará e será ela mesma, enquanto nossa pobre malícia\ncontinua em perigo de seu dente antigo.\nMas desconjunte-se a armação das coisas, sofram ambos os mundos,\nantes que comamos a nossa refeição com medo e durmamos\nna aflição destes terríveis sonhos\nque nos abalam toda noite: melhor estar com os mortos,\nque, para ganhar nossa paz, mandamos à paz,\ndo que sobre o suplício da mente jazer\nem êxtase sem repouso. Duncan está em sua cova;\ndepois da febre intermitente da vida, dorme bem;\na traição fez o seu pior: nem aço, nem veneno,\nmalícia doméstica, tropa estrangeira, nada\npode tocá-lo mais.","ladymacbethcomeongentlemylordsleekoeryou~alamongyourgueststonight~91":"Lady Macbeth — Vamos;\ngentil senhor, alisai vossos aspectos rudes;\nsede radiante e jovial entre vossos convidados esta noite.","macbethsoshalliloveandsoipraybeyouletyou~rtsdisguisingwhattheyare~219":"Macbeth — Assim farei, amor; e assim, peço-te, faze tu:\nque tua lembrança se volte a Banquo;\ndá-lhe preeminência, com o olhar e com a língua:\ninseguro é o tempo em que devemos\nlavar nossas honras nestas correntes lisonjeiras\ne fazer de nossos rostos máscaras para nossos corações,\ndisfarçando o que eles são.","ladymacbethyoumustleavethis~ymacbethyoumustleavethis~27":"Lady Macbeth — Deveis deixar isto.","macbethofullofscorpionsismyminddearwifet~banquoandhisfleancelives~77":"Macbeth — Oh, cheia de escorpiões está a minha mente, querida esposa!\nSabes que Banquo e seu Fleance vivem.","ladymacbethbutinthemnaturescopysnotetern~hemnaturescopysnoteterne~41":"Lady Macbeth — Mas neles a cópia da natureza não é eterna.","macbeththerescomfortyettheyareassailable~edoneadeedofdreadfulnote~212":"Macbeth — Há consolo ainda; são atacáveis;\nentão sê jovial: antes que o morcego tenha feito\nseu voo de claustro, antes que, ao chamado da negra Hécate,\no escaravelho de élitros, com seus zumbidos sonolentos,\ntenha tocado o bocejante toque da noite, será feito\num ato de pavorosa fama.","ladymacbethwhatstobedone~ladymacbethwhatstobedone~24":"Lady Macbeth — Que se vai fazer?","macbethbeinnocentoftheknowledgedearestch~lsopritheegowithmeexeunt~418":"Macbeth — Sê inocente do conhecimento, queridíssima pombinha,\naté aplaudires o ato. Vem, noite que cegas,\nvenda o olho terno do dia compassivo;\ne com tua mão sangrenta e invisível\ncancela e despedaça aquele grande vínculo\nque me mantém pálido! A luz escurece; e o corvo\nbate asas para o bosque de gralhas:\nas boas coisas do dia começam a pender e a cochilar;\nenquanto os negros agentes da noite despertam para as presas.\nAdmiras-te das minhas palavras: mas fica quieta:\nas coisas ruins começadas se fortalecem pelo mal.\nAssim, peço-te, vem comigo. Saem.","aparknearthepalace~aparknearthepalace~18":"Um parque perto do palácio.","enterthreemurderers~enterthreemurderers~19":"Entram três Assassinos.","firstmurdererbutwhodidbidtheejoinwithus~twhodidbidtheejoinwithus~39":"Primeiro Assassino — Mas quem te mandou juntar-te a nós?","thirdmurderermacbeth~thirdmurderermacbeth~20":"Terceiro Assassino — Macbeth.","secondmurdererheneedsnotourmistrustsince~vetodotothedirectionjust~95":"Segundo Assassino — Não precisa de nossa desconfiança, pois transmite\nnossos ofícios e o que temos a fazer\ncom exata direção.","firstmurdererthenstandwithusthewestyetgl~chesthesubjectofourwatch~151":"Primeiro Assassino — Então fica conosco.\nO poente ainda reluz com algumas listras de dia:\nagora o viajante retardado esporeia depressa\npara ganhar a estalagem a tempo; e se aproxima\no objeto da nossa vigília.","thirdmurdererharkihearhorses~dmurdererharkihearhorses~28":"Terceiro Assassino — Escuta! Ouço cavalos.","banquowithingiveusalightthereho~ithingiveusalightthereho~31":"Banquo — Dentro. Dai-nos uma luz aí, ó!","secondmurdererthentishetherestthatarewit~ationalreadyareithecourt~82":"Segundo Assassino — Então é ele: os demais\nque estão na lista dos esperados\njá estão na corte.","firstmurdererhishorsesgoabout~murdererhishorsesgoabout~29":"Primeiro Assassino — Seus cavalos dão a volta.","thirdmurdereralmostamilebuthedoesusually~alacegatemakeittheirwalk~89":"Terceiro Assassino — Quase uma milha: mas ele costuma,\ncomo todos os homens, daqui ao portão do palácio\nfazer a pé o seu passeio.","secondmurdereralightalight~condmurdereralightalight~26":"Segundo Assassino — Uma luz, uma luz!","enterbanquoandfleancewithatorch~nquoandfleancewithatorch~31":"Entram Banquo e Fleance, com uma tocha.","thirdmurderertishe~thirdmurderertishe~18":"Terceiro Assassino — É ele.","firstmurdererstandtot~firstmurdererstandtot~21":"Primeiro Assassino — Firmes.","banquoitwillberaintonight~anquoitwillberaintonight~25":"Banquo — Vai chover esta noite.","firstmurdererletitcomedowntheysetuponban~omedowntheysetuponbanquo~43":"Primeiro Assassino — Que caia. Atacam Banquo.","banquootreacheryflygoodfleanceflyflyflyt~oslavediesfleanceescapes~79":"Banquo — Oh, traição! Foge, bom Fleance, foge, foge, foge!\nPoderás vingar. Oh, escravo! Morre. Fleance escapa.","thirdmurdererwhodidstrikeoutthelight~rwhodidstrikeoutthelight~36":"Terceiro Assassino — Quem apagou a luz?","firstmurdererwastnottheway~rstmurdererwastnottheway~26":"Primeiro Assassino — Não era o jeito?","thirdmurderertheresbutonedownthesonisfle~esbutonedownthesonisfled~41":"Terceiro Assassino — Só um caiu; o filho fugiu.","secondmurdererwehavelostbesthalfofouraff~elostbesthalfofouraffair~43":"Segundo Assassino — Perdemos\na melhor metade do nosso negócio.","firstmurdererwellletsawayandsayhowmuchis~ndsayhowmuchisdoneexeunt~50":"Primeiro Assassino — Bem, vamo-nos, e digamos quanto está feito. Saem.","thesamehallinthepalace~thesamehallinthepalace~22":"O mesmo lugar. Salão no palácio.","abanquetpreparedentermacbethladymacbethr~lennoxlordsandattendants~67":"Um banquete preparado. Entram Macbeth, Lady Macbeth, Ross, Lennox, Lordes e Criados.","macbethyouknowyourowndegreessitdownatfir~tandlasttheheartywelcome~65":"Macbeth — Conheceis vossos graus; sentai-vos: de início\ne no fim, cordial boas-vindas.","lordsthankstoyourmajesty~lordsthankstoyourmajesty~24":"Lordes — Graças a vossa majestade.","macbethourselfwillminglewithsocietyandpl~ewewillrequireherwelcome~114":"Macbeth — Nós mesmo nos misturaremos à companhia\ne faremos de humilde anfitrião.\nNossa anfitriã guarda o seu estado, mas em boa hora\npediremos a sua acolhida.","ladymacbethpronounceitformesirtoallourfr~eartspeakstheyarewelcome~75":"Lady Macbeth — Pronunciai-a por mim, senhor, a todos os nossos amigos;\npois meu coração diz que são bem-vindos.","firstmurdererappearsatthedoor~murdererappearsatthedoor~29":"O Primeiro Assassino aparece à porta.","macbethseetheyencountertheewiththeirhear~doortheresbloodonthyface~169":"Macbeth — Vede, eles vos retribuem com os agradecimentos dos corações.\nOs dois lados estão iguais: aqui me sentarei no meio:\nsede largos na alegria; logo beberemos uma rodada\nao redor da mesa. Aproximando-se da porta. Há sangue em teu rosto.","firstmurderertisbanquosthen~stmurderertisbanquosthen~27":"Primeiro Assassino — Então é de Banquo.","macbethtisbettertheewithoutthanhewithini~hanhewithinishedispatchd~52":"Macbeth — Melhor em ti por fora que nele por dentro.\nEstá despachado?","firstmurderermylordhisthroatiscutthatidi~hroatiscutthatididforhim~47":"Primeiro Assassino — Senhor, a garganta dele está cortada; fi-lo eu.","macbeththouartthebestothecutthroatsyethe~dstitthouartthenonpareil~101":"Macbeth — Tu és o melhor dos degoladores: contudo é bom\nquem fez o mesmo a Fleance: se o fizeste,\nés o sem-par.","firstmurderermostroyalsirfleanceisscaped~troyalsirfleanceisscaped~40":"Primeiro Assassino — Realíssimo senhor,\nFleance escapou.","macbeththencomesmyfitagainihadelsebeenpe~tsandfearsbutbanquossafe~179":"Macbeth — Então volta o meu acesso: de outro modo estaria perfeito,\ninteiro como o mármore, firme como a rocha,\namplo e geral como o ar que envolve:\nmas agora estou encerrado, engaiolado, confinado, preso\na dúvidas e temores insolentes. Mas Banquo está seguro?","firstmurdereraymygoodlordsafeinaditchheb~adtheleastadeathtonature~99":"Primeiro Assassino — Sim, meu bom senhor: seguro numa vala ele jaz,\ncom vinte talhos profundos na cabeça,\no menor deles uma morte para a natureza.","macbeththanksforthattherethegrownserpent~rselvesagainexitmurderer~167":"Macbeth — Obrigado por isso:\nali jaz a serpente crescida; o verme que fugiu\ntem natureza que com o tempo criará veneno,\nmas dentes, no presente, não. Vai-te: amanhã\nouviremos nós mesmos de novo. Sai o Assassino.","ladymacbethmyroyallordyoudonotgivetheche~meetingwerebarewithoutit~188":"Lady Macbeth — Meu real senhor,\nnão dais o ânimo: a festa é vendida\nse não for muitas vezes afiançada, enquanto se faz,\nde que é dada com acolhida: para comer, melhor em casa;\nfora dela, o tempero da carne é a cerimônia;\no encontro seria nu sem ela.","macbethsweetremembrancernowgooddigestion~nappetiteandhealthonboth~69":"Macbeth — Doce lembradora!\nAgora, boa digestão siga o apetite,\ne saúde a ambos!","lennoxmaytpleaseyourhighnesssittheghosto~rsandsitsinmacbethsplace~75":"Lennox — Praza a vossa alteza sentar-se. O Fantasma de Banquo entra e senta-se no lugar de Macbeth.","macbethherehadwenowourcountryshonourroof~nessthanpityformischance~133":"Macbeth — Aqui teríamos agora a honra de nosso país sob o teto,\nestivesse presente a graciosa pessoa de nosso Banquo;\na quem prefiro censurar por descortesia\na lamentar por desgraça!","rosshisabsencesirlaysblameuponhispromise~ceuswithyourroyalcompany~88":"Ross — Sua ausência, senhor,\nlança culpa sobre a sua promessa. Praza a vossa alteza\nhonrar-nos com a sua real companhia.","macbeththetablesfull~macbeththetablesfull~20":"Macbeth — A mesa está cheia.","lennoxhereisaplacereservedsir~xhereisaplacereservedsir~29":"Lennox — Aqui há um lugar reservado, senhor.","macbethwhere~macbethwhere~12":"Macbeth — Onde?","lennoxheremygoodlordwhatistthatmovesyour~istthatmovesyourhighness~48":"Lennox — Aqui, meu bom senhor. Que é que perturba vossa alteza?","macbethwhichofyouhavedonethis~thwhichofyouhavedonethis~29":"Macbeth — Qual de vós fez isto?","lordswhatmygoodlord~lordswhatmygoodlord~19":"Lordes — O quê, meu bom senhor?","macbeththoucanstnotsayididitnevershaketh~vershakethygorylocksatme~54":"Macbeth — Não podes dizer que fui eu: nunca sacudas\ntuas madeixas ensanguentadas para mim.","rossgentlemenrisehishighnessisnotwell~risehishighnessisnotwell~37":"Ross — Senhores, levantai-vos: sua alteza não está bem.","ladymacbethsitworthyfriendsmylordisoften~ndregardhimnotareyouaman~209":"Lady Macbeth — Sentai, dignos amigos: meu senhor é muitas vezes assim,\ne o é desde a juventude: peço-vos, ficai sentados;\no acesso é momentâneo; num pensamento\nele estará bem de novo: se o observardes muito,\nofendê-lo-eis e prolongareis a sua paixão:\ncomei, e não o olheis. Sois homem?","macbethayandaboldonethatdarelookonthatwh~twhichmightappalthedevil~61":"Macbeth — Sim, e ousado, que ouso olhar o que\npoderia apavorar o diabo.","ladymacbethoproperstuffthisistheverypain~lsdoneyoulookbutonastool~267":"Lady Macbeth — Oh, bela coisa!\nIsto é a própria pintura do vosso medo:\neste é o punhal desenhado no ar que, dissestes,\nvos levou a Duncan. Oh, estes sobressaltos e arrancos,\nimpostores do verdadeiro medo, bem convinham\na um conto de mulher ao fogo no inverno,\nautorizado pela avó. Que vergonha!\nPor que fazeis tais caretas? Afinal,\nolhais apenas um banquinho.","macbethpritheeseetherebeholdlooklohowsay~mawsofkitesghostvanishes~177":"Macbeth — Peço-te, vê ali! Vê! Olha! Eis! Que dizes?\nOra, que me importa? Se podes acenar, fala também.\nSe os ossuários e nossas covas devem devolver\naqueles que enterramos, nossos monumentos\nserão os papos dos milhafres. O Fantasma desaparece.","ladymacbethwhatquiteunmanndinfolly~hwhatquiteunmanndinfolly~34":"Lady Macbeth — Quê, de todo desvirilizado na loucura?","macbethifistandhereisawhim~cbethifistandhereisawhim~26":"Macbeth — Tão certo como estou aqui, vi-o.","ladymacbethfieforshame~ladymacbethfieforshame~22":"Lady Macbeth — Ora, que vergonha!","macbethbloodhathbeenshederenowitheoldent~strangethansuchamurderis~311":"Macbeth — Sangue já foi derramado, nos tempos antigos,\nantes que o estatuto humano purgasse a gentil comunidade;\nsim, e depois também, assassínios foram cometidos\nterríveis demais para o ouvido: houve tempos\nem que, saídos os miolos, o homem morria,\ne ali acabava; mas agora ressurgem,\ncom vinte feridas mortais na cabeça,\ne nos empurram de nossos bancos: isto é mais estranho\ndo que tal assassínio.","ladymacbethmyworthylordyournoblefriendsd~ournoblefriendsdolackyou~48":"Lady Macbeth — Meu digno senhor,\nvossos nobres amigos sentem a vossa falta.","macbethidoforgetdonotmuseatmemymostworth~ndhimwethirstandalltoall~273":"Macbeth — Esqueço-me.\nNão vos espanteis de mim, meus dignos amigos;\ntenho uma estranha enfermidade, que nada é\npara os que me conhecem. Vamos, amor e saúde a todos;\nentão me sentarei. Dai-me vinho; enchei até a borda.\nBebo à alegria geral de toda a mesa\ne ao nosso caro amigo Banquo, de quem sentimos falta;\nquisera que estivesse aqui! A todos, e a ele, temos sede,\ne tudo a todos.","lordsourdutiesandthepledge~rdsourdutiesandthepledge~26":"Lordes — Nossos deveres, e o brinde.","reenterghost~reenterghost~12":"Reentra o Fantasma.","macbethavauntandquitmysightlettheearthhi~eswhichthoudostglarewith~135":"Macbeth — Fora! E sai da minha vista! Que a terra te esconda!\nTeus ossos não têm tutano, teu sangue é frio;\nnão há visão nesses olhos\ncom que me fuzilas!","ladymacbeththinkofthisgoodpeersbutasathi~oilsthepleasureofthetime~92":"Lady Macbeth — Pensai nisto, bons pares,\napenas como coisa de costume: não é outra;\nsó estraga o prazer do momento.","macbethwhatmandareidareapproachthouliket~amanagainprayyousitstill~326":"Macbeth — O que homem ousa, ouso eu:\naproxima-te como o rude urso russo,\no rinoceronte armado ou o tigre da Hircânia;\ntoma qualquer forma, menos essa, e meus nervos firmes\nnunca tremerão: ou revive\ne desafia-me ao deserto com tua espada;\nse então eu tremendo ficar em casa, proclama-me\no bebê de uma menina. Fora, sombra horrível!\nIrreal zombaria, fora! O Fantasma desaparece.\nOra, assim: ido ele,\nsou homem de novo. Peço-vos, ficai sentados.","ladymacbethyouhavedisplacedthemirthbroke~gwithmostadmireddisorder~77":"Lady Macbeth — Desfizestes a alegria, quebrastes a boa reunião,\ncom a mais admirável desordem.","macbethcansuchthingsbeandovercomeuslikea~henmineisblanchdwithfear~212":"Macbeth — Podem tais coisas ser,\ne passar sobre nós como nuvem de verão,\nsem especial espanto nosso? Fazeis-me estranho\naté à disposição que possuo,\nquando agora penso que podeis contemplar tais visões\ne conservar o rubi natural de vossas faces,\nenquanto a minha está branqueada de medo.","rosswhatsightsmylord~rosswhatsightsmylord~20":"Ross — Que visões, senhor?","ladymacbethiprayyouspeaknothegrowsworsea~erofyourgoingbutgoatonce~122":"Lady Macbeth — Peço-vos, não falai; ele piora cada vez mais;\nperguntar o enfurece. De uma vez, boa noite:\nnão atendais à ordem da vossa saída,\nmas ide de uma vez.","lennoxgoodnightandbetterhealthattendhism~erhealthattendhismajesty~46":"Lennox — Boa noite; e melhor saúde\nassista a sua majestade!","ladymacbethakindgoodnighttoallexeuntallb~butmacbethandladymacbeth~63":"Lady Macbeth — Uma gentil boa-noite a todos! Saem todos, exceto Macbeth e Lady Macbeth.","macbethitwillhavebloodtheysaybloodwillha~manofbloodwhatisthenight~195":"Macbeth — Terá sangue; dizem que sangue quer sangue:\npedras já se moveram e árvores falaram;\náugures e relações compreendidas\npor pegas, gralhas e corvos revelaram\no mais secreto homem de sangue. Que hora é a noite?","ladymacbethalmostatoddswithmorningwhichi~swithmorningwhichiswhich~46":"Lady Macbeth — Quase em disputa com a manhã, sem se saber qual é qual.","macbethhowsaystthouthatmacduffdenieshisp~spersonatourgreatbidding~62":"Macbeth — Que dizes de Macduff negar sua pessoa\nao nosso grande convite?","ladymacbethdidyousendtohimsir~acbethdidyousendtohimsir~29":"Lady Macbeth — Mandastes a ele, senhor?","macbethihearitbythewaybutiwillsendtheres~eactederetheymaybescannd~368":"Macbeth — Ouço-o de passagem; mas mandarei:\nnão há um deles em cuja casa\neu não tenha um criado pago. Amanhã irei,\ne cedo irei, às irmãs fatídicas:\nmais devem falar; pois agora estou decidido a saber,\npelos piores meios, o pior. Pelo meu bem,\ntodas as causas cederão: estou de sangue\ntão adentro que, se não vadear mais,\nvoltar seria tão penoso quanto atravessar:\ntenho na cabeça coisas estranhas, que passarão à mão;\ne devem ser feitas antes que possam ser examinadas.","ladymacbethyoulacktheseasonofallnaturess~eseasonofallnaturessleep~44":"Lady Macbeth — Falta-vos o tempero de todas as naturezas, o sono.","macbethcomewelltosleepmystrangeandselfab~eyetbutyoungindeedexeunt~104":"Macbeth — Vem, vamos dormir. Meu estranho autoengano\né o medo de iniciante, que carece de duro uso:\nsomos ainda jovens no ato. Saem.","aheath~aheath~6":"Uma charneca.","thunderenterthethreewitchesmeetinghecate~hreewitchesmeetinghecate~40":"Trovões. Entram as três Bruxas, ao encontro de Hécate.","firstwitchwhyhownowhecateyoulookangerly~wnowhecateyoulookangerly~39":"Primeira Bruxa — Ora, que é isso, Hécate! Pareces zangada.","hecatehaveinotreasonbeldamsasyouaresaucy~gycloudandstaysformeexit~978":"Hécate — Não tenho razão, velhas como sois,\ninsolentes e atrevidas? Como ousastes\nnegociar e traficar com Macbeth\nem enigmas e assuntos de morte;\ne eu, a senhora dos vossos encantos,\na secreta artífice de todos os males,\njamais fui chamada a fazer a minha parte\nou a mostrar a glória da nossa arte?\nE, o que é pior, tudo o que fizestes\nfoi só por um filho caprichoso,\nrancoroso e iracundo, que, como os outros,\nama por seus fins, não por vós.\nMas reparai agora: ide-vos,\ne no poço do Aqueronte\nencontrai-me pela manhã: para lá ele\nvirá saber seu destino:\nprovidenciai vossos vasos e vossos feitiços,\nvossos encantos e tudo o mais.\nSou do ar; esta noite a passarei\nnum fim sombrio e fatal:\ngrande obra deve ser feita antes do meio-dia:\nna ponta da lua\npende uma gota vaporosa e profunda;\nhei de colhê-la antes que chegue ao chão:\ne essa, destilada por artes mágicas,\nlevantará tais espíritos artificiais\nque, pela força da sua ilusão,\no atrairão à sua ruína:\ndesprezará o destino, zombará da morte e levará\nsuas esperanças acima da sabedoria, da graça e do medo:\ne todas sabeis que a segurança\né o principal inimigo dos mortais. Música e um canto, dentro: “Venham, venham”, etc.\nEscutai! Sou chamada; meu pequeno espírito, vede,\nestá numa nuvem de névoa e me espera. Sai.","firstwitchcomeletsmakehasteshellsoonbeba~ellsoonbebackagainexeunt~53":"Primeira Bruxa — Vamos, apressemo-nos; logo ela estará de volta. Saem.","enterlennoxandanotherlord~nterlennoxandanotherlord~25":"Entram Lennox e outro Lorde.","lennoxmyformerspeecheshavebuthityourthou~ellwherehebestowshimself~835":"Lennox — Minhas palavras anteriores só tocaram vossos pensamentos,\nque podem interpretar adiante: apenas digo\nque as coisas foram estranhamente conduzidas. O bondoso Duncan\nfoi lamentado por Macbeth: ora, estava morto:\ne o valentíssimo Banquo andou tarde demais;\nde quem, podeis dizer, se vos apraz, que Fleance o matou,\npois Fleance fugiu: os homens não devem andar tarde demais.\nQuem pode deixar de pensar quão monstruoso\nfoi Malcolm e Donalbain\nmatarem o bondoso pai? Ato maldito!\nComo afligiu Macbeth! Não rasgou logo\nem pia fúria os dois delinquentes,\nescravos da bebida e cativos do sono?\nNão foi nobremente feito? Sim, e sabiamente também;\npois teria irritado qualquer coração vivo\nouvir os homens negá-lo. De modo que, digo,\nele conduziu bem todas as coisas: e penso que\nse tivesse os filhos de Duncan sob sua chave —\no que, se apraz ao céu, não terá —, descobririam\no que é matar um pai; assim também Fleance.\nMas, silêncio! Pois por palavras francas e por ter faltado\nà festa do tirano, ouço que\nMacduff vive em desgraça: senhor, podeis dizer\nonde ele se abriga?","lordthesonofduncanfromwhomthistyranthold~paresforsomeattemptofwar~520":"Lorde — O filho de Duncan,\nde quem este tirano retém o direito de nascença,\nvive na corte inglesa e é recebido\npelo piedosíssimo Eduardo com tal graça\nque a malevolência da fortuna nada\ntira de sua alta consideração: para lá Macduff\nfoi rogar ao santo rei que, em seu auxílio,\ndesperte Northumberland e o guerreiro Siward:\nde modo que, com a ajuda destes — e com Aquele lá de cima\na ratificar a obra —, possamos de novo\ndar às nossas mesas carne, às nossas noites sono,\nlivrar nossas festas e banquetes de facas sangrentas,\nprestar leal homenagem e receber livres honras:\ntudo o que agora ansiamos: e esta notícia\nexasperou de tal modo o rei que ele\nprepara alguma tentativa de guerra.","lennoxsenthetomacduff~lennoxsenthetomacduff~21":"Lennox — Mandou ele a Macduff?","lordhedidandwithanabsolutesirnotitheclou~hatclogsmewiththisanswer~126":"Lorde — Mandou: e com um categórico “Senhor, eu não”,\no mensageiro carrancudo me volta as costas\ne resmunga, como quem diz: “Lamentareis o tempo\nque me carrega com esta resposta.”","lennoxandthatwellmightadvisehimtoacautio~ountryunderahandaccursed~215":"Lennox — E isso bem pode\naconselhá-lo à cautela, a manter a distância\nque sua sabedoria possa prover. Algum santo anjo\nvoe à corte da Inglaterra e desdobre\nsua mensagem antes que ele chegue, para que uma pronta bênção\npossa logo voltar a este nosso país sofredor\nsob uma mão maldita!","lordillsendmyprayerswithhimexeunt~ndmyprayerswithhimexeunt~33":"Lorde — Enviarei minhas preces com ele. Saem."}$tr$::jsonb, 435)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_much-ado-about-nothing (650 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_much-ado-about-nothing', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","beforeleonatoshouse~beforeleonatoshouse~19":"Diante da casa de Leonato.","enterleonatoheroandbeatricewithamessenge~ndbeatricewithamessenger~41":"Entram Leonato, Hero e Beatrice, com um Mensageiro.","leonatoilearninthisletterthatdonpedroofa~ncomesthisnighttomessina~69":"Leonato — Fico sabendo por esta carta que Dom Pedro de Aragão chega esta noite a Messina.","messengerheisverynearbythishewasnotthree~eeleaguesoffwhenilefthim~62":"Mensageiro — Já está bem perto: não estava a três léguas quando o deixei.","leonatohowmanygentlemenhaveyoulostinthis~nhaveyoulostinthisaction~46":"Leonato — Quantos cavalheiros perdestes nesta ação?","messengerbutfewofanysortandnoneofname~ewofanysortandnoneofname~37":"Mensageiro — Poucos, de qualquer categoria, e nenhum de nome.","leonatoavictoryistwiceitselfwhentheachie~gflorentinecalledclaudio~138":"Leonato — Uma vitória é duas vezes vitória quando o vencedor traz de volta todos os seus. Vejo aqui que Dom Pedro concedeu muita honra a um jovem florentino chamado Cláudio.","messengermuchdeservedonhispartandequally~stexpectofmetotellyouhow~210":"Mensageiro — Muito merecida da parte dele e igualmente lembrada por Dom Pedro: portou-se além da promessa de sua idade, fazendo, sob a figura de um cordeiro, as façanhas de um leão: superou de fato as expectativas de tal modo que não deveis esperar de mim que vos diga como.","leonatohehathanunclehereinmessinawillbev~nawillbeverymuchgladofit~55":"Leonato — Ele tem um tio aqui em Messina que ficará muito contente com isso.","messengerihavealreadydeliveredhimletters~ithoutabadgeofbitterness~139":"Mensageiro — Já lhe entreguei cartas, e nele se vê muita alegria; tanta, que a alegria não pôde mostrar-se modesta o bastante sem um distintivo de amargura.","leonatodidhebreakoutintotears~todidhebreakoutintotears~29":"Leonato — Rompeu em lágrimas?","messengeringreatmeasure~messengeringreatmeasure~23":"Mensageiro — Em grande medida.","leonatoakindoverflowofkindnessthereareno~patjoythantojoyatweeping~120":"Leonato — Terna transbordação de ternura: não há rostos mais verdadeiros que os assim lavados. Quanto melhor é chorar de alegria do que alegrar-se de chorar!","beatriceiprayyouissigniormountantoreturn~oreturnedfromthewarsorno~57":"Beatrice — Peço-vos, o Senhor Montanto já voltou das guerras ou não?","messengeriknownoneofthatnameladytherewas~nesuchinthearmyofanysort~66":"Mensageiro — Não conheço ninguém desse nome, senhora: não havia nenhum assim no exército, de qualquer categoria.","leonatowhatishethatyouaskforniece~atishethatyouaskforniece~33":"Leonato — Quem é esse por quem perguntas, sobrinha?","heromycousinmeanssigniorbenedickofpadua~nssigniorbenedickofpadua~39":"Hero — Minha prima fala do Senhor Benedito de Pádua.","messengerohesreturnedandaspleasantasever~andaspleasantaseverhewas~45":"Mensageiro — Oh, voltou; e tão divertido como sempre foi.","beatricehesetuphisbillshereinmessinaandc~isedtoeatallofhiskilling~252":"Beatrice — Ele afixou seus cartazes aqui em Messina e desafiou Cupido para um tiro de flecha; e o bobo de meu tio, lendo o desafio, assinou por Cupido e o desafiou com a seta de passarinho. Peço-vos, quantos matou e comeu nessas guerras? Mas quantos matou? Pois na verdade prometi comer tudo o que ele matasse.","leonatofaithnieceyoutaxsigniorbenedickto~bemeetwithyouidoubtitnot~76":"Leonato — Ora, sobrinha, tu censuras demais o Senhor Benedito; mas ele há de se vingar de ti, não duvido.","messengerhehathdonegoodserviceladyinthes~odserviceladyinthesewars~45":"Mensageiro — Ele prestou bons serviços, senhora, nestas guerras.","beatriceyouhadmustyvictualandhehathholpt~hehathanexcellentstomach~97":"Beatrice — Tínheis provisões bolorentas, e ele ajudou a comê-las: é um valentíssimo comilão; tem excelente estômago.","messengerandagoodsoldiertoolady~erandagoodsoldiertoolady~31":"Mensageiro — E um bom soldado também, senhora.","beatriceandagoodsoldiertoaladybutwhatish~oaladybutwhatishetoalord~48":"Beatrice — E um bom soldado para uma dama: mas o que é ele para um lorde?","messengeralordtoalordamantoamanstuffedwi~withallhonourablevirtues~62":"Mensageiro — Um lorde para um lorde, um homem para um homem; recheado de todas as virtudes honradas.","beatriceitissoindeedheisnolessthanastuff~uffingwellweareallmortal~80":"Beatrice — É isso mesmo; não é nada menos que um homem recheado: mas quanto ao recheio — bem, todos somos mortais.","leonatoyoumustnotsirmistakemyniecetherei~skirmishofwitbetweenthem~131":"Leonato — Não deveis, senhor, enganar-vos com minha sobrinha. Há uma espécie de guerra alegre entre o Senhor Benedito e ela: nunca se encontram sem que haja uma escaramuça de espírito entre eles.","beatricealashegetsnothingbythatinourlast~erymonthanewswornbrother~317":"Beatrice — Ai de mim! ele nada ganha com isso. Em nosso último combate, quatro de seus cinco sentidos saíram mancando, e agora o homem todo é governado por um só: de modo que, se ele tiver juízo bastante para se manter aquecido, que o guarde como diferença entre ele e seu cavalo; pois é toda a riqueza que lhe resta, ser conhecido como criatura racional. Quem é seu companheiro agora? Ele tem todo mês um novo irmão de armas jurado.","messengeristpossible~messengeristpossible~20":"Mensageiro — É possível?","beatriceveryeasilypossiblehewearshisfait~rchangeswiththenextblock~93":"Beatrice — Muito facilmente possível: ele usa sua fé como a moda de seu chapéu; muda sempre com a próxima forma.","messengeriseeladythegentlemanisnotinyour~entlemanisnotinyourbooks~45":"Mensageiro — Vejo, senhora, que o cavalheiro não está em vossas boas graças.","beatricenoanhewereiwouldburnmystudybutip~avoyagewithhimtothedevil~123":"Beatrice — Não; se estivesse, queimaria meu gabinete de estudos. Mas, peço-vos, quem é seu companheiro? Não há agora algum jovem brigão que queira fazer com ele uma viagem ao diabo?","messengerheismostinthecompanyoftherightn~nyoftherightnobleclaudio~51":"Mensageiro — Está mais amiúde na companhia do nobilíssimo Cláudio.","beatriceolordhewillhanguponhimlikeadisea~thousandpoundereabecured~187":"Beatriz — Ó Senhor, ele se pendurará nele como uma doença: pega-se mais depressa que a peste, e quem o pega logo enlouquece. Deus ajude o nobre Cláudio! Se pegou o Benedito, custará mil libras antes que se cure.","messengeriwillholdfriendswithyoulady~llholdfriendswithyoulady~36":"Mensageiro — Quero manter amizade convosco, senhora.","beatricedogoodfriend~beatricedogoodfriend~20":"Beatriz — Mantende, bom amigo.","leonatoyouwillneverrunmadniece~oyouwillneverrunmadniece~30":"Leonato — Tu nunca enlouquecerás, sobrinha.","beatricenonottillahotjanuary~ricenonottillahotjanuary~28":"Beatriz — Não, não até um janeiro quente.","messengerdonpedroisapproached~ngerdonpedroisapproached~29":"Mensageiro — Dom Pedro está chegando.","enterdonpedrodonjohnclaudiobenedickandba~udiobenedickandbalthasar~47":"Entram Dom Pedro, Dom João, Cláudio, Benedito e Baltasar.","donpedrogoodsigniorleonatoyouarecometome~oidcostandyouencounterit~103":"Dom Pedro — Bom senhor Leonato, viestes ao encontro do vosso incômodo: o costume do mundo é fugir à despesa, e vós a enfrentais.","leonatonevercametroubletomyhouseinthelik~ndhappinesstakeshisleave~153":"Leonato — Nunca veio incômodo à minha casa com o semblante de vossa graça: pois, ido o incômodo, deveria ficar o conforto; mas, quando partis de mim, fica a tristeza e a alegria se despede.","donpedroyouembraceyourchargetoowillingly~ithinkthisisyourdaughter~64":"Dom Pedro — Abraçais com demasiado gosto o vosso encargo. Creio que esta é vossa filha.","leonatohermotherhathmanytimestoldmeso~herhathmanytimestoldmeso~37":"Leonato — A mãe dela mo disse muitas vezes.","benedickwereyouindoubtsirthatyouaskedher~ndoubtsirthatyouaskedher~40":"Benedito — Tínheis dúvida, senhor, para lho perguntar?","leonatosigniorbenedicknoforthenwereyouac~cknoforthenwereyouachild~44":"Leonato — Senhor Benedito, não; pois então éreis criança.","donpedroyouhaveitfullbenedickwemayguessb~relikeanhonourablefather~132":"Dom Pedro — Levastes o troco inteiro, Benedito: por isso podemos adivinhar o que sois, já homem. Na verdade, a dama dá a ver o pai. Sede feliz, senhora; pois pareceis-vos com um honrado pai.","benedickifsigniorleonatobeherfathershewo~lmessinaaslikehimassheis~100":"Benedito — Se o senhor Leonato é o pai dela, ela não quereria a cabeça dele sobre os ombros por toda a Messina, por mais parecida com ele que seja.","beatriceiwonderthatyouwillstillbetalking~orbenedicknobodymarksyou~69":"Beatriz — Admiro-me que ainda queirais falar, senhor Benedito: ninguém vos dá atenção.","benedickwhatmydearladydisdainareyouyetli~dydisdainareyouyetliving~44":"Benedito — Quê, minha cara Dama Desdém! Ainda viva?","beatriceisitpossibledisdainshoulddiewhil~inifyoucomeinherpresence~141":"Beatriz — É possível que o desdém morra enquanto tem alimento tão adequado quanto o senhor Benedito? A própria cortesia deve converter-se em desdém, se entrardes em sua presença.","benedicktheniscourtesyaturncoatbutitisce~rdheartfortrulyilovenone~145":"Benedito — Então a cortesia é uma vira-casaca. Mas é certo que sou amado por todas as damas, só vós excetuada: e quisera poder achar no coração que não tenho um coração duro; pois, na verdade, não amo ninguém.","beatriceadearhappinesstowomentheywouldel~owthanamanswearhelovesme~176":"Beatriz — Uma felicidade cara às mulheres: senão seriam incomodadas por um pretendente pernicioso. Agradeço a Deus e a meu sangue frio, sou do vosso humor nisso: antes ouvir meu cão ladrar a um corvo do que um homem jurar que me ama.","benedickgodkeepyourladyshipstillinthatmi~redestinatescratchedface~100":"Benedito — Deus conserve vossa senhoria sempre nesse parecer! Assim algum cavalheiro escapará a um rosto arranhado predestinado.","beatricescratchingcouldnotmakeitworseant~weresuchafaceasyourswere~64":"Beatriz — Arranhar não o poderia piorar, se fosse um rosto como o vosso.","benedickwellyouarearareparrotteacher~youarearareparrotteacher~36":"Benedito — Bem, sois uma rara ensinadora de papagaios.","beatriceabirdofmytongueisbetterthanabeas~sbetterthanabeastofyours~48":"Beatriz — Uma ave com minha língua é melhor que uma besta com a vossa.","benedickiwouldmyhorsehadthespeedofyourto~ourwayigodsnameihavedone~95":"Benedito — Quisera que meu cavalo tivesse a rapidez da vossa língua, e tão bom fôlego. Mas segui o vosso caminho, em nome de Deus; acabei.","beatriceyoualwaysendwithajadestrickiknow~ajadestrickiknowyouofold~48":"Beatriz — Acabais sempre com truque de rocim: conheço-vos de velha data.","donpedrothatisthesumofallleonatosigniorc~ritebutpraysfromhisheart~230":"Dom Pedro — Eis a soma de tudo, Leonato. Senhor Cláudio e senhor Benedito, meu caro amigo Leonato vos convidou a todos. Digo-lhe que ficaremos aqui ao menos um mês; e ele pede de coração que alguma ocasião nos detenha mais. Ouso jurar que não é hipócrita, mas pede de coração.","leonatoifyouswearmylordyoushallnotbefors~ourbrotherioweyouallduty~128":"Leonato — Se jurais, senhor, não sereis perjuro. A Dom João. Deixai-me dar-vos boas-vindas, senhor: reconciliado com o príncipe vosso irmão, devo-vos todo o respeito.","donjohnithankyouiamnotofmanywordsbutitha~tofmanywordsbutithankyou~45":"Dom João — Agradeço-vos: não sou de muitas palavras, mas agradeço-vos.","leonatopleaseityourgraceleadon~opleaseityourgraceleadon~30":"Leonato — Praz a vossa graça ir adiante?","donpedroyourhandleonatowewillgotogethere~exceptbenedickandclaudio~72":"Dom Pedro — Vossa mão, Leonato; iremos juntos. Saem todos, exceto Benedito e Cláudio.","claudiobenedickdidstthounotethedaughtero~daughterofsigniorleonato~55":"Cláudio — Benedito, reparaste na filha do senhor Leonato?","benedickinotedhernotbutilookedonher~tedhernotbutilookedonher~35":"Benedito — Não reparei nela; mas olhei-a.","claudioisshenotamodestyounglady~isshenotamodestyounglady~31":"Cláudio — Não é uma jovem dama modesta?","benedickdoyouquestionmeasanhonestmanshou~rofessedtyranttotheirsex~134":"Benedito — Perguntas-me como um homem honesto deve fazer, pelo meu simples e verdadeiro juízo; ou queres que eu fale a meu costume, como declarado tirano do sexo delas?","claudionoipraytheespeakinsoberjudgment~theespeakinsoberjudgment~38":"Cláudio — Não; peço-te que fales em sóbrio juízo.","benedickwhyifaithmethinksshestoolowforah~rbutassheisidonotlikeher~211":"Benedito — Ora, por minha fé, parece-me baixa demais para um alto elogio, morena demais para um elogio de beleza e pequena demais para um grande elogio: só este louvor posso conceder-lhe: que, se fosse diferente do que é, seria feia; e, não sendo outra senão como é, não gosto dela.","claudiothouthinkestiaminsportipraytheete~lmetrulyhowthoulikesther~65":"Cláudio — Pensas que estou a brincar: peço-te que me digas com verdade como a achas.","benedickwouldyoubuyherthatyouinquireafte~erthatyouinquireafterher~44":"Benedito — Queres comprá-la, que perguntas por ela?","claudiocantheworldbuysuchajewel~cantheworldbuysuchajewel~31":"Cláudio — Pode o mundo comprar tal joia?","benedickyeaandacasetoputitintobutspeakyo~amantakeyoutogointhesong~178":"Benedito — Sim, e um estojo para guardá-la. Mas dizes isto com cenho grave? Ou fazes o papel do zombador, a dizer-nos que Cupido é bom caçador de lebres e Vulcano rara carpinteiro? Vamos, em que tom se há de tomar-te, para entrar na canção?","claudioinmineeyesheisthesweetestladythat~estladythateverilookedon~53":"Cláudio — A meus olhos é a mais doce dama que já vi.","benedickicanseeyetwithoutspectaclesandis~tenttoturnhusbandhaveyou~202":"Benedito — Ainda vejo sem óculos e não vejo tal coisa: aí está a prima dela, que, se não estivesse possuída de uma fúria, a excede em beleza tanto como o primeiro de maio o último de dezembro. Mas espero que não tenhas intenção de virar marido, tens?","claudioiwouldscarcetrustmyselfthoughihad~traryifherowouldbemywife~75":"Cláudio — Mal confiaria em mim mesmo, ainda que tivesse jurado o contrário, se Hero quisesse ser minha esposa.","benedickistcometothisinfaithhathnotthewo~pedroisreturnedtoseekyou~234":"Benedito — Chegou-se a isto? Por fé, não tem o mundo um homem que não use o chapéu com desconfiança? Nunca mais verei um solteiro de sessenta anos? Ora vamos, por fé; e queres por força enfiar o pescoço num jugo, trazer-lhe a marca e suspirar os domingos. Olha; Dom Pedro voltou para procurar-te.","reenterdonpedro~reenterdonpedro~15":"Reentra Dom Pedro.","donpedrowhatsecrethathheldyouherethatyou~youfollowednottoleonatos~61":"Dom Pedro — Que segredo vos reteve aqui, que não seguistes para a casa de Leonato?","benedickiwouldyourgracewouldconstrainmet~cewouldconstrainmetotell~45":"Benedito — Quisera que vossa graça me obrigasse a dizer.","donpedroichargetheeonthyallegiance~hargetheeonthyallegiance~34":"Dom Pedro — Ordeno-te, por tua lealdade.","benedickyouhearcountclaudioicanbesecreta~eroleonatosshortdaughter~203":"Benedito — Ouvis, conde Cláudio: sei ser secreto como um mudo; quisera que assim pensásseis; mas, por minha lealdade, notai isto, por minha lealdade. Ele está apaixonado. Por quem? Isso cabe a vossa graça. Notai quão curta é sua resposta: por Hero, a baixinha filha de Leonato.","claudioifthisweresosowereituttered~hisweresosowereituttered~34":"Cláudio — Se isso fosse assim, assim seria dito.","benedickliketheoldtalemylorditisnotsonor~eedgodforbiditshouldbeso~79":"Benedito — Como o velho conto, senhor: “não é assim, nem foi assim, mas, na verdade, Deus não permita que seja assim.”","claudioifmypassionchangenotshortlygodfor~orbiditshouldbeotherwise~62":"Cláudio — Se minha paixão não mudar em breve, Deus não permita que seja de outro modo.","donpedroamenifyouloveherfortheladyisvery~rtheladyisverywellworthy~50":"Dom Pedro — Amém, se a amas; pois a dama é muito digna.","claudioyouspeakthistofetchmeinmylord~eakthistofetchmeinmylord~36":"Cláudio — Dizeis isto para me apanhar, senhor.","donpedrobymytrothispeakmythought~bymytrothispeakmythought~32":"Dom Pedro — Por minha palavra, digo o que penso.","claudioandinfaithmylordispokemine~dinfaithmylordispokemine~33":"Cláudio — E, por fé, senhor, falei o que penso.","benedickandbymytwofaithsandtrothsmylordi~ndtrothsmylordispokemine~49":"Benedito — E, pelas minhas duas fés e palavras, senhor, falei o que penso.","claudiothatiloveherifeel~claudiothatiloveherifeel~24":"Cláudio — Que a amo, sinto.","donpedrothatsheisworthyiknow~edrothatsheisworthyiknow~28":"Dom Pedro — Que ela é digna, sei.","benedickthatineitherfeelhowsheshouldbelo~meiwilldieinitatthestake~129":"Benedito — Que eu nem sinto como ela deve ser amada nem sei como deve ser digna é opinião que o fogo não pode derreter em mim: morrerei nela na fogueira.","donpedrothouwasteveranobstinatehereticin~eticinthedespiteofbeauty~58":"Dom Pedro — Foste sempre um herege obstinado contra a beleza.","claudioandnevercouldmaintainhispartbutin~rtbutintheforceofhiswill~57":"Cláudio — E nunca soube sustentar sua parte senão pela força da vontade.","benedickthatawomanconceivedmeithankherth~efineriwillliveabachelor~314":"Benedito — Que uma mulher me concebeu, agradeço-lhe; que me criou, igualmente lhe dou humílimos agradecimentos: mas que eu leve um toque de caça soado na testa, ou pendure minha trompa num boldrié invisível, todas as mulheres me perdoarão. Para não lhes fazer o agravo de desconfiar de nenhuma, farei a mim o direito de não confiar em nenhuma; e o fim é que, pelo que poderei andar mais elegante, viverei solteiro.","donpedroishallseetheeereidielookpalewith~eereidielookpalewithlove~44":"Dom Pedro — Ver-te-ei, antes de morrer, pálido de amor.","benedickwithangerwithsicknessorwithhunge~seforthesignofblindcupid~214":"Benedito — De raiva, de doença ou de fome, senhor, não de amor: se provardes que perdi alguma vez mais sangue por amor do que recobrarei bebendo, arrancai-me os olhos com a pena de um fazedor de baladas e pendurai-me à porta de um bordel por insígnia do Cupido cego.","donpedrowellifeverthoudostfallfromthisfa~iltproveanotableargument~72":"Dom Pedro — Pois bem, se algum dia caíres desta fé, serás notável argumento.","benedickifidohangmeinabottlelikeacatands~theshoulderandcalledadam~104":"Benedito — Se o fizer, pendurai-me numa garrafa como um gato e atirai-me; e quem me acertar, que lhe deem uma palmada no ombro e o chamem Adão.","donpedrowellastimeshalltryintimethesavag~avagebulldothbeartheyoke~60":"Dom Pedro — Bem, como o tempo provará: “Com o tempo o touro bravio suporta o jugo.”","benedickthesavagebullmaybutifeverthesens~seebenedickthemarriedman~236":"Benedito — O touro bravio talvez; mas se alguma vez o sensato Benedito o suportar, arrancai os chifres ao touro e pregai-mos na testa: e pintai-me vilmente, e em letras grandes como as que escrevem “Aqui há bom cavalo para alugar”, que digam sob a minha insígnia “Aqui podeis ver Benedito, o homem casado.”","claudioifthisshouldeverhappenthouwouldst~ppenthouwouldstbehornmad~49":"Cláudio — Se isto algum dia acontecesse, ficarias louco de chifres.","donpedronayifcupidhavenotspentallhisquiv~uwiltquakeforthisshortly~77":"Dom Pedro — Não, se Cupido não gastou toda a aljava em Veneza, tremerás por isso em breve.","benedickilookforanearthquaketoothen~okforanearthquaketoothen~35":"Benedito — Espero então também um terremoto.","donpedrowellyouwilltemporizewiththehours~hathmadegreatpreparation~170":"Dom Pedro — Bem, contemporizareis com as horas. Entretanto, bom senhor Benedito, ide à casa de Leonato: recomendai-me a ele e dizei-lhe que não lhe faltarei à ceia; pois na verdade ele fez grandes preparativos.","benedickihavealmostmatterenoughinmeforsu~embassageandsoicommityou~68":"Benedito — Tenho quase matéria bastante em mim para tal embaixada; e assim vos confio —","claudiotothetuitionofgodfrommyhouseifiha~ofgodfrommyhouseifihadit~43":"Cláudio — À guarda de Deus: da minha casa, se eu a tivesse —","donpedrothesixthofjulyyourlovingfriendbe~yourlovingfriendbenedick~46":"Dom Pedro — Aos seis de julho: vosso amigo afeiçoado, Benedito.","benedicknaymocknotmocknotthebodyofyourdi~cienceandsoileaveyouexit~185":"Benedito — Não, não zombeis, não zombeis. O corpo do vosso discurso é por vezes guarnecido de retalhos, e as guarnições mal estão alinhavadas: antes de zombardes mais de velhas pontas, examinai a consciência: e assim vos deixo. Sai.","claudiomyliegeyourhighnessnowmaydomegood~urhighnessnowmaydomegood~40":"Cláudio — Meu soberano, vossa alteza pode agora fazer-me bem.","donpedromyloveisthinetoteachteachitbutho~dlessonthatmaydotheegood~103":"Dom Pedro — Meu amor é teu para o ensinares: ensina-o apenas como,\ne verás quão pronto está a aprender\nqualquer lição dura que te possa fazer bem.","claudiohathleonatoanysonmylord~ohathleonatoanysonmylord~30":"Cláudio — Tem Leonato algum filho, senhor?","donpedronochildbutherosheshisonlyheirdos~dostthouaffectherclaudio~61":"Dom Pedro — Nenhum filho além de Hero; ela é sua única herdeira.\nGostas dela, Cláudio?","claudioomylordwhenyouwentonwardonthisend~gilikedherereiwenttowars~309":"Cláudio — Oh, senhor,\nquando partistes para esta ação já terminada,\nolhei-a com olho de soldado,\nque gostou, mas tinha tarefa mais áspera nas mãos\nque levar o gostar ao nome de amor:\nmas agora regressei e os pensamentos de guerra\ndeixaram vagos seus lugares, e em seu lugar\nacorrem em tropel desejos suaves e delicados,\ntodos a lembrar-me quão bela é a jovem Hero,\ndizendo: eu gostava dela antes de ir à guerra.","donpedrothouwiltbelikealoverpresentlyand~gansttotwistsofineastory~205":"Dom Pedro — Logo serás como um amante\ne cansarás o ouvinte com um livro de palavras.\nSe amas a bela Hero, acarinha-o,\ne falarei com ela e com o pai\ne tê-la-ás. Não foi com este fim\nque começaste a tecer tão fina história?","claudiohowsweetlyyoudoministertolovethat~veditwithalongertreatise~139":"Cláudio — Quão docemente servis ao amor,\nvós que conheceis a dor do amor pela cor do rosto!\nMas para que meu gosto não parecesse demasiado súbito,\nqueria tê-lo ungido com mais longo tratado.","donpedrowhatneedthebridgemuchbroaderthan~etusputitpresentlyexeunt~431":"Dom Pedro — Que necessidade tem a ponte de ser mais larga que o rio?\nA mais bela concessão é a necessidade.\nVê, o que serve convém: basta que amas,\ne eu te darei o remédio.\nSei que haverá festança esta noite:\ntomarei teu papel sob algum disfarce\ne direi à bela Hero que sou Cláudio,\ne no seio dela desfecharei meu coração\ne farei prisioneiro o seu ouvido com a força\ne o forte encontro do meu conto amoroso;\ndepois falarei ao pai dela;\ne a conclusão é que ela será tua.\nPonhamo-lo em prática já. Saem.","sceneii~sceneii~7":"Cena II","aroominleonatoshouse~aroominleonatoshouse~20":"Uma sala na casa de Leonato.","enterleonatoandantoniomeeting~leonatoandantoniomeeting~29":"Entram Leonato e Antônio, encontrando-se.","leonatohownowbrotherwhereismycousinyours~nhathheprovidedthismusic~65":"Leonato — Então, irmão? Onde está meu sobrinho, teu filho? Providenciou esta música?","antonioheisverybusyaboutitbutbrotherican~ewsthatyouyetdreamtnotof~79":"Antônio — Está muito ocupado nisso. Mas, irmão, posso contar-te estranhas novas com que ainda não sonhaste.","leonatoaretheygood~leonatoaretheygood~18":"Leonato — São boas?","antonioastheeventstampsthembuttheyhaveag~nstantlybreakwithyouofit~348":"Antônio — Conforme o desfecho as marcar: mas têm boa capa; mostram-se bem por fora. O príncipe e o conde Cláudio, passeando numa alameda de ramos entrelaçados no meu pomar, foram assim ouvidos por um homem meu: o príncipe revelou a Cláudio que amava minha sobrinha, tua filha, e pretendia declará-lo esta noite numa dança; e, se a achasse de acordo, pretendia pegar o presente pelo topete e falar-te logo disso.","leonatohaththefellowanywitthattoldyouthi~lowanywitthattoldyouthis~41":"Leonato — Tem juízo o sujeito que te disse isto?","antonioagoodsharpfellowiwillsendforhiman~imandquestionhimyourself~60":"Antônio — Um bom e esperto sujeito: mandarei chamá-lo; e interroga-o tu mesmo.","leonatononowewillholditasadreamtillitapp~eacarethisbusytimeexeunt~295":"Leonato — Não, não; tomaremos isso por sonho até que se mostre por si: mas avisarei minha filha, para que esteja mais bem preparada para uma resposta, se por acaso for verdade. Vai tu e conta-lhe. Entram criados. Primos, sabeis o que tendes a fazer. Oh, perdão, amigo; vem comigo, e usarei a tua perícia. Bom primo, tem cuidado neste tempo atarefado. Saem.","sceneiii~sceneiii~8":"Cena III","thesame~thesame~7":"O mesmo lugar.","enterdonjohnandconrade~enterdonjohnandconrade~22":"Entram Dom João e Conrado.","conradewhatthegoodyearmylordwhyareyouthu~reyouthusoutofmeasuresad~56":"Conrado — Que diabo, senhor! Por que estais assim triste além da medida?","donjohnthereisnomeasureintheoccasionthat~thesadnessiswithoutlimit~79":"Dom João — Não há medida na causa que o gera; portanto a tristeza é sem limite.","conradeyoushouldhearreason~nradeyoushouldhearreason~26":"Conrado — Deveis ouvir a razão.","donjohnandwhenihavehearditwhatblessingsb~ditwhatblessingsbringsit~47":"Dom João — E quando a tiver ouvido, que bênçãos traz?","conradeifnotapresentremedyatleastapatien~tleastapatientsufferance~51":"Conrado — Se não um remédio imediato, ao menos um sofrimento paciente.","donjohniwonderthatthoubeingasthousayestt~yandclawnomaninhishumour~299":"Dom João — Admiro que tu, sendo, como dizes, nascido sob Saturno, procures aplicar um remédio moral a um mal mortificante. Não posso esconder o que sou: devo estar triste quando tenho causa e sorrir de gracejo de ninguém, comer quando tenho apetite e não esperar o vagar de ninguém, dormir quando tenho sono e não tratar dos negócios de ninguém, rir quando estou alegre e não coçar ninguém em seu humor.","conradeyeabutyoumustnotmakethefullshowof~eseasonforyourownharvest~275":"Conrado — Sim, mas não deveis fazer plena mostra disso até poderdes fazê-lo sem controle. Recentemente vos opusestes a vosso irmão, e ele vos tomou há pouco em sua graça; onde é impossível que criais raiz verdadeira senão pelo bom tempo que vós mesmo fizerdes: é preciso que moldeis a estação para a vossa colheita.","donjohnihadratherbeacankerinahedgethanar~atiamandseeknottoalterme~406":"Dom João — Antes ser um cancro numa sebe do que uma rosa na graça dele, e mais convém ao meu sangue ser desdenhado por todos do que fabricar um porte para roubar amor a alguém: nisto, embora não se possa dizer que sou um honesto lisonjeiro, não se deve negar que sou um vilão franco. Confiaram-me com um açaime e franquearam-me com um peso; portanto decidi não cantar na minha gaiola. Se tivesse a boca livre, morderia; se tivesse a liberdade, faria o que me agrada: entretanto deixai-me ser o que sou e não procureis mudar-me.","conradecanyoumakenouseofyourdiscontent~akenouseofyourdiscontent~38":"Conrado — Não podeis fazer nenhum uso do vosso descontentamento?","donjohnimakealluseofitforiuseitonlywhoco~oriuseitonlywhocomeshere~47":"Dom João — Faço todo o uso dele, pois só dele me sirvo.\nQuem vem aí?","enterborachio~enterborachio~13":"Entra Borráquio.","whatnewsborachio~whatnewsborachio~16":"Que novas, Borráquio?","borachioicameyonderfromagreatsupperthepr~enceofanintendedmarriage~130":"Borráquio — Venho de uma grande ceia ali: o príncipe, vosso irmão, é regiamente recebido por Leonato; e posso dar-vos notícia de um casamento projetado.","donjohnwillitserveforanymodeltobuildmisc~othshimselftounquietness~94":"Dom João — Servirá de modelo para construir sobre ele um mal? Que tolo é esse que se desposa com a inquietação?","borachiomarryitisyourbrothersrighthand~tisyourbrothersrighthand~38":"Borráquio — Ora, é a mão direita de vosso irmão.","donjohnwhothemostexquisiteclaudio~othemostexquisiteclaudio~33":"Dom João — Quem? O requintadíssimo Cláudio?","borachioevenhe~borachioevenhe~14":"Borráquio — Ele mesmo.","donjohnapropersquireandwhoandwhowhichway~whoandwhowhichwaylookshe~47":"Dom João — Um belo escudeiro! E quem, e quem? Para que lado olha ele?","borachiomarryonherothedaughterandheirofl~daughterandheirofleonato~46":"Borráquio — Ora, para Hero, filha e herdeira de Leonato.","donjohnaveryforwardmarchchickhowcameyout~rchchickhowcameyoutothis~45":"Dom João — Um pintinho de março bem adiantado! Como chegaste a isto?","borachiobeingentertainedforaperfumerasiw~hergivehertocountclaudio~234":"Borráquio — Tendo sido tomado por perfumista, enquanto defumava um quarto bolorento, vêm o príncipe e Cláudio, de mãos dadas, em grave conferência: esgueirei-me atrás da tapeçaria; e ali ouvi combinar-se que o príncipe cortejaria Hero para si e, tendo-a obtido, a daria ao conde Cláudio.","donjohncomecomeletusthitherthismayprovef~ebothsureandwillassistme~171":"Dom João — Vamos, vamos para lá: isto pode servir de alimento ao meu desgosto. Esse jovem arrivista tem toda a glória da minha derrota: se puder contrariá-lo de algum modo, abençoo-me de todos os modos. Ambos sois seguros, e me ajudareis?","conradetothedeathmylord~conradetothedeathmylord~23":"Conrado — Até a morte, senhor.","donjohnletustothegreatsuppertheircheeris~wegotoprovewhatstobedone~117":"Dom João — Vamos à grande ceia: o regalo deles é maior por eu estar subjugado. Quisera que o cozinheiro fosse do meu parecer! Vamos provar o que há de fazer-se?","borachiowellwaituponyourlordshipexeunt~ituponyourlordshipexeunt~38":"Borráquio — Aguardaremos vossa senhoria. Saem.","ahallinleonatoshouse~ahallinleonatoshouse~20":"Um salão na casa de Leonato.","enterleonatoantonioherobeatriceandothers~nioherobeatriceandothers~40":"Entram Leonato, Antonio, Hero, Beatrice e outros.","leonatowasnotcountjohnhereatsupper~notcountjohnhereatsupper~34":"Leonato — O conde João não esteve aqui na ceia?","antonioisawhimnot~antonioisawhimnot~17":"Antonio — Não o vi.","beatricehowtartlythatgentlemanlooksineve~amheartburnedanhourafter~78":"Beatrice — Como esse cavalheiro tem o ar azedo! Nunca o vejo sem ficar com azia por uma hora.","heroheisofaverymelancholydisposition~erymelancholydisposition~36":"Hero — Ele tem uma índole muito melancólica.","beatricehewereanexcellentmanthatweremade~ldestsonevermoretattling~162":"Beatrice — Seria um homem excelente aquele que fosse feito exatamente no meio-termo entre ele e Benedick: um é parecido demais com uma estátua e não diz nada, o outro, demais com o filho mais velho de uma madame, sempre tagarelando.","leonatothenhalfsigniorbenedickstongueinc~lyinsigniorbenedicksface~103":"Leonato — Então, metade da língua do senhor Benedick na boca do conde João, e metade da melancolia do conde João no rosto do senhor Benedick…","beatricewithagoodlegandagoodfootuncleand~ldifacouldgethergoodwill~117":"Beatrice — Com uma perna bem-feita, um pé bem-feito, tio, e dinheiro bastante na bolsa, um homem assim conquistaria qualquer mulher do mundo, se conseguisse a boa vontade dela.","leonatobymytrothniecethouwiltnevergetthe~houbesoshrewdofthytongue~76":"Leonato — Por minha fé, sobrinha, tu nunca arranjarás marido, se és tão afiada de língua.","antonioinfaithshestoocurst~tonioinfaithshestoocurst~26":"Antonio — Na verdade, ela é brava demais.","beatricetoocurstismorethancurstishallles~oacowtoocursthesendsnone~127":"Beatrice — Brava demais é mais que brava: assim diminuo o que Deus me manda nesse ponto; pois se diz: “Deus dá chifres curtos à vaca brava”; mas à vaca brava demais não dá nenhum.","leonatosobybeingtoocurstgodwillsendyouno~rstgodwillsendyounohorns~45":"Leonato — Então, por ser brava demais, Deus não te mandará chifres.","beatricejustifhesendmenohusbandforthewhi~hadratherlieinthewoollen~162":"Beatrice — Justo, se não me mandar marido; por essa bênção, eu lhe suplico de joelhos toda manhã e toda noite. Senhor, eu não suportaria um marido com barba no rosto: prefiro dormir entre lençóis de lã.","leonatoyoumaylightonahusbandthathathnobe~nahusbandthathathnobeard~43":"Leonato — Podes dar com um marido que não tenha barba.","beatricewhatshouldidowithhimdresshiminmy~rdandleadhisapesintohell~287":"Beatrice — E o que faria eu com ele? Vesti-lo com minhas roupas e fazer dele minha dama de companhia? Quem tem barba é mais que um rapaz, e quem não tem barba é menos que um homem; e quem é mais que um rapaz não serve para mim, e quem é menos que um homem não sirvo eu para ele: portanto, vou receber seis pence de adiantamento do domador de ursos e levar seus macacos para o inferno.","leonatowellthengoyouintohell~atowellthengoyouintohell~28":"Leonato — Pois bem, então vais para o inferno?","beatricenobuttothegateandtherewillthedev~eweasmerryasthedayislong~261":"Beatrice — Não, só até a porta; e ali o diabo virá ao meu encontro, como um velho corno, com chifres na cabeça, e dirá: “Vai para o céu, Beatrice, vai para o céu; aqui não há lugar para vós, solteironas.” Então entrego meus macacos e sigo para São Pedro, rumo ao céu; ele me mostra onde se sentam os solteiros, e ali vivemos tão alegres quanto o dia é longo.","antoniotoherowellnieceitrustyouwillberul~uwillberuledbyyourfather~54":"Antonio — Para Hero. Bem, sobrinha, confio que serás guiada por teu pai.","beatriceyesfaithitismycousinsdutytomakec~andsayfatherasitpleaseme~162":"Beatrice — Sim, por certo; é dever de minha prima fazer uma reverência e dizer: “Pai, como vos aprouver.” Mas, ainda assim, prima, que ele seja um rapaz bonito, ou então faça outra reverência e diga: “Pai, como me aprouver.”","leonatowellnieceihopetoseeyouonedayfitte~onedayfittedwithahusband~53":"Leonato — Bem, sobrinha, espero ver-te um dia provida de um marido.","beatricenottillgodmakemenofsomeothermeta~itasintomatchinmykindred~228":"Beatrice — Não antes que Deus faça os homens de outro metal que não a terra. Não seria uma aflição para uma mulher ser dominada por um punhado de pó valente? Prestar contas de sua vida a um torrão de barro caprichoso? Não, tio, nenhum; os filhos de Adão são meus irmãos; e, em verdade, tenho por pecado casar dentro da família.","leonatodaughterrememberwhatitoldyouifthe~hatkindyouknowyouranswer~85":"Leonato — Filha, lembra-te do que te disse: se o príncipe te fizer a corte nesse sentido, já sabes a resposta.","beatricethefaultwillbeinthemusiccousinif~ertillhesinkintohisgrave~431":"Beatrice — A culpa será da música, prima, se não fores cortejada a tempo: se o príncipe for importuno demais, dize-lhe que há compasso em todas as coisas e dança a resposta. Pois ouve, Hero: cortejar, casar e arrepender-se é como uma giga escocesa, uma pavana e uma cinquepasse: o primeiro galanteio é ardente e apressado, como uma giga escocesa, e igualmente fantasioso; o casamento, recatado e comedido, como uma pavana, cheio de pompa e antiguidade; e então vem o arrependimento e, com suas pernas ruins, cai na cinquepasse, cada vez mais depressa, até afundar na sepultura.","leonatocousinyouapprehendpassingshrewdly~apprehendpassingshrewdly~40":"Leonato — Prima, percebes com extrema argúcia.","beatriceihaveagoodeyeuncleicanseeachurch~icanseeachurchbydaylight~50":"Beatrice — Tenho bom olho, tio; vejo uma igreja em pleno dia.","leonatotherevellersareenteringbrothermak~odroomallputontheirmasks~67":"Leonato — Os foliões estão entrando, irmão: abri espaço. Todos põem suas máscaras.","enterdonpedroclaudiobenedickbalthasardon~retursulaandothersmasked~81":"Entram Dom Pedro, Cláudio, Benedick, Baltasar, Dom João, Borachio, Margarida, Úrsula e outros, mascarados.","donpedroladywillyouwalkaboutwithyourfrie~uwalkaboutwithyourfriend~42":"Dom Pedro — Senhora, quereis passear com vosso amigo?","herosoyouwalksoftlyandlooksweetlyandsayn~despeciallywheniwalkaway~90":"Hero — Contanto que caminheis suavemente, olheis com doçura e não digais nada, sou vossa para o passeio; e sobretudo quando me afastar.","donpedrowithmeinyourcompany~pedrowithmeinyourcompany~27":"Dom Pedro — Comigo em vossa companhia?","heroimaysaysowheniplease~heroimaysaysowheniplease~24":"Hero — Posso dizê-lo, quando me aprouver.","donpedroandw