-- william-shakespeare_othello (691 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_othello', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","veniceastreet~veniceastreet~13":"Veneza. Uma rua.","enterroderigoandiago~enterroderigoandiago~20":"Entram Rodrigo e Iago.","roderigotushnevertellmeitakeitmuchunkind~ethineshouldstknowofthis~112":"Rodrigo — Bah! Nunca me venha com isso; tomo-o muito a mal \n que tu, Iago, que dispuseste de minha bolsa \n como se os cordões fossem teus, soubesses disto.","iagosbloodbutyouwillnothearmeifeverididd~reamofsuchamatterabhorme~64":"Iago — Pelo sangue de Deus, mas o senhor não quer me ouvir: \n se alguma vez sonhei com tal coisa, abomine-me.","roderigothoutoldstmethoudidstholdhiminth~houdidstholdhiminthyhate~45":"Rodrigo — Disseste-me que o odiavas.","iagodespisemeifidonotthreegreatonesofthe~emarkhismoorshipsancient~835":"Iago — Despreze-me, se não é verdade. Três grandes da cidade, \n em pessoal súplica para me fazer seu tenente, \n tiraram-lhe o chapéu; e, pela fé de um homem, \n sei o meu preço, não valho posto pior: \n mas ele, amante de seu próprio orgulho e de seus intentos, \n esquiva-se, com um circunlóquio empolado \n horrivelmente recheado de epítetos de guerra; \n e, em conclusão, \n rejeita meus intercessores; pois “Certamente”, diz ele, \n “já escolhi o meu oficial.” \n E quem era ele? \n Ora, um grande aritmético, \n um tal Miguel Cássio, florentino, \n sujeito quase danado por uma bela esposa; \n que nunca pôs um esquadrão em campo, \n nem conhece a divisão de uma batalha \n mais que uma fiandeira; a não ser a teoria livresca, \n em que os cônsules togados sabem propor \n tão magistralmente quanto ele: mero palavreado, sem prática, \n é toda a sua soldadesca. Mas ele, senhor, teve a eleição: \n e eu, de quem os olhos dele tinham visto a prova \n em Rodes, em Chipre e em outras terras \n cristãs e pagãs, devo ficar a sotavento e em calmaria \n por causa de devedor e credor: esse contador de fichas, \n ele, em boa hora, há de ser seu tenente, \n e eu — Deus guarde a marca! — alferes de Sua Mourice.","roderigobyheaveniratherwouldhavebeenhish~rwouldhavebeenhishangman~46":"Rodrigo — Pelo céu, eu preferia ter sido o carrasco dele.","iagowhytheresnoremedytisthecurseofservic~rmamaffinedtolovethemoor~193":"Iago — Ora, não há remédio; é a maldição do serviço, \n a promoção vai por cartas e por afeição, \n e não pela velha gradação, em que cada segundo \n era herdeiro do primeiro. Agora, senhor, julgue o senhor mesmo \n se em algum termo justo estou obrigado \n a amar o Mouro.","roderigoiwouldnotfollowhimthen~goiwouldnotfollowhimthen~30":"Rodrigo — Então eu não o seguiria.","iagoosircontentyouifollowhimtoservemytur~awstopeckatiamnotwhatiam~831":"Iago — Oh, senhor, tenha calma; \n sigo-o para me servir dele a meu tempo: \n não podemos todos ser amos, nem todos os amos \n podem ser fielmente seguidos. O senhor notará \n muitos servos devotados e de joelhos dobrados, \n que, enamorados de sua própria obsequiosa servidão, \n gastam seu tempo, como o asno do patrão, \n por nada além de forragem, e na velhice são despedidos: \n chicoteiem-me tais honestos patifes. Outros há \n que, enfeitados de formas e semblantes de dever, \n mantêm contudo o coração servindo a si mesmos, \n e, lançando só aparências de serviço a seus senhores, \n prosperam à custa deles e, quando forraram \n os próprios casacos, \n prestam homenagem a si mesmos: esses sujeitos têm alma; \n e um desses eu me confesso. Pois, senhor, \n é tão certo quanto o senhor ser Rodrigo \n que, se eu fosse o Mouro, não seria Iago: \n ao segui-lo, sigo apenas a mim mesmo; \n o céu é meu juiz, não que eu o faça por amor e dever, \n mas por parecê-lo, para o meu fim particular: \n pois, quando meu agir exterior demonstrar \n o ato e a figura nativos do meu coração \n em cumprimento externo, não tardará muito \n que eu traga o coração à manga \n para os gaios o bicarem: eu não sou o que sou.","roderigowhatafullfortunedoesthethicklips~lipsoweifhecancarrytthus~60":"Rodrigo — Que plena fortuna possui o beiçudo, \n se consegue levar isto adiante!","iagocallupherfatherrousehimmakeafterhimp~ontasitmaylosesomecolour~220":"Iago — Chame o pai dela, \n acorde-o: vá atrás dele, envenene-lhe o deleite, \n proclame-o pelas ruas; inflame-lhe os parentes, \n e, ainda que ele habite clima fértil, \n infeste-o de moscas: embora a sua alegria seja alegria, \n lance-lhe tais mudanças de aflição \n que ela perca alguma cor.","roderigohereisherfathershouseillcallalou~fathershouseillcallaloud~41":"Rodrigo — Eis a casa do pai dela; vou chamar em voz alta.","iagodowithliketimorousaccentanddireyella~eisspiedinpopulouscities~95":"Iago — Faça-o, com tom igualmente temeroso e grito horrendo \n como quando, de noite e por negligência, o fogo \n é avistado em cidades populosas.","roderigowhathobrabantiosigniorbrabantioh~bantiosigniorbrabantioho~41":"Rodrigo — Ó de casa, Brabâncio! Senhor Brabâncio, ó de casa!","iagoawakewhathobrabantiothievesthievesth~ndyourbagsthievesthieves~97":"Iago — Acorde! Ó de casa, Brabâncio! Ladrões! Ladrões! Ladrões! \n Olhe por sua casa, sua filha e suas bolsas! \n Ladrões! Ladrões!","brabantioappearsaboveatawindow~tioappearsaboveatawindow~30":"Brabantio aparece no alto, a uma janela.","brabantiowhatisthereasonofthisterriblesu~monswhatisthematterthere~65":"Brabantio — Qual a razão desta terrível convocação?\nO que há aí?","roderigosigniorisallyourfamilywithin~iorisallyourfamilywithin~36":"Roderigo — Senhor, toda a vossa família está em casa?","iagoareyourdoorslockd~iagoareyourdoorslockd~21":"Iago — Vossas portas estão trancadas?","brabantiowhywhereforeaskyouthis~iowhywhereforeaskyouthis~31":"Brabantio — Ora, por que perguntais isso?","iagozoundssiryourerobbdforshameputonyour~agrandsireofyouariseisay~225":"Iago — Pelas chagas de Cristo, senhor, estais sendo roubado; por vergonha, vesti o roupão;\nvosso coração está partido, perdestes metade da alma;\nneste exato instante, agora mesmo, um velho carneiro negro\nestá cobrindo vossa ovelha branca. Levantai, levantai;\ndespertai os cidadãos ressonantes com o sino,\nou então o diabo vos fará avô:\nlevantai, digo.","brabantiowhathaveyoulostyourwits~owhathaveyoulostyourwits~32":"Brabantio — Quê, perdestes o juízo?","roderigomostreverendsigniordoyouknowmyvo~dsigniordoyouknowmyvoice~43":"Roderigo — Reverendíssimo senhor, conheceis minha voz?","brabantionotiwhatareyou~brabantionotiwhatareyou~23":"Brabantio — Eu não; quem sois?","roderigomynameisroderigo~roderigomynameisroderigo~24":"Roderigo — Meu nome é Roderigo.","brabantiotheworserwelcomeihavechargedthe~stthoucometostartmyquiet~221":"Brabantio — Tanto pior a acolhida:\nordenei-te que não rondasses minhas portas:\ncom honesta franqueza ouviste-me dizer\nque minha filha não é para ti; e agora, em loucura,\ncheio de ceia e de goles que perturbam a mente,\npor malicioso desafio, vens\nperturbar-me o sossego.","roderigosirsirsir~roderigosirsirsir~17":"Roderigo — Senhor, senhor, senhor…","brabantiobutthoumustneedsbesuremyspirita~ertomakethisbittertothee~86":"Brabantio — Mas deves estar bem certo\nde que meu espírito e meu posto têm poder\npara tornar isto amargo para ti.","roderigopatiencegoodsir~roderigopatiencegoodsir~23":"Roderigo — Paciência, bom senhor.","brabantiowhattellstthoumeofrobbingthisis~enicemyhouseisnotagrange~65":"Brabantio — Que me falas de roubo? Isto é Veneza;\nminha casa não é uma granja.","roderigomostgravebrabantioinsimpleandpur~pleandpuresoulicometoyou~55":"Roderigo — Gravíssimo Brabantio,\ncom alma simples e pura venho a vós.","iagozoundssiryouareoneofthosethatwillnot~sinsandgennetsforgermans~237":"Iago — Pelas chagas de Cristo, senhor, sois daqueles que não servem a Deus, se o diabo mandar. Porque viemos prestar-vos serviço e pensais que somos rufiões, quereis ver vossa filha coberta por um cavalo da Barbária; quereis que vossos sobrinhos relinchem para vós; quereis corcéis por primos e ginetes por irmãos.","brabantiowhatprofanewretchartthou~whatprofanewretchartthou~33":"Brabantio — Que profano miserável és tu?","iagoiamonesirthatcomestotellyouyourdaugh~kingthebeastwithtwobacks~85":"Iago — Sou um, senhor, que vem dizer-vos que vossa filha e o Mouro estão agora fazendo a besta de duas costas.","brabantiothouartavillain~brabantiothouartavillain~24":"Brabantio — És um vilão.","iagoyouareasenator~iagoyouareasenator~18":"Iago — Sois… um senador.","brabantiothisthoushaltansweriknowtheerod~tansweriknowtheeroderigo~45":"Brabantio — Disto responderás; conheço-te, Roderigo.","roderigosiriwillansweranythingbutibeseec~estateforthusdeludingyou~713":"Roderigo — Senhor, responderei por tudo. Mas suplico-vos,\nse for do vosso agrado e sábio consentimento,\ncomo em parte vejo que é, que vossa bela filha,\nnesta hora ímpar e tediosa da noite,\ntransportada, sem melhor nem pior guarda\nque um biltre de aluguel, um gondoleiro,\naos grosseiros abraços de um luxurioso Mouro…\nse isto é do vosso conhecimento e aprovação,\nentão vos fizemos ofensas ousadas e atrevidas;\nmas se disto nada sabeis, meus modos me dizem\nque vossa repreensão é injusta. Não creiais\nque, contra todo o senso de civilidade,\neu assim brincaria e zombaria da vossa reverência:\nvossa filha, se não lhe destes licença,\ndigo outra vez, cometeu grosseira revolta,\nligando seu dever, beleza, espírito e fortuna\na um estrangeiro errante e volúvel\nde toda parte e de parte alguma. Certificai-vos logo:\nse ela estiver em seu quarto ou em vossa casa,\nlançai sobre mim a justiça do Estado\npor assim vos iludir.","brabantiostrikeonthetinderhogivemeataper~ylightisaylightexitabove~138":"Brabantio — Batei o isqueiro, ho!\nDai-me uma vela! Chamai todos os meus criados!\nEste acidente não é diferente do meu sonho:\no só crer nele já me oprime.\nLuz, digo! luz! Sai de cima.","iagofarewellforimustleaveyouitseemsnotme~ibewithhimsofarewellexit~529":"Iago — Adeus; pois devo deixar-vos:\nnão parece conveniente, nem salutar a meu posto,\nser chamado — como, se ficar, serei —\ncontra o Mouro: pois sei que o Estado,\nembora isto o possa irritar com alguma censura,\nnão pode com segurança afastá-lo, pois está embarcado\ncom tão ruidosa razão nas guerras de Chipre,\nque já estão em ação, que, por suas almas,\noutro da sua estatura não têm\npara conduzir seus negócios: nesse respeito,\nainda que o odeie como as penas do inferno,\ncontudo, por necessidade da vida presente,\ndevo exibir bandeira e sinal de amor,\no que de fato é só sinal. Para que o encontreis com certeza,\nconduzi ao Sagitário a busca armada;\ne ali estarei eu com ele. Assim, adeus. Sai.","enterbelowbrabantioandservantswithtorche~ioandservantswithtorches~41":"Entram, embaixo, Brabantio e Criados com tochas.","brabantioitistootrueanevilgonesheisandwh~edaretheymarriedthinkyou~282":"Brabantio — É um mal verdadeiro demais: ela se foi;\ne o que me resta de tempo desprezado\né nada senão amargura. Agora, Roderigo,\nonde a viste? Oh, infeliz menina! Com o Mouro, dizes?\nQuem quereria ser pai! Como soubeste que era ela?\nOh, ela me engana além do pensamento! O que ela vos disse? Mais velas:\nlevantai todos os meus parentes. Estão casados, pensais?","roderigotrulyithinktheyare~derigotrulyithinktheyare~26":"Roderigo — Na verdade, penso que sim.","brabantiooheavenhowgotsheoutotreasonofth~droderigoofsomesuchthing~207":"Brabantio — Oh, céus! Como saiu? Oh, traição do sangue!\nPais, daqui por diante não confieis no espírito de vossas filhas\npelo que as vedes fazer. Não há encantos\npelos quais a natureza da juventude e da donzelice\npossa ser abusada? Não lestes, Roderigo,\nalgo semelhante?","roderigoyessirihaveindeed~oderigoyessirihaveindeed~25":"Roderigo — Sim, senhor, de fato li.","brabantiocallupmybrotherowouldyouhadhadh~ayapprehendherandthemoor~104":"Brabantio — Chamai meu irmão. Oh, quisera que a tivésseis tido!\nUns por um caminho, outros por outro. Sabeis\nonde podemos apanhá-la e ao Mouro?","roderigoithinkicandiscoverhimifyouplease~oodguardandgoalongwithme~70":"Roderigo — Penso que posso descobri-lo, se quiserdes\nreunir boa guarda e ir comigo.","brabantioprayyouleadonateveryhouseillcal~lldeserveyourpainsexeunt~143":"Brabantio — Rogo-vos, guiai. Em cada casa baterei;\nposso mandar na maioria. Armas, ho!\nE chamai alguns oficiais especiais da noite.\nAdiante, bom Roderigo: recompensarei vosso trabalho. Saem.","sceneii~sceneii~7":"Cena II","anotherstreet~anotherstreet~13":"Outra rua.","enterothelloiagoandattendantswithtorches~andattendantswithtorches~40":"Entram Otelo, Iago e Criados com tochas.","iagothoughinthetradeofwarihaveslainmenye~yerkdhimhereundertheribs~184":"Iago — Embora no ofício da guerra eu tenha matado homens,\nainda assim tenho por matéria da consciência\nnão cometer assassinato premeditado: falta-me iniquidade\nàs vezes para me servir: nove ou dez vezes\npensei em espetá-lo aqui, sob as costelas.","othellotisbetterasitis~othellotisbetterasitis~22":"Otelo — É melhor como está.","iagonaybuthepratedandspokesuchscurvyandp~orceitonwillgivehimcable~352":"Iago — Não, mas ele tagarelou\ne falou termos tão sórdidos e provocantes\ncontra a vossa honra\nque, com a pouca piedade que tenho,\ncom grande dificuldade o suportei. Mas, rogo-vos, senhor,\nestais firmemente casado? Podeis estar certo disto:\no magnífico é muito amado,\ne tem, em seus efeitos, uma voz poderosa\ntão dupla quanto a do doge: ele vos divorciará;\nou imporá sobre vós o constrangimento e o agravo\nque a lei, com toda a força de aplicá-la,\nlhe der de corda.","othellolethimdohisspitemyserviceswhichih~utlookwhatlightscomeyond~402":"Otelo — Que faça seu despeito:\nos serviços que prestei à Senhoria\nsuplantarão suas queixas. Ainda não se sabe —\no que, quando eu souber que gabar-se é honra,\npromulgarei — que tiro minha vida e ser\nde homens de trono real, e meus méritos\npodem falar de cabeça descoberta a fortuna tão altiva\nquanto esta que alcancei: pois sabe, Iago,\nque, não fosse eu amar a gentil Desdemona,\nnão quereria minha desalojada condição livre\nlançar em limite e confinamento\npelo valor do mar. Mas, olha! que luzes vêm ali?","iagothosearetheraisedfatherandhisfriends~isfriendsyouwerebestgoin~55":"Iago — São o pai despertado e seus amigos:\nmelhor seria entrardes.","othellonotiimustbefoundmypartsmytitleand~anifestmerightlyisitthey~83":"Otelo — Eu não: devo ser encontrado:\nminhas qualidades, meu título e minha alma perfeita\nme manifestarão corretamente. São eles?","iagobyjanusithinkno~iagobyjanusithinkno~19":"Iago — Por Jano, penso que não.","entercassioandcertainofficerswithtorches~rtainofficerswithtorches~40":"Entram Cássio e alguns Oficiais com tochas.","othellotheservantsofthedukeandmylieutena~nyoufriendswhatisthenews~90":"Otelo — Os servos do doge, e meu tenente.\nA bondade da noite sobre vós, amigos!\nQue novas há?","cassiothedukedoesgreetyougeneralandhereq~pearanceevenontheinstant~89":"Cássio — O doge vos saúda, general,\ne requer vossa comparência a toda pressa,\nneste mesmo instante.","othellowhatisthematterthinkyou~owhatisthematterthinkyou~30":"Otelo — Qual o assunto, pensais?","cassiosomethingfromcyprusasimaydivineiti~eralgueststosearchyouout~295":"Cássio — Algo de Chipre, pelo que posso adivinhar:\né negócio de certo calor: as galeras\nenviaram uma dúzia de mensageiros sucessivos\nesta mesma noite, um nos calcanhares do outro,\ne muitos dos cônsules, convocados e reunidos,\njá estão com o doge: fostes ardentemente chamado;\ne, não sendo encontrado em vosso alojamento,\no senado enviou umas três distintas comitivas\npara vos procurar.","othellotiswelliamfoundbyyouiwillbutspend~thehouseandgowithyouexit~75":"Otelo — Bem é que me encontreis. \nGastarei apenas uma palavra aqui na casa,\ne irei convosco. Sai.","cassioancientwhatmakeshehere~ioancientwhatmakeshehere~28":"Cássio — Alferes, que faz ele aqui?","iagofaithhetonighthathboardedalandcarack~awfulprizehesmadeforever~74":"Iago — Na verdade, esta noite abordou uma nau de carga em terra:\nse for presa legítima, está feito para sempre.","cassioidonotunderstand~cassioidonotunderstand~22":"Cássio — Não entendo.","iagohesmarried~iagohesmarried~14":"Iago — Está casado.","cassiotowho~cassiotowho~11":"Cássio — Com quem?","reenterothello~reenterothello~14":"Entra de novo Otelo.","iagomarrytocomecaptainwillyougo~rytocomecaptainwillyougo~31":"Iago — Ora, com… Vamos, capitão, quereis ir?","othellohavewithyou~othellohavewithyou~18":"Otelo — Estou convosco.","cassioherecomesanothertrooptoseekforyou~anothertrooptoseekforyou~39":"Cássio — Aí vem outra tropa a procurar-vos.","iagoitisbrabantiogeneralbeadvisedhecomes~dvisedhecomestobadintent~51":"Iago — É Brabantio. General, ficai avisado;\nvem com mau intento.","enterbrabantioroderigoandofficerswithtor~erswithtorchesandweapons~54":"Entram Brabantio, Roderigo e Oficiais com tochas e armas.","othellohollastandthere~othellohollastandthere~22":"Otelo — Olá! Parai aí!","roderigosignioritisthemoor~derigosignioritisthemoor~26":"Roderigo — Senhor, é o Mouro.","brabantiodownwithhimthieftheydrawonboths~thieftheydrawonbothsides~44":"Brabantio — Abaixo com ele, ladrão! Sacam as espadas, de ambos os lados.","iagoyouroderigocomesiriamforyou~roderigocomesiriamforyou~31":"Iago — Vós, Roderigo! Vamos, senhor, sou vosso adversário.","othellokeepupyourbrightswordsforthedewwi~yearsthanwithyourweapons~108":"Otelo — Guardai vossas espadas brilhantes, pois o orvalho as enferrujará.\nBom senhor, mandareis mais com os anos\ndo que com as vossas armas.","brabantioothoufoulthiefwherehastthoustow~esistsubduehimathisperil~672":"Brabantio — Oh, tu, ladrão imundo, onde escondeste minha filha?\nDanado como és, tu a enfeitiçaste;\npois apelarei a todas as coisas dotadas de senso,\nse ela não estivesse presa em cadeias de magia,\nse uma donzela tão tenra, bela e feliz,\ntão avessa ao casamento que evitava\nos ricos queridinhos de cabelos anelados de nossa nação,\njamais teria, para incorrer em zombaria geral,\nfugido de sua tutela para o seio fuliginoso\nde uma coisa como tu, que causa medo, não prazer.\nJulgue-me o mundo, se não é grosseiro ao senso\nque tu a manipulaste com encantos imundos,\nabusaste de sua delicada juventude com drogas ou minerais\nque enfraquecem a vontade: quero isso debatido;\né provável e palpável ao pensamento.\nPortanto te prendo e te detenho\ncomo abusador do mundo, praticante\nde artes proibidas e sem licença.\nAgarrai-o: se resistir,\nsubjugai-o, por sua conta e risco.","othelloholdyourhandsbothyouofmyinclining~gotoanswerthisyourcharge~143":"Otelo — Detende as mãos,\ntanto vós de minha parte quanto os demais:\nfosse minha deixa de lutar, eu a teria sabido\nsem ninguém que me soprasse a deixa. Aonde quereis que eu vá\npara responder a esta vossa acusação?","brabantiotoprisontillfittimeoflawandcour~tsessioncalltheetoanswer~73":"Brabantio — À prisão, até que o tempo oportuno\nda lei e o curso de sessão direta\nte chamem a responder.","othellowhatifidoobeyhowmaythedukebethere~ofthestatetobringmetohim~133":"Otelo — E se eu obedecer?\nComo ficará satisfeito o doge,\ncujos mensageiros estão aqui a meu lado,\npara algum negócio presente do Estado\nlevar-me a ele?","firstofficertistruemostworthysigniorthed~obleselfiamsureissentfor~85":"Primeiro Oficial — É verdade, digníssimo senhor;\no doge está em conselho e vossa nobre pessoa,\ntenho certeza, foi chamada.","brabantiohowthedukeincouncilinthistimeof~hallourstatesmenbeexeunt~235":"Brabantio — Como! O doge em conselho!\nNesta hora da noite! Levai-o:\nminha causa não é ociosa: o próprio doge,\nou qualquer de meus irmãos do Estado,\nnão pode senão sentir este agravo como seu;\npois se tais ações têm livre passagem,\nescravos e pagãos serão nossos estadistas. Saem.","sceneiii~sceneiii~8":"Cena III","acouncilchamber~acouncilchamber~15":"Uma câmara do conselho.","thedukeandsenatorssittingatatableofficer~tatableofficersattending~50":"O Doge e Senadores sentados a uma mesa; Oficiais presentes.","dukethereisnocompositioninthesenewsthatg~enewsthatgivesthemcredit~54":"Doge — Não há coerência nestas notícias\nque lhes dê crédito.","firstsenatorindeedtheyaredisproportiondm~yahundredandsevengalleys~74":"Primeiro Senador — De fato, são desproporcionais;\nminhas cartas dizem cento e sete galeras.","dukeandmineahundredandforty~eandmineahundredandforty~27":"Doge — E as minhas, cento e quarenta.","secondsenatorandminetwohundredbutthought~leetandbearinguptocyprus~168":"Segundo Senador — E as minhas, duzentas:\nmas embora não coincidam numa conta exata —\ncomo nestes casos, em que a estimativa informa,\nhá muitas vezes diferença — todas elas confirmam\numa frota turca, que rumo a Chipre.","dukenayitispossibleenoughtojudgmentidono~idoapproveinfearfulsense~102":"Doge — Não, é bastante possível ao juízo:\nnão me asseguro tanto no erro\nque não aprove o artigo principal\ncom sentido de temor.","sailorwithinwhathowhathowhatho~withinwhathowhathowhatho~30":"Marinheiro — Dentro. Ei, ho! ei, ho! ei, ho!","firstofficeramessengerfromthegalleys~amessengerfromthegalleys~36":"Primeiro Oficial — Um mensageiro das galeras.","enterasailor~enterasailor~12":"Entra um Marinheiro.","dukenowwhatsthebusiness~dukenowwhatsthebusiness~23":"Doge — Então, qual o assunto?","sailortheturkishpreparationmakesforrhode~othestatebysigniorangelo~85":"Marinheiro — O aparato turco faz rumo a Rodes;\nassim fui mandado relatar aqui ao Estado\npelo senhor Ângelo.","dukehowsayyoubythischange~ukehowsayyoubythischange~25":"Doge — Que dizeis desta mudança?","firstsenatorthiscannotbebynoassayofreaso~andwageadangerprofitless~461":"Primeiro Senador — Isto não pode ser,\npor nenhum ensaio da razão: é um espetáculo\npara manter-nos em falso olhar. Quando consideramos\na importância de Chipre para o Turco,\ne de novo nos deixamos compreender\nque, assim como mais concerne ao Turco que Rodes,\npode ele com mais fácil disputa tomá-la,\nporquanto não se acha em tão guerreira prontidão,\nmas carece por inteiro das capacidades\nde que Rodes está provida: se pensarmos nisto,\nnão devemos crer que o Turco seja tão inábil\npara deixar por último o que lhe interessa primeiro,\nnegligenciando uma empresa de facilidade e ganho,\npara despertar e travar um perigo sem lucro.","dukenayinallconfidencehesnotforrhodes~onfidencehesnotforrhodes~37":"Doge — Não, com toda a confiança, ele não vai a Rodes.","firstofficerhereismorenews~rstofficerhereismorenews~26":"Primeiro Oficial — Eis mais notícias.","enteramessenger~enteramessenger~15":"Entra um Mensageiro.","messengertheottomitesreverendandgracious~ntedthemwithanafterfleet~121":"Mensageiro — Os otomanos, reverendos e graciosos,\nrumando em devido curso para a ilha de Rodes,\nlá se juntaram a uma frota de retaguarda.","firstsenatoraysoithoughthowmanyasyougues~thoughthowmanyasyouguess~41":"Primeiro Senador — Sim, assim pensei. Quantas, a vosso ver?","messengerofthirtysailandnowtheydorestemt~sandpraysyoutobelievehim~210":"Mensageiro — De trinta velas: e agora refazem\nseu curso de volta, dirigindo com franca aparência\nseus propósitos a Chipre. O senhor Montano,\nvosso fiel e valentíssimo servidor,\ncom seu livre dever vos recomenda assim,\ne pede que lhe deis crédito.","duketiscertainthenforcyprusmarcusluccico~cusluccicosisnotheintown~54":"Doge — É certo, então, que é Chipre.\nMarcus Lúcico, não está na cidade?","firstsenatorhesnowinflorence~tsenatorhesnowinflorence~28":"Primeiro Senador — Está agora em Florença.","dukewritefromustohimpostposthastedispatc~himpostposthastedispatch~41":"Doge — Escrevei-lhe de nossa parte; despachai a toda pressa.","firstsenatorherecomesbrabantioandthevali~abantioandthevaliantmoor~47":"Primeiro Senador — Aí vêm Brabantio e o valente Mouro.","enterbrabantioothelloiagoroderigoandoffi~oiagoroderigoandofficers~44":"Entram Brabantio, Otelo, Iago, Roderigo e Oficiais.","dukevaliantothellowemuststraightemployyo~ounselandyourhelptonight~150":"Doge — Valente Otelo, devemos empregar-vos logo\ncontra o inimigo comum otomano.\nPara Brabantio. Não vos vi; bem-vindo, gentil senhor;\nsentimos falta de vosso conselho e ajuda esta noite.","brabantiosodidiyoursgoodyourgracepardonm~orrowsanditisstillitself~241":"Brabantio — Assim eu da vossa. Boa vossa graça, perdoai-me;\nnem meu cargo nem coisa alguma que ouvi de negócios\nme ergueu do leito, nem o cuidado geral\ntoma conta de mim, pois minha dor particular\né de natureza tão torrencial e esmagadora\nque engole e traga outros pesares\ne continua sendo ela mesma.","dukewhywhatsthematter~dukewhywhatsthematter~21":"Doge — Ora, que há?","brabantiomydaughteromydaughter~tiomydaughteromydaughter~30":"Brabantio — Minha filha! Oh, minha filha!","dukesenatordead~dukesenatordead~15":"Doge\nSenador — Morta?","brabantioaytomesheisabusedstolnfrommeand~sesanswitchcraftcouldnot~175":"Brabantio — Sim, para mim;\nfoi abusada, roubada de mim e corrompida\npor feitiços e remédios comprados de charlatães;\npois que a natureza tão desarrazoadamente errasse,\nnão sendo deficiente, cega ou coxa de senso,\nsem feitiçaria não poderia.","dukewhoeerhebethatinthisfoulproceedingha~opersonstoodinyouraction~196":"Doge — Quem quer que seja aquele que neste feio procedimento\nassim ludibriou vossa filha de si mesma\ne vós dela, o sangrento livro da lei\nvós mesmo lereis na letra amarga\nsegundo o vosso sentir, sim, ainda que nosso próprio filho\nestivesse em vossa ação.","brabantiohumblyithankyourgracehereisthem~affairshathhitherbrought~117":"Brabantio — Humildemente agradeço a vossa graça.\nAqui está o homem, este Mouro, que agora, ao que parece,\nvosso mandato especial para os negócios do Estado\ntrouxe até aqui.","dukesenatorweareverysorryfort~enatorweareverysorryfort~29":"Doge\nSenador — Sentimos muito por isso.","duketoothellowhatinyourownpartcanyousayt~urownpartcanyousaytothis~45":"Doge — Para Otelo. Que podeis dizer de vossa parte a isto?","brabantionothingbutthisisso~bantionothingbutthisisso~27":"Brabantio — Nada, senão que é assim.","othellomostpotentgraveandreverendsignior~gedwithaliwonhisdaughter~667":"Otelo — Potentíssimos, graves e reverendos senhores,\nmeus nobilíssimos e aprovados bons mestres,\nque levei a filha deste velho,\né verdade pura; verdade, casei-me com ela:\na própria cabeça e frente de minha ofensa\ntem esta extensão, não mais. Rude sou na fala,\ne pouco abençoado com a suave frase da paz:\npois desde que estes meus braços tiveram sete anos de vigor,\naté há nove luas passadas, usaram\nsua mais cara ação no campo de tendas,\ne pouco deste grande mundo posso falar,\nsenão o que pertence a feitos de refrega e batalha,\ne portanto pouco adornarei minha causa\nao falar por mim mesmo. Contudo, com vossa graciosa paciência,\nentregarei uma narrativa redonda e sem verniz\nde todo o curso do meu amor; que drogas, que encantos,\nque conjuro e que poderosa magia,\npois por tal procedimento sou acusado,\nusei para ganhar a filha dele.","brabantioamaidenneverboldofspiritsostill~iseffecthewroughtuponher~427":"Brabantio — Uma donzela jamais ousada;\nde espírito tão quieto e sossegado que seu próprio movimento\ncorava de si mesma; e ela, a despeito da natureza,\ndos anos, da pátria, do crédito, de tudo,\napaixonar-se pelo que temia olhar!\nÉ um juízo mutilado e imperfeitíssimo\no que confessa que a perfeição assim pudesse errar\ncontra todas as regras da natureza, e deve ser levado\na buscar práticas do inferno astuto\npara explicar por que isto seria. Portanto atesto de novo\nque com alguma mistura poderosa sobre o sangue,\nou com alguma dose conjurada para este efeito,\nele agiu sobre ela.","duketovouchthisisnoproofwithoutmorewider~eemingdopreferagainsthim~126":"Doge — Atestar isto não é prova,\nsem mais ampla e mais manifesta evidência\ndo que estas tênues aparências e pobres verossimilhanças\nde mera suposição que apresentais contra ele.","firstsenatorbutothellospeakdidyoubyindir~ionassoultosoulaffordeth~155":"Primeiro Senador — Mas, Otelo, falai:\npor meios indiretos e forçados\nsubjugastes e envenenastes os afetos desta jovem?\nOu veio por pedido e tão justa conversa\nquanto alma a alma concede?","othelloidobeseechyousendfortheladytothes~ntenceevenfalluponmylife~189":"Otelo — Suplico-vos,\nmandai buscar a dama no Sagitário,\ne deixai-a falar de mim diante do pai:\nse me achardes vil em seu relato,\na confiança, o cargo que de vós tenho,\nnão só tirai, mas fazei vossa sentença\nmesmo cair sobre minha vida.","dukefetchdesdemonahither~dukefetchdesdemonahither~24":"Doge — Trazei Desdemona aqui.","othelloancientconductthemyoubestknowthep~airladysloveandsheinmine~202":"Otelo — Alferes, conduzi-os: vós melhor sabeis o lugar. Saem Iago e Criados.\nE, até que ela venha, tão verdadeiramente como ao céu\nconfesso os vícios do meu sangue,\ntão justamente a vossos graves ouvidos apresentarei\ncomo prosperei no amor desta bela dama,\ne ela no meu.","dukesayitothello~dukesayitothello~16":"Doge — Dizei, Otelo.","othelloherfatherlovedmeoftinvitedmestill~estheladyletherwitnessit~1453":"Otelo — O pai dela me amava; muitas vezes me convidou;\nsempre me pedia a história de minha vida,\nano a ano, as batalhas, cercos, fortunas\nque atravessei.\nEu a percorri toda, desde meus dias de menino\naté o momento mesmo em que ele mandou contá-la;\nnela falei de azares desastrosíssimos,\nde acidentes comoventes por mar e terra,\nde escapadas por um fio de cabelo na iminente brecha mortal,\nde ser tomado pelo inimigo insolente\ne vendido à escravidão, de meu resgate de lá\ne comportamento na história de minhas viagens:\nnela, de antros vastos e desertos ermos,\npedreiras ásperas, rochas e colinas cujas cabeças tocam o céu,\nera meu tema falar — tal foi o processo;\ne dos canibais que uns aos outros se comem,\nos antropófagos, e homens cujas cabeças\ncrescem sob os ombros. Isto ouvir\nDesdemona inclinava-se com seriedade:\nmas os afazeres da casa sempre dali a chamavam:\nos quais, assim que podia, despachava às pressas,\nvoltava, e com ouvido ávido\ndevorava meu discurso: o que observando,\naproveitei uma hora propícia, e achei bom meio\npara tirar dela um rogo de coração sincero\nde que eu dilatasse toda a minha peregrinação,\nda qual, por parcelas, ela algo ouvira,\nmas não com atenção: consenti,\ne muitas vezes a enganei de suas lágrimas,\nquando falei de algum golpe aflitivo\nque minha juventude sofreu. Terminada a história,\ndeu-me por meu trabalho um mundo de suspiros:\njurou, na fé, que era estranho, era estranhíssimo,\nera lastimável, era maravilhosamente lastimável:\ndesejou não tê-la ouvido, contudo desejou\nque o céu a fizesse um homem assim: agradeceu-me,\ne disse-me que, se eu tivesse um amigo que a amasse,\neu apenas lhe ensinasse a contar minha história,\ne isso a conquistaria. Com esta dica falei:\nela me amou pelos perigos que passei,\ne eu a amei porque os lastimou.\nEsta é a única feitiçaria que usei:\naqui vem a dama; que ela o testemunhe.","enterdesdemonaiagoandattendants~sdemonaiagoandattendants~31":"Entram Desdemona, Iago e Criados.","dukeithinkthistalewouldwinmydaughtertoog~herusethantheirbarehands~134":"Doge — Penso que esta história conquistaria também minha filha.\nBom Brabantio,\ntomai este assunto estropiado do melhor modo:\nos homens usam antes armas quebradas\ndo que as mãos nuas.","brabantioiprayyouhearherspeakifsheconfes~wheremostyouoweobedience~189":"Brabantio — Peço-vos, ouvi-a falar:\nse confessar que foi metade da cortejadora,\ndestruição sobre minha cabeça, se minha má censura\ncair sobre o homem! Vinde cá, gentil senhora:\npercebeis, em toda esta nobre companhia,\na quem mais deveis obediência?","desdemonamynoblefatheridoperceivehereadi~rofessduetothemoormylord~296":"Desdemona — Meu nobre pai,\npercebo aqui um dever dividido:\na vós sou obrigada pela vida e educação;\nminha vida e educação ambas me ensinam\ncomo respeitar-vos; sois o senhor do dever;\naté aqui sou vossa filha: mas aqui está meu marido,\ne tanto dever quanto minha mãe mostrou\na vós, preferindo-vos ao seu pai,\ntanto reclamo poder professar\ndevido ao Mouro, meu senhor.","brabantiogodbewiyouihavedonepleaseityour~ogsonthemihavedonemylord~307":"Brabantio — Deus vos guarde! Terminei.\nPraza à vossa graça, avante com os negócios do Estado:\nmelhor adotaria um filho do que o gerar.\nVinde cá, Mouro:\neu aqui te dou, de todo coração, aquilo que,\nse já não o tivesses, de todo coração\neu te negaria. Por vossa causa, joia,\nalegro-me na alma de não ter outro filho:\npois tua fuga me ensinaria tirania,\npara pendurar grilhões neles. Terminei, meu senhor.","dukeletmespeaklikeyourselfandlayasentenc~thatspendsabootlessgrief~381":"Doge — Deixai-me falar como vós, e dar uma sentença\nque, como degrau, possa ajudar estes amantes\nao vosso favor.\nQuando os remédios passaram, as dores terminam\nao ver-se o pior, que há pouco de esperanças dependia.\nLamentar um mal que passou e se foi\né o caminho mais curto para atrair novo mal.\nO que não se pode preservar quando a fortuna toma,\na paciência faz do dano uma zombaria.\nO roubado que sorri rouba algo ao ladrão;\nrouba a si mesmo quem gasta uma dor inútil.","brabantiosolettheturkofcyprususbeguilewe~oceedtotheaffairsofstate~399":"Brabantio — Assim nos engane o Turco em Chipre;\nnão o perdemos, enquanto pudermos sorrir.\nBem suporta a sentença quem nada suporta\nsenão o livre conforto que dela ouve,\nmas suporta a sentença e a dor\naquele que, para pagar a dor, deve tomar a pobre paciência emprestada.\nEstas sentenças, para açúcar ou para fel,\nsendo fortes de ambos os lados, são equívocas:\nmas palavras são palavras; nunca ouvi\nque o coração machucado fosse trespassado pelo ouvido.\nHumildemente vos suplico, passai aos negócios do Estado.","duketheturkwithamostmightypreparationmak~nandboisterousexpedition~316":"Doge — O Turco, com um aparato poderosíssimo, faz rumo a Chipre. Otelo, a fortaleza do lugar vos é mais bem conhecida; e embora tenhamos lá um substituto de suficiência altamente reconhecida, contudo a opinião, soberana senhora dos efeitos, lança sobre vós uma voz mais segura: deveis portanto contentar-vos em manchar o lustre de vossa nova fortuna com esta expedição mais áspera e turbulenta.","othellothetyrantcustommostgravesenatorsh~taslevelswithherbreeding~346":"Otelo — O tirano costume, gravíssimos senadores,\nfez do leito pedregoso e de aço da guerra\nmeu triplamente macio leito de penas: reconheço\numa natural e pronta alacridade\nque encontro na dureza, e empreendo\nestas guerras presentes contra os otomanos.\nHumildíssimo, portanto, curvando-me ao vosso estado,\nimploro apropriada disposição para minha esposa.\nDevida referência de lugar e sustento,\ncom tal acomodação e séquito\nquanto condiga com sua criação.","dukeifyoupleasebetatherfathers~youpleasebetatherfathers~30":"Doge — Se quiserdes,\nseja na casa do pai.","brabantioillnothaveitso~brabantioillnothaveitso~23":"Brabantio — Não o quero assim.","othellonori~othellonori~11":"Otelo — Nem eu.","desdemonanoriiwouldnotthereresidetoputmy~oicetoassistmysimpleness~181":"Desdemona — Nem eu; não quereria residir ali,\npara pôr meu pai em pensamentos impacientes\npor estar à sua vista. Graciosíssimo doge,\nao meu desdobrar emprestai vosso ouvido propício;\ne deixai-me achar um alvará em vossa voz\npara ajudar minha simplicidade.","dukewhatwouldyoudesdemona~ukewhatwouldyoudesdemona~25":"Doge — Que quereis, Desdemona?","desdemonathatididlovethemoortolivewithhi~earabsenceletmegowithhim~382":"Desdemona — Que amei o Mouro para viver com ele,\nminha franca violência e tempestade de fortunas\npodem trombetear ao mundo: meu coração está sujeito\naté à própria qualidade de meu senhor:\nvi o rosto de Otelo em sua mente,\ne à sua honra e a seus valentes méritos\nconsagrei minha alma e fortunas.\nDe modo que, caros senhores, se eu for deixada para trás,\numa traça de paz, e ele for à guerra,\nos ritos pelos quais o amo me são roubados,\ne suportarei um pesado interim\npela sua cara ausência. Deixai-me ir com ele.","othelloletherhaveyourvoicesvouchwithmehe~eheadagainstmyestimation~500":"Otelo — Deixai que tenha vossas vozes.\nTestemunha comigo, céu, que não o peço\npara agradar ao paladar de meu apetite,\nnem para ceder ao ardor — os jovens afetos\nem mim extintos — e à própria satisfação,\nmas para ser livre e generoso para com sua mente:\ne o céu guarde vossas boas almas de pensar\nque descuidarei de vosso sério e grande negócio\npor estar ela comigo: não, quando os brinquedos de asa leve\ndo emplumado Cupido selarem com lasciva moleza\nmeus instrumentos especulativos e de ofício,\nde modo que meus prazeres corrompam e maculem meu serviço,\nque donas de casa façam de meu elmo uma panela,\ne todas as adversidades indignas e baixas\nfaçam frente à minha reputação!","dukebeitasyoushallprivatelydetermineeith~asteandspeedmustanswerit~98":"Doge — Seja como determinardes em particular,\nquer para ela ficar ou ir: o assunto pede pressa,\ne a rapidez deve responder-lhe.","firstsenatoryoumustawaytonight~enatoryoumustawaytonight~30":"Primeiro Senador — Deveis partir esta noite.","othellowithallmyheart~othellowithallmyheart~21":"Otelo — De todo coração.","dukeatnineithemorningherewellmeetagainot~ndrespectasdothimportyou~152":"Doge — Às nove da manhã aqui nos reuniremos de novo.\nOtelo, deixai algum oficial para trás,\ne ele vos trará nossa comissão;\ncom outras coisas de qualidade e respeito\nque vos importam.","othellosopleaseyourgracemyancientamanhei~hallthinktobesentafterme~142":"Otelo — Se praz à vossa graça, meu alferes;\nhomem é de honestidade e confiança:\na seu transporte confio minha esposa,\ncom o mais que for necessário e que vossa boa graça julgar\nse deva enviar depois de mim.","dukeletitbesogoodnighttoeveryonetobraban~awisfarmorefairthanblack~121":"Doge — Seja assim.\nBoa noite a todos. Para Brabantio.\nE, nobre senhor,\nse a virtude não carece de beleza deleitosa,\nvosso genro é muito mais belo que negro.","firstsenatoradieubravemoorusedesdemonawe~ravemoorusedesdemonawell~42":"Primeiro Senador — Adeus, bravo Mouro, tratai bem Desdemona.","brabantiolooktohermoorifthouhasteyestose~tdukesenatorsofficersetc~103":"Brabantio — Olha por ela, Mouro, se tens olhos para ver:\nela enganou o pai, e pode enganar-te. Saem o Doge, Senadores, Oficiais etc.","othellomylifeuponherfaithhonestiagomydes~xeuntothelloanddesdemona~244":"Otelo — Minha vida por sua fidelidade! Honesto Iago,\nminha Desdemona devo deixar a ti:\nrogo-te, que tua esposa a sirva:\ne traze-as depois, na melhor ocasião.\nVem, Desdemona: tenho apenas uma hora\nde amor, de assuntos mundanos e instrução,\npara gastar contigo: devemos obedecer ao tempo. Saem Otelo e Desdemona.","roderigoiago~roderigoiago~12":"Roderigo — Iago…","iagowhatsaystthounobleheart~owhatsaystthounobleheart~27":"Iago — Que dizes, nobre coração?","roderigowhatwillidothinkestthou~owhatwillidothinkestthou~31":"Roderigo — Que pensas que farei?","iagowhygotobedandsleep~iagowhygotobedandsleep~22":"Iago — Ora, vai para a cama e dorme.","roderigoiwillincontinentlydrownmyself~incontinentlydrownmyself~37":"Roderigo — Vou-me afogar já.","iagoifthoudostishallneverlovetheeafterwh~terwhythousillygentleman~59":"Iago — Se o fizeres, nunca mais te amarei. Ora, seu cavalheiro tolo!","roderigoitissillinesstolivewhentoliveist~ewhendeathisourphysician~100":"Roderigo — É tolice viver quando viver é tormento; e então temos receita para morrer quando a morte é nosso médico.","iagoovillainousihavelookedupontheworldfo~ngemyhumanitywithababoon~233":"Iago — Oh, vilania! Olhei para o mundo por quatro vezes sete anos; e desde que pude distinguir entre um benefício e uma injúria, nunca achei homem que soubesse amar a si mesmo. Antes de dizer que me afogaria por amor de uma galinha-d’angola, trocaria minha humanidade com um babuíno.","roderigowhatshouldidoiconfessitismyshame~isnotinmyvirtuetoamendit~79":"Roderigo — Que devo fazer? Confesso que é minha vergonha ser tão apaixonado; mas não está em minha virtude emendá-lo.","iagovirtueafigtisinourselvesthatwearethu~calllovetobeasectorscion~574":"Iago — Virtude! Uma figa! Está em nós sermos assim ou assado. Nossos corpos são nossos jardins, e nossas vontades, os jardineiros: de modo que, se quisermos plantar urtigas, ou semear alface, pôr hissopo e arrancar tomilho, suprir com uma só espécie de ervas, ou distrair com muitas, quer para tê-lo estéril por ociosidade, quer adubado por indústria, ora, o poder e a autoridade corretiva disto estão em nossas vontades. Se a balança de nossas vidas não tivesse um prato de razão para contrabalançar outro de sensualidade, o sangue e a baixeza de nossas naturezas nos conduziriam às conclusões mais absurdas: mas temos razão para esfriar nossos movimentos furiosos, nossos aguilhões carnais, nossas luxúrias sem freio, de que tomo isto que chamas amor por ser uma seita ou rebento.","roderigoitcannotbe~roderigoitcannotbe~18":"Roderigo — Não pode ser.","iagoitismerelyalustofthebloodandapermiss~bedrownedandgowithouther~1086":"Iago — É mera luxúria do sangue e uma permissão da vontade. Vamos, sê homem. Afogar-te! Afoga gatos e cachorrinhos cegos. Professei-me teu amigo e confesso-me atado ao teu merecimento com cabos de dureza perdurável; nunca poderia servir-te melhor do que agora. Põe dinheiro na bolsa; segue as guerras; disfarça o teu rosto com uma barba usurpada; digo, põe dinheiro na bolsa. Não pode ser que Desdemona continue por muito tempo seu amor pelo Mouro — põe dinheiro na bolsa — nem ele o dele por ela: foi um começo violento, e verás uma separação proporcional: — põe só dinheiro na bolsa. Estes Mouros são mutáveis em suas vontades: enche a bolsa de dinheiro: — a comida que para ele agora é tão deliciosa quanto gafanhotos será para ele logo tão amarga quanto colocíntida. Ela deve mudar por juventude: quando estiver saciada de seu corpo, descobrirá o erro de sua escolha: deve ter mudança, deve: portanto põe dinheiro na bolsa. Se queres a todo custo danar-te, faze-o de um jeito mais delicado que afogando-te. Faze todo o dinheiro que puderes: se a santimônia e um frágil voto entre um bárbaro errante e uma veneziana superastuta não forem duros demais para meu engenho e toda a tribo do inferno, tu a gozarás; portanto faze dinheiro. Peste ao afogamento! Está totalmente fora de questão: procura antes ser enforcado ao conseguir teu gozo do que ser afogado e ficar sem ela.","roderigowiltthoubefasttomyhopesifidepend~hopesifidependontheissue~50":"Roderigo — Serás firme em minhas esperanças, se eu depender do resultado?","iagothouartsureofmegomakemoneyihavetoldt~emoreofthistomorrowadieu~328":"Iago — Podes ter certeza de mim: — vai, faze dinheiro: — já te disse muitas vezes, e te digo de novo e de novo, odeio o Mouro: minha causa é de coração; a tua não tem menos razão. Sejamos conjuntos em nossa vingança contra ele: se puderes fazê-lo corno, dás prazer a ti, divertimento a mim. Há muitos acontecimentos no ventre do tempo que serão paridos. Avante! Vai, providencia teu dinheiro. Teremos mais disto amanhã. Adeus.","roderigowhereshallwemeetithemorning~reshallwemeetithemorning~35":"Roderigo — Onde nos encontraremos de manhã?","iagoatmylodging~iagoatmylodging~15":"Iago — Em meu alojamento.","roderigoillbewiththeebetimes~rigoillbewiththeebetimes~28":"Roderigo — Estarei contigo cedo.","iagogotofarewelldoyouhearroderigo~arewelldoyouhearroderigo~33":"Iago — Vai; adeus. Ouves, Roderigo?","roderigowhatsayyou~roderigowhatsayyou~18":"Roderigo — Que dizes?","iagonomoreofdrowningdoyouhear~omoreofdrowningdoyouhear~29":"Iago — Chega de afogamento, ouves?","roderigoiamchangedillgosellallmylandexit~edillgosellallmylandexit~40":"Roderigo — Estou mudado: vou vender toda a minha terra. Sai.","iagothusdoievermakemyfoolmypurseforimine~irthtotheworldslightexit~698":"Iago — Assim faço sempre do meu tolo a minha bolsa:\npois profanaria meu saber ganho\nse gastasse tempo com tal pateta\nsenão por meu divertimento e lucro. Odeio o Mouro:\ne corre fama por aí de que entre meus lençóis\nele fez o meu ofício: não sei se é verdade;\nmas eu, por mera suspeita nesse gênero,\nagirei como por certeza. Ele me tem em boa conta;\nmelhor funcionará meu propósito sobre ele.\nCássio é um homem de bom porte: vejamos agora:\npara obter seu posto e emplumar minha vontade\nem dupla velhacaria — Como, como? Vejamos: —\ndepois de algum tempo, abusar do ouvido de Otelo\ndizendo que ele é íntimo demais de sua esposa.\nTem uma pessoa e um trato suave\npara ser suspeitado, feito para tornar falsas as mulheres.\nO Mouro é de natureza livre e aberta,\nque julga honestos os homens que apenas parecem sê-lo,\ne será tão docilmente levado pelo nariz\nquanto os asnos.\nTenho-o. Está engendrado. Inferno e noite\ndevem trazer este monstruoso parto à luz do mundo. Sai.","aseaportincyprusanopenplacenearthequay~usanopenplacenearthequay~38":"Um porto de mar em Chipre. Um lugar aberto perto do cais.","entermontanoandtwogentlemen~ermontanoandtwogentlemen~27":"Entram Montano e dois Cavalheiros.","montanowhatfromthecapecanyoudiscernatsea~hecapecanyoudiscernatsea~40":"Montano — O que podeis divisar do cabo, no mar?","firstgentlemannothingatallitisahighwroug~venandthemaindescryasail~89":"Primeiro Cavalheiro — Nada absolutamente: as águas estão agitadíssimas;\nnão consigo, entre o céu e o oceano,\navistar uma vela.","montanomethinksthewindhathspokealoudatla~isewhatshallwehearofthis~179":"Montano — Parece-me que o vento falou alto em terra;\nrajada mais cheia nunca sacudiu nossas ameias:\nse assim ele se enfureceu no mar,\nque costelas de carvalho, quando montanhas se derretem sobre elas,\npodem manter a junta? O que ouviremos disto?","secondgentlemanasegregationoftheturkishf~onviewontheenchafedflood~268":"Segundo Cavalheiro — Uma dispersão da frota turca:\npois basta que vos ponhais na praia espumante,\no vagalhão repreendido parece golpear as nuvens;\na vaga sacudida pelo vento, com alta e monstruosa crina,\nparece lançar água sobre a Ursa ardente\ne apagar as guardas do polo sempre fixo:\nnunca vi semelhante tumulto\nnas águas enfurecidas.","montanoifthattheturkishfleetbenotenshelt~simpossibletheybearitout~92":"Montano — Se a frota turca\nnão estiver abrigada e abaiada, estão afogados:\né impossível que resistam.","enterathirdgentleman~enterathirdgentleman~20":"Entra um terceiro Cavalheiro.","thirdgentlemannewsladsourwarsaredonethed~ceonmostpartoftheirfleet~173":"Terceiro Cavalheiro — Novas, rapazes! Nossas guerras acabaram.\nA desesperada tempestade tanto fustigou os turcos\nque seu desígnio fraqueja: uma nobre nau de Veneza\nviu grave naufrágio e sofrimento\nna maior parte da frota deles.","montanohowisthistrue~montanohowisthistrue~20":"Montano — Como! É verdade?","thirdgentlemantheshipishereputinaverones~lcommissionhereforcyprus~153":"Terceiro Cavalheiro — A nau aqui aportou,\numa veronesa; Miguel Cássio,\ntenente do guerreiro Mouro Otelo,\nchegou à terra: o próprio Mouro está no mar,\ne tem plena comissão aqui para Chipre.","montanoiamgladonttisaworthygovernor~ladonttisaworthygovernor~35":"Montano — Alegro-me com isso; é digno governador.","thirdgentlemanbutthissamecassiothoughhes~ithfoulandviolenttempest~153":"Terceiro Cavalheiro — Mas este mesmo Cássio, embora fale de conforto\nquanto à perda turca, mostra-se triste,\ne pede que o Mouro esteja a salvo; pois foram separados\npor tempestade feia e violenta.","montanoprayheavenshebeforihaveservedhima~alblueanindistinctregard~210":"Montano — Peçamos aos céus que esteja;\npois servi sob ele, e o homem comanda\ncomo soldado cabal. Vamos à beira-mar, ho!\nTanto para ver a nau que chegou\nquanto para lançar os olhos pelo valente Otelo,\naté que o oceano e o azul aéreo\nse façam um olhar indistinto.","thirdgentlemancomeletsdosoforeveryminute~xpectancyofmorearrivance~67":"Terceiro Cavalheiro — Vamos, façamo-lo:\npois cada minuto é expectativa\nde mais chegadas.","entercassio~entercassio~11":"Entra Cássio.","cassiothanksyouthevaliantofthiswarlikeis~lostushimonadangeroussea~140":"Cássio — Obrigado, valentes desta ilha guerreira,\nque tanto estimais o Mouro! Oh, que os céus\nlhe deem defesa contra os elementos,\npois o perdi num mar perigoso.","montanoishewellshippd~montanoishewellshippd~21":"Montano — Está bem embarcado?","cassiohisbarkisstoutlytimberdhispilotofv~crywithinasailasailasail~144":"Cássio — Seu barco é robustamente construído, seu piloto\nde habilidade muito experiente e comprovada;\npor isso minhas esperanças, não fartas até a morte,\nestão em ousada cura. Um grito dentro: “Uma vela, uma vela, uma vela!”","enterafourthgentleman~enterafourthgentleman~21":"Entra um quarto Cavalheiro.","cassiowhatnoise~cassiowhatnoise~15":"Cássio — Que ruído?","fourthgentlemanthetownisemptyonthebrowot~sofpeopleandtheycryasail~78":"Quarto Cavalheiro — A cidade está vazia; na beira do mar\npostam-se fileiras de gente, e gritam: “Uma vela!”","cassiomyhopesdoshapehimforthegovernorgun~mforthegovernorgunsheard~46":"Cássio — Minhas esperanças o figuram como o governador. Ouvem-se tiros.","secondgentlementheydodischargetheirshoto~ourtesyourfriendsatleast~66":"Segundo Cavalheiro — Disparam seus tiros de cortesia:\namigos, pelo menos.","cassioiprayyousirgoforthandgiveustruthwh~truthwhotisthatisarrived~57":"Cássio — Rogo-vos, senhor, ide lá fora,\ne dai-nos a verdade de quem é que chegou.","secondgentlemanishallexit~econdgentlemanishallexit~25":"Segundo Cavalheiro — Irei. Sai.","montanobutgoodlieutenantisyourgeneralwiv~tenantisyourgeneralwived~42":"Montano — Mas, bom tenente, vosso general é casado?","cassiomostfortunatelyhehathachievedamaid~eationdoestiretheingener~163":"Cássio — Felicíssimamente: conquistou uma donzela\nque excede a descrição e a fama selvagem;\numa que sobrepuja os floreios das penas que brasonam,\ne no traje essencial da criação\ncansa o engenho do artista.","reentersecondgentleman~reentersecondgentleman~22":"Reentra o segundo Cavalheiro.","hownowwhohasputin~hownowwhohasputin~17":"Então! Quem aportou?","secondgentlemantisoneiagoancienttothegen~eiagoancienttothegeneral~44":"Segundo Cavalheiro — É um certo Iago, alferes do general.","cassiohashadmostfavourableandhappyspeedt~felybythedivinedesdemona~232":"Cássio — Teve a mais favorável e feliz viagem:\nas próprias tempestades, os altos mares e os ventos uivantes,\nos rochedos sulcados e os bancos de areia reunidos —\ntraidores submersos para travar a quilha inocente —\ncomo se tivessem senso da beleza, omitem\nsuas naturezas mortais, deixando passar a salvo\na divina Desdemona.","montanowhatisshe~montanowhatisshe~16":"Montano — Quem é ela?","cassioshethatispakeofourgreatcaptainscap~andbringallcypruscomfort~318":"Cássio — Aquela de quem falei, a capitã de nosso grande capitão,\ndeixada sob a condução do ousado Iago,\ncuja chegada aqui antecipa nossos pensamentos\nem uma semana de pressa. Grande Júpiter, guarda Otelo,\ne enfuna sua vela com teu próprio sopro poderoso,\npara que ele abençoe esta baía com sua alta nau,\ndê os ofegos rápidos do amor nos braços de Desdemona,\ndê fogo renovado a nossos espíritos extintos\ne traga a todo Chipre conforto!","enterdesdemonaemiliaiagoroderigoandatten~agoroderigoandattendants~45":"Entram Desdemona, Emília, Iago, Roderigo e Criados.","obeholdtherichesoftheshipiscomeonshoreye~veryhandenwheeltheeround~149":"Oh, vede,\na riqueza da nau chegou à terra!\nHomens de Chipre, dai-lhe os joelhos.\nSalve, senhora! E a graça do céu,\npor diante, por trás e por todos os lados,\nte circunde!","desdemonaithankyouvaliantcassiowhattidin~ingscanyoutellmeofmylord~62":"Desdemona — Agradeço-vos, valente Cássio.\nQue novas podeis dar-me de meu senhor?","cassioheisnotyetarrivednorknowiaughtbutt~wellandwillbeshortlyhere~70":"Cássio — Ainda não chegou: nem sei de nada\nsenão que está bem e logo estará aqui.","desdemonaobutifearhowlostyoucompany~utifearhowlostyoucompany~35":"Desdemona — Oh, mas receio… Como perdestes companhia?","cassiothegreatcontentionoftheseaandskies~ithinasailasailgunsheard~96":"Cássio — A grande contenda do mar e dos céus\napartou nossa companhia… Mas, escutai! Uma vela. Dentro: “Uma vela, uma vela!” Ouvem-se tiros.","secondgentlemantheygivetheirgreetingtoth~delthislikewiseisafriend~69":"Segundo Cavalheiro — Saúdam a cidadela;\neste também é um amigo.","cassioseeforthenewsexitgentlemangoodanci~showofcourtesykissingher~187":"Cássio — Vede as novas. Sai o Cavalheiro.\nBom alferes, sois bem-vindo. Para Emília. Bem-vinda, senhora.\nNão vos fira a paciência, bom Iago,\nque eu estenda meus modos; é minha educação\nque me dá esta ousada mostra de cortesia. Beijando-a.","iagosirwouldshegiveyousomuchofherlipsaso~stowsonmeyoullhaveenough~82":"Iago — Senhor, se ela vos desse tanto de seus lábios\nquanto de sua língua dá muitas vezes a mim,\nteríeis o bastante.","desdemonaalasshehasnospeech~demonaalasshehasnospeech~27":"Desdemona — Ai, ela não tem fala.","iagoinfaithtoomuchifinditstillwhenihavel~artandchideswiththinking~133":"Iago — Na verdade, demais;\nsinto-o sempre, quando tenho vontade de dormir:\nmas, diante de vossa senhoria, concedo,\nela põe a língua um pouco no coração\ne ralha com o pensamento.","emiliayouhavelittlecausetosayso~ouhavelittlecausetosayso~31":"Emília — Tendes pouca causa para dizê-lo.","iagocomeoncomeonyouarepicturesoutofdoors~yandhousewivesinyourbeds~166":"Iago — Vamos, vamos; sois pinturas fora de casa,\nsinos em vossos salões, gatas selvagens em vossas cozinhas,\nsantas em vossas injúrias, demônios quando ofendidas,\natrizes em vossa lida doméstica e donas de casa em vossas camas.","desdemonaofieupontheeslanderer~onaofieupontheeslanderer~30":"Desdemona — Oh, que vergonha, caluniador!","iagonayitistrueorelseiamaturkyourisetopl~setoplayandgotobedtowork~58":"Iago — Não, é verdade, ou então sou um turco:\nlevantais-vos para brincar e deitais-vos para trabalhar.","emiliayoushallnotwritemypraise~youshallnotwritemypraise~30":"Emília — Não escrevereis meu elogio.","iagonoletmenot~iagonoletmenot~14":"Iago — Não, que eu não o faça.","desdemonawhatwouldstthouwriteofmeifthous~meifthoushouldstpraiseme~55":"Desdemona — Que escreverias de mim, se tivesses de\nlouvar-me?","iagoogentleladydonotputmetotforiamnothin~riamnothingifnotcritical~54":"Iago — Oh, gentil senhora, não me ponhais à prova;\npois nada sou, se não for crítico.","desdemonacomeonassaytheresonegonetotheha~heresonegonetotheharbour~45":"Desdemona — Vamos, tenta. Foi alguém ao porto?","iagoaymadam~iagoaymadam~11":"Iago — Sim, senhora.","desdemonaiamnotmerrybutidobeguilethethin~mehowwouldstthoupraiseme~88":"Desdemona — Não estou alegre; mas engano\no que sou, parecendo outra.\nVamos, como me louvarias?","iagoiamaboutitbutindeedmyinventioncomesf~nesforusetheotherusethit~191":"Iago — Estou nisso; mas, na verdade, minha invenção\nsai da cabeça como visgo de pano grosso;\narranca miolos e tudo: mas minha Musa se esforça,\ne assim é parida.\nSe ela for bela e sábia, beleza e espírito,\num é para o uso, o outro o usa.","desdemonawellpraisedhowifshebeblackandwi~dhowifshebeblackandwitty~43":"Desdemona — Bem louvado! E se for negra e espirituosa?","iagoifshebeblackandtheretohaveawitshellf~thatshallherblacknessfit~73":"Iago — Se for negra, e além disso tiver espírito,\nachará um branco que a sua negrura ajuste.","desdemonaworseandworse~desdemonaworseandworse~22":"Desdemona — Cada vez pior.","emiliahowiffairandfoolish~miliahowiffairandfoolish~25":"Emília — E se for bela e tola?","iagosheneveryetwasfoolishthatwasfairfore~herfollyhelpdhertoanheir~67":"Iago — Nunca foi tola a que foi bela;\npois até a tolice lhe ajudou a ter um herdeiro.","desdemonatheseareoldfondparadoxestomakef~orherthatsfoulandfoolish~113":"Desdemona — São velhos e tolos paradoxos para fazer rir os tolos na taverna. Que miserável elogio tens para a que é feia e tola?","iagotheresnonesofoulandfoolishthereuntob~kswhichfairandwiseonesdo~78":"Iago — Não há nenhuma tão feia e tola ainda por cima\nque não faça as feias travessuras que as belas e sábias fazem.","desdemonaoheavyignorancethoupraisestthew~evouchofverymaliceitself~172":"Desdemona — Oh, pesada ignorância! Louvas melhor o pior. Mas que elogio poderias conceder a uma mulher realmente merecedora, uma que, na autoridade de seu mérito, tivesse com justiça imposto o testemunho da própria malícia?","iagoshethatwaseverfairandneverproudhadto~wightifeversuchwightwere~376":"Iago — A que foi sempre bela e nunca orgulhosa,\ntinha língua à vontade e nunca foi ruidosa,\nnunca lhe faltou ouro e nunca andou garrida,\nfugiu do seu desejo e disse “Agora posso”,\na que, irada, com a vingança ao alcance,\nmandou o agravo ficar e o despeito fugir,\na que em sabedoria nunca foi tão frágil\npara trocar a cabeça do bacalhau pela cauda do salmão;\na que podia pensar e nunca revelar o pensamento,\nver pretendentes seguindo-a e não olhar para trás,\nela era uma criatura, se alguma tal criatura houve…","desdemonatodowhat~desdemonatodowhat~17":"Desdemona — Para fazer o quê?","iagotosucklefoolsandchroniclesmallbeer~olsandchroniclesmallbeer~38":"Iago — Para amamentar tolos e registrar cerveja fraca.","desdemonaomostlameandimpotentconclusiond~faneandliberalcounsellor~134":"Desdemona — Oh, conclusão coxíssima e impotente! Não aprendas com ele, Emília, ainda que seja teu marido. Que dizeis, Cássio? Não é um conselheiro profanuíssimo e licencioso?","cassiohespeakshomemadamyoumayrelishhimmo~esoldierthaninthescholar~70":"Cássio — Fala direto, senhora: podeis apreciá-lo mais no soldado do que no erudito.","iagoasidehetakesherbythepalmaywellsaidwh~inthemooriknowhistrumpet~454":"Iago — À parte. Ele a toma pela palma: sim, bem dito, sussurra: com teia tão pequena quanto esta prenderei mosca tão grande quanto Cássio. Sim, sorri para ela, sorri; vou algemar-te em teu próprio galanteio. Dizeis a verdade; é assim, de fato: se tais truques vos despojarem do posto de tenente, melhor teria sido não beijardes tanto vossos três dedos, nos quais agora de novo estais tão apto a fazer o senhor. Muito bem; bem beijado! Excelente cortesia! É assim, de fato. Mais uma vez os dedos aos lábios? Quisera que fossem seringas de clister, por vossa causa! Trombeta dentro. O Mouro! Conheço sua trombeta.","cassiotistrulyso~cassiotistrulyso~16":"Cássio — É verdade.","desdemonaletsmeethimandreceivehim~letsmeethimandreceivehim~33":"Desdemona — Vamos ao encontro dele e recebamo-lo.","cassiolowherehecomes~cassiolowherehecomes~20":"Cássio — Vede, aí vem ele!","enterothelloandattendants~nterothelloandattendants~25":"Entram Otelo e Criados.","othelloomyfairwarrior~othelloomyfairwarrior~21":"Otelo — Oh, minha bela guerreira!","desdemonamydearothello~desdemonamydearothello~22":"Desdemona — Meu caro Otelo!","othelloitgivesmewondergreatasmycontentto~hissucceedsinunknownfate~349":"Otelo — Dá-me assombro tão grande quanto meu contentamento\nver-te aqui antes de mim. Oh, alegria de minha alma!\nSe após toda tempestade vierem tais calmarias,\nque os ventos soprem até despertarem a morte!\nE que o barco esforçado escale colinas de mar\naltas como o Olimpo e mergulhe de novo tão fundo\nquanto o inferno está do céu! Se fosse agora morrer,\nseria agora ser felicíssimo; pois, receio,\nminha alma tem seu contentamento tão absoluto\nque nenhum outro conforto como este\nsucede no destino desconhecido.","desdemonatheheavensforbidbutthatourloves~reaseevenasourdaysdogrow~84":"Desdemona — Os céus não permitam\nque nossos amores e confortos não aumentem,\nassim como nossos dias crescem!","othelloamentothatsweetpowersicannotspeak~hateerourheartsshallmake~158":"Otelo — Amém a isso, doces poderes!\nNão posso falar bastante deste contentamento;\nprende-me aqui; é demasiada alegria:\ne isto, e isto, as maiores discórdias sejam Beijando-a.\nque nossos corações jamais farão!","iagoasideoyouarewelltunednowbutillsetdow~kethismusicashonestasiam~78":"Iago — À parte. Oh, estais bem afinados agora!\nMas eu baixarei as cravelhas que fazem esta música,\ntão honesto quanto sou.","othellocomeletustothecastlenewsfriendsou~lodesdemonaandattendants~420":"Otelo — Vamos, ao castelo.\nNovas, amigos; nossas guerras acabaram, os turcos\nestão afogados.\nComo vai meu velho conhecido desta ilha?\nQuerida, sereis muito desejada em Chipre;\nachei grande amor entre eles. Oh, minha doce,\ntagarelo fora de moda, e deliro\nnos meus próprios confortos. Rogo-te, bom Iago,\nvai à baía e desembarca meus baús:\ntraze o mestre à cidadela;\nele é bom, e seu merecimento\nexige muito respeito. Vem, Desdemona,\numa vez mais, bem-encontrados em Chipre. Saem Otelo, Desdemona e Criados.","iagodothoumeetmepresentlyattheharbourcom~aisdirectlyinlovewithhim~248":"Iago — Encontra-me já no porto. Vem cá. Se fores valente — como dizem que homens baixos, quando apaixonados, têm então uma nobreza na natureza maior do que a que lhes é nativa — escuta-me. O tenente esta noite vigia na guarda do pátio: — primeiro, devo dizer-te isto — Desdemona está diretamente apaixonada por ele.","roderigowithhimwhytisnotpossible~withhimwhytisnotpossible~32":"Roderigo — Por ele! Ora, não é possível.","iagolaythyfingerthusandletthysoulbeinstr~womanhathfoundhimalready~1152":"Iago — Põe o dedo assim, e instrui tua alma. Nota com que violência ela amou primeiro o Mouro, só por fanfarronices e por contar-lhe mentiras fantásticas: e o amará ainda por tagarelar? Que teu discreto coração não o pense. Seu olho deve ser alimentado; e que deleite terá de olhar o diabo? Quando o sangue se embota com o ato do prazer, deve haver, para de novo inflamá-lo e dar à saciedade um apetite fresco, graça no rosto, afinidade em anos, modos e belezas; do que tudo o Mouro é carente: ora, por falta dessas conveniências requeridas, sua delicada ternura se achará ludibriada, começará a sentir náusea, a desgostar e abominar o Mouro; a própria natureza a instruirá nisso e a compelirá a uma segunda escolha. Agora, senhor, concedido isto — como é posição muito fecunda e sem forçar — quem está tão eminente no grau desta fortuna quanto Cássio? Um patife muito volúvel; sem consciência além de assumir a mera forma de aparência civil e humana, para melhor alcançar sua salgada e escondidíssima afeição dissoluta? Ora, ninguém; ora, ninguém: um patife escorregadio e sutil, um descobridor de ocasiões, que tem um olho capaz de cunhar e forjar vantagens, ainda que a verdadeira vantagem nunca se apresente; um patife diabólico. Além disso, o patife é belo, jovem, e tem todos os requisitos que a loucura e as mentes verdes procuram: um patife pestilento e completo; e a mulher já o achou.","roderigoicannotbelievethatinhershesfullo~llofmostblessedcondition~61":"Roderigo — Não posso crer isso nela; é cheia de condição santíssima.","iagoblessedfigsendthewineshedrinksismade~fhishanddidstnotmarkthat~170":"Iago — Santíssima uma ova! O vinho que ela bebe é feito de uvas: se tivesse sido santa, nunca teria amado o Mouro. Santíssimo pudim! Não a viste brincar com a palma da mão dele? Não notaste isso?","roderigoyesthatididbutthatwasbutcourtesy~didbutthatwasbutcourtesy~40":"Roderigo — Sim, isso notei; mas foi só cortesia.","iagolecherybythishandanindexandobscurepr~llmorefavourablyminister~536":"Iago — Luxúria, por esta mão; um índice e obscuro prólogo à história da lascívia e dos pensamentos imundos. Encontraram-se tão perto com os lábios que seus hálitos se abraçaram. Pensamentos vilíssimos, Roderigo! Quando essas mutualidades abrem assim o caminho, logo em seguida vem o mestre e principal exercício, a conclusão encarnada. Bah! Mas, senhor, sede guiado por mim: trouxe-vos de Veneza. Vigiai esta noite; quanto ao comando, eu o porei sobre vós. Cássio não vos conhece. Não estarei longe de vós: achai alguma ocasião para irritar Cássio, ou falando alto demais, ou maculando sua disciplina; ou de qualquer outro modo que vos aprouver, que o tempo ministrar mais favoravelmente.","roderigowell~roderigowell~12":"Roderigo — Bem.","iagosirheisrashandverysuddenincholerandh~pectationofourprosperity~365":"Iago — Senhor, ele é precipitado e muito súbito na cólera, e talvez bata em vós: provocai-o, para que o faça; pois mesmo disso causarei que os de Chipre se amotinem; cuja apaziguação não voltará a ter verdadeiro sabor senão com a destituição de Cássio. Assim tereis uma jornada mais curta a vossos desejos, pelos meios que então terei para promovê-los; e removido o impedimento do modo mais proveitoso, sem o qual não haveria expectativa de nossa prosperidade.","roderigoiwilldothisificanbringittoanyopp~nbringittoanyopportunity~48":"Roderigo — Farei isto, se puder levá-lo a alguma oportunidade.","iagoiwarranttheemeetmebyandbyatthecitade~ecessariesashorefarewell~79":"Iago — Garanto-te. Encontra-me daqui a pouco na cidadela: devo buscar seus pertences em terra. Adeus.","roderigoadieuexit~roderigoadieuexit~17":"Roderigo — Adeus. Sai.","iagothatcassiolovesheridowellbelieveitth~eisneverseentillusedexit~885":"Iago — Que Cássio a ama, creio-o bem;\nque ela o ama, é natural e de grande crédito:\no Mouro, embora eu não o suporte,\né de natureza constante, amorosa, nobre,\ne ouso pensar que será para Desdemona\num marido dileto. Ora, eu também a amo;\nnão por luxúria absoluta, embora talvez\neu responda por pecado tão grande,\nmas em parte levado a alimentar minha vingança,\npois suspeito que o fogoso Mouro\npulou para o meu lugar; o pensamento disso\nroi, como mineral venenoso, minhas entranhas;\ne nada pode ou deve contentar minha alma\naté que eu esteja quite com ele, esposa por esposa,\nou, falhando isso, ao menos que eu ponha o Mouro\nnum ciúme tão forte\nque o juízo não possa curar. Para o que fazer,\nse este pobre lixo de Veneza, que eu aço\npor sua caça veloz, suportar o incitamento,\nterei nosso Miguel Cássio pelo quadril,\ncalunia-lo-ei ao Mouro em linguagem grosseira —\npois temo Cássio também com meu barrete de dormir —\nfarei o Mouro agradecer-me, amar-me e recompensar-me\npor fazê-lo escandalosamente um asno\ne tramar contra sua paz e sossego\naté a loucura. Está aqui, mas ainda confuso:\na cara limpa da velhacaria nunca se vê até ser usada. Sai.","astreet~astreet~7":"Uma rua.","enteraheraldwithaproclamationpeoplefollo~clamationpeoplefollowing~44":"Entra um Arauto com uma proclamação; Povo seguindo.","heralditisothellospleasureournobleandval~oblegeneralothelloexeunt~482":"Arauto — É vontade de Otelo, nosso nobre e valente general, que, por certas notícias agora chegadas, que informam a mera perdição da frota turca, cada homem se entregue ao triunfo; uns a dançar, outros a fazer fogueiras, cada um ao folguedo e festa a que o inclina seu gosto: pois, além destas benéficas novas, é a celebração de suas núpcias. Tanto foi sua vontade que se proclamasse. Todas as despensas estão abertas, e há plena liberdade de banquetear desde esta presente hora das cinco até que o sino tenha dado as onze. O céu abençoe a ilha de Chipre e nosso nobre general Otelo! Saem.","ahallinthecastle~ahallinthecastle~16":"Um salão no castelo.","enterothellodesdemonacassioandattendants~emonacassioandattendants~40":"Entram Otelo, Desdemona, Cássio e Criados.","othellogoodmichaellookyoutotheguardtonig~pnottooutsportdiscretion~101":"Otelo — Bom Miguel, cuida da guarda esta noite:\nensinemo-nos aquela honrada contenção\nde não ultrapassar a discrição na folia.","cassioiagohathdirectionwhattodobutnotwit~ypersonaleyewillilooktot~78":"Cássio — Iago tem instruções do que fazer;\nmas, não obstante, com meu olho pessoal\nolharei por isso.","othelloiagoismosthonestmichaelgoodnightt~lodesdemonaandattendants~221":"Otelo — Iago é honestíssimo.\nMiguel, boa noite: amanhã, bem cedo,\ndeixa-me falar contigo. Para Desdemona. Vem, meu caro amor,\nfeita a compra, os frutos hão de seguir;\neste lucro ainda está por vir entre mim e ti.\nBoa noite. Saem Otelo, Desdemona e Criados.","enteriago~enteriago~9":"Entra Iago.","cassiowelcomeiagowemusttothewatch~comeiagowemusttothewatch~33":"Cássio — Bem-vindo, Iago; devemos ir à guarda.","iagonotthishourlieutenanttisnotyettenoth~hherandsheissportforjove~177":"Iago — Ainda não, tenente; não são ainda dez horas. Nosso general nos dispensou tão cedo por amor de sua Desdemona; a quem não censuremos por isso: ele ainda não tornou a noite lasciva com ela; e ela é um prazer para Júpiter.","cassioshesamostexquisitelady~ioshesamostexquisitelady~28":"Cássio — É uma dama requintadíssima.","iagoandillwarrantherfullofgame~dillwarrantherfullofgame~30":"Iago — E, garanto-vos, cheia de ardor.","cassioindeedshesamostfreshanddelicatecre~freshanddelicatecreature~45":"Cássio — De fato, é uma criatura frescuríssima e delicada.","iagowhataneyeshehasmethinksitsoundsaparl~undsaparleyofprovocation~55":"Iago — Que olho tem! Parece-me que soa um parlamento de provocação.","cassioaninvitingeyeandyetmethinksrightmo~ndyetmethinksrightmodest~44":"Cássio — Um olho convidativo; e contudo parece-me muito modesto.","iagoandwhenshespeaksisitnotanalarumtolov~aksisitnotanalarumtolove~41":"Iago — E quando fala, não é um alarme ao amor?","cassiosheisindeedperfection~siosheisindeedperfection~27":"Cássio — É de fato a perfeição.","iagowellhappinesstotheirsheetscomelieute~othehealthofblackothello~150":"Iago — Bem, felicidade para seus lençóis! Vamos, tenente, tenho uma caneca de vinho; e aqui fora estão um par de galãs de Chipre que querem muito uma rodada à saúde do negro Otelo.","cassionottonightgoodiagoihaveverypoorand~hercustomofentertainment~127":"Cássio — Esta noite não, bom Iago: tenho miolos pobríssimos e infelizes para beber: bem quisera que a cortesia inventasse algum outro costume de hospitalidade.","iagootheyareourfriendsbutonecupilldrinkf~sbutonecupilldrinkforyou~45":"Iago — Oh, são nossos amigos; só uma taça: beberei por vós.","cassioihavedrunkbutonecuptonightandthatw~askmyweaknesswithanymore~159":"Cássio — Bebi só uma taça esta noite, e essa ainda astuciosamente diluída, e vede que inovação faz aqui: sou infeliz na fraqueza, e não ouso sobrecarregar minha debilidade com mais.","iagowhatmantisanightofrevelsthegallantsd~evelsthegallantsdesireit~47":"Iago — Ora, homem! É noite de festa: os galãs o desejam.","cassiowherearethey~cassiowherearethey~18":"Cássio — Onde estão?","iagohereatthedooriprayyoucallthemin~hedooriprayyoucallthemin~35":"Iago — Aqui à porta; peço-vos, chamai-os.","cassioilldotbutitdislikesmeexit~lldotbutitdislikesmeexit~31":"Cássio — Farei isso; mas não me agrada. Sai.","iagoificanfastenbutonecupuponhimwiththat~elybothwithwindandstream~559":"Iago — Se eu puder impingir-lhe apenas uma taça,\ncom o que já bebeu esta noite,\nficará tão cheio de briga e ofensa\nquanto o cão de minha jovem senhora. Ora, meu doente tolo Roderigo,\nque o amor virou quase do avesso,\nbebeu esta noite a Desdemona\npoções até o fundo da caneca; e deve vigiar:\ntrês rapazes de Chipre, nobres espíritos inchados,\nque guardam suas honras a cautelosa distância,\nos próprios elementos desta ilha guerreira,\nesta noite os atordoei com taças transbordantes,\ne vigiam também. Agora, entre este rebanho de bêbados,\ndevo pôr nosso Cássio em alguma ação\nque ofenda a ilha. — Mas aqui vêm eles:\nse a consequência apenas aprovar meu sonho,\nmeu barco navega livre, com vento e correnteza.","reentercassiowithhimmontanoandgentlemens~ervantsfollowingwithwine~64":"Reentra Cássio; com ele Montano e Cavalheiros; criados seguindo com vinho.","cassioforegodtheyhavegivenmearousealread~havegivenmearousealready~41":"Cássio — Por Deus, já me deram uma rodada.","montanogoodfaithalittleonenotpastapintas~otpastapintasiamasoldier~51":"Montano — Na boa fé, uma pequena; não mais que uma pinta, como sou soldado.","iagosomewinehosingsandletmethecanakincli~soldierdrinksomewineboys~132":"Iago — Vinho, ho! Canta. E deixai-me o caneco tinir, tinir;\ne deixai-me o caneco tinir.\nO soldado é um homem;\na vida, um palmo apenas;\nora, que o soldado beba. Vinho, rapazes!","cassioforegodanexcellentsong~ioforegodanexcellentsong~28":"Cássio — Por Deus, excelente canção.","iagoilearneditinenglandwhereindeedtheyar~oarenothingtoyourenglish~135":"Iago — Aprendi-a na Inglaterra, onde, de fato, são potentíssimos no copo: vosso dinamarquês, vosso alemão e vosso holandês barrigudo — Bebei, ho! — nada são ao lado do inglês.","cassioisyourenglishmansoexpertinhisdrink~mansoexpertinhisdrinking~43":"Cássio — Vosso inglês é tão perito em beber?","iagowhyhedrinksyouwithfacilityyourdanede~thenextpottlecanbefilled~132":"Iago — Ora, ele bebe, com facilidade, vosso dinamarquês até cair de bêbado; não sua para derrubar vosso alemão; dá ao vosso holandês um vômito antes que se possa encher a próxima caneca.","cassiotothehealthofourgeneral~otothehealthofourgeneral~29":"Cássio — À saúde de nosso general!","montanoiamforitlieutenantandilldoyoujust~tenantandilldoyoujustice~43":"Montano — Estou nisso, tenente; e vos farei justiça.","iagoosweetenglandkingstephenwasaworthype~cloakabouttheesomewineho~244":"Iago — Oh, doce Inglaterra!\nO rei Estêvão era um digno par,\nsuas calças custaram-lhe só uma coroa;\ntinha-as por seis pence caras demais,\ncom isso chamou o alfaiate de vilão.\nEra um sujeito de alta renomada,\ne tu és de baixo grau:\né o orgulho que derruba o país;\nentão toma tua velha capa em volta de ti.\nVinho, ho!","cassiowhythisisamoreexquisitesongthanthe~xquisitesongthantheother~45":"Cássio — Ora, esta é uma canção mais requintada que a outra.","iagowillyouheartagain~iagowillyouheartagain~21":"Iago — Quereis ouvi-la de novo?","cassionoforiholdhimtobeunworthyofhisplac~erebesoulsmustnotbesaved~131":"Cássio — Não; pois tenho por indigno de seu posto quem faz tais coisas. Bem, Deus está acima de tudo; e há almas que devem ser salvas, e há almas que não devem ser salvas.","iagoitstruegoodlieutenant~agoitstruegoodlieutenant~25":"Iago — É verdade, bom tenente.","cassioformineownpartnooffencetothegenera~nofqualityihopetobesaved~73":"Cássio — De minha parte — sem ofensa ao general, nem a homem algum de qualidade — espero ser salvo.","iagoandsodoitoolieutenant~agoandsodoitoolieutenant~25":"Iago — E eu também, tenente.","cassioaybutbyyourleavenotbeforemethelieu~enoughandspeakwellenough~280":"Cássio — Sim, mas, com vossa licença, não antes de mim; o tenente deve ser salvo antes do alferes. Não falemos mais disto; vamos aos nossos afazeres. — Perdoai-nos os pecados! — Cavalheiros, olhemos nosso serviço. Não penseis, cavalheiros, que estou bêbado: este é meu alferes; esta é minha mão direita, e esta é a esquerda: não estou bêbado agora; posso ficar de pé bem o bastante, e falar bem o bastante.","allexcellentwell~allexcellentwell~16":"Todos — Excelentemente bem.","cassiowhyverywellthenyoumustnotthinkthen~hinkthenthatiamdrunkexit~56":"Cássio — Ora, muito bem então; então não deveis pensar que estou bêbado. Sai.","montanototheplatformmasterscomeletssetth~sterscomeletssetthewatch~46":"Montano — À plataforma, mestres; vamos, montemos a guarda.","iagoyouseethisfellowthatisgonebeforeheis~rmitywillshakethisisland~235":"Iago — Vedes este sujeito que se foi adiante;\né soldado digno de estar ao lado de César\ne dar comando: e vede só o seu vício;\né, para a sua virtude, um equinócio justo,\num tão longo quanto o outro: é pena dele.\nTemo a confiança que Otelo nele põe.\nNum momento estranho de sua fraqueza,\nabalará esta ilha.","montanobutisheoftenthus~montanobutisheoftenthus~23":"Montano — Mas ele é muitas vezes assim?","iagotisevermoretheprologuetohissleephell~tifdrinkrocknothiscradle~89":"Iago — É sempre o prólogo de seu sono:\nvigiará o relógio um giro duplo,\nse a bebida não embalar seu berço.","montanoitwerewellthegeneralwereputinmind~tonhisevilsisnotthistrue~145":"Montano — Seria bom\nque o general fosse posto a par disto.\nTalvez não o veja; ou sua boa natureza\nestima a virtude que aparece em Cássio,\ne não olha seus males: não é verdade?","enterroderigo~enterroderigo~13":"Entra Roderigo.","iagoasidetohimhownowroderigoiprayyouafte~lieutenantgoexitroderigo~68":"Iago — À parte, para ele. Então, Roderigo! Peço-vos, ide atrás do tenente; ide. Sai Roderigo.","montanoandtisgreatpitythatthenoblemoorsh~stactiontosaysotothemoor~137":"Montano — E é grande pena que o nobre Mouro\narrisque um posto como o de seu segundo\ncom alguém de fraqueza enraizada:\nseria ação honesta dizê-lo\nassim ao Mouro.","iagonotiforthisfairislandidolovecassiowe~atnoisecrywithinhelphelp~108":"Iago — Eu não, por esta bela ilha:\namo bem Cássio; e faria muito\npara curá-lo deste mal. — Mas, escutai! Que ruído? Grito dentro: “Socorro! Socorro!”","reentercassiodrivinginroderigo~rcassiodrivinginroderigo~30":"Reentra Cássio, expulsando Roderigo.","cassioyourogueyourascal~cassioyourogueyourascal~23":"Cássio — Seu patife! Seu canalha!","montanowhatsthematterlieutenant~whatsthematterlieutenant~31":"Montano — Qual é o assunto, tenente?","cassioaknaveteachmemydutyillbeattheknave~eknaveintoatwiggenbottle~58":"Cássio — Um biltre ensinar-me o meu dever!\nSurrarei o biltre até fazê-lo uma garrafa de vime.","roderigobeatme~roderigobeatme~14":"Roderigo — Surrar-me!","cassiodostthouprateroguestrikingroderigo~ateroguestrikingroderigo~40":"Cássio — Ainda tagarelas, patife? Golpeando Roderigo.","montanonaygoodlieutenantstayinghimiprayy~miprayyousirholdyourhand~57":"Montano — Não, bom tenente; Detendo-o.\nrogo-vos, senhor, contende a mão.","cassioletmegosirorillknockyouoerthemazza~illknockyouoerthemazzard~42":"Cássio — Deixai-me, senhor,\nou arrebento-vos a cabeça.","montanocomecomeyouredrunk~ontanocomecomeyouredrunk~25":"Montano — Vamos, vamos, estais bêbado.","cassiodrunktheyfight~cassiodrunktheyfight~20":"Cássio — Bêbado! Lutam.","iagoasidetoroderigoawayisaygooutandcryam~ldyouwillbeshamedforever~251":"Iago — À parte, para Roderigo. Fora, digo; saí, e gritai motim. Sai Roderigo.\nNão, bom tenente — ai, cavalheiros; —\nSocorro, ho! — Tenente — senhor — Montano — senhor;\nSocorro, mestres! — Eis uma bela guarda, de fato! Toca o sino.\nQuem é que toca o sino? — Diabo, ho!\nA cidade se levantará: pela vontade de Deus, tenente, parai!\nSereis envergonhado para sempre.","reenterothelloandattendants~nterothelloandattendants~27":"Reentram Otelo e Criados.","othellowhatisthematterhere~hellowhatisthematterhere~26":"Otelo — Qual é o assunto aqui?","montanozoundsibleedstilliamhurttothedeat~liamhurttothedeathfaints~47":"Montano — Pelas chagas, ainda sangro; estou ferido de morte. Desmaia.","othelloholdforyourlives~othelloholdforyourlives~23":"Otelo — Parai, por vossas vidas!","iagoholdholieutenantsirmontanogentlemenh~akstoyouholdholdforshame~115":"Iago — Parai, ho! Tenente — senhor — Montano — cavalheiros —\nesquecestes todo senso de lugar e dever?\nParai! O general vos fala; parai, parai, por vergonha!","othellowhyhownowhofromwhenceariseththisa~thisonthyloveichargethee~368":"Otelo — Ora, que é isto, ho! De onde surge isto?\nTornamo-nos turcos, e fazemos a nós mesmos\no que o céu proibiu aos otomanos?\nPor vergonha cristã, deixai esta briga bárbara:\naquele que se mover a seguir para tomar a própria raiva\ntem a alma por leve; morre ao movimento.\nCalai aquele sino terrível: assusta a ilha\ne a tira de seu juízo. Qual é o assunto, mestres?\nHonesto Iago, que pareces morto de pesar,\nfala, quem começou isto? Por teu amor, ordeno-te.","iagoidonotknowfriendsallbutnowevennowinq~thatbroughtmetoapartofit~293":"Iago — Não sei: amigos todos, até agora há pouco,\nem quartel, e em termos como noiva e noivo\nque se despem para a cama; e então, agora mesmo —\ncomo se algum planeta tivesse desatinado os homens —\nespadas fora, e investindo um contra o peito do outro,\nem oposição sangrenta. Não posso dizer\nnenhum começo a esta querela mesquinha;\ne quisera que em ação gloriosa tivesse perdido\nas pernas que me trouxeram a parte dela!","othellohowcomesitmichaelyouarethusforgot~tmichaelyouarethusforgot~40":"Otelo — Como é, Miguel, que assim vos esquecestes?","cassioiprayyoupardonmeicannotspeak~yyoupardonmeicannotspeak~34":"Cássio — Peço-vos, perdoai-me; não posso falar.","othelloworthymontanoyouwerewontbecivilth~tbrawlergivemeanswertoit~238":"Otelo — Digno Montano, éreis acostumado a ser civil;\na gravidade e a quietude de vossa juventude\no mundo notou, e vosso nome é grande\nnas bocas da mais sábia censura: qual é o assunto,\nque assim desatais vossa reputação\ne gastais vossa rica estima pelo nome\nde um brigão noturno? Dai-me resposta a isso.","montanoworthyothelloiamhurttodangeryouro~sinwhenviolenceassailsus~249":"Montano — Digno Otelo, estou ferido a perigo:\nvosso oficial, Iago, pode informar-vos —\nenquanto poupo a fala, que algo agora\nme ofende — de tudo que sei: nem sei de coisa\npor mim dita ou feita errada esta noite;\na menos que a caridade para consigo seja por vezes um vício,\ne defender-nos seja pecado\nquando a violência nos assalta.","othellonowbyheavenmybloodbeginsmysafergu~ismonstrousiagowhobegant~431":"Otelo — Agora, pelo céu,\nmeu sangue começa a governar meus guias mais seguros;\ne a paixão, tendo escurecido meu melhor juízo,\nensaia guiar o caminho: se eu me mover uma vez,\nou apenas levantar este braço, o melhor de vós\nafundará em minha reprimenda. Fazei-me saber\ncomo começou este feio tumulto, quem o incitou;\ne aquele que for comprovado nesta ofensa,\nainda que tivesse nascido gêmeo comigo, de um só parto,\nperder-me-á. Quê! Numa cidade de guerra,\nainda selvagem, com os corações do povo cheios de medo,\nconduzir querela privada e doméstica,\nde noite, e no pátio e guarda de segurança!\nÉ monstruoso. Iago, quem começou?","montanoifpartiallyaffinedorleaguedinoffi~hantruththouartnosoldier~92":"Montano — Se por parcialidade aparentado, ou aliado em ofício,\nentregas mais ou menos que a verdade,\nnão és soldado.","iagotouchmenotsonearihadratherhavethisto~hichpatiencecouldnotpass~889":"Iago — Não me toqueis tão de perto:\npreferiria ter esta língua cortada da boca\na que ofenda Miguel Cássio;\ncontudo, persuado-me de que falar a verdade\nem nada o prejudicará. Assim foi, general.\nMontano e eu estando em conversa,\neis que vem um sujeito gritando por socorro:\ne Cássio seguindo-o com espada decidida,\npara executar nele. Senhor, este cavalheiro\nintervém por Cássio, e lhe pede que pare:\neu mesmo persegui o sujeito que gritava,\npara que por sua gritaria — como de fato sucedeu —\na cidade não caísse em pânico: ele, ágil de pé,\nultrapassou meu propósito; e voltei tanto mais\nporque ouvi o tinir e o cair de espadas,\ne Cássio alto em pragas; o que até esta noite\njamais pude dizer antes. Quando voltei —\npois foi breve — achei-os juntos,\nem golpe e estocada; tal como de novo estavam\nquando vós mesmo os apartastes.\nMais desta matéria não posso relatar:\nmas homens são homens; os melhores às vezes esquecem:\nembora Cássio lhe tenha feito algum pequeno mal,\ncomo homens em fúria golpeiam os que lhes querem bem,\ncontudo certamente Cássio, creio, recebeu\ndaquele que fugiu alguma estranha indignidade\nque a paciência não podia passar.","othelloiknowiagothyhonestyandlovedothmin~nevermorebeofficerofmine~115":"Otelo — Sei, Iago,\nque tua honestidade e amor amenizam esta matéria,\ntornando-a leve para Cássio. Cássio, eu te amo,\nmas nunca mais serás meu oficial.","reenterdesdemonaattended~reenterdesdemonaattended~24":"Reentra Desdemona, acompanhada.","lookifmygentlelovebenotraisedupillmaketh~edupillmaketheeanexample~51":"Vede, se meu gentil amor não foi levantado!\nFarei de ti um exemplo.","desdemonawhatsthematter~desdemonawhatsthematter~23":"Desdemona — Qual é o assunto?","othelloallswellnowsweetingcomeawaytobeds~xeuntallbutiagoandcassio~272":"Otelo — Tudo está bem agora, docinha; vem para a cama.\nSenhor, por vossas feridas, eu mesmo serei vosso cirurgião:\nlevai-o. Para Montano, que é levado. \nIago, olha com cuidado pela cidade,\ne silencia aqueles que esta vil briga perturbou.\nVem, Desdemona: é a vida de soldado\nter seus sonos bálsamos acordados por contenda. Saem todos, exceto Iago e Cássio.","iagowhatareyouhurtlieutenant~whatareyouhurtlieutenant~28":"Iago — Quê, estais ferido, tenente?","cassioaypastallsurgery~cassioaypastallsurgery~22":"Cássio — Sim, além de toda cirurgia.","iagomarryheavenforbid~iagomarryheavenforbid~21":"Iago — Ora, o céu não permita!","cassioreputationreputationreputationoiha~putationiagomyreputation~141":"Cássio — Reputação, reputação, reputação! Oh, perdi minha reputação! Perdi a parte imortal de mim mesmo, e o que resta é bestial. Minha reputação, Iago, minha reputação!","iagoasiamanhonestmanithoughtyouhadreceiv~suetohimagainandhesyours~426":"Iago — Por ser eu homem honesto, pensei que tivésseis recebido alguma ferida corporal; há mais sentido nisso do que na reputação. Reputação é imposição ociosa e falsíssima: muitas vezes ganha sem mérito e perdida sem merecimento: não perdestes reputação alguma, a menos que vos repute assim perdedor. Quê, homem! Há meios de recobrar o general: apenas agora fostes demitido em seu humor, um castigo mais por política que por malícia, como quem batesse em seu cão inocente para amedrontar um leão imperioso: suplicai-lhe de novo, e ele é vosso.","cassioiwillrathersuetobedespisedthantode~nownbyletuscalltheedevil~255":"Cássio — Antes suplicarei ser desprezado do que enganar tão bom comandante com tão frívolo, tão bêbado e tão indiscreto oficial. Bêbado? E falar como papagaio? E brigar? Fanfarronar? Praguejar? E discursar disparates com a própria sombra? Oh, tu, espírito invisível do vinho, se não tens nome por que ser conhecido, chamemos-te diabo!","iagowhatwashethatyoufollowedwithyourswor~rswordwhathadhedonetoyou~59":"Iago — Quem era aquele que seguíeis com a espada? Que vos tinha feito?","cassioiknownot~cassioiknownot~14":"Cássio — Não sei.","iagoistpossible~iagoistpossible~15":"Iago — É possível?","cassioirememberamassofthingsbutnothingdi~sformourselvesintobeasts~209":"Cássio — Lembro-me de um monte de coisas, mas nada distintamente; uma querela, mas nada por quê. Oh, Deus, que os homens ponham um inimigo na boca para roubar-lhes os miolos! Que nós, com alegria, prazer, festa e aplauso, nos transformemos em bestas!","iagowhybutyouarenowwellenoughhowcameyout~hhowcameyouthusrecovered~52":"Iago — Ora, mas estais agora bem o bastante: como ficastes assim recuperado?","cassioithathpleasedthedevildrunkennessto~kemefranklydespisemyself~122":"Cássio — Aprouve ao diabo da embriaguez dar lugar ao diabo da ira; uma imperfeição me mostra outra, para fazer-me francamente desprezar-me.","iagocomeyouaretoosevereamoralerasthetime~itismenditforyourowngood~156":"Iago — Vamos, sois moralista severo demais: como estão o tempo, o lugar e a condição deste país, eu desejaria de coração que isto não tivesse acontecido; mas, uma vez que é como é, emendai-o para vosso bem.","cassioiwillaskhimformyplaceagainheshallt~andtheingredientisadevil~218":"Cássio — Pedirei a ele meu posto de volta; dirá que sou um bêbado! Tivesse eu tantas bocas quanto a Hidra, tal resposta as calaria todas. Ser agora um homem sensato, daqui a pouco um tolo e logo uma besta! Oh, estranho! Toda taça desmedida é maldita e o ingrediente é um diabo.","iagocomecomegoodwineisagoodfamiliarcreat~ntithinkyouthinkiloveyou~118":"Iago — Vamos, vamos, bom vinho é criatura familiar boa, se bem usada: não exclameis mais contra ele. E, bom tenente, penso que pensais que vos amo.","cassioihavewellapproveditsiridrunk~ewellapproveditsiridrunk~34":"Cássio — Bem o provei, senhor. Eu, bêbado!","iagoyouoranymanlivingmaybedrunkatatimema~wstrongerthanitwasbefore~521":"Iago — Vós ou qualquer homem vivo pode ficar bêbado, uma vez, homem. Dir-vos-ei o que haveis de fazer. A esposa do nosso general é agora o general: pode-se dizê-lo neste respeito, pois ele se devotou e entregou à contemplação, observação e notação de seus méritos e graças: confessai-vos livremente a ela; importunai sua ajuda para repor-vos no posto: ela é de disposição tão livre, tão bondosa, tão pronta, tão abençoada, que tem por vício em sua bondade não fazer mais do que lhe pedem: esta junta quebrada entre vós e o marido dela suplicai-lhe que a entale; e, minha fortuna contra qualquer aposta que mereça menção, esta rachadura em vosso amor ficará mais forte do que era antes.","cassioyouadvisemewell~cassioyouadvisemewell~21":"Cássio — Aconselhais-me bem.","iagoiprotestinthesincerityofloveandhones~yofloveandhonestkindness~49":"Iago — Protesto, na sinceridade do amor e da honesta bondade.","cassioithinkitfreelyandbetimesinthemorni~rtunesiftheychequemehere~132":"Cássio — Penso-o livremente; e cedo, pela manhã, suplicarei à virtuosa Desdemona que interceda por mim: estou desesperado de minha fortuna, se aqui me detêm.","iagoyouareintherightgoodnightlieutenanti~ieutenantimusttothewatch~54":"Iago — Tendes razão. Boa noite, tenente; devo ir à guarda.","cassiogoodnighthonestiagoexit~ogoodnighthonestiagoexit~29":"Cássio — Boa noite, honesto Iago. Sai.","iagoandwhatshethenthatsaysiplaythevillai~etthatshallenmeshthemall~880":"Iago — E quem é então o que diz que faço o vilão?\nQuando este conselho que dou é livre e honesto,\nprovável ao pensamento e de fato o caminho\npara ganhar o Mouro de novo? Pois é facílimo\nsubjugar a inclinada Desdemona\nem qualquer pedido honesto: ela é feita tão fecunda\nquanto os livres elementos. E então, quanto a ela\nganhar o Mouro — mesmo que renunciasse ao batismo,\ntodos os selos e símbolos do pecado redimido,\nsua alma está tão acorrentada ao amor dela\nque ela pode fazer, desfazer, fazer o que quiser,\ncomo seu apetite fará de deus\nsobre sua fraca função. Como sou eu então vilão\nao aconselhar Cássio a este curso paralelo,\ndiretamente para seu bem? Divindade do inferno!\nQuando os demônios querem impor os pecados mais negros,\nsugerem a princípio com aparências celestes,\ncomo faço agora: pois enquanto este honesto tolo\ninsta com Desdemona para reparar sua fortuna\ne ela por ele roga fortemente ao Mouro,\nderramarei esta pestilência no ouvido dele,\nde que ela o readmite por luxúria do corpo dela;\ne quanto mais ela se esforçar para lhe fazer bem,\ntanto mais desfará seu crédito com o Mouro.\nAssim transformarei sua virtude em piche,\ne da própria bondade dela farei a rede\nque os enredará a todos.","reenterroderigo~reenterroderigo~15":"Reentra Roderigo.","hownowroderigo~hownowroderigo~14":"Então, Roderigo!","roderigoidofollowhereinthechasenotlikeah~rewitreturnagaintovenice~252":"Roderigo — Sigo aqui na caça, não como cão que caça, mas como quem completa o coro de latidos. Meu dinheiro está quase gasto; fui esta noite excessivamente bem cacetado; e penso que o resultado será que terei tanta experiência por meu trabalho e, assim, sem dinheiro algum e um pouco mais de juízo, voltarei a Veneza.","iagohowpooraretheythathavenotpatiencewha~cebycoldnessanddelayexit~654":"Iago — Quão pobres são os que não têm paciência!\nQue ferida jamais sarou senão aos poucos?\nSabes que trabalhamos com engenho, e não com feitiçaria;\ne o engenho depende do tempo moroso.\nNão vai bem? Cássio te bateu.\nE tu, por essa pequena ferida, demitiste Cássio:\nembora outras coisas cresçam belas ao sol,\ncontudo os frutos que florescem primeiro amadurecem primeiro:\ncontenta-te um pouco. Pela missa, é de manhã;\nprazer e ação fazem as horas parecerem curtas.\nRetira-te; vai onde estás aquartelado:\nvai, digo; saberás mais depois:\nvai, some daqui. Sai Roderigo.\nDuas coisas há a fazer:\nminha esposa deve interceder por Cássio junto à sua senhora;\nfarei com que o faça;\neu, entretanto, levarei o Mouro à parte,\ne o trarei no exato momento em que possa achar Cássio\nsolicitando a esposa: sim, é este o caminho:\nnão embotes a trama com frieza e demora. Sai.","beforethecastle~beforethecastle~15":"Diante do castelo.","entercassioandsomemusicians~ercassioandsomemusicians~27":"Entram Cássio e alguns Músicos.","cassiomastersplayhereiwillcontentyourpai~idgoodmorrowgeneralmusic~89":"Cássio — Mestres, toquem aqui; recompensarei o seu trabalho.\nAlgo breve; e saúdem: “Bom dia, general.” Música.","enterclown~enterclown~10":"Entra o Bobo.","clownwhymastershaveyourinstrumentsbeenin~hattheyspeakithenosethus~71":"Bobo — Ora, mestres, os seus instrumentos andaram em Nápoles, que falam assim pelo nariz?","firstmusicianhowsirhow~firstmusicianhowsirhow~22":"Primeiro Músico — Como, senhor, como!","clownaretheseiprayyouwindinstruments~eiprayyouwindinstruments~36":"Bobo — Peço-lhes, são estes instrumentos de sopro?","firstmusicianaymarryaretheysir~usicianaymarryaretheysir~30":"Primeiro Músico — Sim, por certo, senhor.","clownotherebyhangsatail~clownotherebyhangsatail~23":"Bobo — Oh, aí é que está pendurado o rabo.","firstmusicianwherebyhangsatalesir~cianwherebyhangsatalesir~33":"Primeiro Músico — Como assim, o rabo, senhor?","clownmarrysirbymanyawindinstrumentthatik~etomakenomorenoisewithit~149":"Bobo — Ora, senhor, em muitos instrumentos de sopro que conheço. Mas, mestres, aqui está dinheiro para os senhores: e o general gosta tanto da sua música que lhes pede, por amor de Deus, que não façam mais barulho com ela.","firstmusicianwellsirwewillnot~musicianwellsirwewillnot~29":"Primeiro Músico — Pois bem, senhor, não faremos.","clownifyouhaveanymusicthatmaynotbeheardt~eneraldoesnotgreatlycare~98":"Bobo — Se têm alguma música que não se possa ouvir, voltem a ela; mas, como dizem, música de ouvir o general não aprecia muito.","firstmusicianwehavenonesuchsir~usicianwehavenonesuchsir~30":"Primeiro Músico — Não temos nenhuma assim, senhor.","clownthenputupyourpipesinyourbagforillaw~toairawayexeuntmusicians~76":"Bobo — Então guardem as flautas na bolsa, que eu me vou: andem; desapareçam no ar; fora! Saem os Músicos.","cassiodostthouhearmyhonestfriend~stthouhearmyhonestfriend~32":"Cássio — Ouves, meu honesto amigo?","clownnoihearnotyourhonestfriendihearyou~yourhonestfriendihearyou~39":"Bobo — Não, não ouço o seu honesto amigo; ouço o senhor.","cassiopritheekeepupthyquilletstheresapoo~urofspeechwiltthoudothis~179":"Cássio — Peço-te, guarda os teus trocadilhos. Eis uma pobre moeda de ouro para ti: se a dama que serve a esposa do general já estiver de pé, diz-lhe que um certo Cássio lhe pede o pequeno favor de uma palavra: farás isso?","clownsheisstirringsirifshewillstirhither~shallseemtonotifyuntoher~65":"Bobo — Ela está de pé, senhor: se quiser vir até aqui, hei de parecer avisá-la.","cassiodogoodmyfriendexitclown~odogoodmyfriendexitclown~29":"Cássio — Faze-o, meu bom amigo. Sai o Bobo.","inhappytimeiago~inhappytimeiago~15":"A propósito, Iago.","iagoyouhavenotbeenabedthen~goyouhavenotbeenabedthen~26":"Iago — Então não foste para a cama?","cassiowhynothedayhadbrokebeforewepartedi~emonaprocuremesomeaccess~136":"Cássio — Ora, não; o dia já tinha rompido\nquando nos separamos. Tomei a liberdade, Iago,\nde mandar chamar a tua mulher: o meu pedido a ela\né que me consiga junto à virtuosa Desdêmona\nalgum acesso.","iagoillsendhertoyoupresentlyandilldevise~andbusinessmaybemorefree~109":"Iago — Mando-a ter contigo já;\ne darei um jeito de afastar o Mouro,\npara que tua conversa e teu assunto\nfiquem mais livres.","cassioihumblythankyoufortexitiagoineverk~rentinemorekindandhonest~71":"Cássio — Agradeço-te humildemente. Sai Iago.\nNunca conheci\num florentino mais gentil e honesto.","enteremilia~enteremilia~11":"Entra Emília.","emiliagoodmorrowgoodlieutenantiamsorryfo~hefronttobringyouinagain~352":"Emília — Bom dia, bom Tenente: lamento\no seu desfavor; mas tudo há de acabar bem.\nO general e sua esposa estão falando disso;\ne ela o defende com firmeza: o Mouro responde\nque aquele a quem o senhor feriu tem grande fama em Chipre\ne grande parentela, e que, por prudente sabedoria,\nnão podia deixar de dispensá-lo; mas jura que o estima\ne não precisa de outro intercessor senão o seu próprio afeto\npara agarrar a melhor ocasião pela frente\ne reconduzi-lo ao posto.","cassioyetibeseechyouifyouthinkfitorthati~coursewithdesdemonaalone~103":"Cássio — Ainda assim, suplico-lhe,\nse julgar conveniente, ou se isso for possível,\nque me dê oportunidade de uma breve conversa\ncom Desdêmona a sós.","emiliaprayyoucomeiniwillbestowyouwhereyo~metospeakyourbosomfreely~76":"Emília — Por favor, entre;\nvou pô-lo onde terá tempo\nde abrir o coração livremente.","cassioiammuchboundtoyouexeunt~oiammuchboundtoyouexeunt~29":"Cássio — Fico-lhe muito obrigado. Saem.","aroominthecastle~aroominthecastle~16":"Uma sala no castelo.","enterothelloiagoandgentlemen~rothelloiagoandgentlemen~28":"Entram Otelo, Iago e Cavalheiros.","othellotheselettersgiveiagotothepilotand~ntheworksrepairtheretome~113":"Otelo — Estas cartas, Iago, entrega ao piloto;\ne por ele apresenta meus respeitos ao senado:\nfeito isso, estarei passeando pelas fortificações;\nvem ter comigo lá.","iagowellmygoodlordilldot~iagowellmygoodlordilldot~24":"Iago — Pois não, meu bom senhor, assim farei.","othellothisfortificationgentlemenshallwe~tiongentlemenshallweseet~44":"Otelo — Esta fortaleza, senhores, vamos vê-la?","gentlemenwellwaituponyourlordshipexeunt~ituponyourlordshipexeunt~39":"Cavalheiros — Seguiremos Vossa Senhoria. Saem.","thegardenofthecastle~thegardenofthecastle~20":"O jardim do castelo.","enterdesdemonacassioandemilia~desdemonacassioandemilia~29":"Entram Desdêmona, Cássio e Emília.","desdemonabethouassuredgoodcassioiwilldoa~llmyabilitiesinthybehalf~64":"Desdêmona — Fica tranquilo, bom Cássio, farei\ntudo o que puder em teu favor.","emiliagoodmadamdoiwarrantitgrievesmyhusb~usbandasifthecasewerehis~61":"Emília — Faça-o, boa senhora: garanto que isso aflige meu marido\ncomo se o caso fosse dele.","desdemonaothatsanhonestfellowdonotdoubtc~againasfriendlyasyouwere~93":"Desdêmona — Oh, esse é um homem honesto. Não duvides, Cássio,\nque hei de ter meu senhor e a ti de novo\ntão amigos como já foram.","cassiobounteousmadamwhatevershallbecomeo~ythingbutyourtrueservant~88":"Cássio — Generosa senhora,\nseja qual for o destino de Miguel Cássio,\nele nunca será outra coisa que seu fiel servidor.","desdemonaiknowtithankyouyoudolovemylordy~offthaninapolitedistance~135":"Desdêmona — Eu sei; agradeço-te. Tu amas meu senhor:\nconheces-o há muito; e podes ter a certeza\nde que ele não se manterá distante\nmais do que numa polida reserva.","cassioaybutladythatpolicymayeitherlastso~llforgetmyloveandservice~178":"Cássio — Sim, mas, senhora,\ntal prudência pode durar tanto,\nou alimentar-se de dieta tão tênue e aguada,\nou crescer de tal modo por força das circunstâncias,\nque, estando eu ausente e meu posto preenchido,\nmeu general esqueça meu afeto e serviço.","desdemonadonotdoubtthatbeforeemiliaherei~rdiethangivethycauseaway~333":"Desdêmona — Não duvides disso; diante de Emília aqui\ndou-te garantia do teu posto: fica certo,\nse jurar uma amizade, cumpri-la-ei\naté o último artigo: meu senhor não terá sossego;\nvou mantê-lo desperto até domá-lo e falar até esgotar-lhe a paciência;\nsua cama lhe parecerá uma escola, sua mesa um confessionário;\nentremearei tudo o que ele fizer\ncom o pedido de Cássio: portanto, alegra-te, Cássio;\npois teu advogado antes morrerá\ndo que abandonar tua causa.","emiliamadamherecomesmylord~iliamadamherecomesmylord~26":"Emília — Senhora, aí vem meu senhor.","cassiomadamilltakemyleave~assiomadamilltakemyleave~25":"Cássio — Senhora, vou pedir licença.","desdemonawhystayandhearmespeak~onawhystayandhearmespeak~30":"Desdêmona — Ora, fica e ouve-me falar.","cassiomadamnotnowiamveryillateaseunfitfo~eunfitformineownpurposes~56":"Cássio — Senhora, agora não: sinto-me muito mal,\nincapaz de servir aos meus próprios fins.","desdemonawelldoyourdiscretionexitcassio~yourdiscretionexitcassio~39":"Desdêmona — Pois bem, faze como julgares melhor. Sai Cássio.","enterothelloandiago~enterothelloandiago~19":"Entram Otelo e Iago.","iagohailikenotthat~iagohailikenotthat~18":"Iago — Ah! Não gosto disso.","othellowhatdostthousay~othellowhatdostthousay~22":"Otelo — Que dizes?","iagonothingmylordorifiknownotwhat~ngmylordorifiknownotwhat~33":"Iago — Nada, meu senhor: ou se... não sei o quê.","othellowasnotthatcassiopartedfrommywife~atcassiopartedfrommywife~39":"Otelo — Não era Cássio aquele que se afastou de minha esposa?","iagocassiomylordnosureicannotthinkitthat~uiltylikeseeingyoucoming~83":"Iago — Cássio, meu senhor! Não, certamente, não posso crer\nque ele fosse escapulir assim, com ar de culpado,\nao vê-lo chegar.","othelloidobelievetwashe~othelloidobelievetwashe~23":"Otelo — Creio que era ele.","desdemonahownowmylordihavebeentalkingwit~guishesinyourdispleasure~87":"Desdêmona — Então, meu senhor!\nEstive falando com um suplicante aqui,\num homem que definha sob o vosso desagrado.","othellowhoistyoumean~othellowhoistyoumean~20":"Otelo — De quem falas?","desdemonawhyyourlieutenantcassiogoodmylo~tfaceipritheecallhimback~215":"Desdêmona — Ora, vosso tenente, Cássio. Bom meu senhor,\nse tenho algum encanto ou poder para vos mover,\naceitai logo a reconciliação dele;\npois se ele não é quem de fato vos ama,\nquem erra por ignorância e não por astúcia,\nentão nada entendo de um rosto honesto.\nPeço-vos, chamai-o de volta.","othellowenthehencenow~othellowenthehencenow~21":"Otelo — Ele saiu agora há pouco?","desdemonaaysoothsohumbledthathehathleftp~thhimgoodlovecallhimback~93":"Desdêmona — Sim, em verdade; tão humilhado\nque deixou comigo parte de sua dor,\npara que eu sofresse com ele. Meu amor, chamai-o de volta.","othellonotnowsweetdesdemonasomeothertime~etdesdemonasomeothertime~40":"Otelo — Agora não, doce Desdêmona; em outra ocasião.","desdemonabutshalltbeshortly~demonabutshalltbeshortly~27":"Desdêmona — Mas será em breve?","othellothesoonersweetforyou~ellothesoonersweetforyou~27":"Otelo — Tanto mais cedo, doce, por vós.","desdemonashalltbetonightatsupper~ashalltbetonightatsupper~32":"Desdêmona — Será esta noite, à ceia?","othellononottonight~othellononottonight~19":"Otelo — Não, esta noite não.","desdemonatomorrowdinnerthen~demonatomorrowdinnerthen~27":"Desdêmona — Amanhã ao almoço, então?","othelloishallnotdineathomeimeetthecaptai~tthecaptainsatthecitadel~54":"Otelo — Não almoçarei em casa; encontro os capitães na cidadela.","desdemonawhythentomorrownightortuesdaymo~himintrustmeicoulddomuch~507":"Desdêmona — Ora, então amanhã à noite; ou terça de manhã;\nterça ao meio-dia, ou à noite; quarta de manhã:\npeço-vos, marcai a hora, mas que não\nexceda três dias: por minha fé, ele está arrependido;\ne contudo sua falta, no nosso juízo comum —\nsalvo que, dizem, a guerra deve dar exemplos\ntirados dos melhores — mal chega a ser culpa\nque mereça uma censura em particular. Quando virá ele?\nDizei-me, Otelo: pasmo em minha alma\ncom o que me pediríeis que eu negasse\nou em que hesitasse tanto. Ora! Miguel Cássio,\nque veio cortejar convosco, e tantas vezes,\nquando eu falava de vós com desdém,\ntomou o vosso partido; ter tanto trabalho\npara trazê-lo de volta! Crede-me, eu poderia muito—","othellopritheenomorelethimcomewhenhewill~williwilldenytheenothing~60":"Otelo — Basta, peço-te: que venha quando quiser;\nnada te negarei.","desdemonawhythisisnotaboontisasishoulden~ghtandfearfultobegranted~252":"Desdêmona — Ora, isto não é um favor;\né como se eu vos pedisse que usásseis luvas,\nou comêsseis pratos nutritivos, ou vos agasalhásseis,\nou vos suplicasse algo de especial proveito\npara a vossa própria pessoa: não, quando eu tiver um pedido\nem que pretenda realmente pôr à prova o vosso amor,\nele será cheio de peso e de grave dificuldade,\ne temível de conceder.","othelloiwilldenytheenothingwhereonidobes~eavemebutalittletomyself~86":"Otelo — Nada te negarei:\nem troca, suplico-te, concede-me isto:\ndeixa-me um pouco a sós comigo mesmo.","desdemonashallidenyyounofarewellmylord~idenyyounofarewellmylord~38":"Desdêmona — Eu vos negaria? Não: adeus, meu senhor.","othellofarewellmydesdemonaillcometothees~onaillcometotheestraight~47":"Otelo — Adeus, minha Desdêmona: irei ter contigo logo.","desdemonaemiliacomebeasyourfanciesteachy~exeuntdesdemonaandemilia~89":"Desdêmona — Emília, vem. Sede como vossos humores mandarem;\nseja qual for o que sejais, eu vos obedeço. Saem Desdêmona e Emília.","othelloexcellentwretchperditioncatchmyso~etheenotchaosiscomeagain~91":"Otelo — Criatura excelente! Que a perdição me apanhe a alma\nse eu não te amo! e quando eu não te amar,\no caos terá voltado.","iagomynoblelord~iagomynoblelord~15":"Iago — Meu nobre senhor—","othellowhatdostthousayiago~hellowhatdostthousayiago~26":"Otelo — Que dizes, Iago?","iagodidmichaelcassiowhenyouwoodmyladykno~woodmyladyknowofyourlove~51":"Iago — Miguel Cássio, quando cortejáveis minha senhora,\nsabia do vosso amor?","othellohedidfromfirsttolastwhydostthouas~irsttolastwhydostthouask~41":"Otelo — Sabia, de começo a fim: por que perguntas?","iagobutforasatisfactionofmythoughtnofurt~ofmythoughtnofurtherharm~47":"Iago — Só para satisfação de meu pensamento;\nnenhum mal além disso.","othellowhyofthythoughtiago~hellowhyofthythoughtiago~26":"Otelo — Por que do teu pensamento, Iago?","iagoididnotthinkhehadbeenacquaintedwithh~hadbeenacquaintedwithher~42":"Iago — Não pensei que ele a conhecesse.","othellooyesandwentbetweenusveryoft~sandwentbetweenusveryoft~34":"Otelo — Oh, sim; e foi muitas vezes o mensageiro entre nós.","iagoindeed~iagoindeed~10":"Iago — É mesmo!","othelloindeedayindeeddiscernstthouaughti~aughtinthatishenothonest~58":"Otelo — É mesmo! sim, é mesmo: percebes algo nisso?\nNão é ele honesto?","iagohonestmylord~iagohonestmylord~16":"Iago — Honesto, meu senhor!","othellohonestayhonest~othellohonestayhonest~21":"Otelo — Honesto! sim, honesto.","iagomylordforaughtiknow~iagomylordforaughtiknow~23":"Iago — Meu senhor, até onde sei.","othellowhatdostthouthink~othellowhatdostthouthink~24":"Otelo — Que pensas?","iagothinkmylord~iagothinkmylord~15":"Iago — Penso, meu senhor!","othellothinkmylordbyheavenheechoesmeasif~stlovemeshowmethythought~381":"Otelo — Penso, meu senhor!\nPor Deus, ele me faz eco,\ncomo se houvesse algum monstro em seu pensamento\nhediondo demais para ser mostrado. Queres dizer algo:\nouvi-te dizer agora mesmo que não gostavas daquilo,\nquando Cássio deixou minha esposa: o que não te agradou?\nE quando te disse que ele fora meu confidente\nem todo o curso do meu namoro, exclamaste: “É mesmo!”\ne contraíste e franziste a testa,\ncomo se então tivesses trancado no cérebro\nalguma ideia horrível: se me amas,\nmostra-me teu pensamento.","iagomylordyouknowiloveyou~agomylordyouknowiloveyou~25":"Iago — Meu senhor, sabeis que vos amo.","othelloithinkthoudostandforiknowthourtfu~artthatpassioncannotrule~273":"Otelo — Creio que sim;\ne, porque sei que és cheio de afeto e honestidade,\ne pesas as palavras antes de lhes dar fôlego,\npor isso estas tuas pausas me assustam mais:\npois tais coisas num velhaco falso e desleal\nsão truques de costume, mas num homem justo\nsão revelações contidas, brotando de um coração\nque a paixão não consegue governar.","iagoformichaelcassioidarebeswornithinkth~wornithinkthatheishonest~52":"Iago — Quanto a Miguel Cássio,\nousaria jurar que o julgo honesto.","othelloithinksotoo~othelloithinksotoo~18":"Otelo — Também penso assim.","iagomenshouldbewhattheyseemorthosethatbe~otwouldtheymightseemnone~65":"Iago — Os homens deviam ser o que parecem;\nou os que não são, oxalá não parecessem sê-lo!","othellocertainmenshouldbewhattheyseem~nmenshouldbewhattheyseem~37":"Otelo — Certo, os homens deviam ser o que parecem.","iagowhythenithinkcassiosanhonestman~ithinkcassiosanhonestman~35":"Iago — Pois então, penso que Cássio é um homem honesto.","othellonayyettheresmoreinthisipritheespe~fthoughtstheworstofwords~120":"Otelo — Não, há mais nisto ainda:\npeço-te, fala-me como falas a teus pensamentos,\ncomo os ruminas, e dá ao pior de teus pensamentos\na pior das palavras.","iagogoodmylordpardonmethoughiamboundtoev~sitwithmeditationslawful~286":"Iago — Bom meu senhor, perdoai-me:\nembora eu esteja obrigado a todo ato de dever,\nnão estou obrigado ao que até os escravos são livres de recusar.\nRevelar meus pensamentos? Ora, digamos que sejam vis e falsos;\nonde há palácio em que coisas imundas\nàs vezes não se intrometam? quem tem peito tão puro\nonde certas ideias impuras\nnão mantenham seus tribunais e audiências e se sentem em sessão\ncom meditações legítimas?","othellothoudostconspireagainstthyfriendi~arastrangertothythoughts~105":"Otelo — Conspiras contra teu amigo, Iago,\nse pensas que ele foi ofendido e fazes teu ouvido\num estranho aos teus pensamentos.","iagoidobeseechyouthoughiperchanceamvicio~omtoletyouknowmythoughts~344":"Iago — Suplico-vos—\nembora eu talvez seja perverso em minha suspeita,\npois, confesso, é a praga da minha natureza\nespiar abusos, e muitas vezes meu ciúme\nforma faltas que não existem—que vossa sabedoria, contudo,\ndiante de alguém que concebe tão imperfeitamente,\nnão dê atenção, nem edifique para si um tormento\ncom suas observações dispersas e incertas.\nNão convém ao vosso sossego nem ao vosso bem,\nnem à minha virilidade, honestidade ou sabedoria,\nque eu vos revele meus pensamentos.","othellowhatdostthoumean~othellowhatdostthoumean~23":"Otelo — Que queres dizer?","iagogoodnameinmanandwomandearmylordisthe~shimandmakesmepoorindeed~235":"Iago — O bom nome, em homem e mulher, caro senhor,\né a joia mais íntima de suas almas:\nquem me rouba a bolsa rouba lixo; é algo, é nada;\nfoi minha, é dele, e já foi escrava de milhares:\nmas quem me surrupia o bom nome\nrouba-me o que não o enriquece\ne me faz realmente pobre.","othellobyheavenillknowthythoughts~heavenillknowthythoughts~33":"Otelo — Por Deus, saberei teus pensamentos.","iagoyoucannotifmyheartwereinyourhandnors~lnotwhilsttisinmycustody~67":"Iago — Não podereis, ainda que meu coração estivesse em vossa mão;\nnem podereis, enquanto estiver sob minha guarda.","othelloha~othelloha~9":"Otelo — Ah!","iagoobewaremylordofjealousyitisthegreene~suspectsyetstronglyloves~211":"Iago — Oh, guardai-vos, meu senhor, do ciúme;\né o monstro de olhos verdes que zomba\ndo alimento de que se nutre; vive em bem-aventurança o corno\nque, certo de sua sorte, não ama quem o ultraja;\nmas, oh, que minutos malditos conta\naquele que adora, porém duvida, suspeita, porém ama intensamente!","othelloomisery~othelloomisery~14":"Otelo — Oh, miséria!","iagopoorandcontentisrichandrichenoughbut~ytribedefendfromjealousy~149":"Iago — Pobre e contente é rico, e rico bastante,\nmas riqueza sem fim é pobre como o inverno\npara quem teme sempre vir a ser pobre.\nBom Deus, defendei do ciúme\nas almas de toda a minha tribo!","othellowhywhyisthisthinkstthouildmakeali~atoncewithloveorjealousy~560":"Otelo — Por quê, por quê isso? \nPensas que eu faria uma vida de ciúme,\nseguindo sempre as mudanças da lua\ncom suspeitas renovadas? Não; duvidar de uma vez\né resolver-se de uma vez: trocai-me por um bode\nquando eu voltar os assuntos da minha alma\npara tais conjecturas infladas e vazias\ncomo a tua insinuação. Não é me fazer ciumento\ndizer que minha esposa é bela, come bem, gosta de companhia,\né solta de língua, canta, toca e dança bem;\nonde há virtude, isso são mais virtudes:\nnem de meus próprios fracos méritos tirarei\no menor medo ou dúvida de sua deslealdade;\npois ela tinha olhos, e escolheu-me. Não, Iago;\nverei antes de duvidar; quando duvidar, provarei;\ne, feita a prova, só resta isto—\nfora de uma vez com o amor e o ciúme!","iagoiamgladofitfornowishallhavereasontos~vetundonebutkeeptunknown~422":"Iago — Folgo em ouvi-lo; pois agora terei motivo\npara mostrar o amor e o dever que vos devoto\ncom ânimo mais franco: portanto, como é meu dever,\nrecebei de mim este aviso. Não falo ainda de prova.\nVigiai vossa esposa; observai-a bem com Cássio;\ntende o olhar assim, nem ciumento nem desprevenido:\nnão quisera que vossa natureza livre e nobre,\npor excesso de bondade, fosse enganada; vigiai:\nconheço bem o temperamento do nosso país;\nem Veneza deixam o céu ver as travessuras\nque não ousam mostrar aos maridos; sua melhor consciência\nnão é deixar de fazê-lo, mas mantê-lo ignorado.","othellodostthousayso~othellodostthousayso~20":"Otelo — Dizes isso?","iagoshediddeceiveherfathermarryingyouand~ourlooksshelovedthemmost~91":"Iago — Ela enganou o pai, casando convosco;\ne quando parecia tremer e temer vossos olhares,\nera quando mais os amava.","othelloandsoshedid~othelloandsoshedid~18":"Otelo — E assim foi.","iagowhygotothenshethatsoyoungcouldgiveou~ardonfortoomuchlovingyou~175":"Iago — Ora, vede então;\nquem, tão jovem, soube fingir tão bem,\nvedando os olhos do pai, fechados como carvalho—\nele pensou que era feitiçaria—mas eu muito me culpo;\nhumildemente vos peço perdão\npor amar-vos demais.","othelloiamboundtotheeforever~lloiamboundtotheeforever~28":"Otelo — Ficarei obrigado a ti para sempre.","iagoiseethishathalittledashdyourspirits~halittledashdyourspirits~39":"Iago — Vejo que isto abateu um pouco o vosso ânimo.","othellonotajotnotajot~othellonotajotnotajot~21":"Otelo — Nem um pouco, nem um pouco.","iagoifaithifearithasihopeyouwillconsider~rgerreachthantosuspicion~162":"Iago — Em verdade, temo que sim.\nEspero que considereis que o que foi dito\nvem do meu afeto. Mas vejo que estais abalado:\ndevo rogar-vos que não forceis minhas palavras\npara consequências mais grosseiras nem alcance maior\ndo que a suspeita.","othelloiwillnot~othelloiwillnot~15":"Otelo — Não forçarei.","iagoshouldyoudosomylordmyspeechshouldfal~iendmylordiseeyouremoved~121":"Iago — Se o fizésseis, meu senhor,\nminhas palavras teriam um desfecho tão vil\nque meus pensamentos não visam. Cássio é meu digno amigo—\nMeu senhor, vejo que estais abalado.","othellononotmuchmovedidonotthinkbutdesde~thinkbutdesdemonashonest~51":"Otelo — Não, não muito abalado:\nnão creio senão que Desdêmona é honesta.","iagolongliveshesoandlongliveyoutothinkso~oandlongliveyoutothinkso~40":"Iago — Que ela viva assim por muito tempo! e vós vivais por muito tempo para crê-lo!","othelloandyethownatureerringfromitself~ownatureerringfromitself~38":"Otelo — E no entanto, como a natureza, errando contra si mesma—","iagoaytheresthepointastobeboldwithyounot~tryformsandhappilyrepent~348":"Iago — Sim, aí está o ponto: como—para ser franco convosco—\nnão ter desejado tantos partidos propostos\nde seu próprio clima, cor e condição,\npara onde vemos que em tudo a natureza tende—\nPuxa! sente-se em tal vontade o mais rançoso cheiro\nde desproporção sórdida, pensamentos contra a natureza.\nMas perdoai-me; não falo em termos precisos\nsobre ela; embora eu possa temer\nque sua vontade, voltando ao seu melhor juízo,\npasse a comparar-vos com as formas de seu país\ne talvez se arrependa.","othellofarewellfarewellifmorethoudostper~wifetoobserveleavemeiago~90":"Otelo — Adeus, adeus:\nse perceberes mais, faze-me saber mais;\nincumbe tua mulher de observar: deixa-me, Iago:","iagogoingmylorditakemyleave~ogoingmylorditakemyleave~27":"Iago — Saindo. Meu senhor, peço licença.","othellowhydidimarrythishonestcreaturedou~oremuchmorethanheunfolds~83":"Otelo — Por que me casei? Esta criatura honesta sem dúvida\nvê e sabe mais, muito mais, do que revela.","iagoreturningmylordiwouldimightentreatyo~freeidobeseechyourhonour~416":"Iago — Voltando. Meu senhor, quisera rogar a Vossa Honra\nque não escrutineis mais este assunto; deixai-o ao tempo:\nembora seja justo que Cássio tenha seu posto,\npois, por certo, ele o preenche com grande competência,\ncontudo, se aprouver mantê-lo afastado por algum tempo,\npor isso percebereis ele e seus meios:\nobservai se vossa senhora insiste em sua readmissão\ncom qualquer importunação forte ou veemente;\nmuito se verá nisso. Entretanto,\ndeixai que me julguem demasiado diligente em meus temores—\ncomo tenho justa causa para temer que sou—\ne considerai-a inocente, suplico a Vossa Honra.","othellofearnotmygovernment~hellofearnotmygovernment~26":"Otelo — Não temas pelo meu governo.","iagoioncemoretakemyleaveexit~ioncemoretakemyleaveexit~28":"Iago — Mais uma vez peço licença. Sai.","othellothisfellowsofexceedinghonestyandk~edoquickendesdemonacomes~686":"Otelo — Este homem é de extrema honestidade,\ne conhece, com espírito instruído, todas as qualidades\ndo trato humano. Se eu provar que ela é um falcão bravio,\nainda que suas correias fossem as minhas queridas fibras do coração,\neu a assobiaria para longe e a soltaria ao vento,\npara pedir à sorte. Talvez, por ser negro\ne não ter as brandas prendas da conversação\nque os galanteadores têm, ou por ter declinado\npara o vale dos anos—mas isso é pouco—\nela se foi. Fui ludibriado; e meu alívio\ndeverá ser detestá-la. Oh, maldição do matrimônio,\nque podemos chamar nossas essas criaturas delicadas,\ne não seus apetites! Antes ser um sapo\ne viver do vapor de uma masmorra\ndo que guardar um canto na coisa que amo\npara o uso de outros. Contudo, é a praga dos grandes;\nsão menos privilegiados do que os humildes;\né destino inevitável, como a morte:\nessa praga bifurcada nos é fadada\ndesde que nascemos. Desdêmona vem:","reenterdesdemonaandemilia~eenterdesdemonaandemilia~25":"Entram de novo Desdêmona e Emília.","ifshebefalseothenheavenmocksitselfillnot~ocksitselfillnotbelievet~48":"Se ela é falsa, oh, então o céu zomba de si mesmo!\nNão acreditarei.","desdemonahownowmydearothelloyourdinneran~iteddoattendyourpresence~93":"Desdêmona — Então, meu caro Otelo!\nVosso jantar e os generosos ilhéus\npor vós convidados aguardam vossa presença.","othelloiamtoblame~othelloiamtoblame~17":"Otelo — Tenho culpa.","desdemonawhydoyouspeaksofaintlyareyounot~aksofaintlyareyounotwell~44":"Desdêmona — Por que falais tão fraco?\nNão estais bem?","othelloihaveapainuponmyforeheadhere~eapainuponmyforeheadhere~35":"Otelo — Tenho uma dor aqui na testa.","desdemonafaiththatswithwatchingtwillaway~thinthishouritwillbewell~89":"Desdêmona — Pois é, isso é de velar; passará:\ndeixai-me só atá-la com força, dentro de uma hora\nestará boa.","othelloyournapkinistoolittleheputsthehan~talonecomeillgoinwithyou~94":"Otelo — Teu lenço é pequeno demais: Afasta de si o lenço, e ele cai.\nDeixa-o. Vem, entrarei contigo.","desdemonaiamverysorrythatyouarenotwellex~xeuntothelloanddesdemona~63":"Desdêmona — Sinto muito que não estejais bem. Saem Otelo e Desdêmona.","emiliaiamgladihavefoundthisnapkinthiswas~ingbuttopleasehisfantasy~317":"Emília — Alegro-me de ter achado este lenço:\nfoi a primeira lembrança que ela recebeu do Mouro:\nmeu marido caprichoso já cem vezes\nme pediu que o roubasse; mas ela tanto ama o presente,\npois ele a conjurou que o guardasse sempre,\nque o traz sempre consigo\npara beijar e falar-lhe. Mandarei copiar o bordado\ne darei a Iago: o que ele fará com isso\nsabe o céu, não eu;\neu nada quero senão agradar-lhe o capricho.","reenteriago~reenteriago~11":"Entra de novo Iago.","iagohownowwhatdoyouherealone~hownowwhatdoyouherealone~28":"Iago — Ora essa! que fazes aqui sozinha?","emiliadonotyouchideihaveathingforyou~ouchideihaveathingforyou~36":"Emília — Não me repreendas; tenho uma coisa para ti.","iagoathingformeitisacommonthing~ingformeitisacommonthing~31":"Iago — Uma coisa para mim? é coisa comum—","emiliaha~emiliaha~8":"Emília — Ah!","iagotohaveafoolishwife~iagotohaveafoolishwife~22":"Iago — Ter uma mulher tola.","emiliaoisthatallwhatwillyougivemenowfort~owforthesamehandkerchief~58":"Emília — Oh, é só isso? O que me darás agora\npelo mesmo lenço?","iagowhathandkerchief~iagowhathandkerchief~20":"Iago — Que lenço?","emiliawhathandkerchiefwhythatthemoorfirs~hsooftenyoudidbidmesteal~88":"Emília — Que lenço?\nOra, aquele que o Mouro deu primeiro a Desdêmona;\naquele que tantas vezes me mandaste roubar.","iagohaststolnitfromher~iagohaststolnitfromher~22":"Iago — Roubaste-o dela?","emilianofaithsheletitdropbynegligenceand~gheretooktuplookhereitis~83":"Emília — Não, por minha fé; ela o deixou cair por descuido.\nE, por sorte, eu, estando aqui, o apanhei.\nOlha, aqui está.","iagoagoodwenchgiveitme~iagoagoodwenchgiveitme~22":"Iago — Boa moça; dá-mo.","emiliawhatwillyoudowithtthatyouhavebeens~soearnesttohavemefilchit~63":"Emília — Que farás com ele, que tanto te empenhaste\nem que eu o surrupiasse?","iagosnatchingitwhywhatsthattoyou~chingitwhywhatsthattoyou~32":"Iago — Arrebatando-o. Ora, que te importa?","emiliaifitbenotforsomepurposeofimportgiv~runmadwhensheshalllackit~86":"Emília — Se não é para algum fim importante,\ndevolve-mo: pobre senhora, ela enlouquecerá\nquando sentir a falta.","iagobenotacknownontihaveuseforitgoleavem~didsaysolookwherehecomes~380":"Iago — Finge que não sabes; tenho uso para ele.\nVai, deixa-me. Sai Emília.\nVou perder este lenço no alojamento de Cássio\ne deixar que ele o encontre. Ninharias leves como o ar\nsão para os ciumentos confirmações fortes\ncomo provas da Sagrada Escritura: isto pode render algo.\nO Mouro já muda com meu veneno:\nideias perigosas são, por natureza, venenos\nque de início mal se sentem amargar,\nmas, com um pouco de ação sobre o sangue,\nardem como minas de enxofre. Eu disse que seria assim:\nvede, lá vem ele!","notpoppynormandragoranorallthedrowsysyru~whichthouowedstyesterday~113":"Nem papoula, nem mandrágora,\nnem todos os xaropes sonolentos do mundo\nte darão jamais aquele doce sono\nque tinhas ontem.","othellohahafalsetome~othellohahafalsetome~20":"Otelo — Ah! ah! falsa para mim?","iagowhyhownowgeneralnomoreofthat~ownowgeneralnomoreofthat~32":"Iago — Ora, então, general! chega disso.","othelloavauntbegonethouhastsetmeontherac~sedthanbuttoknowtalittle~91":"Otelo — Afasta-te! some! puseste-me no potro de tortura:\njuro que é melhor ser muito enganado\ndo que saber só um pouco.","iagohownowmylord~iagohownowmylord~16":"Iago — Então, meu senhor!","othellowhatsensehadiofherstolnhoursoflus~knowtandhesnotrobbdatall~208":"Otelo — Que sentido tive eu de suas horas furtadas de luxúria?\nNão as vi, não as pensei, não me fizeram mal:\ndormi bem na noite seguinte, estava livre e alegre;\nnão achei os beijos de Cássio em seus lábios:\naquele que é roubado, não sentindo falta do que foi furtado,\nque não o saiba, e não terá sido roubado de modo algum.","iagoiamsorrytohearthis~iagoiamsorrytohearthis~22":"Iago — Lamento ouvir isto.","othelloihadbeenhappyifthegeneralcamppion~lothellosoccupationsgone~453":"Otelo — Eu teria sido feliz, se todo o acampamento,\naté os sapadores, tivesse provado seu doce corpo,\ndesde que eu nada soubesse. Oh, agora, para sempre,\nadeus ao espírito tranquilo! adeus ao contentamento!\nAdeus à tropa emplumada e às grandes guerras\nque fazem da ambição virtude! Oh, adeus!\nAdeus ao corcel que relincha e à trombeta estridente,\nao tambor que agita a alma, ao pífaro que fere o ouvido,\nao estandarte real e a toda a dignidade,\norgulho, pompa e aparato da guerra gloriosa!\nE vós, engenhos mortais, cujas gargantas rudes\nimitam os clamores letais do imortal Jove,\nadeus! A ocupação de Otelo acabou!","iagoistpossiblemylord~iagoistpossiblemylord~21":"Iago — É possível, meu senhor?","othellovillainbesurethouprovemyloveawhor~ogthananswermywakedwrath~157":"Otelo — Miserável, certifica-te de provar que meu amor é uma prostituta,\ncertifica-te disso; dá-me a prova dos olhos:\nou, pelo valor da alma eterna do homem,\nmelhor te fora ter nascido cão\ndo que responder à minha ira desperta!","iagoistcometothis~iagoistcometothis~17":"Iago — Chegou a isto?","othellomakemetoseetorattheleastsoproveit~adoubtonorwoeuponthylife~104":"Otelo — Faze-me vê-lo; ou, ao menos, prova-o de tal modo\nque a prova não tenha dobradiça nem argola\nonde pendurar uma dúvida; ou ai da tua vida!","othelloifthoudostslanderherandtorturemen~nationaddgreaterthanthat~184":"Otelo — Se a difamas e me torturas,\nnunca mais reze; abandona todo remorso;\nsobre a cabeça do horror acumula horrores;\nfaze atos que façam o céu chorar e a terra toda pasmar;\npois nada podes acrescentar à tua danação\nmaior do que isso.","iagoograceoheavenforgivemeareyouamanhave~ithlovebreedssuchoffence~264":"Iago — Oh, graça! Oh, céu, perdoai-me!\nSois um homem? tendes alma ou sentidos?\nDeus convosco; tomai meu cargo. Oh, miserável tolo,\nque vives para fazer da tua honestidade um vício!\nOh, mundo monstruoso! Toma nota, toma nota, ó mundo,\nde que ser franco e honesto não é seguro.\nAgradeço-vos esta lição; e daqui por diante\nnão amarei amigo algum, já que o amor gera tal ofensa.","othellonaystaythoushouldstbehonest~staythoushouldstbehonest~34":"Otelo — Não, fica: deves ser honesto.","iagoishouldbewiseforhonestysafoolandlose~olandlosesthatitworksfor~55":"Iago — Devia ser sábio, pois a honestidade é tola\ne perde aquilo por que trabalha.","othellobytheworldithinkmywifebehonestand~ureitwouldiweresatisfied~263":"Otelo — Pelo mundo,\npenso que minha esposa é honesta e penso que não é;\npenso que és justo e penso que não és.\nQuero alguma prova. Seu nome, que era fresco\ncomo o rosto de Diana, está agora manchado e negro\ncomo a minha própria face. Se há cordas ou facas,\nveneno ou fogo, ou correntes que sufocam,\nnão suportarei. Quem me dera ter certeza!","iagoiseesiryouareeatenupwithpassionidore~toyouyouwouldbesatisfied~80":"Iago — Vejo, senhor, que estais consumido pela paixão:\narrependo-me de a ter exposto a vós.\nQuereis ter certeza?","othellowouldnayiwill~othellowouldnayiwill~20":"Otelo — Quero! não, terei.","iagoandmaybuthowhowsatisfiedmylordwouldy~sslygapeonbeholdhertoppd~82":"Iago — E podeis: mas como? como certeza, meu senhor?\nQuereis, qual supervisor, olhar embasbacado\nvê-la coberta?","othellodeathanddamnationo~thellodeathanddamnationo~25":"Otelo — Morte e danação! Oh!","iagoitwereatediousdifficultyithinktobrin~usatisfactionyoumayhavet~398":"Iago — Seria, penso, uma tediosa dificuldade\ntrazê-los a essa vista: danados sejam, então,\nse olhos mortais algum dia os virem deitados\nmais do que em seus próprios travesseiros! E então? como então?\nO que direi? Onde está a certeza?\nÉ impossível que vejais isto,\nainda que fossem lascivos como bodes, ardentes como macacos,\nsalaces como lobos no cio e tolos tão grosseiros\ncomo a ignorância embriagada. Mas contudo, digo,\nse a imputação e fortes circunstâncias,\nque levam direto à porta da verdade,\nvos puderem dar certeza, podeis tê-la.","othellogivemealivingreasonshesdisloyal~livingreasonshesdisloyal~38":"Otelo — Dá-me uma razão viva de que ela é desleal.","iagoidonotliketheofficebutsithiamenterdi~atethatgavetheetothemoor~516":"Iago — Não gosto do ofício:\nmas, já que entrei nesta causa tão fundo,\naguilhoado a isso por tola honestidade e amor,\nprosseguirei. Dormi há pouco com Cássio;\ne, atormentado por um dente que me dava raiva,\nnão conseguia dormir.\nHá uma espécie de homens de alma tão solta\nque murmuram seus assuntos em sonhos:\nCássio é desses:\nouvi-o dizer dormindo: “Doce Desdêmona,\nsejamos cautelosos, escondamos nossos amores”;\ne então, senhor, ele apertava e torcia minha mão,\ngritava: “Oh, doce criatura!” e depois beijava-me com força,\ncomo se arrancasse pela raiz os beijos\nque cresciam em meus lábios: depois pôs a perna\nsobre minha coxa, e suspirou, e beijou; e então\ngritou: “Maldito destino que te deu ao Mouro!”","othelloomonstrousmonstrous~helloomonstrousmonstrous~26":"Otelo — Oh, monstruoso! monstruoso!","iagonaythiswasbuthisdream~agonaythiswasbuthisdream~25":"Iago — Não, isto foi só o sonho dele.","othellobutthisdenotedaforegoneconclusion~doubtthoughitbebutadream~74":"Otelo — Mas isto denotava uma conclusão já consumada:\né uma dúvida sagaz, ainda que seja só um sonho.","iagoandthismayhelptothickenotherproofsth~sthatdodemonstratethinly~61":"Iago — E isto pode ajudar a reforçar outras provas\nque demonstram fracamente.","othelloilltearheralltopieces~lloilltearheralltopieces~28":"Otelo — Vou despedaçá-la toda.","iagonaybutbewiseyetweseenothingdoneshema~awberriesinyourwifeshand~139":"Iago — Não, sede sábio: ainda nada vemos feito;\nela pode ser honesta ainda. Dizei-me só isto:\nnunca vistes por vezes um lenço\nbordado de morangos na mão de vossa esposa?","othelloigavehersuchaonetwasmyfirstgift~rsuchaonetwasmyfirstgift~38":"Otelo — Dei-lhe um assim; foi meu primeiro presente.","iagoiknownotthatbutsuchahandkerchiefiams~eecassiowipehisbeardwith~91":"Iago — Não sei disso; mas tal lenço—\ntenho certeza de que era de vossa esposa—vi hoje\nCássio enxugar a barba com ele.","othelloifitbethat~othelloifitbethat~17":"Otelo — Se for esse—","iagoifitbethatoranythatwashersitspeaksag~nstherwiththeotherproofs~66":"Iago — Se for esse, ou qualquer um que foi dela,\nfala contra ela, junto com as outras provas.","othelloothattheslavehadfortythousandlive~ghtfortisofaspicstongues~271":"Otelo — Oh, que o escravo tivesse quarenta mil vidas!\nUma é pobre demais, fraca demais para minha vingança.\nAgora vejo que é verdade. Olha aqui, Iago;\ntodo o meu terno amor assim sopro para o céu.\nSe foi. \nSurge, negra vingança, de tua cova oca!\nCede, ó amor, tua coroa e trono do coração\nao ódio tirânico! Incha, peito, com tua carga,\npois é de línguas de áspides!","iagoyetbecontent~iagoyetbecontent~16":"Iago — Contudo, acalmai-vos.","othelloobloodbloodblood~othelloobloodbloodblood~23":"Otelo — Oh, sangue, sangue, sangue!","iagopatienceisayyourmindperhapsmaychange~yourmindperhapsmaychange~40":"Iago — Paciência, digo; vossa mente talvez mude.","othelloneveriagoliketotheponticseawhosei~redvowihereengagemywords~321":"Otelo — Nunca, Iago: como o mar Pôntico,\ncuja corrente gelada e curso compulsivo\nnunca sentem refluxo, mas seguem direto\npara a Propôntida e o Helesponto,\nassim meus pensamentos sanguinários, com passo violento,\nnunca olharão para trás, nunca refluirão a humilde amor,\naté que uma vingança ampla e capaz\nos engula. Agora, por aquele céu de mármore, Ajoelha-se.\nna devida reverência de um voto sagrado\nempenho aqui minhas palavras.","iagodonotriseyetkneelswitnessyoueverburn~oodybusinessevertheyrise~237":"Iago — Não vos levanteis ainda.\nAjoelha-se. Sede testemunhas, luzes sempre ardentes lá em cima,\nelementos que nos envolveis em redor,\ntestemunhai que aqui Iago entrega\na execução de seu engenho, mãos e coração\nao serviço do ultrajado Otelo! Que ele mande,\ne obedecer será em mim compaixão,\nseja qual for o sangrento negócio. Levantam-se.","othelloigreetthylovenotwithvainthanksbut~eesaythatcassiosnotalive~149":"Otelo — Saúdo teu afeto,\nnão com vãos agradecimentos, mas com aceitação generosa,\ne já neste instante te porei à prova:\ndentro destes três dias deixa-me ouvir-te dizer\nque Cássio não está vivo.","iagomyfriendisdeadtisdoneatyourrequestbu~yourrequestbutletherlive~51":"Iago — Meu amigo está morto; está feito a vosso pedido:\nmas deixai-a viver.","othellodamnherlewdminxodamnhercomegowith~ilnowartthoumylieutenant~133":"Otelo — Danada seja ela, rameira lasciva! Oh, danada seja!\nVem, vai comigo à parte; retirar-me-ei\npara me prover de algum meio rápido de morte\npara a bela demônia. Agora és meu tenente.","iagoiamyourownforeverexeunt~oiamyourownforeverexeunt~27":"Iago — Sou vosso para sempre. Saem.","sceneiv~sceneiv~7":"Cena IV","enterdesdemonaemiliaandclown~rdesdemonaemiliaandclown~28":"Entram Desdêmona, Emília e o Bobo.","desdemonadoyouknowsirrahwherelieutenantc~herelieutenantcassiolies~49":"Desdêmona — Sabes, rapaz, onde o Tenente Cássio se aloja?","clownidarenotsayheliesanywhere~darenotsayheliesanywhere~30":"Bobo — Não ouso dizer que ele minta em lugar algum.","desdemonawhyman~desdemonawhyman~15":"Desdêmona — Por quê, homem?","clownhesasoldierandforonetosayasoldierli~ayasoldierliesisstabbing~52":"Bobo — É soldado, e dizer que um soldado mente é pedir uma estocada.","desdemonagotowherelodgeshe~sdemonagotowherelodgeshe~26":"Desdêmona — Ora essa: onde ele se hospeda?","clowntotellyouwherehelodgesistotellyouwh~dgesistotellyouwhereilie~47":"Bobo — Dizer-vos onde ele se hospeda é dizer-vos onde eu minto.","desdemonacananythingbemadeofthis~acananythingbemadeofthis~32":"Desdêmona — Pode-se tirar algo disso?","clowniknownotwherehelodgesandformetodevi~weretolieinmineownthroat~103":"Bobo — Não sei onde ele se hospeda, e inventar eu um alojamento e dizer que ele mora aqui ou mora ali seria mentir pela minha própria garganta.","desdemonacanyouinquirehimoutandbeedified~moutandbeedifiedbyreport~48":"Desdêmona — Podes indagar por ele e ser esclarecido pelo que ouvires?","clowniwillcatechisetheworldforhimthatism~questionsandbythemanswer~67":"Bobo — Catequizarei o mundo por ele; isto é, farei perguntas e, por elas, responderei.","desdemonaseekhimbidhimcomehithertellhimi~halfandhopeallwillbewell~86":"Desdêmona — Procura-o, manda-o vir aqui: diz-lhe que comovi meu senhor em seu favor e espero que tudo corra bem.","clowntodothisiswithinthecompassofmanswit~illattemptthedoingitexit~78":"Bobo — Fazer isso está dentro do alcance do engenho humano: e por isso tentarei fazê-lo. Sai.","desdemonawhereshouldilosethathandkerchie~sethathandkerchiefemilia~47":"Desdêmona — Onde terei perdido aquele lenço, Emília?","emiliaiknownotmadam~emiliaiknownotmadam~19":"Emília — Não sei, senhora.","desdemonabelievemeihadratherhavelostmypu~ughtoputhimtoillthinking~164":"Desdêmona — Crê-me, antes eu tivesse perdido a bolsa\ncheia de cruzados: e, se meu nobre Mouro\nnão fosse de espírito leal e feito de nenhuma baixeza\ncomo as criaturas ciumentas, bastaria\npara levá-lo a pensar mal.","emiliaishenotjealous~emiliaishenotjealous~20":"Emília — Não é ele ciumento?","desdemonawhoheithinkthesunwherehewasborn~rewallsuchhumoursfromhim~65":"Desdêmona — Quem, ele? Creio que o sol onde nasceu\nlhe sorveu todos esses humores.","emilialookwherehecomes~emilialookwherehecomes~22":"Emília — Olhe, lá vem ele.","desdemonaiwillnotleavehimnowtillcassiobe~owtillcassiobecalldtohim~50":"Desdêmona — Não o deixarei agora até que Cássio\nseja chamado a ele.","enterothello~enterothello~12":"Entra Otelo.","howistwithyoumylord~howistwithyoumylord~19":"Como estais, meu senhor?","othellowellmygoodladyasideohardnesstodis~ssemblehowdoyoudesdemona~63":"Otelo — Bem, minha boa senhora.\nÀ parte. Oh, que dificuldade fingir!—\nComo estás, Desdêmona?","desdemonawellmygoodlord~desdemonawellmygoodlord~23":"Desdêmona — Bem, meu bom senhor.","othellogivemeyourhandthishandismoistmyla~andthishandismoistmylady~42":"Otelo — Dá-me a tua mão: esta mão está úmida, senhora.","desdemonaityethathfeltnoagenorknownnosor~eltnoagenorknownnosorrow~43":"Desdêmona — Ainda não sentiu idade nem conheceu tristeza.","othellothisarguesfruitfulnessandliberalh~elstisagoodhandafrankone~220":"Otelo — Isto indica fertilidade e coração liberal:\nquente, quente e úmida: esta tua mão requer\nreclusão da liberdade, jejum e oração,\nmuita castigação, exercício devoto;\npois há aqui um diabo jovem e suarento\nque costuma rebelar-se. É uma boa mão,\numa mão franca.","desdemonayoumayindeedsaysofortwasthathan~thandthatgaveawaymyheart~60":"Desdêmona — Podeis dizê-lo, de fato;\npois foi essa mão que deu meu coração.","othelloaliberalhandtheheartsofoldgavehan~heraldryishandsnothearts~75":"Otelo — Uma mão liberal: os corações de outrora davam mãos;\nmas nossa nova heráldica é mãos, não corações.","desdemonaicannotspeakofthiscomenowyourpr~ofthiscomenowyourpromise~45":"Desdêmona — Não posso falar disso. Vamos, vossa promessa.","othellowhatpromisechuck~othellowhatpromisechuck~23":"Otelo — Que promessa, pombinha?","desdemonaihavesenttobidcassiocomespeakwi~idcassiocomespeakwithyou~45":"Desdêmona — Mandei dizer a Cássio que viesse falar convosco.","othelloihaveasaltandsorryrheumoffendsmel~smelendmethyhandkerchief~60":"Otelo — Tenho um catarro salgado e penoso que me incomoda;\nempresta-me teu lenço.","desdemonaheremylord~desdemonaheremylord~19":"Desdêmona — Aqui, meu senhor.","othellothatwhichigaveyou~othellothatwhichigaveyou~24":"Otelo — Aquele que te dei.","desdemonaihaveitnotaboutme~sdemonaihaveitnotaboutme~26":"Desdêmona — Não o tenho comigo.","othellonot~othellonot~10":"Otelo — Não?","desdemonanoindeedmylord~desdemonanoindeedmylord~23":"Desdêmona — Não, de fato, meu senhor.","othellothatisafaultthathandkerchiefdidan~nasnothingelsecouldmatch~460":"Otelo — Isso é uma falta.\nAquele lenço\nfoi dado a minha mãe por uma egípcia;\nera feiticeira e quase lia\nos pensamentos das pessoas: disse-lhe que, enquanto\no guardasse,\nela seria amável e sujeitaria meu pai\ninteiramente a seu amor, mas se o perdesse\nou o desse de presente, o olhar de meu pai\no faria detestá-la e seu espírito iria caçar\nnovos desejos: ela, morrendo, deu-mo;\ne mandou-me, quando meu destino quisesse que me casasse,\ndá-lo à esposa. Assim fiz: e cuida dele;\ntem-no por querido como a tua preciosa vista;\nperdê-lo ou dá-lo seria tal perdição\nque nada mais se lhe igualaria.","desdemonaistpossible~desdemonaistpossible~20":"Desdêmona — É possível?","othellotistruetheresmagicinthewebofitasi~conservedofmaidenshearts~225":"Otelo — É verdade: há magia na trama dele:\numa sibila, que contara no mundo\nduzentas voltas do sol em seu curso,\nem seu furor profético bordou a obra;\nos bichos que criaram a seda eram sagrados;\ne foi tingido em múmia, que os hábeis\nconservaram de corações de donzelas.","desdemonaindeedisttrue~desdemonaindeedisttrue~22":"Desdêmona — Verdade! é verdade?","othellomostveritablethereforelooktotwell~ablethereforelooktotwell~40":"Otelo — Verdadeiríssimo; portanto cuida bem dele.","desdemonathenwouldtogodthatihadneverseen~dtogodthatihadneverseent~41":"Desdêmona — Então prouvera a Deus que eu nunca o tivesse visto!","othellohawherefore~othellohawherefore~18":"Otelo — Ah! por quê?","desdemonawhydoyouspeaksostartinglyandras~speaksostartinglyandrash~41":"Desdêmona — Por que falais de modo tão brusco e precipitado?","othelloistlostistgonespeakisitoutotheway~tgonespeakisitoutotheway~40":"Otelo — Está perdido? sumiu? fala, está fora do lugar?","desdemonaheavenblessus~desdemonaheavenblessus~22":"Desdêmona — Deus nos abençoe!","othellosayyou~othellosayyou~13":"Otelo — Que dizes?","desdemonaitisnotlostbutwhatanifitwere~notlostbutwhatanifitwere~37":"Desdêmona — Não está perdido; mas e se estivesse?","othellohow~othellohow~10":"Otelo — Como!","desdemonaisayitisnotlost~desdemonaisayitisnotlost~24":"Desdêmona — Digo que não está perdido.","othellofetchtletmeseet~othellofetchtletmeseet~22":"Otelo — Vai buscá-lo, deixa-me vê-lo.","desdemonawhysoicansirbutiwillnotnowthisi~letcassiobereceivedagain~95":"Desdêmona — Ora, posso, senhor, mas não agora.\nIsto é um truque para me desviar do meu pedido:\npeço-vos, que Cássio seja recebido de novo.","othellofetchmethehandkerchiefmymindmisgi~ndkerchiefmymindmisgives~43":"Otelo — Traze-me o lenço: minha mente pressente algo.","desdemonacomecomeyoullnevermeetamoresuff~ermeetamoresufficientman~49":"Desdêmona — Vamos, vamos;\nnunca encontrareis homem mais capaz.","othellothehandkerchief~othellothehandkerchief~22":"Otelo — O lenço!","desdemonaipraytalkmeofcassio~emonaipraytalkmeofcassio~28":"Desdêmona — Peço-vos, falai-me de Cássio.","desdemonaamanthatallhistimehathfoundedhi~loveshareddangerswithyou~83":"Desdêmona — Um homem que durante toda a vida\nfundou sua boa fortuna em vosso amor,\ndividiu perigos convosco—","desdemonainsoothyouaretoblame~monainsoothyouaretoblame~29":"Desdêmona — Em verdade, estais errado.","othelloawayexit~othelloawayexit~15":"Otelo — Fora! Sai.","emiliaisnotthismanjealous~miliaisnotthismanjealous~25":"Emília — Não é ciumento este homem?","desdemonaineersawthisbeforesuretheressom~mostunhappyinthelossofit~92":"Desdêmona — Nunca vi isto antes.\nCertamente há algum prodígio neste lenço:\nsou muito infeliz por tê-lo perdido.","emiliatisnotayearortwoshowsusamantheyare~ookyoucassioandmyhusband~138":"Emília — Não é em um ano ou dois que se conhece um homem:\nsão todos só estômagos, e nós somos só comida;\ncomem-nos famintos e, quando estão cheios,\nrotam-nos. Vede, Cássio e meu marido!","entercassioandiago~entercassioandiago~18":"Entram Cássio e Iago.","iagothereisnootherwaytisshemustdotandlot~ppinessgoandimportuneher~68":"Iago — Não há outro meio; é ela quem deve fazê-lo:\ne, vê, que sorte! vai, e importuna-a.","desdemonahownowgoodcassiowhatsthenewswit~assiowhatsthenewswithyou~44":"Desdêmona — Então, bom Cássio! que novas me trazes?","cassiomadammyformersuitidobeseechyouthat~thercoursetofortunesalms~378":"Cássio — Senhora, o meu pedido de antes: suplico-vos\nque, por vossos bons ofícios, eu possa de novo\nexistir e ser membro do afeto daquele\na quem, com todo o ofício do meu coração,\ninteiramente honro: não quisera ser adiado.\nSe minha ofensa for de tal natureza mortal\nque nem meu serviço passado, nem as dores presentes,\nnem o mérito proposto no futuro\npossam resgatar-me ao seu amor,\nsaber isso já será meu benefício;\nentão me vestirei de um contentamento forçado\ne me recolherei a algum outro caminho,\nà esmola da fortuna.","desdemonaalasthricegentlecassiomyadvocat~lfidareletthatsufficeyou~315":"Desdêmona — Ai, três vezes gentil Cássio!\nMinha intercessão não está agora afinada;\nmeu senhor não é meu senhor; nem o reconheceria\nse estivesse tão mudado de semblante como de humor.\nAssim me ajudem todos os espíritos santificados,\ncomo falei por ti o melhor que pude\ne me pus no alvo de seu desagrado\npor minha franca palavra! deves ter paciência por algum tempo:\no que eu puder farei; e farei mais\ndo que por mim ousaria: que isso te baste.","iagoismylordangry~iagoismylordangry~17":"Iago — Está meu senhor irado?","emiliahewenthencebutnowandcertainlyinstr~inlyinstrangeunquietness~55":"Emília — Saiu daqui agorinha,\ne por certo em estranha inquietação.","iagocanhebeangryihaveseenthecannonwhenit~tterintindeedifhebeangry~196":"Iago — Pode ele estar irado? Vi o canhão\nquando lhe lançou as fileiras pelos ares\ne, como o diabo, de seu próprio braço\nfez voar seu irmão:—e pode ele estar irado?\nAlgo de peso, então: irei ao seu encontro:\nhá deveras assunto nisto, se ele está irado.","desdemonaipritheedosoexitiagosomethingsu~essandhesindictedfalsely~511":"Desdêmona — Peço-te, faze-o. Sai Iago.\nAlgo, por certo, de Estado,\nvindo de Veneza, ou alguma trama não chocada\nque se lhe tornou patente aqui em Chipre,\nturvou-lhe o espírito claro: e em tais casos\nas naturezas dos homens se enredam com coisas menores,\nainda que grandes sejam seu objeto. É bem assim;\npois, se nos dói um dedo, ele comunica\naos outros membros sãos essa mesma sensação\nde dor: não, devemos pensar que os homens não são deuses,\nnem esperar deles tais atenções\ncomo convêm ao dia de bodas. Maldita seja eu, Emília,\npor ter sido, guerreira desajeitada que sou,\na acusar sua dureza em minha alma;\nmas agora vejo que havia subornado a testemunha,\ne ele foi falsamente acusado.","emiliaprayheavenitbestatemattersasyouthi~ojealoustoyconcerningyou~85":"Emília — Queira o céu que sejam assuntos de Estado, como pensa,\ne não uma suspeita nem um capricho ciumento\nque vos diga respeito.","desdemonaalasthedayinevergavehimcause~thedayinevergavehimcause~37":"Desdêmona — Ai do dia! Nunca lhe dei motivo.","emiliabutjealoussoulswillnotbeanswerdsot~otuponitselfbornonitself~136":"Emília — Mas almas ciumentas não se contentam com isso;\nnem sempre têm ciúme por causa,\nmas por serem ciumentas: é um monstro\ngerado de si mesmo, nascido de si mesmo.","desdemonaheavenkeepthatmonsterfromothell~tmonsterfromothellosmind~46":"Desdêmona — Que o céu guarde esse monstro longe da mente de Otelo!","emilialadyamen~emilialadyamen~14":"Emília — Senhora, amém.","desdemonaiwillgoseekhimcassiowalkhereabo~ktoeffectittomyuttermost~102":"Desdêmona — Vou procurá-lo. Cássio, anda por aqui perto:\nse eu o achar disposto, apresentarei teu pedido\ne me empenharei em obtê-lo com todo o meu esforço.","cassioihumblythankyourladyshipexeuntdesd~exeuntdesdemonaandemilia~54":"Cássio — Agradeço humildemente a Vossa Senhoria. Saem Desdêmona e Emília.","enterbianca~enterbianca~11":"Entra Bianca.","biancasaveyoufriendcassio~iancasaveyoufriendcassio~25":"Bianca — Deus vos guarde, amigo Cássio!","cassiowhatmakeyoufromhomehowisitwithyoum~oveiwascomingtoyourhouse~91":"Cássio — Que fazes longe de casa?\nComo vais, minha belíssima Bianca?\nPor minha fé, doce amor, ia a tua casa.","biancaandiwasgoingtoyourlodgingcassiowha~coretimesowearyreckoning~164":"Bianca — E eu ia ao teu alojamento, Cássio.\nComo, ficar uma semana ausente? sete dias e noites?\nCento e sessenta e oito horas? e as horas de ausência dos amantes\noito vezes vinte mais tediosas que o relógio?\nOh, cansativa conta!","cassiopardonmebiancaihavethiswhilewithle~erchieftakemethisworkout~178":"Cássio — Perdoa-me, Bianca:\nandei todo este tempo oprimido por pensamentos de chumbo:\nmas, num tempo mais contínuo,\nsaldarei esta conta de ausência. Doce Bianca, Dando-lhe o lenço de Desdêmona.\ncopia-me este bordado.","biancaocassiowhencecamethisthisissometok~useistcometothiswellwell~109":"Bianca — Oh, Cássio, de onde veio isto?\nÉ alguma lembrança de uma amiga mais nova:\nà ausência sentida agora sinto uma causa:\nChegou-se a isto? Pois bem, pois bem.","cassiogotowomanthrowyourvileguessesinthe~rancenoingoodtrothbianca~148":"Cássio — Ora, mulher!\nAtira tuas vis suspeitas nos dentes do diabo,\nde onde as tiraste. Estás agora ciumenta,\ncrendo que isto vem de alguma amante, de alguma lembrança:\nNão, por minha boa fé, Bianca.","biancawhywhoseisit~biancawhywhoseisit~18":"Bianca — Ora, então de quem é?","cassioiknownotsweetifounditinmychamberil~dotandleavemeforthistime~135":"Cássio — Não sei, doce: achei-o em meu quarto.\nGosto do trabalho: antes que o reclamem—\ncomo é bem provável—quero que seja copiado:\nleva-o e faze-o; e deixa-me por esta vez.","biancaleaveyouwherefore~biancaleaveyouwherefore~23":"Bianca — Deixar-te! por quê?","cassioidoattendhereonthegeneralandthinki~wishtohavehimseemewomand~80":"Cássio — Aguardo aqui o general;\ne não julgo conveniente, nem é meu desejo,\nque ele me veja acompanhado de mulher.","biancawhyiprayyou~biancawhyiprayyou~17":"Bianca — Por quê, peço-te?","cassionotthatiloveyounot~cassionotthatiloveyounot~24":"Cássio — Não que eu não te ame.","biancabutthatyoudonotlovemeiprayyoubring~fishallseeyousoonatnight~88":"Bianca — Mas que não me amas.\nPeço-te, acompanha-me um pouco no caminho,\ne diz-me se te verei cedo à noite.","cassiotisbutalittlewaythaticanbringyoufo~tendherebutillseeyousoon~68":"Cássio — É pouco o caminho que posso acompanhar-te;\npois aguardo aqui: mas verei-te em breve.","biancatisverygoodimustbecircumstancedexe~ustbecircumstancedexeunt~43":"Bianca — Muito bem; devo me conformar às circunstâncias. Saem."}$tr$::jsonb, 691)
